struct NativeDragGhostPreview {
    text: String,
    icons: Vec<IconId>,
    width: f32,
    height: f32,
}

impl Render for NativeDragGhostPreview {
    fn render(&mut self, _window: &mut Window, _cx: &mut Context<Self>) -> impl IntoElement {
        let (background, foreground) = crate::internal_drag_preview_colors();
        div()
            .w(px(self.width))
            .h(px(self.height))
            .overflow_hidden()
            .px(px(12.0))
            .py(px(8.0))
            .rounded_sm()
            .border_1()
            .border_color(gpui::hsla(0.0, 0.0, 0.7, 0.8))
            .bg(background)
            .text_color(foreground)
            .text_sm()
            .child(crate::drag_preview_contents(
                &self.text,
                &self.icons,
                foreground,
            ))
    }
}

