fn workspace_drop_hover_distance(
    left: gpui::Point<gpui::Pixels>,
    right: gpui::Point<gpui::Pixels>,
) -> f32 {
    let dx = (left.x - right.x).as_f32();
    let dy = (left.y - right.y).as_f32();
    dx.hypot(dy)
}

