fn clamp_sidebar_width(width: f32, window_width: f32) -> f32 {
    let requested = if width.is_finite() {
        width
    } else {
        DEFAULT_SIDEBAR_WIDTH
    };
    let available_max = (window_width - MIN_FILE_VIEW_WIDTH).max(SIDEBAR_MIN_WIDTH);
    requested.clamp(SIDEBAR_MIN_WIDTH, SIDEBAR_MAX_WIDTH.min(available_max))
}

#[cfg(target_os = "windows")]
fn native_cursor_screen_position() -> Option<(f32, f32)> {
    use windows::Win32::{Foundation::POINT, UI::WindowsAndMessaging::GetCursorPos};
    let mut point = POINT::default();
    unsafe { GetCursorPos(&mut point).ok()? };
    Some((point.x as f32, point.y as f32))
}

#[cfg(target_os = "windows")]
fn native_window_has_capture(window: &Window) -> bool {
    use windows::Win32::UI::Input::KeyboardAndMouse::GetCapture;
    native_window_handle(window).is_some_and(|hwnd| unsafe { GetCapture() == hwnd })
}

#[cfg(not(target_os = "windows"))]
fn native_cursor_screen_position() -> Option<(f32, f32)> {
    None
}

#[cfg(not(target_os = "windows"))]
fn native_window_has_capture(_window: &Window) -> bool {
    true
}

#[cfg(target_os = "windows")]
fn native_window_handle(window: &Window) -> Option<windows::Win32::Foundation::HWND> {
    let raw = raw_window_handle::HasWindowHandle::window_handle(window)
        .ok()?
        .as_raw();
    match raw {
        raw_window_handle::RawWindowHandle::Win32(handle) => Some(
            windows::Win32::Foundation::HWND(handle.hwnd.get() as *mut std::ffi::c_void),
        ),
        _ => None,
    }
}

#[cfg(not(target_os = "windows"))]
fn native_window_handle(_window: &Window) -> Option<()> {
    None
}

#[cfg(target_os = "windows")]
fn native_topmost_window_is(
    expected: windows::Win32::Foundation::HWND,
    screen: (f32, f32),
) -> bool {
    use windows::Win32::{Foundation::POINT, UI::WindowsAndMessaging::WindowFromPoint};
    let point = POINT {
        x: screen.0.round() as i32,
        y: screen.1.round() as i32,
    };
    unsafe { WindowFromPoint(point) == expected }
}

#[cfg(not(target_os = "windows"))]
fn native_topmost_window_is(_expected: (), _screen: (f32, f32)) -> bool {
    false
}

#[cfg(target_os = "windows")]
fn native_client_origin(hwnd: windows::Win32::Foundation::HWND) -> Option<(f32, f32)> {
    use windows::Win32::{Foundation::POINT, Graphics::Gdi::ClientToScreen};
    let mut origin = POINT::default();
    if !unsafe { ClientToScreen(hwnd, &mut origin) }.as_bool() {
        return None;
    }
    Some((origin.x as f32, origin.y as f32))
}

#[cfg(not(target_os = "windows"))]
fn native_client_origin(_hwnd: ()) -> Option<(f32, f32)> {
    None
}

fn pinned_tab_disambiguation_hints(labels: &[TabLabel]) -> Vec<Option<String>> {
    let ancestors: Vec<Vec<String>> = labels
        .iter()
        .map(|label| {
            if !label.locked {
                return Vec::new();
            }
            let mut names = Vec::new();
            let mut path = std::path::Path::new(label.location.as_ref());
            while let Some(parent) = path.parent() {
                if let Some(name) = parent.file_name() {
                    names.push(name.to_string_lossy().into_owned());
                } else if let Some(prefix) =
                    parent.components().find_map(|component| match component {
                        std::path::Component::Prefix(prefix) => Some(prefix),
                        _ => None,
                    })
                {
                    // 同じ祖先名が別ドライブや別の UNC share にある場合も識別する。
                    names.push(prefix.as_os_str().to_string_lossy().into_owned());
                    break;
                }
                path = parent;
            }
            names
        })
        .collect();

    labels
        .iter()
        .enumerate()
        .map(|(index, label)| {
            if !label.locked {
                return None;
            }
            let title_key = label.title.to_string().to_lowercase();
            let location_key = label.location.to_string().to_lowercase();
            let peers: Vec<usize> = labels
                .iter()
                .enumerate()
                .filter_map(|(other_index, other)| {
                    (other_index != index
                        && other.locked
                        && other.title.to_string().to_lowercase() == title_key)
                        .then_some(other_index)
                })
                .collect();
            if peers.is_empty()
                || peers
                    .iter()
                    .any(|peer| labels[*peer].location.to_string().to_lowercase() == location_key)
            {
                return None;
            }
            (0..ancestors[index].len()).find_map(|depth| {
                let candidate = &ancestors[index][depth];
                peers
                    .iter()
                    .all(|peer| {
                        ancestors[*peer]
                            .get(depth)
                            .is_none_or(|other| other.to_lowercase() != candidate.to_lowercase())
                    })
                    .then(|| candidate.clone())
            })
        })
        .collect()
}

