/// v5 と同じく、cascade を閉じた時点で全列を捨てる短命な overlay state。
struct FolderTreeMenuUi {
    anchor: gpui::Bounds<gpui::Pixels>,
    kind: FolderTreeAnchorKind,
    /// ボタンを menu が開いている間だけ残すための表示 owner。menu は shell の短命 state
    /// だが、item の hover/active 表現は directory view に置く。
    owner_view: gpui::Entity<DirectoryListDemo>,
    model: folder_tree_menu::Model,
    column_scrolls: Vec<ScrollHandle>,
    /// `ScrollHandle` は列 index ではなく model の column ID に属する。hover で child を
    /// 差し替えると同じ index に別の列が来るため、古い max offset を持ち越さない。
    column_scroll_ids: Vec<u64>,
    /// Per-column row geometry is a disposable projection keyed by stable model IDs.
    column_height_ids: Vec<u64>,
    column_heights: Vec<Rc<RefCell<RowHeights>>>,
    /// Parent row index for each painted child anchor; absent entries are not live anchors.
    entry_anchor_indices: Vec<Option<usize>>,
    measurement_notification_pending: Rc<Cell<bool>>,
    /// index N の列を開いた親項目の実際の paint bounds。N=0 は root anchor なので持たない。
    ///
    /// 値を hover 時に copy すると、複数行化・scroll・resize の後に子列だけが
    /// 古い位置へ残る。v5 の `PendingChild::anchor` と同じく、paint ごとに更新される
    /// cell を列の寿命と一緒に保持する。
    entry_anchors: Vec<Rc<RefCell<Option<gpui::Bounds<gpui::Pixels>>>>>,
    /// 各列の実測 bounds。内容が短い列を最大高で早まって clamp しないための
    /// flow-layout の高さの根拠で、entry anchor と同じく paint 後の次 frame に使う。
    column_bounds: Vec<Rc<RefCell<Option<gpui::Bounds<gpui::Pixels>>>>>,
    /// 実測 bounds を得た viewport。window resize 後に旧座標で child を一 frame
    /// 描かないため、異なれば bounds/anchor を無効化してから再計測する。
    bounds_viewport: Option<gpui::Size<gpui::Pixels>>,
    /// loading/ready/error の切替で古い実測高さを使わないための layout 世代。
    column_layout_signature: Vec<(u64, u8, usize, usize)>,
    hover_scroll: Vec<FolderTreeHoverScroll>,
    /// hover edge の連続 scroll は frame 数ではなく経過時間で送る。高 refresh rate
    /// display だけ速くならず、一時的な frame drop でも一気に飛ばない。
    hover_scroll_last: Option<Instant>,
}

