/// 保存されたタブを、復元する形へ開く。
///
/// **id は保存された key をそのまま使う。** 実行をまたいで同じタブを指すので、
/// 将来 workspace ごとの保存に移るときも番号を振り直さない。
///
/// 構造として読めない location だけを落とす。存在しない path は落とさない
/// （offline の drive や、今切れている共有も保存したタブとして残す）。ThisPc は
/// filesystem validation や enumeration を経ず、view の virtual effect から始まる。
fn restored_tabs(saved_tabs: &[session_store::TabSnapshot]) -> Vec<(usize, SavedViewState, bool)> {
    let mut tabs = Vec::with_capacity(saved_tabs.len());
    for tab in saved_tabs {
        let Ok(location) = tab.location.to_location() else {
            continue;
        };
        // u64 の key を id にする。64bit では常に収まる。
        let Ok(id) = usize::try_from(tab.key) else {
            continue;
        };
        tabs.push((
            id,
            SavedViewState {
                location: Some(location),
                layout: tab.layout,
                icon_scale: tab.icon_scale,
                sort: tab.sort,
                group: tab.group,
            },
            tab.locked,
        ));
    }
    tabs
}

fn restored_active_id(active: Option<u64>, tabs: &[(usize, SavedViewState, bool)]) -> usize {
    active
        .and_then(|key| usize::try_from(key).ok())
        .filter(|id| tabs.iter().any(|(tab_id, _, _)| tab_id == id))
        .unwrap_or(tabs[0].0)
}

/// 起動時の通知を並べる最大行数。壊れたファイルで画面を埋めない。
const MAX_NOTICE_ROWS: usize = 3;

#[derive(Clone, Debug, PartialEq, Eq)]
enum SessionNotice {
    Raw(String),
    Message(Message),
    MessageDetail { message: Message, detail: String },
}

impl SessionNotice {
    fn render(&self, translator: &Translator) -> String {
        match self {
            Self::Raw(reason) => translator.session_not_saved(reason),
            Self::Message(message) => translator.session_not_saved(&translator.text(*message)),
            Self::MessageDetail { message, detail } => {
                translator.session_not_saved_detail(*message, detail)
            }
        }
    }
}

fn append_operation_notice(current: &mut Option<Vec<Message>>, next: Message) {
    let messages = current.get_or_insert_with(Vec::new);
    if !messages.contains(&next) {
        messages.push(next);
    }
}

fn next_terminal_request_ticket(ticket: &mut u64) -> u64 {
    *ticket = ticket.wrapping_add(1);
    *ticket
}

fn terminal_request_is_current(current: u64, completed: u64) -> bool {
    current == completed
}

fn remap_pane_layout_ids(
    layout: &mut session_store::PaneLayoutSnapshot,
    ids: &HashMap<u64, u64>,
) -> bool {
    match layout {
        session_store::PaneLayoutSnapshot::Pane { key } => {
            let Some(mapped) = ids.get(key) else {
                return false;
            };
            *key = *mapped;
            true
        }
        session_store::PaneLayoutSnapshot::Split { first, second, .. } => {
            remap_pane_layout_ids(first, ids) && remap_pane_layout_ids(second, ids)
        }
    }
}

