/// Workspace owns pane contents/focus and the tree that determines spatial layout.
struct Workspace {
    name: String,
    pane_layout: PaneLayoutNode,
    panes: Vec<WorkspacePane>,
    job_progress: Option<JobProgressPane>,
    focused_pane_id: PaneId,
    next_pane_id: Option<u64>,
    topology_revision: u64,
}

impl Workspace {
    fn single_pane() -> Self {
        Self {
            name: "Workspace 1".into(),
            pane_layout: PaneLayoutNode::single(PaneId(1)),
            panes: vec![WorkspacePane {
                id: PaneId(1),
                content: PaneContent::Directory(DirectoryPane {
                    tabs: Vec::new(),
                    active_tab_id: 0,
                }),
            }],
            job_progress: None,
            focused_pane_id: PaneId(1),
            next_pane_id: Some(2),
            topology_revision: 1,
        }
    }

    fn allocate_pane_id(&mut self) -> Option<PaneId> {
        let value = self.next_pane_id?;
        self.next_pane_id = value.checked_add(1);
        Some(PaneId(value))
    }

    fn ensure_floating_job_progress(&mut self) {
        if self.job_progress.is_some() {
            return;
        }
        let Some(id) = self.allocate_pane_id() else {
            return;
        };
        self.job_progress = Some(JobProgressPane {
            pane: WorkspacePane {
                id,
                content: PaneContent::JobProgress(()),
            },
            generation: id.0,
            placement: JobProgressPlacement::Floating { right: 16.0, top: 72.0, width: 400.0, max_height: 360.0 },
        });
    }

    fn insert_pane_after(&mut self, source: PaneId) -> Option<PaneId> {
        if self.panes.len() >= session_store::MAX_PANES || !self.pane_layout.contains(source) {
            return None;
        }
        let id = self.allocate_pane_id()?;
        let direction = self
            .pane_layout
            .parent_split_direction(source)
            .unwrap_or(SplitDirection::Horizontal);
        if !self.pane_layout.split_next_to(source, id, direction, true) {
            return None;
        }
        self.panes.push(WorkspacePane {
            id,
            content: PaneContent::Directory(DirectoryPane {
                tabs: Vec::new(),
                active_tab_id: 0,
            }),
        });
        self.bump_topology_revision();
        Some(id)
    }

    fn bump_topology_revision(&mut self) {
        self.topology_revision = self.topology_revision.wrapping_add(1).max(1);
    }

    fn remove_pane(&mut self, pane_id: PaneId) -> Option<PaneId> {
        let neighbor = self.pane_layout.remove_pane(pane_id)?;
        self.panes.retain(|pane| pane.id != pane_id);
        let neighbor = if self.directory_pane(neighbor).is_some() {
            neighbor
        } else {
            self.directory_pane_ids().into_iter().next()?
        };
        self.bump_topology_revision();
        Some(neighbor)
    }

    fn relocate_pane_split(
        &mut self,
        source: PaneId,
        target: PaneId,
        direction: SplitDirection,
        after: bool,
        expected_revision: u64,
    ) -> bool {
        if expected_revision != self.topology_revision
            || source == target
            || self.directory_pane(source).is_none()
            || self.directory_pane(target).is_none()
        {
            return false;
        }

        let mut replacement = self.pane_layout.clone();
        if !replacement.relocate_pane_split(source, target, direction, after) {
            return false;
        }

        self.pane_layout = replacement;
        self.focused_pane_id = source;
        self.bump_topology_revision();
        true
    }

    fn merge_pane_into(
        &mut self,
        source: PaneId,
        target: PaneId,
        expected_revision: u64,
    ) -> bool {
        if expected_revision != self.topology_revision
            || source == target
            || self.directory_pane(source).is_none()
            || self.directory_pane(target).is_none()
        {
            return false;
        }

        let mut replacement = self.pane_layout.clone();
        if replacement.remove_pane(source).is_none() || !replacement.contains(target) {
            return false;
        }
        let Some(source_index) = self.panes.iter().position(|pane| pane.id == source) else {
            return false;
        };
        let first_directory = replacement
            .pane_ids()
            .into_iter()
            .find(|pane_id| *pane_id != source && self.directory_pane(*pane_id).is_some());
        let Some(first_directory) = first_directory else {
            return false;
        };

        let source_pane = self.panes.remove(source_index);
        let source_directory = match source_pane.content {
            PaneContent::Directory(directory) => directory,
            PaneContent::JobProgress(()) => {
                unreachable!("source directory was validated before mutation")
            }
        };
        let moved_active_tab = source_directory.tabs.last().map(|tab| tab.id);
        let target_directory = self
            .directory_pane_mut(target)
            .expect("distinct target directory remains after source removal");
        target_directory.tabs.extend(source_directory.tabs);
        if let Some(active_tab_id) = moved_active_tab {
            target_directory.active_tab_id = active_tab_id;
        }

        self.pane_layout = replacement;
        self.focused_pane_id = first_directory;
        self.bump_topology_revision();
        true
    }

    fn swap_panes(&mut self, first: PaneId, second: PaneId) -> bool {
        if self.pane_layout.swap_panes(first, second) {
            self.bump_topology_revision();
            true
        } else {
            false
        }
    }

    // focused_pane_id tracks the directory command target. GPUI leaf focus is
    // separate presentation state and will not retarget this ID.
    fn focused_pane(&self) -> &DirectoryPane {
        self.panes
            .iter()
            .find(|pane| pane.id == self.focused_pane_id)
            .and_then(|pane| match &pane.content {
                PaneContent::Directory(directory) => Some(directory),
                PaneContent::JobProgress(()) => None,
            })
            .expect("focused pane ID always names the directory command target")
    }

    fn focused_pane_mut(&mut self) -> &mut DirectoryPane {
        self.panes
            .iter_mut()
            .find(|pane| pane.id == self.focused_pane_id)
            .and_then(|pane| match &mut pane.content {
                PaneContent::Directory(directory) => Some(directory),
                PaneContent::JobProgress(()) => None,
            })
            .expect("focused pane ID always names the directory command target")
    }

    fn tabs(&self) -> impl Iterator<Item = &Tab> {
        self.panes.iter().filter_map(|pane| match &pane.content {
            PaneContent::Directory(directory) => Some(&directory.tabs),
            PaneContent::JobProgress(()) => None,
        }).flatten()
    }

    fn directory_pane_ids(&self) -> std::collections::HashSet<PaneId> {
        self.panes
            .iter()
            .filter_map(|pane| match &pane.content {
                PaneContent::Directory(_) => Some(pane.id),
                PaneContent::JobProgress(()) => None,
            })
            .collect()
    }

    fn pane_and_tab(
        &self,
        tab_id: usize,
        entity_id: gpui::EntityId,
    ) -> Option<(&WorkspacePane, &Tab)> {
        self.panes.iter().find_map(|pane| {
            let directory = pane.directory();
            directory.tabs
                .iter()
                .find(|tab| tab.id == tab_id && tab.view.entity_id() == entity_id)
                .map(|tab| (pane, tab))
        })
    }

    fn owns_tab(&self, tab_id: usize, entity_id: gpui::EntityId) -> bool {
        self.pane_and_tab(tab_id, entity_id).is_some()
    }

    fn directory_pane(&self, id: PaneId) -> Option<&DirectoryPane> {
        self.panes.iter().find(|pane| pane.id == id).and_then(|pane| match &pane.content {
            PaneContent::Directory(directory) => Some(directory),
            PaneContent::JobProgress(()) => None,
        })
    }

    fn directory_pane_mut(&mut self, id: PaneId) -> Option<&mut DirectoryPane> {
        self.panes.iter_mut().find(|pane| pane.id == id).and_then(|pane| match &mut pane.content {
            PaneContent::Directory(directory) => Some(directory),
            PaneContent::JobProgress(()) => None,
        })
    }

}

/// Stable identity for a workspace owned by this window.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(super) struct WorkspaceId(NonZeroU64);

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct WorkspacePaneId {
    workspace: WorkspaceId,
    pane: PaneId,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct JobProgressSelection {
    workspace: WorkspaceId,
    pane: PaneId,
    generation: u64,
}

impl WorkspaceId {
    const INITIAL: Self = Self(NonZeroU64::new(1).expect("workspace IDs are non-zero"));

    pub(super) fn value(self) -> u64 {
        self.0.get()
    }
}

/// Window authority for workspace order and active identity.
///
/// Restores and retains every workspace in the window.
struct WorkspaceCollection {
    ordered: Vec<(WorkspaceId, Workspace)>,
    active: WorkspaceId,
}

fn directory_tab_is_visible(
    active_workspace: WorkspaceId,
    tab_workspace: WorkspaceId,
    pane_active_tab: usize,
    tab: usize,
) -> bool {
    active_workspace == tab_workspace && pane_active_tab == tab
}

impl WorkspaceCollection {
    fn initial() -> Self {
        Self {
            ordered: vec![(WorkspaceId::INITIAL, Workspace::single_pane())],
            active: WorkspaceId::INITIAL,
        }
    }

    fn active(&self) -> &Workspace {
        self.ordered
            .iter()
            .find_map(|(id, workspace)| (*id == self.active).then_some(workspace))
            .expect("active workspace ID must belong to the window")
    }

    fn active_mut(&mut self) -> &mut Workspace {
        self.ordered
            .iter_mut()
            .find_map(|(id, workspace)| (*id == self.active).then_some(workspace))
            .expect("active workspace ID must belong to the window")
    }

    fn insert(&mut self, id: WorkspaceId, workspace: Workspace) {
        self.ordered.push((id, workspace));
    }

    fn get(&self, id: WorkspaceId) -> Option<&Workspace> {
        self.ordered
            .iter()
            .find_map(|(candidate, workspace)| (*candidate == id).then_some(workspace))
    }

    fn activate(&mut self, id: WorkspaceId) -> bool {
        if self.get(id).is_none() || self.active == id {
            return false;
        }
        self.active = id;
        true
    }

    fn tabs(&self) -> impl Iterator<Item = &Tab> {
        self.ordered
            .iter()
            .flat_map(|(_, workspace)| workspace.tabs())
    }

    fn find_tab(&self, tab_id: usize, entity_id: gpui::EntityId) -> Option<&Tab> {
        self.ordered.iter().find_map(|(_, workspace)| {
            workspace
                .tabs()
                .find(|tab| tab.id == tab_id && tab.view.entity_id() == entity_id)
        })
    }

    fn find_tab_by_id(&self, tab_id: usize) -> Option<&Tab> {
        // FilerShell が window 内の全 workspace に対して tab ID を単調に割り当てる。
        self.ordered
            .iter()
            .find_map(|(_, workspace)| workspace.tabs().find(|tab| tab.id == tab_id))
    }
}

fn workspace_tab_bounds_hit(
    menu_mode: bool,
    bounds: Option<gpui::Bounds<gpui::Pixels>>,
    point: gpui::Point<gpui::Pixels>,
) -> Option<gpui::Bounds<gpui::Pixels>> {
    if menu_mode {
        return None;
    }
    bounds.filter(|bounds| bounds.contains(&point))
}

fn pane_drop_zone(
    bounds: gpui::Bounds<gpui::Pixels>,
    point: gpui::Point<gpui::Pixels>,
) -> Option<PaneDropZone> {
    if !bounds.contains(&point)
        || bounds.size.width.as_f32() <= 0.0
        || bounds.size.height.as_f32() <= 0.0
    {
        return None;
    }
    let x = (point.x - bounds.origin.x).as_f32() / bounds.size.width.as_f32();
    let y = (point.y - bounds.origin.y).as_f32() / bounds.size.height.as_f32();
    if (x - 0.5).abs().max((y - 0.5).abs()) <= 0.15 {
        return Some(PaneDropZone::Merge);
    }
    if x.min(1.0 - x) >= y {
        return Some(PaneDropZone::Split {
            direction: SplitDirection::Vertical,
            after: false,
        });
    }
    if x.max(1.0 - x) <= y {
        return Some(PaneDropZone::Split {
            direction: SplitDirection::Vertical,
            after: true,
        });
    }
    if y.min(1.0 - y) >= x {
        return Some(PaneDropZone::Split {
            direction: SplitDirection::Horizontal,
            after: false,
        });
    }
    if y.max(1.0 - y) <= x {
        return Some(PaneDropZone::Split {
            direction: SplitDirection::Horizontal,
            after: true,
        });
    }
    None
}

fn directory_event_allowed_during_batch_rename(
    event: &DirectoryEvent,
    batch_rename_active: bool,
) -> bool {
    !batch_rename_active
        || !matches!(
            event,
            DirectoryEvent::OpenTab(_) | DirectoryEvent::OpenFolder(_)
        )
}

