impl FilerShell {
    pub(crate) fn batch_rename_target_is_current(
        &self,
        tab_id: usize,
        view_id: gpui::EntityId,
        cx: &gpui::App,
    ) -> bool {
        let pane = self.workspace.active().focused_pane();
        pane.active_tab_id == tab_id
            && pane.tabs.iter().any(|tab| {
                tab.id == tab_id
                    && tab.view.entity_id() == view_id
                    && tab.view.read(cx).batch_rename_probe_is_admissible()
            })
            && self.top_overlay(cx).is_none()
    }

    fn prune_consumed_internal_move_sessions(&mut self) {
        let live_views = self
            .workspace
            .active()
            .panes
            .iter()
            .flat_map(|pane| pane.directory().tabs.iter().map(|tab| tab.view.entity_id()))
            .collect::<HashSet<_>>();
        self.consumed_internal_move_sessions
            .retain(|view_id, _| live_views.contains(view_id));
    }

    fn internal_move_session_was_consumed(
        &self,
        source_view_entity_id: gpui::EntityId,
        session_id: u64,
    ) -> bool {
        self.consumed_internal_move_sessions
            .get(&source_view_entity_id)
            .is_some_and(|consumed| *consumed >= session_id)
    }

    fn internal_drag_route_is_current(
        &self,
        route: &InternalDragSourceRoute,
        source_view_entity_id: gpui::EntityId,
        snapshot: &InternalDragSnapshot,
        allow_taken_payload: bool,
        cx: &gpui::App,
    ) -> bool {
        if route.view != source_view_entity_id
            || route.session_id != snapshot.session_id
            || route.location_generation != snapshot.location_generation
            || route.presentation_revision != snapshot.presentation_revision
            || route.snapshot.session_id != snapshot.session_id
            || route.snapshot.location_generation != snapshot.location_generation
            || route.snapshot.presentation_revision != snapshot.presentation_revision
            || route.snapshot.sources != snapshot.sources
            || self.internal_move_session_was_consumed(route.view, route.session_id)
        {
            return false;
        }
        let Some(workspace) = self.workspace.get(route.workspace) else {
            return false;
        };
        let Some((pane, tab)) = workspace.pane_and_tab(route.tab, route.view) else {
            return false;
        };
        let slot_snapshot = route.snapshot_slot.borrow();
        let slot_matches = if allow_taken_payload {
            slot_snapshot.as_ref().is_none_or(|slot_snapshot| {
                slot_snapshot.session_id == route.session_id
                    && slot_snapshot.location_generation == route.location_generation
                    && slot_snapshot.presentation_revision == route.presentation_revision
                    && slot_snapshot.sources == route.snapshot.sources
            })
        } else {
            slot_snapshot.as_ref().is_some_and(|slot_snapshot| {
                slot_snapshot.session_id == route.session_id
                    && slot_snapshot.location_generation == route.location_generation
                    && slot_snapshot.presentation_revision == route.presentation_revision
                    && slot_snapshot.sources == route.snapshot.sources
            })
        };
        pane.id == route.pane
            && pane.directory().active_tab_id == route.tab
            && slot_matches
            && matches!(
                &route.input_source,
                gpui::MouseInputSource::Mouse
                    | gpui::MouseInputSource::Touch
                    | gpui::MouseInputSource::Pen
            )
            && (route.input_source != gpui::MouseInputSource::Touch
                || route.snapshot.touch_start_position.is_some())
            && tab
                .view
                .read(cx)
                .accepts_internal_drag_session(route.session_id)
            && tab
                .view
                .read(cx)
                .accepts_internal_drag_source(&route.snapshot)
    }

    fn retained_internal_drag_source(
        &self,
        source_view_entity_id: gpui::EntityId,
        snapshot: &InternalDragSnapshot,
        cx: &gpui::App,
    ) -> Option<(&WorkspacePane, &Tab)> {
        let route = self.retained_internal_drag_route.as_ref()?;
        if route.workspace == self.workspace.active
            || !self.internal_drag_route_is_current(
                route,
                source_view_entity_id,
                snapshot,
                true,
                cx,
            )
        {
            return None;
        }
        let workspace = self.workspace.get(route.workspace)?;
        let (pane, tab) = workspace.pane_and_tab(route.tab, route.view)?;
        (pane.id == route.pane).then_some((pane, tab))
    }

    fn consume_internal_move_session(
        &mut self,
        source_view_entity_id: gpui::EntityId,
        session_id: u64,
    ) -> bool {
        self.prune_consumed_internal_move_sessions();
        if self.internal_move_session_was_consumed(source_view_entity_id, session_id) {
            return false;
        }
        self.consumed_internal_move_sessions
            .insert(source_view_entity_id, session_id);
        self.clear_internal_drag_route_for(source_view_entity_id, session_id);
        true
    }

    pub(super) fn internal_cross_pane_move_candidate(
        &self,
        source_view_entity_id: gpui::EntityId,
        snapshot: &InternalDragSnapshot,
        target_tab_id: usize,
        target_view_entity_id: gpui::EntityId,
        target: &InternalDropTarget,
        target_projection_current: Option<bool>,
        source_projection_current: Option<bool>,
        cx: &gpui::App,
    ) -> bool {
        if self.internal_move_session_was_consumed(source_view_entity_id, snapshot.session_id)
            || self.pending_native_drag.as_ref().is_some_and(|pending| {
                pending.view_id == source_view_entity_id
                    && pending.session_id == snapshot.session_id
                    && pending.admitted_local_move.is_some()
            })
        {
            return false;
        }
        let active_source = self.workspace.active().panes.iter().find_map(|pane| {
            pane.directory()
                .tabs
                .iter()
                .find(|tab| tab.view.entity_id() == source_view_entity_id)
                .map(|tab| (self.workspace.active, pane, tab))
        });
        let retained_workspace = self
            .retained_internal_drag_route
            .as_ref()
            .map(|route| route.workspace);
        let source = active_source.or_else(|| {
            self.retained_internal_drag_source(source_view_entity_id, snapshot, cx)
                .zip(retained_workspace)
                .map(|((pane, tab), workspace)| (workspace, pane, tab))
        });
        let Some((source_workspace, source_pane, source_tab)) = source else {
            return false;
        };
        let Some((target_pane, target_tab)) = self
            .workspace
            .active()
            .pane_and_tab(target_tab_id, target_view_entity_id)
        else {
            return false;
        };
        let same_view = source_workspace == self.workspace.active
            && source_view_entity_id == target_view_entity_id;
        let source_current = if same_view {
            source_projection_current == Some(true)
        } else {
            source_tab
                .view
                .read(cx)
                .accepts_internal_drag_session(snapshot.session_id)
                && source_tab
                    .view
                    .read(cx)
                    .accepts_internal_drag_source(snapshot)
                && (source_workspace == self.workspace.active
                    || self
                        .retained_internal_drag_source(source_view_entity_id, snapshot, cx)
                        .is_some())
        };
        let target_current = target_projection_current.unwrap_or_else(|| {
            target_tab
                .view
                .read(cx)
                .accepts_internal_drag_target(target)
        });
        source_pane.directory().active_tab_id == source_tab.id
            && target_pane.directory().active_tab_id == target_tab_id
            && source_current
            && target_current
            && internal_drop_target_is_valid(
                &snapshot.sources,
                Some(&target.path),
                EntryKind::Folder,
                false,
            )
    }

    pub(super) fn admit_internal_cross_pane_move(
        &mut self,
        source_view_entity_id: gpui::EntityId,
        snapshot: &InternalDragSnapshot,
        target_tab_id: usize,
        target_view_entity_id: gpui::EntityId,
        target: InternalDropTarget,
        target_projection_current: bool,
        source_projection_current: Option<bool>,
        cx: &mut Context<Self>,
    ) {
        if !self.internal_cross_pane_move_candidate(
            source_view_entity_id,
            snapshot,
            target_tab_id,
            target_view_entity_id,
            &target,
            Some(target_projection_current),
            source_projection_current,
            cx,
        ) {
            return;
        }
        if !self.consume_internal_move_session(source_view_entity_id, snapshot.session_id) {
            return;
        }
        self.cancel_native_drag_candidate_for(source_view_entity_id, Some(snapshot.session_id), cx);
        let request = internal_move_request(snapshot.sources.clone(), target, target_tab_id);
        let paths = request.sources.clone();
        if let Err(action) = self
            .native_drag_pin_drains
            .defer(DeferredNativeAction::Submit(request), paths)
        {
            self.process_deferred_native_action(action, cx);
        }
    }

    pub(super) fn admit_internal_background_move(
        &mut self,
        source_view_entity_id: gpui::EntityId,
        snapshot: &InternalDragSnapshot,
        target_tab_id: usize,
        target_view_entity_id: gpui::EntityId,
        target: ExternalDropTarget,
        target_projection_current: bool,
        source_projection_current: Option<bool>,
        cx: &mut Context<Self>,
    ) {
        let ExternalDropTarget::Background { .. } = &target else {
            return;
        };
        if self.internal_move_session_was_consumed(source_view_entity_id, snapshot.session_id)
            || !target_projection_current
        {
            return;
        }
        let active_source = self.workspace.active().panes.iter().find_map(|pane| {
            pane.directory()
                .tabs
                .iter()
                .find(|tab| tab.view.entity_id() == source_view_entity_id)
                .map(|tab| (self.workspace.active, pane, tab))
        });
        let retained_workspace = self
            .retained_internal_drag_route
            .as_ref()
            .map(|route| route.workspace);
        let source = active_source.or_else(|| {
            self.retained_internal_drag_source(source_view_entity_id, snapshot, cx)
                .zip(retained_workspace)
                .map(|((pane, tab), workspace)| (workspace, pane, tab))
        });
        let Some((source_workspace, source_pane, source_tab)) = source else {
            return;
        };
        let Some((target_pane, _target_tab)) = self
            .workspace
            .active()
            .pane_and_tab(target_tab_id, target_view_entity_id)
        else {
            return;
        };
        let same_view = source_workspace == self.workspace.active
            && source_view_entity_id == target_view_entity_id;
        let source_current = if same_view {
            source_projection_current == Some(true)
        } else {
            source_tab
                .view
                .read(cx)
                .accepts_internal_drag_session(snapshot.session_id)
                && source_tab
                    .view
                    .read(cx)
                    .accepts_internal_drag_source(snapshot)
                && (source_workspace == self.workspace.active
                    || self
                        .retained_internal_drag_source(source_view_entity_id, snapshot, cx)
                        .is_some())
        };
        if source_pane.directory().active_tab_id != source_tab.id
            || target_pane.directory().active_tab_id != target_tab_id
            || !source_current
        {
            return;
        }
        let Some(request) =
            internal_background_move_request(&snapshot.sources, &target, target_tab_id)
        else {
            return;
        };
        if self.pending_native_drag.as_ref().is_some_and(|pending| {
            pending.view_id == source_view_entity_id
                && pending.session_id == snapshot.session_id
                && pending.admitted_local_move.is_some()
        }) || !self.consume_internal_move_session(source_view_entity_id, snapshot.session_id)
        {
            return;
        }
        self.cancel_native_drag_candidate_for(
            source_view_entity_id,
            Some(snapshot.session_id),
            cx,
        );
        let paths = request.sources.clone();
        if let Err(action) = self
            .native_drag_pin_drains
            .defer(DeferredNativeAction::Submit(request), paths)
        {
            self.process_deferred_native_action(action, cx);
        }
    }

    fn pane_tab_presentation(&mut self, pane_id: PaneId) -> &mut PaneTabPresentation {
        self.pane_tab_presentations
            .entry(WorkspacePaneId {
                workspace: self.workspace.active,
                pane: pane_id,
            })
            .or_default()
    }

    fn schedule_active_tab_reveal(
        &mut self,
        pane_id: PaneId,
        active_tab_id: usize,
        group_height: Pixels,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let workspace_id = self.workspace.active;
        let group_height_bits = group_height.as_f32().to_bits();
        let presentation = self.pane_tab_presentation(pane_id);
        let active_changed = presentation.last_requested_active_tab_id != Some(active_tab_id);
        let group_height_changed =
            presentation.last_requested_group_height_bits != Some(group_height_bits);
        if !active_changed && !group_height_changed {
            return;
        }
        presentation.last_requested_active_tab_id = Some(active_tab_id);
        presentation.last_requested_group_height_bits = Some(group_height_bits);

        let shell = cx.entity().downgrade();
        window.on_next_frame(move |_, cx| {
            let _ = shell.update(cx, |this, cx| {
                if this.workspace.active != workspace_id {
                    return;
                }
                if this
                    .pane_tab_presentation(pane_id)
                    .last_requested_group_height_bits
                    != Some(group_height_bits)
                {
                    return;
                }
                let active_index = this.workspace.active().directory_pane(pane_id).and_then(|pane| {
                    (pane.active_tab_id == active_tab_id)
                        .then(|| pane.tabs.iter().position(|tab| tab.id == active_tab_id))
                        .flatten()
                });
                let Some(index) = active_index else {
                    return;
                };
                if active_changed || group_height_changed {
                    this.pane_tab_presentation(pane_id)
                        .scroll
                        .scroll_to_item(vertical_tab_scroll_child_index(index));
                }
                if this.workspace.active().focused_pane_id == pane_id {
                    if let Some(index) = this
                        .workspace
                        .active()
                        .panes
                        .iter()
                        .position(|pane| pane.id == pane_id)
                    {
                        this.pane_rail_scroll.scroll_to_item(index);
                    }
                }
                cx.notify();
            });
        });
    }

    fn pane_tab_group_height(
        &self,
        tabs: &[TabLabel],
        active_tab_id: usize,
        minimum_height: f32,
        window: &Window,
    ) -> Pixels {
        let window_height = window.bounds().size.height.as_f32();
        let notice_row_count = usize::from(self.session_notice.is_some())
            + usize::from(self.journal_startup_notice.is_some())
            + usize::from(self.operation_notice.is_some());
        let notice_height = notice_row_count as f32 * NOTICE_ROW_HEIGHT
            + if self.recovery_records.is_empty() {
                0.0
            } else {
                RECOVERY_NOTICE_ROW_HEIGHT
                    + 72.0 * MAX_VISIBLE_RECOVERY_RECORDS as f32
                    + 52.0
                    + if self.recovery_expanded.is_some() {
                        120.0
                    } else {
                        0.0
                    }
            };
        let estimated_rail_height =
            (window_height - titlebar::HEIGHT - notice_height - 44.0).max(0.0);
        let measured_rail_height = self.pane_rail_scroll.bounds().size.height.as_f32();
        let maximum_height = if measured_rail_height > 0.0 {
            // ScrollHandleの実測値を使いつつ、resize直後に前frameの値が残っても
            // windowとnoticeから求めた現在の上限より大きくならないようにする。
            measured_rail_height.min(estimated_rail_height)
        } else {
            estimated_rail_height
        };
        VerticalTabs::group_height_for_pinned_and_active(
            tabs,
            active_tab_id,
            minimum_height,
            maximum_height,
            self.workspace.active().pane_layout.pane_ids().len() > 1,
        )
    }
}

