/// Transfer rate is a disposable shell projection, not operation state.  The
/// operation owner remains authoritative for the byte counter and lifecycle;
/// this short history only turns accepted progress into a readable rate.
fn format_operation_bytes(bytes: u64) -> String {
    const UNITS: [&str; 4] = ["B", "KB", "MB", "GB"];
    let mut value = bytes as f64;
    let mut unit = 0;
    while value >= 1024.0 && unit + 1 < UNITS.len() {
        value /= 1024.0;
        unit += 1;
    }
    if unit == 0 {
        format!("{bytes} B")
    } else {
        format!("{value:.1} {}", UNITS[unit])
    }
}

