fn session_close_snapshots_match(left: &SessionSnapshot, right: &SessionSnapshot) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.write_revision = 0;
    right.write_revision = 0;
    left == right
}

fn workspace_transfer_snapshot(
    snapshot: &SessionSnapshot,
    source_window: u64,
    source_workspace: WorkspaceId,
    source_order: &[WorkspaceId],
    destination_window: u64,
    target_workspace: WorkspaceId,
    destination_order: &[WorkspaceId],
) -> Result<SessionSnapshot, String> {
    let mut snapshot = snapshot.clone();
    let source_index = snapshot
        .windows
        .iter()
        .position(|window| window.id == source_window)
        .ok_or_else(|| "workspace transfer source window is missing".to_owned())?;
    let destination_index = snapshot
        .windows
        .iter()
        .position(|window| window.id == destination_window)
        .ok_or_else(|| "workspace transfer destination window is missing".to_owned())?;
    if source_index == destination_index {
        return Err("workspace transfer route resolved to one window".into());
    }
    let actual_source_order = snapshot.windows[source_index]
        .workspaces
        .iter()
        .map(|workspace| NonZeroU64::new(workspace.id).map(WorkspaceId).ok_or(()))
        .collect::<Result<Vec<_>, ()>>()
        .map_err(|_| "workspace transfer snapshot has a zero workspace ID".to_owned())?;
    let actual_destination_order = snapshot.windows[destination_index]
        .workspaces
        .iter()
        .map(|workspace| NonZeroU64::new(workspace.id).map(WorkspaceId).ok_or(()))
        .collect::<Result<Vec<_>, ()>>()
        .map_err(|_| "workspace transfer snapshot has a zero workspace ID".to_owned())?;
    if actual_source_order != source_order || actual_destination_order != destination_order {
        return Err("workspace collection order changed during transfer".into());
    }
    let source_workspace_index = snapshot.windows[source_index]
        .workspaces
        .iter()
        .position(|workspace| workspace.id == source_workspace.value())
        .ok_or_else(|| "workspace transfer source member is missing".to_owned())?;
    if !snapshot.windows[destination_index]
        .workspaces
        .iter()
        .any(|workspace| workspace.id == target_workspace.value())
    {
        return Err("workspace transfer target member is missing".into());
    }
    let workspace = snapshot.windows[source_index]
        .workspaces
        .remove(source_workspace_index);
    let destination = &mut snapshot.windows[destination_index];
    let target_index = destination
        .workspaces
        .iter()
        .position(|workspace| workspace.id == target_workspace.value())
        .ok_or_else(|| "workspace transfer target member is missing".to_owned())?;
    destination.workspaces.insert(target_index, workspace);
    destination.active_workspace = source_workspace.value();

    if snapshot.windows[source_index].workspaces.is_empty() {
        snapshot.windows.remove(source_index);
    } else {
        let source = &mut snapshot.windows[source_index];
        if source.active_workspace == source_workspace.value() {
            source.active_workspace =
                source.workspaces[source_workspace_index.min(source.workspaces.len() - 1)].id;
        }
    }
    snapshot.active_window = destination_window;
    snapshot.validate().map_err(|error| error.to_string())?;
    Ok(snapshot)
}

const MAX_QUEUED_SHORTCUT_ICON_KEYS: usize = 32;

struct ShortcutIconSubscriber {
    view: gpui::WeakEntity<DirectoryListDemo>,
    view_id: gpui::EntityId,
    tab_id: usize,
    target: crate::file_info_shortcut::Target,
    request_ticket: u64,
    source_generation: u64,
}

struct ShortcutIconRequest {
    source: crate::file_info_shortcut::Target,
    subscribers: Vec<ShortcutIconSubscriber>,
}

fn same_shortcut_source(
    first: &crate::file_info_shortcut::Target,
    second: &crate::file_info_shortcut::Target,
) -> bool {
    first.path == second.path
        && first.source_identity == second.source_identity
        && first.size == second.size
        && first.modified == second.modified
}

fn add_shortcut_icon_subscriber(
    request: &mut ShortcutIconRequest,
    subscriber: ShortcutIconSubscriber,
) {
    if request.subscribers.iter().any(|existing| {
        existing.view_id == subscriber.view_id
            && existing.request_ticket == subscriber.request_ticket
    }) {
        return;
    }
    request.subscribers.push(subscriber);
}

