    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires distinct local fixed NTFS C: and E: fixtures"]
    fn ordinary_cross_volume_file_move_synthesizes_unknown_after_suppressed_terminal(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::path::{Component, Prefix};
        use std::time::{Duration, Instant};

        initialize_directory_binding_test_globals(cx);
        let volume = std::env::temp_dir();
        let destination_volume = std::env::var_os("GPUI_FILER_CROSS_VOLUME_TEST_ROOT")
            .map(PathBuf::from)
            .filter(|path| path.is_absolute())
            .expect(r"GPUI_FILER_CROSS_VOLUME_TEST_ROOT must name E:\Temp");
        let drive_letter = |path: &std::path::Path| {
            let Some(Component::Prefix(prefix)) = path.components().next() else {
                panic!("fixture path must have a drive prefix");
            };
            let (Prefix::Disk(letter) | Prefix::VerbatimDisk(letter)) = prefix.kind() else {
                panic!("fixture path must have a drive prefix");
            };
            letter.to_ascii_uppercase()
        };
        let source_letter = drive_letter(&volume);
        let destination_letter = drive_letter(&destination_volume);
        assert_ne!(
            source_letter, destination_letter,
            "cross-volume fixture must use distinct drives"
        );
        let fixed_ntfs = |letter: u8| {
            let drive = format!("{}:\\", letter as char);
            let drive_wide = drive.encode_utf16().chain([0]).collect::<Vec<_>>();
            let mut filesystem = [0u16; 32];
            unsafe {
                windows::Win32::Storage::FileSystem::GetDriveTypeW(windows::core::PCWSTR(
                    drive_wide.as_ptr(),
                )) == 3
                    && windows::Win32::Storage::FileSystem::GetVolumeInformationW(
                        windows::core::PCWSTR(drive_wide.as_ptr()),
                        None,
                        None,
                        None,
                        None,
                        Some(&mut filesystem),
                    )
                    .is_ok()
                    && String::from_utf16_lossy(&filesystem)
                        .trim_end_matches('\0')
                        .eq_ignore_ascii_case("NTFS")
            }
        };
        assert!(
            fixed_ntfs(source_letter),
            "source fixture requires fixed NTFS"
        );
        assert!(
            fixed_ntfs(destination_letter),
            "destination fixture requires fixed NTFS"
        );

        let source_temp = tempfile::Builder::new()
            .prefix("gpui-filer-move-source-")
            .tempdir_in(&volume)
            .unwrap();
        let destination_temp = tempfile::Builder::new()
            .prefix("gpui-filer-move-destination-")
            .tempdir_in(&destination_volume)
            .unwrap();
        let source_dir = source_temp.path().join("source");
        std::fs::create_dir(&source_dir).unwrap();
        let destination_dir = destination_temp.path().to_path_buf();
        let source = source_dir.join("payload.bin");
        let destination = destination_dir.join("payload.bin");
        let bytes = b"real cross-volume Move with missing terminal".repeat(64);
        std::fs::write(&source, &bytes).unwrap();
        let source_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &source,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity();

        let journal_path = source_temp.path().join("journal-v1.json");
        let store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        cx.update(|cx| {
            cx.set_global(
                operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    store,
                ),
            )
        });
        let real_writer = cx.update(|cx| {
            cx.global::<operations::application::OperationApplicationOwner>()
                .journal
                .clone()
                .expect("owner starts real JournalWriter")
        });
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let (test_writer, driver) = operations::journal::JournalWriter::test_driver();
        visual.update(|_, cx| {
            cx.update_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner.journal = Some(test_writer)
            })
        });

        let (terminal_tx, terminal_rx) = async_channel::bounded(1);
        let (start_tx, start_rx) = std::sync::mpsc::sync_channel(1);
        let (release_tx, release_rx) = std::sync::mpsc::sync_channel(1);
        struct SendOnDrop(Option<std::sync::mpsc::SyncSender<()>>);
        impl Drop for SendOnDrop {
            fn drop(&mut self) {
                if let Some(sender) = self.0.take() {
                    let _ = sender.send(());
                }
            }
        }
        let mut start_guard = SendOnDrop(Some(start_tx));
        let mut release_guard = SendOnDrop(Some(release_tx));
        let (sender_closed_tx, sender_closed_rx) = async_channel::bounded(1);
        let (returned_tx, returned_rx) = async_channel::bounded(1);
        let (joined_tx, joined_rx) = async_channel::bounded(1);
        let mut token = None;
        visual.update(|_, cx| {
            shell.update(cx, |this, cx| {
                cx.background_executor().allow_parking();
                let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
                let mut request = copy_request(
                    source.to_string_lossy().as_ref(),
                    destination_dir.to_string_lossy().as_ref(),
                );
                request.kind = OperationKind::Move;
                let submitted = owner.runtime.submit(request).unwrap();
                token = Some(submitted);
                owner.configure_worker_pump_test(move |worker, fact_sender| {
                    let start_rx = start_rx;
                    let release_rx = release_rx;
                    let sender_closed_tx = sender_closed_tx;
                    let worker_returned_tx = returned_tx;
                    let (command, cancellation, controls, lease) = (
                        worker.command,
                        worker.cancellation,
                        worker.controls,
                        worker.source_cleanup_lease,
                    );
                    let thread = std::thread::spawn(move || {
                        start_rx.recv().expect("Running record ACK releases worker");
                        executor::execute_prepare_with_source_cleanup_lease(
                            command,
                            cancellation.as_ref(),
                            &controls,
                            lease,
                            |fact| match fact {
                                executor::ExecutorFact::Terminal { token, report } => {
                                    terminal_tx.try_send((token, report)).unwrap();
                                }
                                fact => fact_sender.publish(fact),
                            },
                        );
                        drop(fact_sender);
                        sender_closed_tx.try_send(()).unwrap();
                        release_rx
                            .recv()
                            .expect("RAII gate releases native worker return");
                        worker_returned_tx.try_send(()).unwrap();
                    });
                    Box::pin(async move {
                        returned_rx
                            .recv()
                            .await
                            .expect("native Move worker returned");
                        thread.join().expect("ordinary Move worker did not panic");
                        joined_tx.try_send(()).unwrap();
                    })
                });
                this.start_next_operation(cx);
            })
        });
        let token = token.expect("Move admitted");

        let running_deadline = Instant::now() + Duration::from_secs(30);
        let running = loop {
            visual.run_until_parked();
            if let Some(operations::journal::JournalWriterCommandForTest::UnacknowledgedUpsert(
                attempt,
            )) = driver.try_command()
            {
                if attempt.state == operations::journal::JournalState::Running {
                    break attempt;
                }
            }
            assert!(
                Instant::now() < running_deadline,
                "Shell did not submit Running"
            );
            std::thread::sleep(Duration::from_millis(1));
        };
        let ack = real_writer.upsert_with_reply(running.clone());
        let ack_deadline = Instant::now() + Duration::from_secs(15);
        loop {
            match ack.try_recv() {
                Ok(Ok(())) => break,
                Ok(Err(error)) => panic!("real Running write failed: {error}"),
                Err(async_channel::TryRecvError::Closed) => panic!("Running ACK closed"),
                Err(async_channel::TryRecvError::Empty) => {}
            }
            assert!(Instant::now() < ack_deadline, "Running ACK timed out");
            std::thread::sleep(Duration::from_millis(1));
        }
        start_guard.0.take().unwrap().send(()).unwrap();
        let terminal_deadline = Instant::now() + Duration::from_secs(30);
        let (actual_token, actual_report) = loop {
            visual.run_until_parked();
            if let Ok(value) = terminal_rx.try_recv() {
                break value;
            }
            assert!(
                Instant::now() < terminal_deadline,
                "executor did not produce terminal"
            );
            std::thread::sleep(Duration::from_millis(1));
        };
        assert_eq!(actual_token, token);
        assert_eq!(
            actual_report.outcome,
            operations::model::TerminalOutcome::Succeeded
        );
        let sender_closed_deadline = Instant::now() + Duration::from_secs(15);
        loop {
            match sender_closed_rx.try_recv() {
                Ok(()) => break,
                Err(async_channel::TryRecvError::Closed) => panic!("sender-closed signal closed"),
                Err(async_channel::TryRecvError::Empty) => {}
            }
            assert!(
                Instant::now() < sender_closed_deadline,
                "executor fact sender did not close"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        visual.run_until_parked();
        let held_attempt = visual.read_entity(&shell, |_, cx| {
            cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner
                    .runtime
                    .job(token)
                    .unwrap()
                    .attempts
                    .into_iter()
                    .find(|attempt| attempt.token == token)
                    .unwrap()
            })
        });
        assert_eq!(held_attempt.state, operations::model::AttemptState::Running);
        assert!(held_attempt.terminal.is_none());
        assert!(
            driver.try_command().is_none(),
            "Shell emits no terminal journal command while native return is held"
        );
        assert_eq!(std::fs::read(&destination).unwrap(), bytes);
        assert!(!source.exists());
        assert_ne!(
            crate::directory::EntrySourceIdentity::from_path_no_follow(
                &destination,
                crate::directory::EntryKind::File
            )
            .unwrap()
            .filesystem_identity(),
            source_identity,
            "cross-volume copy-and-delete publishes a distinct file identity"
        );

        release_guard.0.take().unwrap().send(()).unwrap();
        let unknown_deadline = Instant::now() + Duration::from_secs(30);
        let unknown = loop {
            visual.run_until_parked();
            if let Some(operations::journal::JournalWriterCommandForTest::Upsert(upsert)) =
                driver.try_command()
            {
                if upsert.attempt.key == running.key
                    && upsert.attempt.state == operations::journal::JournalState::Terminal
                {
                    break upsert;
                }
            }
            assert!(
                Instant::now() < unknown_deadline,
                "Shell did not synthesize terminal Unknown after join"
            );
            std::thread::sleep(Duration::from_millis(1));
        };
        assert_eq!(
            unknown.attempt.terminal_outcome,
            Some(operations::journal::JournalTerminalOutcome::Unknown)
        );
        assert_eq!(unknown.attempt.kind, operations::journal::JournalKind::Move);
        assert_eq!(
            unknown.attempt.state,
            operations::journal::JournalState::Terminal
        );
        joined_rx
            .try_recv()
            .expect("native worker join precedes synthesized Unknown");
        let runtime_terminal = visual.read_entity(&shell, |_, cx| {
            cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner
                    .runtime
                    .job(token)
                    .unwrap()
                    .attempts
                    .into_iter()
                    .find(|attempt| attempt.token == token)
                    .unwrap()
                    .terminal
                    .unwrap()
            })
        });
        assert_eq!(
            runtime_terminal.outcome,
            operations::model::TerminalOutcome::Unknown
        );
        assert!(matches!(
            runtime_terminal.retry,
            operations::model::RetryPlan::RequiresReinspection
        ));
        assert!(
            runtime_terminal.receipts.is_empty(),
            "Unknown must not fabricate an undo receipt"
        );
        let accepted_counters = held_attempt
            .progress
            .as_ref()
            .map(|progress| progress.counters)
            .unwrap_or_default();
        assert!(
            held_attempt.progress.is_some(),
            "cross-volume Move reports progress facts"
        );
        assert_eq!(runtime_terminal.final_counters, accepted_counters);
        assert_eq!(
            runtime_terminal
                .change_hints
                .iter()
                .map(|hint| hint.directory.clone())
                .collect::<Vec<_>>(),
            [source_dir.clone(), destination_dir.clone()]
        );
        let shell_terminal_candidate = visual.read_entity(&shell, |_, cx| {
            cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner.runtime.journal_attempt(token).unwrap()
            })
        });
        assert_eq!(unknown.attempt, shell_terminal_candidate);
        let expected_unknown = unknown.attempt.clone();
        let unknown_key = expected_unknown.key.clone();
        let durable = real_writer.upsert_with_reply(unknown.attempt.clone());
        let durable_deadline = Instant::now() + Duration::from_secs(15);
        loop {
            match durable.try_recv() {
                Ok(Ok(())) => break,
                Ok(Err(error)) => panic!("real Unknown write failed: {error}"),
                Err(async_channel::TryRecvError::Closed) => panic!("Unknown ACK closed"),
                Err(async_channel::TryRecvError::Empty) => {}
            }
            assert!(Instant::now() < durable_deadline, "Unknown ACK timed out");
            std::thread::sleep(Duration::from_millis(1));
        }
        visual.run_until_parked();
        assert!(
            visual.read_entity(&shell, |shell, cx| shell
                .operation_worker_claimed_for_test(cx)),
            "durable Unknown remains pending until Shell receives its ACK"
        );
        unknown.reply(Ok(()));
        let lane_deadline = Instant::now() + Duration::from_secs(20);
        while visual.read_entity(&shell, |shell, cx| {
            shell.operation_worker_claimed_for_test(cx)
        }) {
            visual.run_until_parked();
            assert!(
                Instant::now() < lane_deadline,
                "worker lane did not release"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        let reopened = operations::journal::JournalStore::open(journal_path).unwrap();
        let durable = serde_json::from_slice::<serde_json::Value>(
            &std::fs::read(source_temp.path().join("journal-v1.json")).unwrap(),
        )
        .unwrap();
        assert!(
            durable["attempts"]
                .as_array()
                .unwrap()
                .contains(&serde_json::to_value(&expected_unknown).unwrap())
        );
        assert_eq!(reopened.attempt_keys(), [unknown_key]);
        assert!(
            reopened.recoveries().is_empty(),
            "terminal Unknown is not replayed as Running recovery"
        );
        assert!(!source.exists());
        assert_eq!(std::fs::read(&destination).unwrap(), bytes);
        assert_eq!(std::fs::read_dir(&source_dir).unwrap().count(), 0);
        assert_eq!(std::fs::read_dir(&destination_dir).unwrap().count(), 1);
    }

