            assert_eq!(lane_a_running.key, visual.update(|_, cx| cx
                .global::<operations::application::OperationApplicationOwner>()
                .runtime.journal_attempt(lane_a_token).unwrap().key));
            let lane_a_key = lane_a_running.key.clone();
            persist_attempt(&real_writer, lane_a_running)
                .expect("lane A Running record is durable before execution");
            lane_a_start_tx.send_blocking(()).unwrap();
            let lane_a_terminal_deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
            let mut lane_a_terminal_durable = false;
