                        assert!(visual.update(|_, cx| cx
                            .global::<operations::application::OperationApplicationOwner>()
                            .runtime.job(cleanup_token).unwrap().attempts.last().unwrap().terminal.is_none()));
                        assert!(cleanup_started_rx.try_recv().is_err(), "cancellation still precedes executor entry");
