    #[cfg(windows)]
    fn run_shell_cross_volume_move_batch_undo(cx: &mut gpui::TestAppContext, inject_partial_restore: bool, inject_partial_forward: bool) {
        initialize_directory_binding_test_globals(cx);
        let source_root = tempfile::Builder::new().prefix("gpui-filer-shell-cross-batch-source-")
            .tempdir_in(env!("CARGO_MANIFEST_DIR")).expect("fixed source-volume fixture");
        let destination_volume = std::env::var_os("GPUI_FILER_CROSS_VOLUME_TEST_ROOT")
            .map(std::path::PathBuf::from).expect("selector requires GPUI_FILER_CROSS_VOLUME_TEST_ROOT");
        let destination_root = tempfile::Builder::new().prefix("gpui-filer-shell-cross-batch-destination-")
            .tempdir_in(&destination_volume).expect("destination-volume fixture");
        let source_parent = source_root.path().join("source-parent");
        let destination_parent = destination_root.path().join("destination-parent");
        std::fs::create_dir(&source_parent).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        let names = ["batch-a.bin", "batch-b.bin", "batch-c.bin"];
        let bytes: [&[u8]; 3] = [b"cross volume A", b"cross volume B", b"cross volume C"];
        let sources = names.iter().map(|name| source_parent.join(name)).collect::<Vec<_>>();
        let destinations = names.iter().map(|name| destination_parent.join(name)).collect::<Vec<_>>();
        for (path, data) in sources.iter().zip(bytes) { std::fs::write(path, data).unwrap(); }
        let source_identity = crate::directory::EntrySourceIdentity::from_path(&sources[0], crate::directory::EntryKind::File)
            .unwrap().filesystem_identity();
        let destination_parent_identity = crate::directory::EntrySourceIdentity::from_path(&destination_parent, crate::directory::EntryKind::Folder)
            .unwrap().filesystem_identity();
        assert_ne!(source_identity.windows_parts().unwrap().0, destination_parent_identity.windows_parts().unwrap().0,
            "the selector must use distinct volumes");

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| FilerShell::new(persistence::Startup::disabled(), Arc::new(input::KeymapRuntime::new()), Vec::new(), cx));
            SearchShellRoot { shell }
        });
        let shell = visual.read_entity(&harness, |root, _| root.shell.clone());
        let (source_view, source_tab, destination_view, destination_tab) = visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let pane = shell.workspace.active().focused_pane_id;
                shell.add_tab_in(pane, Some(Location::Path(source_parent.clone())), cx);
                shell.add_tab_in(pane, Some(Location::Path(destination_parent.clone())), cx);
                let mut source = None;
                let mut destination = None;
                for tab in shell.workspace.active().tabs() {
                    match tab.view.read(cx).location().as_ref().and_then(Location::path) {
                        Some(path) if path == source_parent.as_path() => source = Some((tab.view.clone(), tab.id)),
                        Some(path) if path == destination_parent.as_path() => destination = Some((tab.view.clone(), tab.id)),
                        _ => {}
                    }
                }
                let (source_view, source_tab) = source.unwrap();
                let (destination_view, destination_tab) = destination.unwrap();
                (source_view, source_tab, destination_view, destination_tab)
            })
        });
        visual.update(|_, cx| {
            source_view.update(cx, |view, cx| view.refresh_listing(cx));
            destination_view.update(cx, |view, cx| view.refresh_listing(cx));
        });
        let ready_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        for tab_id in [source_tab, destination_tab] {
            visual.update(|_, cx| shell.update(cx, |shell, cx| {
                let workspace = shell.workspace.active;
                let pane = shell.workspace.active().focused_pane_id;
                shell.handle_tab(workspace, pane, &TabIntent::Activate(tab_id), cx);
            }));
            let view = if tab_id == source_tab { &source_view } else { &destination_view };
            loop {
                visual.run_until_parked();
                if visual.read_entity(view, |view, _| view.session.accepted_scan_ticket().is_some()
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready) { break; }
                assert!(std::time::Instant::now() < ready_deadline, "cross-volume batch parent scan timed out");
                std::thread::sleep(std::time::Duration::from_millis(2));
            }
        }
        let source_scan_before = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
        let destination_scan_before = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
        let (token, worker) = visual.update(|_, cx| {
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            let mut request = copy_request(sources[0].to_string_lossy().as_ref(), destination_parent.to_string_lossy().as_ref());
            request.kind = OperationKind::Move;
            request.sources = if inject_partial_forward { sources[..2].to_vec() } else { sources.clone() };
            let token = owner.runtime.submit(request).unwrap();
            (token, owner.runtime.start_next().unwrap())
        });
        if inject_partial_forward {
            executor::fail_cross_volume_move_source_disposition_for_path_for_test(&sources[1]);
        }
        let mut facts = Vec::new();
        executor::execute_prepare(worker.command, worker.cancellation.as_ref(), &worker.controls, |fact| facts.push(fact));
        if inject_partial_forward {
            assert_eq!(facts.iter().filter(|fact| matches!(fact,
                executor::ExecutorFact::MoveUndoCandidate { token: actual, item, receipt }
                    if *actual == token && *item == operations::model::ItemId(0)
                        && receipt.source == sources[0] && receipt.destination == destinations[0]
                        && receipt.cross_volume_file.is_some())).count(), 1,
                "only completed A yields an exact cross-volume Undo candidate");
            assert!(facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::PublishedMoveSourceRetained { token: actual, proof }
                    if *actual == token && proof.item == operations::model::ItemId(1)
                        && proof.source == sources[1] && proof.destination == destinations[1])),
                "partial B reports exact published-destination/source-retained evidence");
            assert!(facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::Terminal { token: actual, report }
                    if *actual == token && report.outcome == operations::model::TerminalOutcome::Partial
                        && report.receipts.iter().any(|receipt| receipt.item == operations::model::ItemId(0)
                            && receipt.outcome == operations::model::ItemOutcome::Completed)
                        && report.receipts.iter().any(|receipt| receipt.item == operations::model::ItemId(1)
                            && receipt.outcome != operations::model::ItemOutcome::Completed))),
                "the actual executor terminal records Completed A and non-Completed B");
            let terminal_event = visual.update(|_, cx| {
                let runtime = &mut cx.global_mut::<operations::application::OperationApplicationOwner>().runtime;
                facts.into_iter().filter_map(|fact| runtime.commit_fact(fact).map(|commit| commit.event)).next()
                    .expect("Runtime accepts actual Partial batch terminal")
            });
            visual.read_entity(&shell, |_, cx| {
                let (attempt, (_, entries)) = cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                    (owner.runtime.job(token).unwrap().attempts.last().unwrap().clone(), owner.runtime.undo_snapshot_for_test())
                });
                let terminal = attempt.terminal.as_ref().expect("Runtime stores the accepted terminal");
                assert_eq!(terminal.outcome, operations::model::TerminalOutcome::Partial);
                assert!(terminal.receipts.iter().any(|receipt| receipt.item == operations::model::ItemId(0) && receipt.outcome == operations::model::ItemOutcome::Completed));
                assert!(terminal.receipts.iter().any(|receipt| receipt.item == operations::model::ItemId(1) && receipt.outcome != operations::model::ItemOutcome::Completed));
                assert!(matches!(entries.as_slice(), [operations::runtime::UndoEntry::Move(receipts)] if receipts.len() == 1
                    && receipts[0].source == sources[0] && receipts[0].destination == destinations[0]),
                    "Runtime admits only A's exact candidate: {entries:?}");
            });
            visual.update(|_, cx| shell.update(cx, |shell, cx| shell.reconcile_operation_terminal(terminal_event, cx)));
            assert!(!sources[0].exists() && sources[1].exists() && sources[2].exists()
                && destinations[0].exists() && destinations[1].exists() && !destinations[2].exists());
            assert_eq!(std::fs::read(&destinations[0]).unwrap(), bytes[0]);
            assert_eq!(std::fs::read(&sources[1]).unwrap(), bytes[1]);
            assert_eq!(std::fs::read(&destinations[1]).unwrap(), bytes[1]);
            let partial_source_identity = crate::directory::EntrySourceIdentity::from_path(&sources[1], crate::directory::EntryKind::File).unwrap().filesystem_identity();
            let partial_destination_identity = crate::directory::EntrySourceIdentity::from_path(&destinations[1], crate::directory::EntryKind::File).unwrap().filesystem_identity();
            let settle_deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
            for tab_id in [source_tab, destination_tab] {
                visual.update(|_, cx| shell.update(cx, |shell, cx| {
                    let workspace = shell.workspace.active;
                    let pane = shell.workspace.active().focused_pane_id;
                    shell.handle_tab(workspace, pane, &TabIntent::Activate(tab_id), cx);
                }));
            }
            loop {
                visual.run_until_parked();
                if visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.scan_id > source_scan_before && ticket.path == source_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready))
                    && visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.scan_id > destination_scan_before && ticket.path == destination_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready)) { break; }
                assert!(std::time::Instant::now() < settle_deadline, "Partial Move parent scans did not reconcile: source={:?}, destination={:?}",
                    visual.read_entity(&source_view, |view, _| (view.session.accepted_scan_ticket().map(|ticket| (ticket.scan_id, ticket.path.clone())), view.session.status().clone())),
                    visual.read_entity(&destination_view, |view, _| (view.session.accepted_scan_ticket().map(|ticket| (ticket.scan_id, ticket.path.clone())), view.session.status().clone())));
                std::thread::sleep(std::time::Duration::from_millis(2));
            }
            let partial_source_scan = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
            let partial_destination_scan = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
            visual.update(|window, cx| {
                assert!(destination_view.read(cx).is_focused_for_test(window));
                assert!(window.dispatch_keystroke(gpui::Keystroke::parse("ctrl-z").unwrap(), cx));
            });
            for tab_id in [source_tab, destination_tab] {
                visual.update(|_, cx| shell.update(cx, |shell, cx| {
                    let workspace = shell.workspace.active;
                    let pane = shell.workspace.active().focused_pane_id;
                    shell.handle_tab(workspace, pane, &TabIntent::Activate(tab_id), cx);
                }));
            }
            loop {
                visual.run_until_parked();
                let settled = visual.read_entity(&shell, |shell, cx| {
                    let (reserved, entries) = cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.undo_snapshot_for_test());
                    !reserved && entries.is_empty() && !shell.operation_worker_claimed_for_test(cx)
                });
                let a_restored = std::fs::read(&sources[0]).ok().as_deref() == Some(bytes[0]) && !destinations[0].exists();
                let b_unchanged = sources[2].exists() && !destinations[2].exists()
                    && std::fs::read(&sources[1]).ok().as_deref() == Some(bytes[1])
                    && std::fs::read(&destinations[1]).ok().as_deref() == Some(bytes[1])
                    && crate::directory::EntrySourceIdentity::from_path(&sources[1], crate::directory::EntryKind::File).is_some_and(|identity| identity.filesystem_identity() == partial_source_identity)
                    && crate::directory::EntrySourceIdentity::from_path(&destinations[1], crate::directory::EntryKind::File).is_some_and(|identity| identity.filesystem_identity() == partial_destination_identity);
                let source_fresh = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.scan_id > partial_source_scan && ticket.path == source_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready));
                let destination_fresh = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.scan_id > partial_destination_scan && ticket.path == destination_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready));
                if settled && a_restored && b_unchanged && source_fresh && destination_fresh { break; }
                assert!(std::time::Instant::now() < settle_deadline, "focused Ctrl+Z did not restore only A and reconcile both parents");
                std::thread::sleep(std::time::Duration::from_millis(2));
            }
            return;
        }
        for (index, (source, destination)) in sources.iter().zip(&destinations).enumerate() {
            assert!(facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::MoveUndoCandidate { token: actual, item, receipt }
                    if *actual == token && item.0 == index as u32 && receipt.cross_volume_file.is_some()
                        && &receipt.source == source && &receipt.destination == destination)),
                "executor returns each exact cross-volume Undo candidate");
        }
        let terminal_event = visual.update(|_, cx| {
            let runtime = &mut cx.global_mut::<operations::application::OperationApplicationOwner>().runtime;
            facts.into_iter().filter_map(|fact| runtime.commit_fact(fact).map(|commit| commit.event)).next()
                .expect("Runtime accepts exact batch terminal")
        });
        visual.read_entity(&shell, |_, cx| {
            let (_, entries) = cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.undo_snapshot_for_test());
            assert!(matches!(entries.as_slice(), [operations::runtime::UndoEntry::Move(receipts)] if receipts.len() == 3), "Runtime admits the exact three-item cross-volume group; entries={entries:?}");
        });
        visual.update(|_, cx| shell.update(cx, |shell, cx| shell.reconcile_operation_terminal(terminal_event, cx)));
        assert!(sources.iter().all(|source| !source.exists()));
        for (destination, data) in destinations.iter().zip(bytes) { assert_eq!(std::fs::read(destination).unwrap(), data); }

        let move_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        loop {
            visual.run_until_parked();
            let destination_visible = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > destination_scan_before && ticket.path == destination_parent
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready
                    && destinations.iter().all(|path| view.entries.iter().any(|entry| entry.path.as_deref() == Some(path.as_path())))));
            if destination_visible { break; }
            assert!(std::time::Instant::now() < move_deadline, "cross-volume batch destination did not reconcile");
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        let undo_source_scan_before = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
        let undo_destination_scan_before = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
        if inject_partial_restore {
            executor::fail_cross_volume_move_undo_destination_delete_after_successes_for_test(1);
        }
        visual.update(|window, cx| {
            assert!(destination_view.read(cx).is_focused_for_test(window));
            assert!(window.dispatch_keystroke(gpui::Keystroke::parse("ctrl-z").unwrap(), cx));
        });
        let settle_deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        loop {
            visual.run_until_parked();
            let (reserved, entries, lane) = visual.read_entity(&shell, |shell, cx| {
                let (reserved, entries) = cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.undo_snapshot_for_test());
                (reserved, entries, shell.operation_worker_claimed_for_test(cx))
            });
            let files_match = if inject_partial_restore {
                !sources[0].exists() && sources[1].exists() && sources[2].exists()
                    && destinations[0].exists() && destinations[1].exists() && !destinations[2].exists()
                    && bytes.iter().enumerate().all(|(index, data)| {
                        let path = if index == 2 { &sources[index] } else { &destinations[index] };
                        std::fs::read(path).ok().as_deref() == Some(*data)
                    })
            } else {
                sources.iter().zip(bytes).all(|(path, data)| std::fs::read(path).ok().as_deref() == Some(data))
                    && destinations.iter().all(|path| !path.exists())
            };
            let ledger_matches = if inject_partial_restore {
                matches!(entries.as_slice(), [operations::runtime::UndoEntry::Move(receipts)] if receipts.len() == 1 && receipts[0].source == sources[0])
            } else { entries.is_empty() };
            let source_fresh = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > undo_source_scan_before && ticket.path == source_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready));
            let destination_fresh = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > undo_destination_scan_before && ticket.path == destination_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready));
            let notice = !inject_partial_restore || visual.read_entity(&shell, |shell, _| shell.operation_notice.as_ref().is_some_and(|messages| messages.contains(&Message::UndoOperationPartial)));
            if !reserved && !lane && ledger_matches && files_match && source_fresh && destination_fresh && notice { break; }
            assert!(std::time::Instant::now() < settle_deadline, "batch inverse did not settle: ledger={ledger_matches}, files={files_match}, scans={source_fresh}/{destination_fresh}, fs={:?}/{:?}, source state={:?}, notice={notice}, lane={lane}",
                sources.iter().map(|path| (path.exists(), std::fs::read(path).ok())).collect::<Vec<_>>(),
                destinations.iter().map(|path| (path.exists(), std::fs::read(path).ok())).collect::<Vec<_>>(),
                visual.read_entity(&source_view, |view, _| (view.session.accepted_scan_ticket().map(|ticket| ticket.scan_id), view.session.status().clone())));
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        if inject_partial_restore {
            let second_source_scan = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
            let second_destination_scan = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
            visual.update(|window, cx| { assert!(window.dispatch_keystroke(gpui::Keystroke::parse("ctrl-z").unwrap(), cx)); });
            loop {
                visual.run_until_parked();
                let complete = visual.read_entity(&shell, |shell, cx| {
                    let (reserved, entries) = cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.undo_snapshot_for_test());
                    !reserved && entries.is_empty() && !shell.operation_worker_claimed_for_test(cx)
                }) && std::fs::read(&sources[0]).ok().as_deref() == Some(bytes[0]) && !destinations[0].exists()
                    && sources[1].exists() && destinations[1].exists() && sources[2].exists() && !destinations[2].exists()
                    && visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.scan_id > second_source_scan && view.session.status() == &crate::directory_session::ListingStatus::Ready))
                    && visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.scan_id > second_destination_scan && view.session.status() == &crate::directory_session::ListingStatus::Ready));
                if complete { break; }
                assert!(std::time::Instant::now() < settle_deadline, "second Ctrl+Z did not retry only retained A");
                std::thread::sleep(std::time::Duration::from_millis(2));
            }
        }
    }

    #[cfg(windows)]
    fn run_shell_cross_volume_move_undo(cx: &mut gpui::TestAppContext, inject_partial_restore: bool) {
        initialize_directory_binding_test_globals(cx);
        let source_root = tempfile::Builder::new().prefix("gpui-filer-shell-cross-undo-source-")
            .tempdir_in(env!("CARGO_MANIFEST_DIR")).expect("fixed source-volume fixture");
        let destination_volume = std::env::var_os("GPUI_FILER_CROSS_VOLUME_TEST_ROOT")
            .map(std::path::PathBuf::from)
            .expect("invoked selector requires GPUI_FILER_CROSS_VOLUME_TEST_ROOT");
        let destination_root = tempfile::Builder::new().prefix("gpui-filer-shell-cross-undo-destination-")
            .tempdir_in(&destination_volume).expect("destination-volume fixture");
        let source_parent = source_root.path().join("source-parent");
        let destination_parent = destination_root.path().join("destination-parent");
        std::fs::create_dir(&source_parent).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        let source = source_parent.join("cross-volume-item.bin");
        let destination = destination_parent.join("cross-volume-item.bin");
        let bytes = b"rendered cross-volume Move Undo";
        std::fs::write(&source, bytes).unwrap();
        let source_identity = crate::directory::EntrySourceIdentity::from_path(&source, crate::directory::EntryKind::File)
            .unwrap().filesystem_identity();
        let destination_parent_identity = crate::directory::EntrySourceIdentity::from_path(&destination_parent, crate::directory::EntryKind::Folder)
            .unwrap().filesystem_identity();
        assert_ne!(source_identity.windows_parts().unwrap().0, destination_parent_identity.windows_parts().unwrap().0,
            "the invoked selector must use different volumes");

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| FilerShell::new(
                persistence::Startup::disabled(), Arc::new(input::KeymapRuntime::new()), Vec::new(), cx,
            ));
            SearchShellRoot { shell }
        });
        let shell = visual.read_entity(&harness, |root, _| root.shell.clone());
        let (source_view, source_tab, destination_view, destination_tab) = visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let pane_id = shell.workspace.active().focused_pane_id;
                shell.add_tab_in(pane_id, Some(Location::Path(source_parent.clone())), cx);
                shell.add_tab_in(pane_id, Some(Location::Path(destination_parent.clone())), cx);
                let mut source = None;
                let mut destination = None;
                for tab in shell.workspace.active().tabs() {
                    match tab.view.read(cx).location().as_ref().and_then(Location::path) {
                        Some(path) if path == source_parent.as_path() => source = Some((tab.view.clone(), tab.id)),
                        Some(path) if path == destination_parent.as_path() => destination = Some((tab.view.clone(), tab.id)),
                        _ => {}
                    }
                }
                let (source_view, source_tab) = source.expect("source tab opened");
                let (destination_view, destination_tab) = destination.expect("destination tab opened");
                (source_view, source_tab, destination_view, destination_tab)
            })
        });
        visual.update(|_, cx| {
            source_view.update(cx, |view, cx| view.refresh_listing(cx));
            destination_view.update(cx, |view, cx| view.refresh_listing(cx));
        });
        let ready_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        for tab_id in [source_tab, destination_tab] {
            visual.update(|_, cx| shell.update(cx, |shell, cx| {
                let workspace_id = shell.workspace.active;
                let pane_id = shell.workspace.active().focused_pane_id;
                shell.handle_tab(workspace_id, pane_id, &TabIntent::Activate(tab_id), cx);
            }));
            let view = if tab_id == source_tab { &source_view } else { &destination_view };
            loop {
                visual.run_until_parked();
                if visual.read_entity(view, |view, _| view.session.accepted_scan_ticket().is_some()
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready) { break; }
                assert!(std::time::Instant::now() < ready_deadline, "cross-volume Undo parent scan timed out");
                std::thread::sleep(std::time::Duration::from_millis(2));
            }
        }
        let source_scan_before = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
        let destination_scan_before = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().unwrap().scan_id);
        let undo_events = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let events = Arc::clone(&undo_events);
        let _subscription = visual.update(|_, cx| cx.subscribe(&destination_view, move |_, event: &DirectoryEvent, _| {
            if matches!(event, DirectoryEvent::UndoFileOperation) { events.fetch_add(1, Ordering::AcqRel); }
        }));

        let (token, worker) = visual.update(|_, cx| {
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            let mut request = copy_request(source.to_string_lossy().as_ref(), destination_parent.to_string_lossy().as_ref());
            request.kind = OperationKind::Move;
            let token = owner.runtime.submit(request).unwrap();
            (token, owner.runtime.start_next().expect("cross-volume Move worker starts"))
        });
        let mut facts = Vec::new();
        executor::execute_prepare(worker.command, worker.cancellation.as_ref(), &worker.controls, |fact| facts.push(fact));
        assert!(facts.iter().any(|fact| matches!(fact,
            executor::ExecutorFact::MoveUndoCandidate { token: actual, item, receipt }
                if *actual == token && *item == operations::model::ItemId(0)
                    && receipt.cross_volume_file.is_some() && receipt.source == source && receipt.destination == destination)),
            "cross-volume Move worker returns its exact copied-object Undo proof");
        let terminal_event = visual.update(|_, cx| {
            let runtime = &mut cx.global_mut::<operations::application::OperationApplicationOwner>().runtime;
            facts.into_iter().filter_map(|fact| runtime.commit_fact(fact).map(|commit| commit.event)).next()
                .expect("Runtime accepts the exact Move terminal")
        });
        visual.update(|_, cx| shell.update(cx, |shell, cx| shell.reconcile_operation_terminal(terminal_event, cx)));
        assert!(!source.exists());
        assert_eq!(std::fs::read(&destination).unwrap(), bytes);

        let move_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        loop {
            visual.run_until_parked();
            let visible = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > destination_scan_before && ticket.path == destination_parent
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready
                    && view.entries.iter().any(|entry| entry.path.as_deref() == Some(destination.as_path()))));
            if visible { break; }
            assert!(std::time::Instant::now() < move_deadline, "cross-volume Move destination did not reconcile");
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        if inject_partial_restore {
            executor::fail_next_cross_volume_move_undo_destination_delete_for_test();
        }
        visual.update(|window, cx| {
            assert!(destination_view.read(cx).is_focused_for_test(window));
            assert!(window.dispatch_keystroke(gpui::Keystroke::parse("ctrl-z").unwrap(), cx));
        });
        let undo_deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        loop {
            visual.run_until_parked();
            let settled = visual.read_entity(&shell, |shell, cx| {
                let (reserved, entries) = cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.undo_snapshot_for_test());
                !reserved && entries.is_empty() && !shell.operation_worker_claimed_for_test(cx)
            });
            let restored = std::fs::read(&source).ok().as_deref() == Some(bytes)
                && if inject_partial_restore {
                    std::fs::read(&destination).ok().as_deref() == Some(bytes)
                } else {
                    !destination.exists()
                };
            let source_reconciled = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > source_scan_before && ticket.path == source_parent
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready
                    && view.entries.iter().any(|entry| entry.path.as_deref() == Some(source.as_path()))));
            let destination_reconciled = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > destination_scan_before && ticket.path == destination_parent
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready
                    && (inject_partial_restore
                        == view.entries.iter().any(|entry| entry.path.as_deref() == Some(destination.as_path())))));
            let notice_matches = !inject_partial_restore || visual.read_entity(&shell, |shell, _|
                shell.operation_notice.as_ref().is_some_and(|notices| notices.contains(&Message::UndoOperationPartial)));
            if settled && restored && source_reconciled && destination_reconciled && notice_matches { break; }
            assert!(std::time::Instant::now() < undo_deadline,
                "cross-volume Ctrl+Z did not settle with the expected outcome and notice: settled={settled}, restored={restored}, source_reconciled={source_reconciled}, destination_reconciled={destination_reconciled}, notice_matches={notice_matches}");
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        assert_eq!(undo_events.load(Ordering::Acquire), 1, "focused Ctrl+Z used the rendered DirectoryView route");
    }

    #[gpui::test]
    fn shell_move_undo_restores_exact_file_consumes_receipt_and_reconciles_both_parents(
        cx: &mut gpui::TestAppContext,
    ) {
        initialize_directory_binding_test_globals(cx);
        let temp = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
        let source_parent = temp.path().join("move-source-parent");
        let destination_parent = temp.path().join("move-destination-parent");
        let source = source_parent.join("move-item.bin");
        let destination = destination_parent.join("move-item.bin");
        let bytes = b"Shell routed Move Undo exact object";
        std::fs::create_dir(&source_parent).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        std::fs::write(&source, bytes).unwrap();
        let source_identity = crate::directory::EntrySourceIdentity::from_path(
            &source,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity();

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            SearchShellRoot { shell }
        });
        let shell = visual.read_entity(&harness, |root, _| root.shell.clone());
        let (source_view, source_tab, destination_view, destination_tab) = visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let pane_id = shell.workspace.active().focused_pane_id;
                shell.add_tab_in(
                    pane_id,
                    Some(Location::Path(source_parent.clone())),
                    cx,
                );
                shell.add_tab_in(
                    pane_id,
                    Some(Location::Path(destination_parent.clone())),
                    cx,
                );
                let mut source = None;
                let mut destination = None;
                for tab in shell.workspace.active().tabs() {
                    match tab
                        .view
                        .read(cx)
                        .location()
                        .as_ref()
                        .and_then(Location::path)
                    {
                        Some(path) if path == source_parent.as_path() => {
                            source = Some((tab.view.clone(), tab.id))
                        }
                        Some(path) if path == destination_parent.as_path() => {
                            destination = Some((tab.view.clone(), tab.id))
                        }
                        _ => {}
                    }
                }
                let (source_view, source_tab) = source.expect("Shell opened source parent");
                let (destination_view, destination_tab) =
                    destination.expect("Shell opened destination parent");
                (source_view, source_tab, destination_view, destination_tab)
            })
        });

        visual.update(|_, cx| {
            source_view.update(cx, |view, cx| view.refresh_listing(cx));
            destination_view.update(cx, |view, cx| view.refresh_listing(cx));
        });

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
        for tab_id in [source_tab, destination_tab] {
            visual.update(|_, cx| {
                shell.update(cx, |shell, cx| {
                    let workspace_id = shell.workspace.active;
                    let pane_id = shell.workspace.active().focused_pane_id;
                    shell.handle_tab(
                        workspace_id,
                        pane_id,
                        &TabIntent::Activate(tab_id),
                        cx,
                    );
                });
            });
            loop {
            visual.run_until_parked();
                let ready = visual.read_entity(
                    if tab_id == source_tab { &source_view } else { &destination_view },
                    |view, _| {
                        view.session.accepted_scan_ticket().is_some()
                            && view.session.status()
                                == &crate::directory_session::ListingStatus::Ready
                    },
                );
                if ready {
                    break;
                }
                assert!(std::time::Instant::now() < deadline, "parent view did not finish its baseline scan");
                std::thread::sleep(std::time::Duration::from_millis(2));
            }
        }
        let source_scan_before = visual.read_entity(&source_view, |view, _| {
            view.session.accepted_scan_ticket().unwrap().scan_id
        });
        let destination_scan_before = visual.read_entity(&destination_view, |view, _| {
            view.session.accepted_scan_ticket().unwrap().scan_id
        });
        let undo_events = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let undo_events_for_subscription = Arc::clone(&undo_events);
        let _undo_event_subscription = visual.update(|_, cx| {
            cx.subscribe(
                &destination_view,
                move |_, event: &DirectoryEvent, _| {
                    if matches!(event, DirectoryEvent::UndoFileOperation) {
                        undo_events_for_subscription.fetch_add(1, Ordering::AcqRel);
                    }
                },
            )
        });

        let (token, worker) = visual.update(|_, cx| {
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            let mut request = copy_request(
                source.to_string_lossy().as_ref(),
                destination_parent.to_string_lossy().as_ref(),
            );
            request.kind = OperationKind::Move;
            request.move_identity_guard = Some(operations::model::MoveIdentityGuard {

                source_identities: vec![source_identity.clone()],
                destination_identity: crate::directory::EntrySourceIdentity::from_path(
                    &destination_parent,
                    crate::directory::EntryKind::Folder,
                )
                .unwrap()
                .filesystem_identity(),
                });
            let token = owner.runtime.submit(request).unwrap();
            (token, owner.runtime.start_next().expect("guarded Move worker starts"))
        });
        let mut facts = Vec::new();
        executor::execute_prepare(
            worker.command,
            worker.cancellation.as_ref(),
            &worker.controls,
            |fact| facts.push(fact),
        );
        assert!(facts.iter().any(|fact| matches!(
            fact,
            executor::ExecutorFact::MoveUndoCandidate { token: actual, item, receipt }
                if *actual == token && *item == operations::model::ItemId(0)
                    && receipt.source == source && receipt.destination == destination
        )), "the real Move worker returns its exact mutation-time Undo proof: {facts:#?}");
        visual.update(|_, cx| {
            let terminal_event = {
                let runtime = &mut cx
                    .global_mut::<operations::application::OperationApplicationOwner>()
                    .runtime;
                let terminal_event = facts
                    .into_iter()
                    .filter_map(|fact| runtime.commit_fact(fact).map(|commit| commit.event))
                    .next()
                    .expect("Runtime accepts the exact Move terminal");
                let (reserved, entries) = runtime.undo_snapshot_for_test();
                assert!(!reserved);
                assert!(matches!(entries.as_slice(), [UndoEntry::Move(receipts)] if matches!(receipts.as_slice(), [receipt] if receipt.source == source && receipt.destination == destination)));
                terminal_event
            };
            shell.update(cx, |shell, cx| shell.reconcile_operation_terminal(terminal_event, cx));
        });
        assert!(!source.exists());
        assert_eq!(std::fs::read(&destination).unwrap(), bytes);

        let expected_move_receipt = visual.read_entity(&shell, |_, cx| {
            let (_, entries) = cx
                .read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                    owner.runtime.undo_snapshot_for_test()
                });
            match entries.as_slice() {
                [UndoEntry::Move(receipts)] => receipts[0].clone(),
                _ => panic!("the accepted Move contributes exactly one Undo receipt"),
            }
        });
        let move_listing_deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
        let destination_move_scan_id = loop {
            visual.run_until_parked();
            let visible_move = visual.read_entity(&destination_view, |view, _| {
                view.session.accepted_scan_ticket().is_some_and(|ticket| {
                    ticket.scan_id > destination_scan_before
                        && ticket.path == destination_parent
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && view.entries.iter().any(|entry| {
                            entry.path.as_deref() == Some(destination.as_path())
                                && entry.source_identity.as_ref().is_some_and(|identity| {
                                    identity.filesystem_identity() == source_identity
                                })
                        })
                })
            });
            if visible_move {
                break visual.read_entity(&destination_view, |view, _| {
                    view.session.accepted_scan_ticket().unwrap().scan_id
                });
            }
            assert!(
                std::time::Instant::now() < move_listing_deadline,
                "Move did not reconcile a newer Ready destination listing containing the moved identity"
            );
            std::thread::sleep(std::time::Duration::from_millis(2));
        };

        let original_occupant_bytes = b"original-name occupant";
        let second_candidate = source_parent.join("move-item (2).bin");
        let second_occupant_bytes = b"second-candidate occupant";
        std::fs::write(&source, original_occupant_bytes).unwrap();
        let last_candidate = source_parent.join("move-item (999).bin");
        let mut occupants = Vec::with_capacity(999);
        for (path, occupant_bytes) in [
            (source.clone(), original_occupant_bytes.to_vec()),
            (second_candidate.clone(), second_occupant_bytes.to_vec()),
        ] {
            std::fs::write(&path, &occupant_bytes).unwrap();
            let identity = crate::directory::EntrySourceIdentity::from_path(
                &path,
                crate::directory::EntryKind::File,
            )
            .unwrap()
            .filesystem_identity();
            occupants.push((path, occupant_bytes, identity));
        }
        for index in 3..=999 {
            let path = source_parent.join(format!("move-item ({index}).bin"));
            let occupant_bytes = format!("candidate occupant {index}").into_bytes();
            std::fs::write(&path, &occupant_bytes).unwrap();
            let identity = crate::directory::EntrySourceIdentity::from_path(
                &path,
                crate::directory::EntryKind::File,
            )
            .unwrap()
            .filesystem_identity();
            occupants.push((path, occupant_bytes, identity));
        }

        let destination_undo_scan_before = visual.read_entity(&destination_view, |view, _| {
            let ticket = view.session.accepted_scan_ticket().unwrap();
            assert!(ticket.scan_id >= destination_move_scan_id);
            assert_eq!(ticket.path, destination_parent);
            assert_eq!(view.session.status(), &crate::directory_session::ListingStatus::Ready);
            assert!(view.entries.iter().any(|entry| {
                entry.path.as_deref() == Some(destination.as_path())
                    && entry.source_identity.as_ref().is_some_and(|identity| {
                        identity.filesystem_identity() == source_identity
                    })
            }));
            ticket.scan_id
        });
        visual.update(|window, cx| {
            assert!(destination_view.read(cx).is_focused_for_test(window));
            assert!(window.dispatch_keystroke(gpui::Keystroke::parse("ctrl-z").unwrap(), cx));
        });
        visual.read_entity(&shell, |_shell, cx| {
            assert_eq!(undo_events.load(Ordering::Acquire), 1);
            let (reserved, receipts) = cx
                .read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                    owner.runtime.undo_snapshot_for_test()
                });
            assert!(reserved, "the failed attempt holds the exact Runtime receipt reservation");
            assert!(matches!(
                receipts.as_slice(),
                [UndoEntry::Move(receipts)] if receipts.as_slice() == [expected_move_receipt.clone()]
            ));
        });

        let failed_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        loop {
            visual.run_until_parked();
            let (reserved, receipts) = visual.read_entity(&shell, |_, cx| {
                let (reserved, receipts) = cx
                    .read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                        owner.runtime.undo_snapshot_for_test()
                    });
                (reserved, receipts)
            });
            let receipt_retained = !reserved
                && matches!(
                    receipts.as_slice(),
                    [UndoEntry::Move(receipts)] if receipts.as_slice() == [expected_move_receipt.clone()]
                );
            let occupants_unchanged = occupants.iter().all(|(path, expected_bytes, identity)| {
                std::fs::read(path).is_ok_and(|actual| actual == *expected_bytes)
                    && crate::directory::EntrySourceIdentity::from_path(
                        path,
                        crate::directory::EntryKind::File,
                    )
                    .is_some_and(|actual| actual.filesystem_identity() == *identity)
            });
            let moved_unchanged = std::fs::read(&destination).is_ok_and(|actual| actual == bytes)
                && crate::directory::EntrySourceIdentity::from_path(
                    &destination,
                    crate::directory::EntryKind::File,
                )
                .is_some_and(|actual| actual.filesystem_identity() == source_identity);
            if receipt_retained && occupants_unchanged && moved_unchanged {
                break;
            }
            assert!(
                std::time::Instant::now() < failed_deadline,
                "exhausted Move Undo did not retain its receipt and filesystem objects: reserved={reserved}, receipt_retained={receipt_retained}, occupants_unchanged={occupants_unchanged}, moved_unchanged={moved_unchanged}"
            );
            std::thread::sleep(std::time::Duration::from_millis(2));
        }

        let lane_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        while visual.read_entity(&shell, |shell, cx| shell.operation_worker_claimed_for_test(cx)) {
            visual.run_until_parked();
            assert!(std::time::Instant::now() < lane_deadline, "exhausted Undo did not release the Shell serial lane");
            std::thread::sleep(std::time::Duration::from_millis(2));
        }

        std::fs::remove_file(&last_candidate).unwrap();
        visual.update(|_, cx| {
            source_view.update(cx, |view, cx| view.refresh_listing(cx));
            destination_view.update(cx, |view, cx| view.refresh_listing(cx));
        });
        let retry_scan_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        let (source_retry_scan_before, destination_retry_scan_before) = loop {
            visual.run_until_parked();
            let source_scan = visual.read_entity(&source_view, |view, _| {
                view.session.accepted_scan_ticket().filter(|ticket| {
                    ticket.scan_id > source_scan_before
                        && ticket.path == source_parent
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && occupants.iter().filter(|(path, _, _)| path != &last_candidate).all(
                            |(path, _, identity)| {
                                view.entries.iter().any(|entry| {
                                    entry.path.as_deref() == Some(path.as_path())
                                        && entry.source_identity.as_ref().is_some_and(|actual| {
                                            actual.filesystem_identity() == *identity
                                        })
                                })
                            },
                        )
                        && !view.entries.iter().any(|entry| {
                            entry.path.as_deref() == Some(last_candidate.as_path())
                        })
                }).map(|ticket| ticket.scan_id)
            });
            let destination_scan = visual.read_entity(&destination_view, |view, _| {
                view.session.accepted_scan_ticket().filter(|ticket| {
                    ticket.scan_id >= destination_undo_scan_before
                        && ticket.path == destination_parent
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && view.entries.iter().any(|entry| {
                            entry.path.as_deref() == Some(destination.as_path())
                                && entry.source_identity.as_ref().is_some_and(|actual| {
                                    actual.filesystem_identity() == source_identity
                                })
                        })
                }).map(|ticket| ticket.scan_id)
            });
            if let (Some(source_scan), Some(destination_scan)) = (source_scan, destination_scan) {
                break (source_scan, destination_scan);
            }
            assert!(
                std::time::Instant::now() < retry_scan_deadline,
                "parent views did not accept the pre-retry filesystem state"
            );
            std::thread::sleep(std::time::Duration::from_millis(2));
        };

        visual.update(|window, cx| {
            assert!(destination_view.read(cx).is_focused_for_test(window));
            assert!(window.dispatch_keystroke(gpui::Keystroke::parse("ctrl-z").unwrap(), cx));
        });
        visual.read_entity(&shell, |_, cx| {
            assert_eq!(undo_events.load(Ordering::Acquire), 2);
            let (reserved, receipts) = cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.undo_snapshot_for_test());
            assert!(reserved, "the retry synchronously reserves the retained Move receipt");
            assert!(matches!(
                receipts.as_slice(),
                [UndoEntry::Move(receipts)] if receipts.as_slice() == [expected_move_receipt.clone()]
            ));
        });

        loop {
            visual.run_until_parked();
            let source_restored = last_candidate.exists()
                && crate::directory::EntrySourceIdentity::from_path(
                    &last_candidate,
                    crate::directory::EntryKind::File,
                )
                .is_some_and(|identity| identity.filesystem_identity() == source_identity)
                && std::fs::read(&last_candidate).is_ok_and(|contents| contents == bytes);
            let occupants_preserved = occupants.iter()
                .filter(|(path, _, _)| path != &last_candidate)
                .all(|(path, expected_bytes, expected_identity)| {
                    std::fs::read(path).is_ok_and(|actual| actual == *expected_bytes)
                        && crate::directory::EntrySourceIdentity::from_path(
                            path,
                            crate::directory::EntryKind::File,
                        )
                        .is_some_and(|actual| actual.filesystem_identity() == *expected_identity)
                });
            let dest_absent = !destination.exists();
            let undo_settled = visual.read_entity(&shell, |_, cx| {
                cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                    let (reserved, entries) = owner.runtime.undo_snapshot_for_test();
                    !reserved && entries.is_empty()
                })
            });
            let source_reconciled = visual.read_entity(&source_view, |view, _| {
                view.session.accepted_scan_ticket().is_some_and(|ticket| {
                    ticket.scan_id > source_scan_before
                        && ticket.scan_id > source_retry_scan_before
                        && ticket.path == source_parent
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && occupants.iter()
                            .filter(|(path, _, _)| path != &last_candidate)
                            .all(|(path, _, expected_identity)| {
                                view.entries.iter().any(|entry| {
                                    entry.path.as_deref() == Some(path.as_path())
                                        && entry.source_identity.as_ref().is_some_and(|actual| {
                                            actual.filesystem_identity() == *expected_identity
                                        })
                                })
                            })
                        && view.entries.iter().any(|entry| {
                            entry.path.as_deref() == Some(last_candidate.as_path())
                                && entry.source_identity.as_ref().is_some_and(|identity| {
                                    identity.filesystem_identity() == source_identity
                                })
                        })
                })
            });
            let destination_reconciled = visual.read_entity(&destination_view, |view, _| {
                view.session.accepted_scan_ticket().is_some_and(|ticket| {
                    ticket.scan_id > destination_retry_scan_before
                        && ticket.path == destination_parent
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && !view.entries.iter().any(|entry| entry.path.as_deref() == Some(destination.as_path()))
                })
            });
            let both_reconciled = source_reconciled && destination_reconciled;
            let lane_released = visual.read_entity(&shell, |shell, cx| {
                !shell.operation_worker_claimed_for_test(cx)
            });
            if source_restored && occupants_preserved && dest_absent && undo_settled && both_reconciled && lane_released {
                break;
            }
            assert!(std::time::Instant::now() < deadline, "Shell Move Undo retry did not restore, preserve occupants, consume, release lane, and reconcile: restored={source_restored}, occupants_preserved={occupants_preserved}, dest_absent={dest_absent}, settled={undo_settled}, lane_released={lane_released}, source_reconciled={source_reconciled}, destination_reconciled={destination_reconciled}; source_view={:?}, destination_view={:?}", visual.read_entity(&source_view, |view, _| (view.session.accepted_scan_ticket().cloned(), view.session.status().clone(), view.entries.iter().filter_map(|entry| entry.path.clone()).collect::<Vec<_>>())), visual.read_entity(&destination_view, |view, _| (view.session.accepted_scan_ticket().cloned(), view.session.status().clone(), view.entries.iter().filter_map(|entry| entry.path.clone()).collect::<Vec<_>>())));
            std::thread::sleep(std::time::Duration::from_millis(2));
        }

    }

    #[cfg(windows)]
    #[gpui::test]
    fn shell_directory_move_undo_refusal_retains_receipt_and_retry_reconciles_both_parents(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::os::windows::fs::OpenOptionsExt;
        use std::path::{Component, Prefix};
        use windows::Win32::Storage::FileSystem::{
            GetDriveTypeW, GetVolumeInformationW, FILE_FLAG_BACKUP_SEMANTICS, FILE_SHARE_READ,
            FILE_SHARE_WRITE,
        };
        initialize_directory_binding_test_globals(cx);
        let temp = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
        let prefix = temp.path().components().find_map(|component| match component {
            Component::Prefix(prefix) => Some(prefix),
            _ => None,
        }).expect("directory Undo fixture uses a drive path");
        let letter = match prefix.kind() {
            Prefix::Disk(letter) | Prefix::VerbatimDisk(letter) => letter,
            _ => panic!("directory Undo fixture requires a local fixed volume"),
        };
        let volume_root = format!("{}:\\", letter as char).encode_utf16().chain([0]).collect::<Vec<_>>();
        let mut filesystem = [0u16; 32];
        assert!(unsafe {
            GetDriveTypeW(windows::core::PCWSTR(volume_root.as_ptr())) == 3
                && GetVolumeInformationW(
                    windows::core::PCWSTR(volume_root.as_ptr()), None, None, None, None,
                    Some(&mut filesystem),
                ).is_ok()
                && String::from_utf16_lossy(&filesystem).trim_end_matches('\0').eq_ignore_ascii_case("NTFS")
        }, "directory Undo fixture requires fixed local NTFS");
        let source_parent = temp.path().join("directory-move-source-parent");
        let destination_parent = temp.path().join("directory-move-destination-parent");
        let source = source_parent.join("nested.dotted");
        let destination = destination_parent.join("nested.dotted");
        let child_dir = source.join("nested-child");
        let child_file = child_dir.join("payload.bin");
        let bytes = b"same-volume directory Move Undo payload";
        std::fs::create_dir(&source_parent).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        std::fs::create_dir_all(&child_dir).unwrap();
        std::fs::write(&child_file, bytes).unwrap();
        let root_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &source,
            crate::directory::EntryKind::Folder,
        ).unwrap();
        let child_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &source.join("nested-child"),
            crate::directory::EntryKind::Folder,
        ).unwrap();
        let file_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &child_file,
            crate::directory::EntryKind::File,
        ).unwrap();

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| FilerShell::new(
                persistence::Startup::disabled(),
                Arc::new(input::KeymapRuntime::new()),
                Vec::new(),
                cx,
            ));
            SearchShellRoot { shell }
        });
        let shell = visual.read_entity(&harness, |root, _| root.shell.clone());
        let (source_view, destination_view) = visual.update(|_, cx| shell.update(cx, |shell, cx| {
            let pane = shell.workspace.active().focused_pane_id;
            shell.add_tab_in(pane, Some(Location::Path(source_parent.clone())), cx);
            shell.add_tab_in(pane, Some(Location::Path(destination_parent.clone())), cx);
            let views = shell.workspace.active().tabs().filter_map(|tab| {
                let path = tab.view.read(cx).location().as_ref().and_then(Location::path)?.to_path_buf();
                Some((path, tab.view.clone()))
            }).collect::<Vec<_>>();
            (views.iter().find(|(path, _)| path == &source_parent).unwrap().1.clone(),
             views.iter().find(|(path, _)| path == &destination_parent).unwrap().1.clone())
        }));
        visual.update(|_, cx| {
            source_view.update(cx, |view, cx| view.refresh_listing(cx));
            destination_view.update(cx, |view, cx| view.refresh_listing(cx));
        });
        let baseline_deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
        let (source_scan_before, destination_scan_before) = loop {
            visual.run_until_parked();
            let source_scan = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket()
                .filter(|_| view.session.status() == &crate::directory_session::ListingStatus::Ready)
                .map(|ticket| ticket.scan_id));
            let destination_scan = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket()
                .filter(|_| view.session.status() == &crate::directory_session::ListingStatus::Ready)
                .map(|ticket| ticket.scan_id));
            if let (Some(source_scan), Some(destination_scan)) = (source_scan, destination_scan) {
                break (source_scan, destination_scan);
            }
            assert!(std::time::Instant::now() < baseline_deadline, "directory Move parent scans did not become Ready");
            std::thread::sleep(std::time::Duration::from_millis(2));
        };

        let (token, worker) = visual.update(|_, cx| {
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            let mut request = copy_request(source.to_string_lossy().as_ref(), destination_parent.to_string_lossy().as_ref());
            request.kind = OperationKind::Move;
            request.move_identity_guard = Some(operations::model::MoveIdentityGuard {

                source_identities: vec![root_identity.filesystem_identity()],
                destination_identity: crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination_parent, crate::directory::EntryKind::Folder,
                ).unwrap().filesystem_identity(),
                });
            let token = owner.runtime.submit(request).unwrap();
            (token, owner.runtime.start_next().expect("directory Move worker starts"))
        });
        let mut facts = Vec::new();
        executor::execute_prepare(worker.command, worker.cancellation.as_ref(), &worker.controls, |fact| facts.push(fact));
        assert!(facts.iter().any(|fact| matches!(fact,
            executor::ExecutorFact::MoveUndoCandidate { token: actual, receipt, .. }
                if *actual == token && receipt.object_kind == operations::model::MoveUndoObjectKind::Directory
                    && receipt.source == source && receipt.destination == destination
        )), "production directory Move returns the exact typed Undo proof");
        visual.update(|_, cx| {
            let terminal = {
                let runtime = &mut cx.global_mut::<operations::application::OperationApplicationOwner>().runtime;
                facts.into_iter().filter_map(|fact| runtime.commit_fact(fact).map(|commit| commit.event))
                    .last().expect("Runtime accepts directory Move terminal")
            };
            shell.update(cx, |shell, cx| shell.reconcile_operation_terminal(terminal, cx));
        });
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination, crate::directory::EntryKind::Folder,
        ), Some(root_identity.clone()));
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination.join("nested-child"), crate::directory::EntryKind::Folder,
        ), Some(child_identity.clone()));
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination.join("nested-child/payload.bin"), crate::directory::EntryKind::File,
        ), Some(file_identity.clone()));
        assert_eq!(std::fs::read(destination.join("nested-child/payload.bin")).unwrap(), bytes);
        let exact_receipt = visual.update(|_, cx| {
            let (_, entries) = cx.global::<operations::application::OperationApplicationOwner>().runtime.undo_snapshot_for_test();
            match entries.as_slice() {
                [UndoEntry::Move(receipts)] if receipts.len() == 1 => receipts[0].clone(),
                _ => panic!("one exact directory Move receipt is admitted"),
            }
        });

        let held_directory = std::fs::OpenOptions::new().read(true)
            .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0)
            .custom_flags(FILE_FLAG_BACKUP_SEMANTICS.0)
            .open(&destination).expect("hold destination directory without delete sharing");
        visual.update(|_, cx| shell.update(cx, |shell, cx| shell.undo_trash(cx)));
        let refusal_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        let (refusal_source_scan, refusal_destination_scan) = loop {
            visual.run_until_parked();
            let (reserved, entries) = visual.read_entity(&shell, |_, cx| cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.undo_snapshot_for_test()));
            let lane_released = visual.read_entity(&shell, |shell, cx| !shell.operation_worker_claimed_for_test(cx));
            let scans = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket()
                .filter(|ticket| ticket.path == source_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready)
                .map(|ticket| ticket.scan_id))
                .zip(visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket()
                    .filter(|ticket| ticket.path == destination_parent && view.session.status() == &crate::directory_session::ListingStatus::Ready)
                    .map(|ticket| ticket.scan_id)));
            if !reserved && lane_released && matches!(entries.as_slice(), [UndoEntry::Move(receipts)] if receipts.as_slice() == [exact_receipt.clone()]) {
                if let Some((source_scan, destination_scan)) = scans {
                    if source_scan > source_scan_before && destination_scan > destination_scan_before { break (source_scan, destination_scan); }
                }
            }
            assert!(std::time::Instant::now() < refusal_deadline, "directory Undo refusal did not retain receipt, release lane, and refresh both parents");
            std::thread::sleep(std::time::Duration::from_millis(2));
        };
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination, crate::directory::EntryKind::Folder,
        ), Some(root_identity.clone()));
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination.join("nested-child"), crate::directory::EntryKind::Folder,
        ), Some(child_identity.clone()));
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination.join("nested-child/payload.bin"), crate::directory::EntryKind::File,
        ), Some(file_identity.clone()));
        assert_eq!(std::fs::read(destination.join("nested-child/payload.bin")).unwrap(), bytes);
        assert!(!source.exists());
        drop(held_directory);

        visual.update(|_, cx| shell.update(cx, |shell, cx| shell.undo_trash(cx)));
        let retry_deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        loop {
            visual.run_until_parked();
            let restored = crate::directory::EntrySourceIdentity::from_path_no_follow(
                &source, crate::directory::EntryKind::Folder,
            ) == Some(root_identity.clone())
                && crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &source.join("nested-child"), crate::directory::EntryKind::Folder,
                ) == Some(child_identity.clone())
                && crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &source.join("nested-child/payload.bin"), crate::directory::EntryKind::File,
                ) == Some(file_identity.clone())
                && std::fs::read(source.join("nested-child/payload.bin")).ok().as_deref() == Some(bytes)
                && !destination.exists();
            let settled = visual.read_entity(&shell, |_, cx| cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                let (reserved, entries) = owner.runtime.undo_snapshot_for_test(); !reserved && entries.is_empty()
            }));
            let lane_released = visual.read_entity(&shell, |shell, cx| !shell.operation_worker_claimed_for_test(cx));
            let source_reconciled = visual.read_entity(&source_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > refusal_source_scan && ticket.path == source_parent
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready)
                && view.entries.iter().any(|entry| entry.path.as_deref() == Some(source.as_path())
                    && entry.source_identity.as_ref().is_some_and(|actual| actual.filesystem_identity() == root_identity.filesystem_identity())));
            let destination_reconciled = visual.read_entity(&destination_view, |view, _| view.session.accepted_scan_ticket().is_some_and(|ticket|
                ticket.scan_id > refusal_destination_scan && ticket.path == destination_parent
                    && view.session.status() == &crate::directory_session::ListingStatus::Ready)
                && !view.entries.iter().any(|entry| entry.path.as_deref() == Some(destination.as_path())));
            if restored && settled && lane_released && source_reconciled && destination_reconciled { break; }
            assert!(std::time::Instant::now() < retry_deadline, "directory Undo retry did not restore the exact root, consume receipt, release lane, and reconcile both parents");
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
    }

    #[cfg(windows)]
    #[gpui::test]
    fn shell_copy_undo_removes_the_exact_completed_output(cx: &mut gpui::TestAppContext) {
        initialize_directory_binding_test_globals(cx);
        let temp = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
        let source = temp.path().join("copy-source.bin");
        let destination = temp.path().join("destination");
        let copied = destination.join("copy-source.bin");
        let bytes = b"shell-routed Copy undo fixture";
        std::fs::create_dir(&destination).unwrap();
        std::fs::write(&source, bytes).unwrap();

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let (token, worker) = visual.update(|_, cx| {
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            let token = owner
                .runtime
                .submit(copy_request(
                    source.to_string_lossy().as_ref(),
                    destination.to_string_lossy().as_ref(),
                ))
                .unwrap();
            (
                token,
                owner.runtime.start_next().expect("Copy worker starts"),
            )
        });

        let mut facts = Vec::new();
        executor::execute_prepare(
            worker.command,
            worker.cancellation.as_ref(),
            &worker.controls,
            |fact| facts.push(fact),
        );
        let terminal = facts.iter().find_map(|fact| match fact {
            executor::ExecutorFact::Terminal {
                token: actual,
                report,
            } if *actual == token => Some(report.clone()),
            _ => None,
        });
        let terminal = terminal.expect("executor reports exact Copy terminal");
        assert_eq!(
            terminal.outcome,
            operations::model::TerminalOutcome::Succeeded
        );
        assert!(terminal.receipts.iter().any(|receipt| {
            receipt.outcome == operations::model::ItemOutcome::Completed
                && receipt
                    .copy_undo
                    .as_ref()
                    .is_some_and(|receipt| receipt.destination == copied)
        }));
        visual.update(|_, cx| {
            let runtime = &mut cx
                .global_mut::<operations::application::OperationApplicationOwner>()
                .runtime;
            let mut terminal_committed = false;
            for fact in facts {
                terminal_committed |= runtime.commit_fact(fact).is_some();
            }
            assert!(
                terminal_committed,
                "exact Copy terminal is accepted by Runtime"
            );
        });
        assert_eq!(std::fs::read(&copied).unwrap(), bytes);

        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| shell.undo_trash(cx));
            cx.background_executor().allow_parking();
        });
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            visual.run_until_parked();
            if !copied.exists() {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "Shell Copy undo did not remove the exact unchanged output"
            );
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        assert_eq!(std::fs::read(&source).unwrap(), bytes);
        assert!(!copied.exists());

        // reserve_undo().is_none() is ambiguous while a reservation is held.
        // A later queued operation proves the undo completion released the lane.
        let sentinel_destination = temp.path().join("sentinel-destination");
        std::fs::create_dir(&sentinel_destination).unwrap();
        let sentinel_output = sentinel_destination.join("copy-source.bin");
        let sentinel_token = visual.update(|_, cx| {
            cx.global_mut::<operations::application::OperationApplicationOwner>()
                .runtime
                .submit(copy_request(
                    source.to_string_lossy().as_ref(),
                    sentinel_destination.to_string_lossy().as_ref(),
                ))
                .unwrap()
        });
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let mut sentinel_worker = None;
        loop {
            let (worker, already_running, already_terminal) = visual.update(|_, cx| {
                let runtime = &mut cx
                    .global_mut::<operations::application::OperationApplicationOwner>()
                    .runtime;
                let state = runtime.job(sentinel_token).and_then(|job| {
                    job.attempts
                        .iter()
                        .find(|attempt| attempt.token == sentinel_token)
                        .map(|attempt| attempt.state)
                });
                let already_running = state == Some(operations::model::AttemptState::Running);
                let already_terminal = state == Some(operations::model::AttemptState::Terminal);
                let worker = (!(already_running || already_terminal))
                    .then(|| runtime.start_next())
                    .flatten();
                (worker, already_running, already_terminal)
            });
            if let Some(worker) = worker {
                sentinel_worker = Some(worker);
                break;
            }
            if already_running || already_terminal {
                break;
            }
            visual.run_until_parked();
            assert!(
                std::time::Instant::now() < deadline,
                "Copy undo reservation kept the serial operation lane closed"
            );
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        if let Some(worker) = sentinel_worker {
            let mut sentinel_facts = Vec::new();
            executor::execute_prepare(
                worker.command,
                worker.cancellation.as_ref(),
                &worker.controls,
                |fact| sentinel_facts.push(fact),
            );
            visual.update(|_, cx| {
                let runtime = &mut cx
                    .global_mut::<operations::application::OperationApplicationOwner>()
                    .runtime;
                assert!(
                    sentinel_facts
                        .into_iter()
                        .filter_map(|fact| runtime.commit_fact(fact))
                        .next()
                        .is_some()
                );
            });
        }
        loop {
            visual.run_until_parked();
            let terminal = visual.read_entity(&shell, |_, cx| {
                cx.read_global::<operations::application::OperationApplicationOwner, _>(
                    |owner, _| {
                        owner.runtime.job(sentinel_token).is_some_and(|job| {
                            job.attempts.iter().any(|attempt| {
                                attempt.token == sentinel_token
                                    && attempt.state == operations::model::AttemptState::Terminal
                            })
                        })
                    },
                )
            });
            if terminal {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "sentinel Copy did not reach Runtime terminal state after undo"
            );
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        assert_eq!(std::fs::read(&sentinel_output).unwrap(), bytes);
        let undo = visual.update(|_, cx| {
            cx.global_mut::<operations::application::OperationApplicationOwner>()
                .runtime
                .reserve_undo()
        });
        let (reservation, entry) = undo.expect("sentinel Copy receipt is now the LIFO entry");
        assert!(
            matches!(entry, UndoEntry::Copy(receipt) if receipt.destination == sentinel_output)
        );
        assert!(visual.update(|_, cx| {
            cx.global_mut::<operations::application::OperationApplicationOwner>()
                .runtime
                .finish_trash_undo(reservation, true)
        }));
        std::fs::remove_file(&sentinel_output).unwrap();
        assert!(visual.update(|_, cx| {
            cx.global_mut::<operations::application::OperationApplicationOwner>()
                .runtime
                .reserve_undo()
                .is_none()
        }));
    }

