    #[cfg(windows)]
    struct E7ShellPumpFixtureReaper {
        fixture: Option<tempfile::TempDir>,
        worker_state: Arc<std::sync::atomic::AtomicU8>,
        abort_executor: Arc<std::sync::atomic::AtomicBool>,
        cancellation: Arc<std::sync::Mutex<Option<operations::runtime::Cancellation>>>,
        queued_copy_cancellation: Arc<std::sync::Mutex<Option<operations::runtime::Cancellation>>>,
        queued_copy_worker_state: Arc<std::sync::atomic::AtomicU8>,
        abort_queued_copy: Arc<std::sync::atomic::AtomicBool>,
        queued_copy_joined: Arc<std::sync::Mutex<std::sync::mpsc::Receiver<()>>>,
        release_return: async_channel::Sender<()>,
        release_terminal_publish: async_channel::Sender<()>,
        release_terminal_fact: async_channel::Sender<()>,
        release_destination_published_ack: async_channel::Sender<()>,
        release_cleanup_ack: async_channel::Sender<()>,
        pending_terminal_upsert: Arc<std::sync::Mutex<Option<operations::journal::JournalWriterUpsertForTest>>>,
        terminal_driver: Arc<std::sync::Mutex<Option<Arc<std::sync::Mutex<operations::journal::JournalWriterTestDriver>>>>>,
        restore_journal: Option<Box<dyn FnOnce()>>,
        joined: async_channel::Receiver<bool>,
        completed: bool,
    }

    #[cfg(windows)]
    impl E7ShellPumpFixtureReaper {
        fn complete(&mut self) {
            self.completed = true;
            self.fixture.take();
        }
    }

    #[cfg(windows)]
    impl Drop for E7ShellPumpFixtureReaper {
        fn drop(&mut self) {
            if self.completed {
                return;
            }
            self.abort_executor.store(true, std::sync::atomic::Ordering::Release);
            if let Some(upsert) = self.pending_terminal_upsert.lock().unwrap().take() {
                upsert.reply(Err("E7 selector cleanup released pending terminal upsert".into()));
            }
            if let Some(driver) = self.terminal_driver.lock().unwrap().as_ref() {
                while let Some(command) = driver.lock().unwrap().try_command() {
                    if let operations::journal::JournalWriterCommandForTest::Upsert(upsert) = command {
                        upsert.reply(Err("E7 selector cleanup released terminal writer request".into()));
                    }
                }
            }
            if let Some(restore_journal) = self.restore_journal.take() {
                restore_journal();
            }
            if let Some(cancellation) = self.cancellation.lock().unwrap().as_ref() {
                cancellation.store(true, std::sync::atomic::Ordering::Release);
            }
            self.abort_queued_copy.store(true, std::sync::atomic::Ordering::Release);
            if let Some(cancellation) = self.queued_copy_cancellation.lock().unwrap().as_ref() {
                cancellation.store(true, std::sync::atomic::Ordering::Release);
            }
            let queued_copy_needs_join = match self.queued_copy_worker_state.compare_exchange(
                0,
                3,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            ) {
                Ok(_) => false,
                Err(1) => true,
                Err(_) => false,
            };
            let _ = self.release_terminal_publish.try_send(());
            let _ = self.release_terminal_fact.try_send(());
            let _ = self.release_destination_published_ack.try_send(());
            let _ = self.release_cleanup_ack.try_send(());
            let _ = self.release_return.try_send(());
            if self.worker_state.compare_exchange(
                0,
                3,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            ).is_ok() {
                return;
            }
            if let Some(fixture) = self.fixture.take() {
                let joined = self.joined.clone();
                let queued_copy_needs_join = queued_copy_needs_join;
                let queued_copy_joined = self.queued_copy_joined.clone();
                std::thread::spawn(move || {
                    let joined_deadline = std::time::Instant::now() + std::time::Duration::from_secs(90);
                    let native_returned = loop {
                        match joined.try_recv() {
                            Ok(joined) => break joined,
                            Err(async_channel::TryRecvError::Closed) => break false,
                            Err(async_channel::TryRecvError::Empty) => {}
                        }
                        if std::time::Instant::now() >= joined_deadline {
                            break false;
                        }
                        std::thread::sleep(std::time::Duration::from_millis(10));
                    };
                    if !native_returned {
                        // A live or unconfirmed worker may still use fixture paths.
                        std::mem::forget(fixture);
                        return;
                    }
                    if queued_copy_needs_join {
                        if queued_copy_joined.lock().unwrap().recv_timeout(std::time::Duration::from_secs(30)).is_err() {
                            // Preserve the fixture if the queued native worker has not been confirmed joined.
                            std::mem::forget(fixture);
                            return;
                        }
                    }
                    drop(fixture);
                });
            }
        }
    }

    #[cfg(windows)]
    fn e7_fact_summary(facts: &[executor::ExecutorFact]) -> Vec<String> {
        facts
            .iter()
            .map(|fact| match fact {
                executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { ledger, .. } => {
                    format!(
                        "phase:{:?}/{:?}/{:?}",
                        ledger.phase, ledger.source_location, ledger.target_location
                    )
                }
                executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { intent, .. } => {
                    format!("cleanup-intent:{}", intent.ordinal)
                }
                executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition {
                    intent, ..
                } => format!("cleanup-receipt:{}", intent.ordinal),
                executor::ExecutorFact::DirectoryMoveReplaceRenameBackupComplete { .. } => {
                    "backup-complete".into()
                }
                executor::ExecutorFact::Terminal { report, .. } => format!(
                    "terminal:{:?}:{:?}",
                    report.outcome,
                    report
                        .receipts
                        .iter()
                        .map(|receipt| (receipt.item, receipt.outcome, receipt.detail.as_deref()))
                        .collect::<Vec<_>>()
                ),
                _ => format!("other:{:?}", std::mem::discriminant(fact)),
            })
            .collect()
    }

