    #[cfg(windows)]
    fn run_same_volume_directory_move_replace_e7_with_shell_lifecycle(
        cx: &mut gpui::TestAppContext,
        cleanup_write_refusal: E7CleanupWriteRefusal,
        shell_lifecycle: E7ShellLifecycle,
        terminal_scenario: E7TerminalScenario,
    ) {
        use operations::journal::DirectoryMoveReplaceRenamePhase as E7Phase;
        use std::time::{Duration, Instant};

        let cancellation_phase = match terminal_scenario {
            E7TerminalScenario::CancelAtDisplaceIntent => Some(E7Phase::DisplaceIntent),
            E7TerminalScenario::CancelAtTargetDisplaced => Some(E7Phase::TargetDisplaced),
            E7TerminalScenario::CancelAtDestinationPublished => Some(E7Phase::DestinationPublished),
            E7TerminalScenario::CancelAtBackupCleanupIntent
            | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused
            | E7TerminalScenario::CancelAtBackupCleanupReceipt
            | E7TerminalScenario::CancelAtBackupRootCleanupIntent
            | E7TerminalScenario::CancelAtBackupRootCleanupReceipt => Some(E7Phase::DestinationPublished),
            _ => None,
        };
        let root_cleanup_cancel = matches!(terminal_scenario,
            E7TerminalScenario::CancelAtBackupRootCleanupIntent | E7TerminalScenario::CancelAtBackupRootCleanupReceipt);
        let root_cleanup_selected = root_cleanup_cancel || matches!(cleanup_write_refusal,
            E7CleanupWriteRefusal::BackupRootIntent | E7CleanupWriteRefusal::BackupRootReceipt);
        let cleanup_cancel = matches!(terminal_scenario,
            E7TerminalScenario::CancelAtBackupCleanupIntent | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused
            | E7TerminalScenario::CancelAtBackupCleanupReceipt
            | E7TerminalScenario::CancelAtBackupRootCleanupIntent | E7TerminalScenario::CancelAtBackupRootCleanupReceipt);
        let cleanup_receipt_cancel = matches!(terminal_scenario,
            E7TerminalScenario::CancelAtBackupCleanupReceipt | E7TerminalScenario::CancelAtBackupRootCleanupReceipt);
        let cleanup_intent_cancel = matches!(terminal_scenario,
            E7TerminalScenario::CancelAtBackupCleanupIntent | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused
            | E7TerminalScenario::CancelAtBackupRootCleanupIntent);
        let terminal_refused = matches!(terminal_scenario,
            E7TerminalScenario::Refused | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused);
        let should_queue_copy = shell_lifecycle == E7ShellLifecycle::DropOriginWithSurvivor
            || cancellation_phase.is_some();
        let capture_failure_snapshot = cleanup_write_refusal != E7CleanupWriteRefusal::None;

        initialize_directory_binding_test_globals(cx);
        let fixture = tempfile::Builder::new()
            .prefix(match cleanup_write_refusal {
                E7CleanupWriteRefusal::None => "gpui-filer-shell-e7-success-",
                E7CleanupWriteRefusal::FirstChildIntent => "gpui-filer-shell-e7-child-intent-failure-",
                E7CleanupWriteRefusal::FirstChildReceipt => "gpui-filer-shell-e7-child-receipt-failure-",
                E7CleanupWriteRefusal::BackupRootIntent => "gpui-filer-shell-e7-root-intent-failure-",
                E7CleanupWriteRefusal::BackupRootReceipt => "gpui-filer-shell-e7-root-receipt-failure-",
            })
            .tempdir_in(std::env::current_dir().unwrap())
            .expect("create same-volume E7 fixture");
        let fixture_path = fixture.path().to_path_buf();
        let source_parent = fixture_path.join("source-parent");
        let destination_parent = fixture_path.join("destination-parent");
        std::fs::create_dir_all(&source_parent).unwrap();
        std::fs::create_dir_all(&destination_parent).unwrap();
        let source = source_parent.join("incoming");
        let destination = destination_parent.join("incoming");
        std::fs::create_dir_all(source.join("nested")).unwrap();
        std::fs::create_dir_all(source.join("empty")).unwrap();
        std::fs::write(source.join("nested/source.bin"), b"incoming source payload").unwrap();
        std::fs::create_dir_all(destination.join("nested")).unwrap();
        std::fs::create_dir_all(destination.join("empty")).unwrap();
        std::fs::write(destination.join("nested/displaced.bin"), b"displaced target payload").unwrap();
        std::fs::write(destination.join("root.txt"), b"displaced root payload").unwrap();
        std::fs::write(destination.join("z-last.txt"), b"third cleanup candidate").unwrap();
        let sentinel = fixture_path.join("unrelated-sentinel.txt");
        std::fs::write(&sentinel, b"unrelated sentinel").unwrap();

        fn fixed_ntfs(path: &std::path::Path) -> bool {
            use std::path::{Component, Prefix};
            use windows::{Win32::Storage::FileSystem::{GetDriveTypeW, GetVolumeInformationW}, core::PCWSTR};
            let Some(Component::Prefix(prefix)) = path.components().next() else { return false };
            let (Prefix::Disk(letter) | Prefix::VerbatimDisk(letter)) = prefix.kind() else { return false };
            let root = format!("{}:\\", letter as char);
            let wide = root.encode_utf16().chain(std::iter::once(0)).collect::<Vec<_>>();
            let mut filesystem = [0u16; 32];
            unsafe {
                GetDriveTypeW(PCWSTR(wide.as_ptr())) == 3
                    && GetVolumeInformationW(PCWSTR(wide.as_ptr()), None, None, None, None, Some(&mut filesystem)).is_ok()
                    && String::from_utf16_lossy(&filesystem).trim_end_matches(char::from(0)).eq_ignore_ascii_case("NTFS")
            }
        }
        assert!(fixed_ntfs(&fixture_path), "E7 fixture must be on a local fixed NTFS volume");

        let source_inventory = {
            fn visit(root: &std::path::Path, path: &std::path::Path, out: &mut Vec<(PathBuf, Vec<u8>)>) {
                for entry in std::fs::read_dir(path).unwrap() {
                    let entry = entry.unwrap();
                    let child = entry.path();
                    let relative = child.strip_prefix(root).unwrap().to_path_buf();
                    if entry.file_type().unwrap().is_dir() {
                        out.push((relative.clone(), Vec::new()));
                        visit(root, &child, out);
                    } else {
                        out.push((relative, std::fs::read(child).unwrap()));
                    }
                }
            }
            let mut entries = Vec::new();
            visit(&source, &source, &mut entries);
            entries.sort_by(|a, b| a.0.cmp(&b.0));
            entries
        };
        fn snapshot_e7_tree(
            root: &std::path::Path,
        ) -> Vec<(
            PathBuf,
            crate::directory::EntryKind,
            crate::filesystem_identity::FilesystemIdentity,
            Option<Vec<u8>>,
        )> {
            fn visit(
                root: &std::path::Path,
                path: &std::path::Path,
                out: &mut Vec<(
                    PathBuf,
                    crate::directory::EntryKind,
                    crate::filesystem_identity::FilesystemIdentity,
                    Option<Vec<u8>>,
                )>,
            ) {
                for entry in std::fs::read_dir(path).unwrap() {
                    let entry = entry.unwrap();
                    let child = entry.path();
                    let kind = if entry.file_type().unwrap().is_dir() {
                        crate::directory::EntryKind::Folder
                    } else {
                        crate::directory::EntryKind::File
                    };
                    let identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &child, kind,
                    ).unwrap().filesystem_identity();
                    let content = (kind == crate::directory::EntryKind::File)
                        .then(|| std::fs::read(&child).unwrap());
                    out.push((child.strip_prefix(root).unwrap().to_path_buf(), kind, identity, content));
                    if kind == crate::directory::EntryKind::Folder {
                        visit(root, &child, out);
                    }
                }
            }
            let mut entries = Vec::new();
            visit(root, root, &mut entries);
            entries.sort_by(|a, b| a.0.cmp(&b.0));
            entries
        }
        fn e7_child_path(root: &std::path::Path, components: &[Vec<u16>]) -> PathBuf {
            use std::os::windows::ffi::OsStringExt;
            components.iter().fold(root.to_path_buf(), |path, component| {
                path.join(std::ffi::OsString::from_wide(component))
            })
        }
        fn expected_e7_backup_after_receipts(
            snapshot: &[(PathBuf, crate::directory::EntryKind, crate::filesystem_identity::FilesystemIdentity, Option<Vec<u8>>)],
            children: &[operations::journal::JournalDirectoryMoveReplaceRenameChild],
        ) -> Vec<(PathBuf, crate::directory::EntryKind, crate::filesystem_identity::FilesystemIdentity, Option<Vec<u8>>)> {
            let mut expected = snapshot.to_vec();
            for child in children.iter().filter(|child| child.disposition_recorded) {
                let removed = e7_child_path(Path::new(""), &child.relative_components);
                expected.retain(|(relative, _, _, _)| relative != &removed);
            }
            expected
        }
        let source_cancel_snapshot = (cancellation_phase.is_some() || capture_failure_snapshot)
            .then(|| snapshot_e7_tree(&source));
        let target_cancel_snapshot = (cancellation_phase.is_some() || capture_failure_snapshot)
            .then(|| snapshot_e7_tree(&destination));
        let target_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination,
            crate::directory::EntryKind::Folder,
        ).unwrap().filesystem_identity();
        let source_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &source,
            crate::directory::EntryKind::Folder,
        ).unwrap().filesystem_identity();
        let source_parent_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &source_parent,
            crate::directory::EntryKind::Folder,
        ).unwrap().filesystem_identity();
        let destination_parent_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination_parent,
            crate::directory::EntryKind::Folder,
        ).unwrap().filesystem_identity();
        let sentinel_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &sentinel,
            crate::directory::EntryKind::File,
        ).unwrap().filesystem_identity();

        let journal_path = fixture_path.join("journal").join("journal-v1.json");
        std::fs::create_dir_all(journal_path.parent().unwrap()).unwrap();
        let store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        cx.update(|cx| {
            *cx.global_mut::<operations::application::OperationApplicationOwner>() =
                operations::application::OperationApplicationOwner::for_test_with_journal_store(store);
        });
        let _real_writer = cx.update(|cx| cx.global::<operations::application::OperationApplicationOwner>()
            .journal.clone().expect("E7 fixture starts its real JournalWriter"));
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| FilerShell::new(
                persistence::Startup::disabled(),
                Arc::new(input::KeymapRuntime::new()),
                Vec::new(),
                cx,
            ));
            E7ShellLifetimeRoot { shell: Some(shell) }
        });
        let mut shell_handle = Some(visual.read_entity(&harness, |root, _| root.shell.as_ref().unwrap().clone()));
        let shell = shell_handle.as_ref().unwrap();
        let final_shell_weak = shell.downgrade();
        let (terminal_reply_observed_tx, terminal_reply_observed_rx) = std::sync::mpsc::sync_channel(1);
        if terminal_scenario != E7TerminalScenario::Normal {
            visual.update(|_, cx| shell.update(cx, |shell, _| {
                shell.terminal_reply_observer_for_test = Some(terminal_reply_observed_tx);
            }));
        }
        let survivor = should_queue_copy.then(|| visual.update(|_, cx| cx.new(|cx| FilerShell::new(
            persistence::Startup::disabled(),
            Arc::new(input::KeymapRuntime::new()),
            Vec::new(),
            cx,
        ))));
        let queued_copy_cancellation = Arc::new(std::sync::Mutex::new(None));
        let queued_copy_worker_state = Arc::new(std::sync::atomic::AtomicU8::new(0));
        let abort_queued_copy = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let (queued_copy_joined_tx, queued_copy_joined_rx) = std::sync::mpsc::channel();
        let (source_view, source_tab) = visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let pane = shell.workspace.active().focused_pane_id;
                shell.add_tab_in(pane, Some(Location::Path(source_parent.clone())), cx);
                shell.workspace.active().tabs().find_map(|tab| {
                    (tab.view.read(cx).location().as_ref().and_then(Location::path)
                        == Some(source_parent.as_path()))
                    .then(|| (tab.view.clone(), tab.id))
                }).expect("Shell opened source parent")
            })
        });
        let destination_view = visual.update(|_, cx| {
            cx.new(|cx| DirectoryListDemo::new_at(
                Arc::new(input::KeymapRuntime::new()),
                Some(Location::Path(destination_parent.clone())),
                cx,
            ))
        });
        let (destination_pane, destination_tab) = visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                shell.add_pane_with_view_for_test(destination_view.clone(), cx)
                    .expect("second E7 parent pane is available")
            })
        });
        visual.update(|_, cx| {
            source_view.update(cx, |view, cx| view.refresh_listing(cx));
            destination_view.update(cx, |view, cx| view.refresh_listing(cx));
        });
        let initial_scan_deadline = Instant::now() + Duration::from_secs(20);
        let source_pane = visual.read_entity(&shell, |shell, _| shell.workspace.active().focused_pane_id);
        for (pane, tab, view, expected_path) in [
            (source_pane, source_tab, &source_view, &source_parent),
            (destination_pane, destination_tab, &destination_view, &destination_parent),
        ] {
            visual.update(|_, cx| shell.update(cx, |shell, cx| {
                shell.handle_tab(
                    shell.workspace.active,
                    pane,
                    &TabIntent::Activate(tab),
                    cx,
                );
            }));
            loop {
                visual.run_until_parked();
                if visual.read_entity(view, |view, _| {
                    view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.path == *expected_path)
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                }) {
                    break;
                }
                assert!(Instant::now() < initial_scan_deadline, "initial E7 parent listing did not become Ready");
                std::thread::sleep(Duration::from_millis(2));
            }
        }
        let (source_scan, destination_scan) = visual.update(|_, cx| (
            source_view.read(cx).session.accepted_scan_ticket().unwrap().scan_id,
            destination_view.read(cx).session.accepted_scan_ticket().unwrap().scan_id,
        ));
        let real_writer = visual.read_global::<operations::application::OperationApplicationOwner, _>(
            |owner, _| owner.journal.as_ref().unwrap().clone(),
        );
        let observed = Arc::new(std::sync::Mutex::new(Vec::<executor::ExecutorFact>::new()));
        let observed_by_worker = observed.clone();
        let stale_fact_sender = Arc::new(std::sync::Mutex::new(
            None::<operations::transport::WorkerFactSender>,
        ));
        let stale_fact_sender_for_setup = stale_fact_sender.clone();
        let worker_state = Arc::new(std::sync::atomic::AtomicU8::new(0));
        let abort_executor = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let cancellation = Arc::new(std::sync::Mutex::new(None));
        let (test_joined_tx, test_joined_rx) = async_channel::bounded::<bool>(1);
        let (reaper_joined_tx, reaper_joined_rx) = async_channel::bounded::<bool>(1);
        let (worker_joined_tx, worker_joined_rx) = async_channel::bounded::<bool>(1);
        let (release_return_tx, release_return_rx) = async_channel::bounded::<()>(1);
        let test_release_return_tx = release_return_tx.clone();
        let (release_terminal_publish_tx, release_terminal_publish_rx) =
            async_channel::bounded::<()>(1);
        let (terminal_fact_waiting_tx, terminal_fact_waiting_rx) = async_channel::bounded::<()>(1);
        let (release_terminal_fact_tx, release_terminal_fact_rx) = async_channel::bounded::<()>(1);
        let pending_terminal_upsert = Arc::new(std::sync::Mutex::new(None));
        let terminal_driver_for_reaper = Arc::new(std::sync::Mutex::new(None));
        let mut cleanup_visual = visual.clone();
        let cleanup_writer = real_writer.clone();
        let (destination_published_ack_tx, destination_published_ack_rx) =
            async_channel::bounded::<(operations::model::AttemptToken, operations::model::ConflictToken, operations::journal::JournalDirectoryMoveReplaceRename)>(1);
        let (release_destination_published_ack_tx, release_destination_published_ack_rx) =
            async_channel::bounded::<()>(1);
        let (cleanup_ack_tx, cleanup_ack_rx) = async_channel::bounded::<(
            operations::model::AttemptToken,
            operations::model::ItemId,
            operations::journal::JournalDirectoryMoveReplaceRenameChildIntent,
            bool,
        )>(1);
        let (release_cleanup_ack_tx, release_cleanup_ack_rx) = async_channel::bounded::<()>(1);
        let selected_cleanup = Arc::new(std::sync::Mutex::new(None::<operations::journal::JournalDirectoryMoveReplaceRenameChildIntent>));
        let cleanup_acks = Arc::new(std::sync::Mutex::new(Vec::<(
            operations::model::AttemptToken,
            operations::model::ItemId,
            operations::journal::JournalDirectoryMoveReplaceRenameChildIntent,
            bool,
        )>::new()));
        let (failed_cleanup_tx, failed_cleanup_rx) = async_channel::bounded(1);
        let (cancel_forwarded_tx, cancel_forwarded_rx) = async_channel::bounded::<()>(1);
        let mut fixture_reaper = E7ShellPumpFixtureReaper {
            fixture: Some(fixture),
            worker_state: worker_state.clone(),
            abort_executor: abort_executor.clone(),
            cancellation: cancellation.clone(),
            queued_copy_cancellation: queued_copy_cancellation.clone(),
            queued_copy_worker_state: queued_copy_worker_state.clone(),
            abort_queued_copy: abort_queued_copy.clone(),
            queued_copy_joined: Arc::new(std::sync::Mutex::new(queued_copy_joined_rx)),
            release_return: release_return_tx,
            release_terminal_publish: release_terminal_publish_tx.clone(),
            release_terminal_fact: release_terminal_fact_tx.clone(),
            release_destination_published_ack: release_destination_published_ack_tx.clone(),
            release_cleanup_ack: release_cleanup_ack_tx.clone(),
            pending_terminal_upsert: pending_terminal_upsert.clone(),
            terminal_driver: terminal_driver_for_reaper.clone(),
            restore_journal: Some(Box::new(move || cleanup_visual.update(|_, cx| {
                cx.update_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.journal = Some(cleanup_writer));
            }))),
            joined: reaper_joined_rx,
            completed: false,
        };
        let observed_by_worker_for_configure = observed_by_worker.clone();
        let selected_cleanup_for_setup = selected_cleanup.clone();
        let cleanup_acks_for_setup = cleanup_acks.clone();
        let token = visual.update(|_, cx| {
            cx.background_executor().allow_parking();
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            let worker_state_for_executor = worker_state.clone();
            let abort_for_executor = abort_executor.clone();
            let cancellation_for_executor = cancellation.clone();
            let journal_path_for_executor = journal_path.clone();
            let release_terminal_publish = release_terminal_publish_rx.clone();
            let terminal_fact_waiting = terminal_fact_waiting_tx.clone();
            let release_terminal_fact = release_terminal_fact_rx.clone();
            owner.configure_worker_pump_test(move |worker, fact_sender| {
                let operations::runtime::WorkerStart { command, cancellation, controls, .. } = worker;
                if terminal_scenario == E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused {
                    // この clone は transport を開いたままにするため、遅延 fact の再生時だけ保持する。
                    *stale_fact_sender_for_setup.lock().unwrap() = Some(fact_sender.clone());
                }
                if worker_state_for_executor.compare_exchange(
                    0,
                    1,
                    std::sync::atomic::Ordering::AcqRel,
                    std::sync::atomic::Ordering::Acquire,
                ).is_err() {
                    return Box::pin(async {});
                }
                *cancellation_for_executor.lock().unwrap() = Some(cancellation.clone());
                let observed = observed_by_worker_for_configure.clone();
                let abort_for_forwarder = abort_for_executor.clone();
                let abort_for_native = abort_for_executor.clone();
                let cleanup_write_refusal = cleanup_write_refusal;
                let failed_cleanup_tx = failed_cleanup_tx.clone();
                let cancel_forwarded_tx = cancel_forwarded_tx.clone();
                let journal_path_for_native = journal_path_for_executor.clone();
                let gate_phase = if let Some(phase) = cancellation_phase {
                    Some(phase)
                } else if shell_lifecycle != E7ShellLifecycle::KeepOrigin {
                    Some(E7Phase::DestinationPublished)
                } else {
                    None
                };
                let destination_published_ack_tx = destination_published_ack_tx.clone();
                let release_destination_published_ack_rx = release_destination_published_ack_rx.clone();
                let cleanup_ack_tx = cleanup_ack_tx.clone();
                let release_cleanup_ack_rx = release_cleanup_ack_rx.clone();
                let selected_cleanup_for_forwarder = selected_cleanup_for_setup.clone();
                let cleanup_acks_for_forwarder = cleanup_acks_for_setup.clone();
                let (executor_control_tx, executor_control_rx) = std::sync::mpsc::channel();
                let forwarder = std::thread::spawn(move || {
                    loop {
                        if abort_for_forwarder.load(std::sync::atomic::Ordering::Acquire) {
                            break;
                        }
                        match controls.recv_timeout(Duration::from_millis(20)) {
                            Ok(control) => {
                                if abort_for_forwarder.load(std::sync::atomic::Ordering::Acquire) {
                                    break;
                                }
                                if matches!(&control, executor::WorkerControl::Cancel) {
                                    let _ = cancel_forwarded_tx.send_blocking(());
                                }
                                let cleanup_ack = match &control {
                                    executor::WorkerControl::DirectoryMoveReplaceRenameCleanupIntentJournaledExact { token, item, intent } =>
                                        Some((*token, *item, intent.clone(), false)),
                                    executor::WorkerControl::DirectoryMoveReplaceRenameCleanupReceiptJournaledExact { token, item, intent } =>
                                        Some((*token, *item, intent.clone(), true)),
                                    _ => None,
                                };
                                if let Some(ack) = cleanup_ack {
                                    cleanup_acks_for_forwarder.lock().unwrap().push(ack);
                                }
                                if let executor::WorkerControl::DirectoryMoveReplaceRenamePhaseJournaledExact {
                                        token,
                                        conflict_token,
                                        ledger,
                                    } = &control
                                    && gate_phase.is_some_and(|phase| ledger.phase == phase)
                                {
                                    destination_published_ack_tx.send_blocking((
                                        *token,
                                        *conflict_token,
                                        ledger.clone(),
                                    )).expect("selector receives exact E7 phase ACK");
                                    release_destination_published_ack_rx.recv_blocking()
                                        .expect("selector releases exact E7 phase ACK");
                                }
                                let cleanup = match (&control, terminal_scenario) {
                                    (executor::WorkerControl::DirectoryMoveReplaceRenameCleanupIntentJournaledExact { token, item, intent },
                                        E7TerminalScenario::CancelAtBackupCleanupIntent
                                        | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused
                                        | E7TerminalScenario::CancelAtBackupRootCleanupIntent)
                                        if selected_cleanup_for_forwarder.lock().unwrap().as_ref() == Some(intent) => Some((*token, *item, intent.clone(), false)),
                                    (executor::WorkerControl::DirectoryMoveReplaceRenameCleanupReceiptJournaledExact { token, item, intent },
                                        E7TerminalScenario::CancelAtBackupCleanupReceipt | E7TerminalScenario::CancelAtBackupRootCleanupReceipt)
                                        if selected_cleanup_for_forwarder.lock().unwrap().as_ref() == Some(intent) => Some((*token, *item, intent.clone(), true)),
                                    _ => None,
                                };
                                if let Some(cleanup) = cleanup {
                                    cleanup_ack_tx.send_blocking(cleanup).expect("selector receives exact selected cleanup ACK");
                                    release_cleanup_ack_rx.recv_blocking().expect("selector releases exact selected cleanup ACK");
                                }
                                if executor_control_tx.send(control).is_err() {
                                    break;
                                }
                            }
                            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {}
                            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
                        }
                    }
                });
                let native = std::thread::spawn(move || {
                    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        let mut failed_cleanup_captured = false;
                        executor::execute_prepare_with_directory_move_replace_rename_enabled_for_test(
                            command,
                            cancellation.as_ref(),
                            &executor_control_rx,
                            None,
                            |fact| {
                                if cleanup_write_refusal != E7CleanupWriteRefusal::None
                                    && matches!(&fact, executor::ExecutorFact::Terminal { .. })
                                {
                                    release_terminal_publish
                                        .recv_blocking()
                                        .expect("test releases terminal publication after journal lock drops");
                                }
                                let held_terminal_fact = terminal_scenario != E7TerminalScenario::Normal
                                    && matches!(&fact, executor::ExecutorFact::Terminal { .. });
                                if held_terminal_fact {
                                    // 端末factの内容もゲート中に診断できるよう、配送待ちへ入る前に一度だけ記録する。
                                    observed.lock().unwrap().push(fact.clone());
                                    terminal_fact_waiting.send_blocking(())
                                        .expect("test observes exact E7 Terminal fact gate");
                                    release_terminal_fact.recv_blocking()
                                        .expect("test releases exact E7 Terminal fact after writer setup");
                                }
                                if cleanup_write_refusal != E7CleanupWriteRefusal::None
                                    && !failed_cleanup_captured
                                {
                                    let selected_cleanup = match (&fact, cleanup_write_refusal) {
                                        (executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token, item, intent },
                                            E7CleanupWriteRefusal::FirstChildIntent | E7CleanupWriteRefusal::BackupRootIntent)
                                            if item.0 == 0 && match cleanup_write_refusal {
                                                E7CleanupWriteRefusal::FirstChildIntent => intent.ordinal == 0 && !intent.relative_components.is_empty(),
                                                E7CleanupWriteRefusal::BackupRootIntent => intent.relative_components.is_empty(),
                                                _ => false,
                                            } => Some((*token, *item, intent.clone(), false)),
                                        (executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token, item, intent },
                                            E7CleanupWriteRefusal::FirstChildReceipt | E7CleanupWriteRefusal::BackupRootReceipt)
                                            if item.0 == 0 && match cleanup_write_refusal {
                                                E7CleanupWriteRefusal::FirstChildReceipt => intent.ordinal == 0 && !intent.relative_components.is_empty(),
                                                E7CleanupWriteRefusal::BackupRootReceipt => intent.relative_components.is_empty(),
                                                _ => false,
                                            } => Some((*token, *item, intent.clone(), true)),
                                        _ => None,
                                    };
                                    if let Some((token, item, intent, receipt)) = selected_cleanup {
                                        use std::os::windows::fs::OpenOptionsExt;
                                        use windows::Win32::Storage::FileSystem::{
                                            FILE_SHARE_READ, FILE_SHARE_WRITE,
                                        };
                                        let predecessor = std::fs::read(&journal_path_for_native)
                                            .expect("read durable BackupCleanup predecessor");
                                        let journal_lock = std::fs::OpenOptions::new()
                                            .read(true)
                                            .share_mode(FILE_SHARE_READ.0 | FILE_SHARE_WRITE.0)
                                            .open(&journal_path_for_native)
                                            .expect("hold journal predecessor against replacement");
                                        failed_cleanup_tx.send_blocking((
                                            token,
                                            item,
                                            intent,
                                            receipt,
                                            predecessor,
                                            journal_lock,
                                        )).expect("test receives exact selected backup cleanup write");
                                        failed_cleanup_captured = true;
                                    }
                                }
                                if !held_terminal_fact {
                                    observed.lock().unwrap().push(fact.clone());
                                }
                                fact_sender.publish(fact);
                            },
                        );
                    }));
                    abort_for_native.store(true, std::sync::atomic::Ordering::Release);
                    forwarder.join().expect("E7 worker control forwarder did not panic");
                    if let Err(payload) = outcome {
                        std::panic::resume_unwind(payload);
                    }
                });
                let joined_senders = [test_joined_tx, reaper_joined_tx, worker_joined_tx];
                std::thread::spawn(move || {
                    let joined = native.join().is_ok();
                    for sender in joined_senders {
                        let _ = sender.send_blocking(joined);
                    }
                });
                Box::pin(async move {
                    let _ = worker_joined_rx.recv().await.expect("native worker return observed");
                    release_return_rx.recv().await.expect("test releases worker return after terminal readback");
                })
            });
            let request = operations::model::OperationRequest {
                kind: OperationKind::Move,
                virtual_source: None,
                sources: vec![source.clone()],
                destination: Some(destination_parent.clone()),
                batch_rename_plan: None,
                move_identity_guard: Some(operations::model::MoveIdentityGuard {
                    source_identities: vec![source_identity.clone()],
                    destination_identity: destination_parent_identity.clone(),
                }),
                clipboard_move_source_evidence: None,
                rename_reparse_guard: None,
                move_destination_identity_guard: None,
                move_replace_source_evidence: None,
                trash_source_guards: None,
                source_cleanup_identity_guard: None,
                initial_conflict_policy: None,
                copy_destination_identity_guard: None,
                create_parent_directory_identity_guard: None,
                zip_create_guard: None,
                shortcut_create_guard: None,
                seven_zip_create_guard: None,
                seven_zip_extract_guard: None,
                origin: None,
            };
            let token = owner.runtime.submit(request).unwrap();
            shell.update(cx, |shell, cx| shell.start_next_operation(cx));
            token
        });

        let conflict = {
            let until = Instant::now() + Duration::from_secs(30);
            loop {
                visual.run_until_parked();
                if let Some(conflict) = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.job(token).and_then(|job| job.attempts.first()
                        .and_then(|attempt| attempt.pending_conflict.as_ref().map(|pending| pending.token)))) {
                    break conflict;
                }
                assert!(Instant::now() < until, "E7 Move did not reach the ordinary Replace conflict");
                std::thread::sleep(Duration::from_millis(1));
            }
        };
        visual.update(|_, cx| shell.update(cx, |shell, cx| {
            shell.resolve_operation_conflict(conflict, operations::model::ConflictDecision::Replace, false, cx);
        }));

        let mut queued_copy = if shell_lifecycle == E7ShellLifecycle::DropOriginWithSurvivor {
            let ack_deadline = Instant::now() + Duration::from_secs(30);
            let (ack_token, ack_conflict, ack_ledger) = loop {
                visual.run_until_parked();
                match destination_published_ack_rx.try_recv() {
                    Ok(ack) => break ack,
                    Err(async_channel::TryRecvError::Closed) => {
                        panic!("E7 exact phase ACK gate closed before interception")
                    }
                    Err(async_channel::TryRecvError::Empty) => {}
                }
                if Instant::now() >= ack_deadline {
                    // native 側の失敗と配送待ちを区別できるよう、期限切れ時の事実を残す。
                    let attempt = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                        owner.runtime.journal_attempt(token));
                    let facts = observed_by_worker.lock().unwrap().clone();
                    let acks = cleanup_acks.lock().unwrap().clone();
                    let attempt_summary = attempt.as_ref().map(|attempt| (
                        attempt.state,
                        attempt.terminal_outcome,
                        attempt.directory_move_replace_rename.as_ref().map(|ledger| (
                            ledger.phase,
                            ledger.source_location,
                            ledger.target_location,
                            ledger.pending_cleanup.as_ref().map(|intent| intent.ordinal),
                        )),
                    ));
                    let fact_summary = e7_fact_summary(&facts);
                    let ack_summary = acks.iter().map(|(_, item, intent, receipt)|
                        (item.0, intent.ordinal, intent.relative_components.len(), *receipt)
                    ).collect::<Vec<_>>();
                    let pending_phases = facts.iter().filter_map(|fact| match fact {
                        executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { token: fact_token, conflict_token, ledger }
                            if *fact_token == token => Some((*conflict_token, ledger.clone())),
                        _ => None,
                    }).map(|(conflict, ledger)| visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                        owner.runtime.directory_move_replace_rename_phase_pending(token, conflict, &ledger)
                    )).collect::<Vec<_>>();
                    panic!("E7 did not reach the selected exact phase ACK gate: scenario={terminal_scenario:?}, attempt={attempt_summary:?}, facts={fact_summary:?}, cleanup_acks={ack_summary:?}, pending_phases={pending_phases:?}");
                }
                std::thread::sleep(Duration::from_millis(1));
            };
            assert_eq!(ack_token, token, "intercepted ACK belongs to this exact attempt");
            assert_eq!(ack_conflict, conflict, "intercepted ACK belongs to this exact conflict");
            assert_eq!(ack_ledger.phase, cancellation_phase.unwrap_or(E7Phase::DestinationPublished));
            let key = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).expect("E7 attempt remains current").key);
            let durable = real_writer.read_attempt(key).recv_blocking().unwrap().unwrap().unwrap();
            assert_eq!(durable.directory_move_replace_rename.as_ref(), Some(&ack_ledger),
                "held exact phase ACK ledger matches the real JournalWriter readback");

            let origin_weak = shell.downgrade();
            let source_copy = fixture_path.join("queued-copy-source.bin");
            let copy_destination = fixture_path.join("queued-copy-destination");
            let copy_output = copy_destination.join("queued-copy-source.bin");
            std::fs::write(&source_copy, b"queued copy remains behind the E7 lane").unwrap();
            std::fs::create_dir(&copy_destination).unwrap();
            let survivor = survivor.as_ref().expect("lifetime selector retains a survivor Shell");
            let survivor_source_view = visual.update(|_, cx| cx.new(|cx| DirectoryListDemo::new_at(
                Arc::new(input::KeymapRuntime::new()),
                Some(Location::Path(source_parent.clone())),
                cx,
            )));
            let survivor_destination_view = visual.update(|_, cx| cx.new(|cx| DirectoryListDemo::new_at(
                Arc::new(input::KeymapRuntime::new()),
                Some(Location::Path(destination_parent.clone())),
                cx,
            )));
            visual.update(|_, cx| survivor.update(cx, |shell, cx| {
                shell.replace_active_view_with_binding_for_test(survivor_source_view.clone(), cx);
                shell.add_pane_with_view_for_test(survivor_destination_view.clone(), cx)
                    .expect("survivor retains both E7 parent listings");
            }));
            visual.update(|_, cx| {
                survivor_source_view.update(cx, |view, cx| view.refresh_listing(cx));
                survivor_destination_view.update(cx, |view, cx| view.refresh_listing(cx));
            });
            let survivor_listing_deadline = Instant::now() + Duration::from_secs(20);
            loop {
                visual.run_until_parked();
                let ready = visual.read_entity(&survivor_source_view, |view, _|
                    view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.path == source_parent)
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready)
                    && visual.read_entity(&survivor_destination_view, |view, _|
                        view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.path == destination_parent)
                            && view.session.status() == &crate::directory_session::ListingStatus::Ready);
                if ready { break; }
                assert!(Instant::now() < survivor_listing_deadline, "survivor parent listings did not reach initial Ready scans");
                std::thread::sleep(Duration::from_millis(1));
            }
            let (survivor_source_scan, survivor_destination_scan) = visual.update(|_, cx| (
                survivor_source_view.read(cx).session.accepted_scan_ticket().unwrap().scan_id,
                survivor_destination_view.read(cx).session.accepted_scan_ticket().unwrap().scan_id,
            ));
            visual.update(|_, cx| {
                harness.update(cx, |root, _| root.shell = Some(survivor.clone()));
            });
            drop(shell_handle.take());
            visual.run_until_parked();
            assert!(origin_weak.upgrade().is_none(), "origin FilerShell Entity is destroyed while the E7 ACK is held");

            let queued_token = visual.update(|_, cx| {
                let token = cx.global_mut::<operations::application::OperationApplicationOwner>()
                    .runtime.submit(copy_request(
                        source_copy.to_string_lossy().as_ref(),
                        copy_destination.to_string_lossy().as_ref(),
                    )).expect("independent Copy queues behind active E7");
                cx.global_mut::<operations::application::OperationApplicationOwner>()
                    .configure_worker_pump_test({
                        let queued_copy_cancellation = queued_copy_cancellation.clone();
                        let queued_copy_worker_state = queued_copy_worker_state.clone();
                        let abort_queued_copy = abort_queued_copy.clone();
                        let queued_copy_joined_tx = queued_copy_joined_tx.clone();
                        move |worker, fact_sender| {
                        let (command, cancellation, controls, lease) = (
                            worker.command, worker.cancellation, worker.controls, worker.source_cleanup_lease,
                        );
                        if queued_copy_worker_state.compare_exchange(
                            0,
                            1,
                            std::sync::atomic::Ordering::AcqRel,
                            std::sync::atomic::Ordering::Acquire,
                        ).is_err() {
                            return Box::pin(async {});
                        }
                        *queued_copy_cancellation.lock().unwrap() = Some(cancellation.clone());
                        if abort_queued_copy.load(std::sync::atomic::Ordering::Acquire) {
                            cancellation.store(true, std::sync::atomic::Ordering::Release);
                            queued_copy_worker_state.store(2, std::sync::atomic::Ordering::Release);
                            let _ = queued_copy_joined_tx.send(());
                            return Box::pin(async {});
                        }
                        let (joined_tx, joined_rx) = async_channel::bounded::<()>(1);
                        let native = std::thread::spawn(move || {
                            executor::execute_prepare_with_source_cleanup_lease(
                                command, cancellation.as_ref(), &controls, lease,
                                |fact| fact_sender.publish(fact),
                            );
                        });
                        let queued_copy_worker_state_for_join = queued_copy_worker_state.clone();
                        std::thread::spawn(move || {
                            native.join().expect("queued Copy native worker does not panic");
                            queued_copy_worker_state_for_join.store(2, std::sync::atomic::Ordering::Release);
                            let _ = queued_copy_joined_tx.send(());
                            let _ = joined_tx.send_blocking(());
                        });
                        Box::pin(async move {
                            joined_rx.recv().await.expect("queued Copy native worker returns");
                        })
                    }});
                survivor.update(cx, |shell, cx| shell.start_next_operation(cx));
                token
            });
            assert!(!copy_output.exists(), "queued Copy has no filesystem effect while E7 ACK is held");
            if cleanup_cancel || cleanup_write_refusal != E7CleanupWriteRefusal::None {
                if root_cleanup_selected {
                    let root_intent = operations::journal::JournalDirectoryMoveReplaceRenameChildIntent {
                        ordinal: ack_ledger.approved_target_children.len() as u32,
                        node_kind: operations::journal::JournalDirectoryNodeKind::Directory,
                        relative_components: Vec::new(),
                        identity: ack_ledger.approved_target_identity.clone(),
                        content_fact: "root".into(),
                    };
                    *selected_cleanup.lock().unwrap() = Some(root_intent);
                } else if matches!(cleanup_write_refusal,
                    E7CleanupWriteRefusal::FirstChildIntent | E7CleanupWriteRefusal::FirstChildReceipt)
                {
                    let selected = ack_ledger.approved_target_children.first()
                        .expect("first-child refusal has an approved cleanup child");
                    assert_eq!(selected.ordinal, 0);
                    assert!(!selected.relative_components.is_empty());
                    assert!(!selected.identity.is_empty());
                    assert!(!selected.content_fact.is_empty());
                    *selected_cleanup.lock().unwrap() = Some(
                        operations::journal::JournalDirectoryMoveReplaceRenameChildIntent {
                            ordinal: selected.ordinal,
                            node_kind: selected.node_kind,
                            relative_components: selected.relative_components.clone(),
                            identity: selected.identity.clone(),
                            content_fact: selected.content_fact.clone(),
                        },
                    );
                } else {
                let file_children = ack_ledger.approved_target_children.iter()
                    .filter(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                    .collect::<Vec<_>>();
                assert!(file_children.len() >= 3,
                    "fixture manifest supplies three ordered ordinary-file cleanup entries A/B/C");
                let selected = file_children[file_children.len() / 2];
                let selected_index = ack_ledger.approved_target_children.iter()
                    .position(|child| child == selected).expect("selected file belongs to approved manifest");
                let earlier = ack_ledger.approved_target_children[..selected_index].iter()
                    .rev().find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                    .expect("selected B has an earlier ordinary-file cleanup entry A");
                let later = ack_ledger.approved_target_children[selected_index + 1..].iter()
                    .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                    .expect("selected B has a later ordinary-file cleanup entry C");
                for child in [earlier, selected, later] {
                    assert_eq!(child.node_kind, operations::journal::JournalDirectoryNodeKind::File);
                    assert!(!child.relative_components.is_empty());
                    assert!(!child.identity.is_empty());
                    assert!(!child.content_fact.is_empty());
                }
                *selected_cleanup.lock().unwrap() = Some(
                    operations::journal::JournalDirectoryMoveReplaceRenameChildIntent {
                        ordinal: selected.ordinal,
                        node_kind: selected.node_kind,
                        relative_components: selected.relative_components.clone(),
                        identity: selected.identity.clone(),
                        content_fact: selected.content_fact.clone(),
                    },
                );
                }
            }
            if let Some(cancel_phase) = cancellation_phase.filter(|_| !cleanup_cancel) {
                assert_eq!(ack_ledger.phase, cancel_phase);
                let source_snapshot = source_cancel_snapshot.as_ref().unwrap();
                let target_snapshot = target_cancel_snapshot.as_ref().unwrap();
                let backup = {
                    use std::os::windows::ffi::OsStringExt;
                    PathBuf::from(std::ffi::OsString::from_wide(&ack_ledger.backup.units))
                };
                match cancel_phase {
                    E7Phase::DestinationPublished => {
                        assert!(!source.exists(), "DestinationPublished has already moved the source root");
                        assert_eq!(snapshot_e7_tree(&destination), *source_snapshot,
                            "held DestinationPublished ACK preserves the published source tree");
                        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                            &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                        assert_eq!(snapshot_e7_tree(&backup), *target_snapshot,
                            "held DestinationPublished ACK preserves every target descendant at backup");
                        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                            &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    }
                    E7Phase::DisplaceIntent => {
                        assert_eq!(snapshot_e7_tree(&source), *source_snapshot,
                            "held ACK preserves every source descendant path, kind, identity and byte");
                        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                            &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                        assert_eq!(snapshot_e7_tree(&destination), *target_snapshot,
                            "DisplaceIntent leaves every target descendant unchanged");
                        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                            &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                        assert!(!backup.exists(), "no backup exists before DisplaceIntent ACK");
                    }
                    E7Phase::TargetDisplaced => {
                        assert!(!destination.exists(), "TargetDisplaced leaves destination vacant");
                        assert_eq!(snapshot_e7_tree(&backup), *target_snapshot,
                            "TargetDisplaced preserves every target descendant at backup");
                        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                            &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    }
                    _ => unreachable!(),
                }
                let cancel = visual.update(|_, cx| cx.global_mut::<operations::application::OperationApplicationOwner>()
                    .runtime.cancel(token));
                assert!(cancel.is_none(), "active E7 cancellation records a request but cannot finish the attempt yet");
                assert!(cancellation.lock().unwrap().as_ref().unwrap()
                    .load(std::sync::atomic::Ordering::Acquire),
                    "the shared cancellation flag changes while the exact phase ACK is held");
                assert!(cancel_forwarded_rx.try_recv().is_err(),
                    "the queued Cancel is not forwarded until the held exact ACK is released");
                assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.journal_attempt(token).is_some_and(|attempt| attempt.terminal_outcome.is_some())),
                    "the attempt remains nonterminal until the held phase ACK is released");
                if cancel_phase == E7Phase::DisplaceIntent {
                    assert_eq!(snapshot_e7_tree(&source), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    assert_eq!(snapshot_e7_tree(&destination), *target_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    assert!(!backup.exists());
                } else if cancel_phase == E7Phase::TargetDisplaced {
                    assert_eq!(snapshot_e7_tree(&source), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    assert!(!destination.exists());
                    assert_eq!(snapshot_e7_tree(&backup), *target_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                } else {
                    assert!(!source.exists());
                    assert_eq!(snapshot_e7_tree(&destination), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    assert_eq!(snapshot_e7_tree(&backup), *target_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                }
                assert!(!copy_output.exists(), "queued Copy remains inert while E7 terminal is unresolved");
            }
            Some((queued_token, source_copy, copy_output, survivor_source_view, survivor_destination_view,
                survivor_source_scan, survivor_destination_scan))
        } else {
            None
        };
        if shell_lifecycle == E7ShellLifecycle::DropFinalShell {
            visual.update(|_, cx| harness.update(cx, |root, _| root.shell = None));
            visual.run_until_parked();
            drop(shell_handle.take());
            visual.run_until_parked();
            assert!(final_shell_weak.upgrade().is_none(), "the final Shell entity is destroyed while the E7 ACK is held");
            let lease_deadline = Instant::now() + Duration::from_secs(10);
            loop {
                visual.run_until_parked();
                let live_shells = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.live_shell_count_for_test());
                if live_shells == 0 {
                    break;
                }
                assert!(Instant::now() < lease_deadline,
                    "the final Shell entity is gone but its application lease remains: {live_shells}");
                std::thread::sleep(Duration::from_millis(1));
            }
        }
        if shell_lifecycle != E7ShellLifecycle::KeepOrigin {
            release_destination_published_ack_tx
                .send_blocking(())
                .expect("release the exact E7 phase ACK after queue admission and cancellation checks");
        }

        if cleanup_cancel {
            let expected_receipt = cleanup_receipt_cancel;
            let deadline = Instant::now() + Duration::from_secs(90);
            let (ack_token, ack_item, ack_intent, is_receipt) = loop {
                visual.run_until_parked();
                match cleanup_ack_rx.try_recv() {
                    Ok(ack) => break ack,
                    Err(async_channel::TryRecvError::Closed) => panic!("cleanup ACK gate closed before exact interception"),
                    Err(async_channel::TryRecvError::Empty) => {}
                }
                if Instant::now() >= deadline {
                    // root cleanup の長い列で止まった段階を次の再現時に識別できるようにする。
                    let attempt = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                        owner.runtime.journal_attempt(token));
                    let facts = observed_by_worker.lock().unwrap().clone();
                    let acks = cleanup_acks.lock().unwrap().clone();
                    let attempt_summary = attempt.as_ref().map(|attempt| (
                        attempt.state,
                        attempt.terminal_outcome,
                        attempt.directory_move_replace_rename.as_ref().map(|ledger| (
                            ledger.phase,
                            ledger.source_location,
                            ledger.target_location,
                            ledger.pending_cleanup.as_ref().map(|intent| intent.ordinal),
                            ledger.backup_root_disposed,
                        )),
                    ));
                    let fact_summary = e7_fact_summary(&facts);
                    let ack_summary = acks.iter().map(|(_, item, intent, receipt)|
                        (item.0, intent.ordinal, intent.relative_components.len(), *receipt)
                    ).collect::<Vec<_>>();
                    let selected = selected_cleanup.lock().unwrap().as_ref().map(|intent|
                        (intent.ordinal, intent.relative_components.len())
                    );
                    let pending_cleanup = facts.iter().filter_map(|fact| match fact {
                        executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, intent, .. }
                            if *fact_token == token => Some((intent.clone(), false)),
                        executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, intent, .. }
                            if *fact_token == token => Some((intent.clone(), true)),
                        _ => None,
                    }).map(|(intent, receipt)| visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                        owner.runtime.pending_directory_move_replace_rename_cleanup_transition(token, &intent, receipt)
                    )).collect::<Vec<_>>();
                    panic!("selected cleanup ACK did not reach the Shell control forwarder: scenario={terminal_scenario:?}, attempt={attempt_summary:?}, facts={fact_summary:?}, cleanup_acks={ack_summary:?}, selected={selected:?}, pending_cleanup={pending_cleanup:?}");
                }
                std::thread::sleep(Duration::from_millis(1));
            };
            let selected = selected_cleanup.lock().unwrap().clone().expect("selected exact cleanup intent was installed");
            assert_eq!(ack_token, token);
            assert_eq!(ack_item, operations::model::ItemId(0));
            assert_eq!(ack_intent, selected, "held control matches the full selected manifest tuple");
            assert_eq!(is_receipt, expected_receipt);
            let exact_ledger = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).unwrap().directory_move_replace_rename.unwrap());
            assert_eq!(exact_ledger.phase, E7Phase::BackupCleanup);
            assert_eq!(exact_ledger.source_location, operations::journal::DirectoryMoveReplaceSourceLocation::Published);
            assert_eq!(exact_ledger.target_location, if root_cleanup_cancel && expected_receipt {
                operations::journal::DirectoryMoveReplaceTargetLocation::Disposed
            } else {
                operations::journal::DirectoryMoveReplaceTargetLocation::Backup
            });
            assert_eq!(exact_ledger.backup_root_disposed, root_cleanup_cancel && expected_receipt);
            assert_eq!(exact_ledger.pending_cleanup.as_ref(), cleanup_intent_cancel.then_some(&selected));
            let held_key = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).unwrap().key);
            let durable_at_hold = real_writer.read_attempt(held_key).recv_blocking().unwrap().unwrap().unwrap();
            assert_eq!(durable_at_hold.directory_move_replace_rename.as_ref(), Some(&exact_ledger),
                "emitted cleanup fact, Runtime accepted ledger, and durable ACK ledger converge before cancellation");
            let backup = {
                use std::os::windows::ffi::OsStringExt;
                PathBuf::from(std::ffi::OsString::from_wide(&exact_ledger.backup.units))
            };
            if root_cleanup_cancel {
                let expected_root = operations::journal::JournalDirectoryMoveReplaceRenameChildIntent {
                    ordinal: exact_ledger.approved_target_children.len() as u32,
                    node_kind: operations::journal::JournalDirectoryNodeKind::Directory,
                    relative_components: Vec::new(),
                    identity: exact_ledger.approved_target_identity.clone(),
                    content_fact: "root".into(),
                };
                assert_eq!(selected, expected_root, "root intent is derived from the approved ledger");
                assert!(exact_ledger.approved_target_children.iter().all(|child| child.disposition_recorded),
                    "root cleanup starts only after every approved child receipt");
                assert!(!source.exists(), "root cleanup begins only after publishing the source root");
                assert_eq!(snapshot_e7_tree(&destination), *source_cancel_snapshot.as_ref().unwrap(),
                    "held root cleanup ACK preserves the complete published source tree");
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                if cleanup_intent_cancel {
                    assert_eq!(snapshot_e7_tree(&backup),
                        expected_e7_backup_after_receipts(target_cancel_snapshot.as_ref().unwrap(), &exact_ledger.approved_target_children));
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                }
            } else {
            let selected_position = exact_ledger.approved_target_children.iter()
                .position(|child| child.ordinal == selected.ordinal).unwrap();
            let a = exact_ledger.approved_target_children[..selected_position].iter().rev()
                .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                .expect("A is an earlier ordinary-file cleanup entry");
            let c = exact_ledger.approved_target_children[selected_position + 1..].iter()
                .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                .expect("C is a later ordinary-file cleanup entry");
            assert!(a.disposition_recorded, "A is durably receipted before selected B");
            assert_eq!(exact_ledger.approved_target_children[selected_position].disposition_recorded, expected_receipt,
                "Runtime accepts B receipt before holding its control ACK");
            assert!(!c.disposition_recorded, "C remains untouched after B");
            }
            if !root_cleanup_cancel {
                let selected_position = exact_ledger.approved_target_children.iter()
                    .position(|child| child.ordinal == selected.ordinal).unwrap();
                let a = exact_ledger.approved_target_children[..selected_position].iter().rev()
                    .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File).unwrap();
                let c = exact_ledger.approved_target_children[selected_position + 1..].iter()
                    .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File).unwrap();
                assert!(!e7_child_path(&backup, &a.relative_components).exists());
                assert!(e7_child_path(&backup, &c.relative_components).is_file());
            }
            let intent_fact_seen = observed_by_worker.lock().unwrap().iter().any(|fact| matches!(fact,
                executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, item, intent }
                    if *fact_token == token && *item == ack_item && *intent == selected));
            assert!(intent_fact_seen, "selected cleanup intent was emitted through the production fact route");
            if expected_receipt {
                assert!(observed_by_worker.lock().unwrap().iter().any(|fact| matches!(fact,
                    executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, item, intent }
                        if *fact_token == token && *item == ack_item && *intent == selected)),
                    "selected native disposition and receipt fact precede the held receipt ACK");
            }
            let cancel = visual.update(|_, cx| cx.global_mut::<operations::application::OperationApplicationOwner>().runtime.cancel(token));
            assert!(cancel.is_none());
            assert!(cancellation.lock().unwrap().as_ref().unwrap().load(std::sync::atomic::Ordering::Acquire));
            assert!(cancel_forwarded_rx.try_recv().is_err(), "Cancel remains queued behind selected cleanup ACK");
            assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).is_some_and(|attempt| attempt.terminal_outcome.is_some())));
            if !expected_receipt {
                assert!(backup.is_dir());
                if root_cleanup_cancel {
                    assert_eq!(snapshot_e7_tree(&backup),
                        expected_e7_backup_after_receipts(target_cancel_snapshot.as_ref().unwrap(), &exact_ledger.approved_target_children),
                        "root intent follows durable removal of every approved child");
                } else {
                let relative = e7_child_path(Path::new(""), &selected.relative_components);
                let original = target_cancel_snapshot.as_ref().unwrap().iter()
                    .find(|entry| entry.0 == relative).expect("selected B exists in the captured target tree");
                assert_eq!(original.1, crate::directory::EntryKind::File);
                let selected_path = e7_child_path(&backup, &selected.relative_components);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &selected_path, crate::directory::EntryKind::File).unwrap().filesystem_identity(), original.2);
                assert_eq!(std::fs::read(&selected_path).unwrap(), original.3.as_ref().unwrap().as_slice(),
                    "intent ACK cancellation precedes B native disposition");
                let mut expected_backup = target_cancel_snapshot.as_ref().unwrap().clone();
                for child in &exact_ledger.approved_target_children {
                    if child.disposition_recorded {
                        let removed = e7_child_path(Path::new(""), &child.relative_components);
                        expected_backup.retain(|(relative, _, _, _)| relative != &removed);
                    }
                }
                assert_eq!(snapshot_e7_tree(&backup), expected_backup,
                    "while B intent is held, only earlier receipted manifest entries are absent");
                }
            }
            assert!(!queued_copy.as_ref().unwrap().2.exists(), "queued Copy remains inert while cleanup ACK is held");
            release_cleanup_ack_tx.send_blocking(()).expect("release exact cleanup ACK before queued Cancel is forwarded");
            let cancel_deadline = Instant::now() + Duration::from_secs(30);
            loop {
                visual.run_until_parked();
                if cancel_forwarded_rx.try_recv().is_ok() { break; }
                assert!(Instant::now() < cancel_deadline,
                    "queued Cancel is forwarded only after selected cleanup ACK release");
                std::thread::sleep(Duration::from_millis(1));
            }
        }

        let failed_cleanup_checkpoint = if cleanup_write_refusal != E7CleanupWriteRefusal::None {
            let (failed_token, failed_item, failed_intent, failed_receipt, predecessor, journal_lock) = {
                let until = Instant::now() + Duration::from_secs(90);
                loop {
                    visual.run_until_parked();
                    if let Ok(checkpoint) = failed_cleanup_rx.try_recv() {
                        break checkpoint;
                    }
                    if Instant::now() >= until {
                        let attempt = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                            owner.runtime.journal_attempt(token));
                        let facts = observed_by_worker.lock().unwrap().clone();
                        let acks = cleanup_acks.lock().unwrap().clone();
                        let attempt_summary = attempt.as_ref().map(|attempt| (
                            attempt.state,
                            attempt.terminal_outcome,
                            attempt.directory_move_replace_rename.as_ref().map(|ledger| (
                                ledger.phase,
                                ledger.source_location,
                                ledger.target_location,
                                ledger.pending_cleanup.as_ref().map(|intent| intent.ordinal),
                                ledger.backup_root_disposed,
                            )),
                        ));
                        let fact_summary = e7_fact_summary(&facts);
                        let ack_summary = acks.iter().map(|(_, item, intent, receipt)|
                            (item.0, intent.ordinal, intent.relative_components.len(), *receipt)
                        ).collect::<Vec<_>>();
                        panic!("selected backup cleanup write did not reach the Shell pump: scenario={terminal_scenario:?}, refusal={cleanup_write_refusal:?}, attempt={attempt_summary:?}, facts={fact_summary:?}, cleanup_acks={ack_summary:?}");
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
            };
            assert_eq!(failed_token, token);
            assert_eq!(failed_item, operations::model::ItemId(0));
            let expected_receipt = matches!(cleanup_write_refusal,
                E7CleanupWriteRefusal::FirstChildReceipt | E7CleanupWriteRefusal::BackupRootReceipt);
            assert_eq!(failed_receipt, expected_receipt, "the refusal targets the selected intent/receipt boundary");
            let selected = selected_cleanup.lock().unwrap().clone().expect("exact cleanup identity was selected before releasing DestinationPublished");
            assert_eq!(failed_intent, selected, "refused write names the exact approved node and path");
            assert!(!failed_intent.identity.is_empty(), "refused write retains the approved node identity");
            match cleanup_write_refusal {
                E7CleanupWriteRefusal::FirstChildIntent | E7CleanupWriteRefusal::FirstChildReceipt => {
                    assert_eq!(failed_intent.ordinal, 0);
                    assert!(!failed_intent.relative_components.is_empty(), "child refusal identifies a non-root path");
                }
                E7CleanupWriteRefusal::BackupRootIntent | E7CleanupWriteRefusal::BackupRootReceipt => {
                    assert!(failed_intent.relative_components.is_empty(), "root refusal identifies the backup root");
                    let (volume, index) = target_identity.windows_parts().unwrap();
                    assert_eq!(failed_intent.identity, format!("{volume}:{index:016x}"));
                }
                E7CleanupWriteRefusal::None => unreachable!(),
            }

            let cancel_until = Instant::now() + Duration::from_secs(30);
            loop {
                visual.run_until_parked();
                if cancel_forwarded_rx.try_recv().is_ok() {
                    break;
                }
                assert!(Instant::now() < cancel_until, "Shell did not reject the selected cleanup write and cancel the waiting executor");
                std::thread::sleep(Duration::from_millis(1));
            }
            assert!(!cleanup_acks.lock().unwrap().contains(&(failed_token, failed_item, failed_intent.clone(), failed_receipt)),
                "the exact failed cleanup write has no corresponding WorkerControl ACK when Cancel reaches the executor");
            assert_eq!(
                std::fs::read(&journal_path).expect("read journal while writer replacement is denied"),
                predecessor,
                "the real JournalWriter refusal leaves the exact durable predecessor bytes unchanged",
            );
            let key = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).expect("exact E7 attempt remains current").key);
            let refusal = if failed_receipt {
                real_writer.record_directory_move_replace_rename_cleanup_receipt(
                    key, failed_item.0, failed_intent.clone(),
                ).recv_blocking().expect("real JournalWriter refusal reply")
            } else {
                real_writer.record_directory_move_replace_rename_cleanup_intent(
                    key, failed_item.0, failed_intent.clone(),
                ).recv_blocking().expect("real JournalWriter refusal reply")
            }.expect_err("held primary lock refuses the exact cleanup write through JournalWriter");
            assert!(refusal.contains("replace failed (2147942432)"),
                "expected real sharing refusal for exact cleanup write, got {refusal}");
            assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner.runtime.journal_attempt(token)
                    .is_some_and(|attempt| attempt.terminal_outcome.is_some())
            }), "terminal cannot commit while native Terminal fact publication is gated");
            let facts = observed_by_worker.lock().unwrap();
            let cleanup_facts = facts.iter().filter_map(|fact| match fact {
                executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, item, intent }
                    if *fact_token == token && *item == failed_item => Some((false, intent.clone())),
                executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, item, intent }
                    if *fact_token == token && *item == failed_item => Some((true, intent.clone())),
                _ => None,
            }).collect::<Vec<_>>();
            assert_eq!(cleanup_facts.last(), Some(&(failed_receipt, failed_intent.clone())),
                "the exact refused intent/receipt is the final backup-cleanup fact");
            assert!(!facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::DirectoryMoveReplaceRenameBackupComplete { token: fact_token, item }
                    if *fact_token == token && *item == failed_item
            )), "refused cleanup write emits no BackupComplete fact");
            assert!(!facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { token: fact_token, ledger, .. }
                    if *fact_token == token && ledger.phase == E7Phase::Complete
            )), "refused cleanup write emits no Complete phase");
            if !failed_receipt {
                assert!(!facts.iter().any(|fact| matches!(fact,
                    executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, item, intent }
                        if *fact_token == token && *item == failed_item && intent == &failed_intent
                )), "intent refusal performs no disposition for its selected node");
            } else {
                assert!(facts.iter().any(|fact| matches!(fact,
                    executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, item, intent }
                        if *fact_token == token && *item == failed_item && intent == &failed_intent
                )), "receipt refusal follows native disposition of the selected node");
            }
            drop(facts);
            drop(journal_lock);
            release_terminal_publish_tx
                .send_blocking(())
                .expect("release terminal publication after the journal lock drops");
            Some((failed_intent, failed_receipt, predecessor))
        } else {
            None
        };

        let mut terminal_predecessor = None;
        if terminal_scenario != E7TerminalScenario::Normal {
            let gate_deadline = Instant::now() + Duration::from_secs(90);
            loop {
                visual.run_until_parked();
                if terminal_fact_waiting_rx.try_recv().is_ok() {
                    break;
                }
                if cancellation_phase.is_some() {
                    assert!(!queued_copy.as_ref().unwrap().2.exists(),
                        "queued Copy remains inert while cancellation terminal is unresolved");
                }
                assert!(Instant::now() < gate_deadline, "E7 terminal fact did not reach the test gate");
                std::thread::sleep(Duration::from_millis(1));
            }
            let key = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).expect("exact E7 attempt remains current").key);
            let predecessor = real_writer.read_attempt(key).recv_blocking().unwrap().unwrap().unwrap();
            let expected_phase = match cancellation_phase {
                Some(E7Phase::DisplaceIntent) => E7Phase::NoEffect,
                Some(E7Phase::TargetDisplaced) => E7Phase::TargetDisplaced,
                Some(E7Phase::DestinationPublished) if cleanup_cancel => E7Phase::BackupCleanup,
                Some(E7Phase::DestinationPublished) => E7Phase::DestinationPublished,
                Some(_) => unreachable!(),
                None => E7Phase::Complete,
            };
            assert!(matches!(predecessor.state,
                operations::journal::JournalState::Running | operations::journal::JournalState::CancelRequested));
            let durable_phase = predecessor.directory_move_replace_rename.as_ref().unwrap().phase;
            if durable_phase != expected_phase {
                let runtime_ledger = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.journal_attempt(token).and_then(|attempt| attempt.directory_move_replace_rename));
                let observed_phases = observed_by_worker.lock().unwrap().iter().filter_map(|fact| match fact {
                    executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { token: fact_token, ledger, .. }
                        if *fact_token == token => Some((ledger.phase, ledger.source_location, ledger.target_location)),
                    _ => None,
                }).collect::<Vec<_>>();
                panic!("E7 terminal predecessor phase mismatch: scenario={terminal_scenario:?}, expected={expected_phase:?}, durable={durable_phase:?}, runtime={runtime_ledger:?}, observed_phases={observed_phases:?}");
            }
            assert!(predecessor.cross_volume_move_replace.is_none());
            assert!(predecessor.directory_moves.is_empty());
            if cancellation_phase.is_none() {
                assert!(!source.exists());
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                assert_eq!(std::fs::read(destination.join("nested/source.bin")).unwrap(), b"incoming source payload");
                assert!(!destination.join("nested/displaced.bin").exists());
                assert!(!destination.join("root.txt").exists());
            } else if matches!(cancellation_phase, Some(E7Phase::DisplaceIntent | E7Phase::TargetDisplaced)) {
                let e7 = predecessor.directory_move_replace_rename.as_ref().unwrap();
                assert_eq!(snapshot_e7_tree(&source), *source_cancel_snapshot.as_ref().unwrap());
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                let backup = {
                    use std::os::windows::ffi::OsStringExt;
                    PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units))
                };
                if cancellation_phase == Some(E7Phase::DisplaceIntent) {
                    assert_eq!(e7.phase, E7Phase::NoEffect);
                    assert_eq!(snapshot_e7_tree(&destination), *target_cancel_snapshot.as_ref().unwrap());
                    assert!(!backup.exists());
                } else {
                    assert_eq!(e7.phase, E7Phase::TargetDisplaced);
                    assert!(!destination.exists());
                    assert_eq!(snapshot_e7_tree(&backup), *target_cancel_snapshot.as_ref().unwrap());
                }
            } else if cleanup_cancel {
                let e7 = predecessor.directory_move_replace_rename.as_ref().unwrap();
                assert_eq!(e7.phase, E7Phase::BackupCleanup);
                assert!(!source.exists());
                assert_eq!(snapshot_e7_tree(&destination), *source_cancel_snapshot.as_ref().unwrap());
                let backup = {
                    use std::os::windows::ffi::OsStringExt;
                    PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units))
                };
                if !root_cleanup_cancel || cleanup_intent_cancel {
                    assert!(backup.is_dir());
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                }
            } else {
                let e7 = predecessor.directory_move_replace_rename.as_ref().unwrap();
                assert_eq!(e7.phase, E7Phase::DestinationPublished);
                assert!(!source.exists());
                assert_eq!(snapshot_e7_tree(&destination), *source_cancel_snapshot.as_ref().unwrap());
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                let backup = {
                    use std::os::windows::ffi::OsStringExt;
                    PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units))
                };
                assert_eq!(snapshot_e7_tree(&backup), *target_cancel_snapshot.as_ref().unwrap());
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
            }
            assert_eq!(std::fs::read(&sentinel).unwrap(), b"unrelated sentinel");
            terminal_predecessor = Some((predecessor, std::fs::read(&journal_path).unwrap()));

            let (test_writer, terminal_driver) = operations::journal::JournalWriter::test_driver();
            let terminal_driver = Arc::new(std::sync::Mutex::new(terminal_driver));
            *terminal_driver_for_reaper.lock().unwrap() = Some(terminal_driver.clone());
            visual.update(|_, cx| cx.update_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.journal = Some(test_writer)));
            release_terminal_fact_tx.send_blocking(()).expect("release exact Terminal fact after driver install");

            let terminal_upsert = {
                let deadline = Instant::now() + Duration::from_secs(90);
                loop {
                    visual.run_until_parked();
                    if let Some(operations::journal::JournalWriterCommandForTest::Upsert(upsert)) = terminal_driver.lock().unwrap().try_command() {
                        if upsert.attempt.state == operations::journal::JournalState::Terminal {
                            break upsert;
                        }
                    }
                    assert!(Instant::now() < deadline, "Shell did not submit E7 terminal through the test writer");
                    std::thread::sleep(Duration::from_millis(1));
                }
            };
            assert_eq!(terminal_upsert.attempt.key, terminal_predecessor.as_ref().unwrap().0.key);
            let expected_outcome = match terminal_scenario {
                E7TerminalScenario::CancelAtDisplaceIntent => operations::journal::JournalTerminalOutcome::Cancelled,
                E7TerminalScenario::CancelAtTargetDisplaced | E7TerminalScenario::CancelAtDestinationPublished
                | E7TerminalScenario::CancelAtBackupCleanupIntent
                | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused
                | E7TerminalScenario::CancelAtBackupCleanupReceipt
                | E7TerminalScenario::CancelAtBackupRootCleanupIntent | E7TerminalScenario::CancelAtBackupRootCleanupReceipt => operations::journal::JournalTerminalOutcome::Partial,
                E7TerminalScenario::Refused | E7TerminalScenario::LostReply | E7TerminalScenario::Normal => operations::journal::JournalTerminalOutcome::Succeeded,
            };
            assert_eq!(terminal_upsert.attempt.terminal_outcome, Some(expected_outcome));
            *pending_terminal_upsert.lock().unwrap() = Some(terminal_upsert);
            visual.update(|_, cx| cx.update_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.journal = Some(real_writer.clone())));

            let terminal_attempt_for_writer = pending_terminal_upsert.lock().unwrap().as_ref()
                .expect("retain exact Shell terminal request for cleanup").attempt.clone();
            let terminal_key = terminal_attempt_for_writer.key.clone();
            let predecessor_bytes = &terminal_predecessor.as_ref().unwrap().1;
            if terminal_refused {
                let lock = TestJournalPrimaryLock::hold(&journal_path);
                let error = real_writer.upsert_with_reply(terminal_attempt_for_writer.clone()).recv_blocking()
                    .expect("real JournalWriter terminal reply")
                    .expect_err("primary lock must refuse exact E7 predecessor-to-Terminal replacement");
                assert!(error.contains("replace failed (2147942432)"), "expected actual sharing violation, got {error}");
                pending_terminal_upsert.lock().unwrap().take().unwrap().reply(Err(error));
                drop(lock);
                assert_eq!(std::fs::read(&journal_path).unwrap(), *predecessor_bytes);
                assert_eq!(real_writer.read_attempt(terminal_key.clone()).recv_blocking().unwrap().unwrap().unwrap(), terminal_predecessor.as_ref().unwrap().0);
            } else {
                real_writer.upsert_with_reply(terminal_attempt_for_writer.clone()).recv_blocking()
                    .expect("real JournalWriter terminal reply")
                    .expect("real JournalWriter durably stores exact Terminal");
                assert_eq!(real_writer.read_attempt(terminal_key).recv_blocking().unwrap().unwrap().unwrap(), terminal_attempt_for_writer);
                if cancellation_phase.is_some() {
                    pending_terminal_upsert.lock().unwrap().take().unwrap().reply(Ok(()));
                } else {
                    drop(pending_terminal_upsert.lock().unwrap().take()); // Receiver closure intentionally loses the Shell reply.
                }
            }
            assert!(!queued_copy.as_ref().expect("terminal scenarios queue Copy behind E7").2.exists(),
                "queued Copy stays inert while terminal reply/native return are unresolved");
            let reply_deadline = Instant::now() + Duration::from_secs(30);
            loop {
                visual.run_until_parked();
                match terminal_reply_observed_rx.try_recv() {
                    Ok(reply) => {
                        let expected_durable = cancellation_phase.is_some() && !terminal_refused;
                        assert_eq!(reply, (token, expected_durable), "Shell observes the exact terminal writer reply");
                        break;
                    }
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => panic!("E7 terminal reply observer disconnected"),
                    Err(std::sync::mpsc::TryRecvError::Empty) => {}
                }
                assert!(Instant::now() < reply_deadline, "Shell did not report the exact E7 terminal reply");
                std::thread::sleep(Duration::from_millis(1));
            }
            assert!(!queued_copy.as_ref().unwrap().2.exists(), "queued Copy remains inert after terminal reply while native return is held");
        }

        let terminal_attempt = {
            let until = Instant::now() + Duration::from_secs(90);
            loop {
                visual.run_until_parked();
                let expected_outcome = match terminal_scenario {
                    E7TerminalScenario::CancelAtDisplaceIntent => operations::journal::JournalTerminalOutcome::Cancelled,
                    E7TerminalScenario::CancelAtTargetDisplaced | E7TerminalScenario::CancelAtDestinationPublished
                    | E7TerminalScenario::CancelAtBackupCleanupIntent
                    | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused
                    | E7TerminalScenario::CancelAtBackupCleanupReceipt
                    | E7TerminalScenario::CancelAtBackupRootCleanupIntent | E7TerminalScenario::CancelAtBackupRootCleanupReceipt => operations::journal::JournalTerminalOutcome::Partial,
                E7TerminalScenario::Normal | E7TerminalScenario::Refused | E7TerminalScenario::LostReply => {
                        if cleanup_write_refusal != E7CleanupWriteRefusal::None {
                            operations::journal::JournalTerminalOutcome::Partial
                        } else {
                            operations::journal::JournalTerminalOutcome::Succeeded
                        }
                    }
                };
                if let Some(attempt) = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.journal_attempt(token).filter(|attempt|
                        attempt.terminal_outcome == Some(expected_outcome))) {
                    break attempt;
                }
                if Instant::now() >= until {
                    let attempt = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                        owner.runtime.journal_attempt(token));
                    let facts = observed_by_worker.lock().unwrap().clone();
                    let acks = cleanup_acks.lock().unwrap().clone();
                    let attempt_summary = attempt.as_ref().map(|attempt| (
                        attempt.state,
                        attempt.terminal_outcome,
                        attempt.directory_move_replace_rename.as_ref().map(|ledger| (
                            ledger.phase,
                            ledger.source_location,
                            ledger.target_location,
                            ledger.pending_cleanup.as_ref().map(|intent| intent.ordinal),
                            ledger.backup_root_disposed,
                        )),
                    ));
                    let fact_summary = e7_fact_summary(&facts);
                    let ack_summary = acks.iter().map(|(_, item, intent, receipt)|
                        (item.0, intent.ordinal, intent.relative_components.len(), *receipt)
                    ).collect::<Vec<_>>();
                    panic!("E7 Shell-pump terminal did not settle in Runtime: scenario={terminal_scenario:?}, expected={expected_outcome:?}, attempt={attempt_summary:?}, facts={fact_summary:?}, cleanup_acks={ack_summary:?}");
                }
                std::thread::sleep(Duration::from_millis(1));
            }
        };
        let native_join_deadline = Instant::now() + Duration::from_secs(90);
        let native_joined = loop {
            match test_joined_rx.try_recv() {
                Ok(joined) => break joined,
                Err(async_channel::TryRecvError::Closed) => panic!("native executor join observer closed before reporting completion"),
                Err(async_channel::TryRecvError::Empty) => {}
            }
            assert!(Instant::now() < native_join_deadline, "native executor did not join before the bounded deadline");
            std::thread::sleep(Duration::from_millis(2));
        };
        assert!(native_joined, "E7 native executor joined without panic");
        if let Some((failed_intent, failed_receipt, _)) = failed_cleanup_checkpoint.as_ref() {
            assert!(!cleanup_acks.lock().unwrap().contains(&(token, operations::model::ItemId(0), failed_intent.clone(), *failed_receipt)),
                "the exact failed cleanup write still has no corresponding WorkerControl ACK after native join");
            let facts = observed_by_worker.lock().unwrap();
            assert_eq!(facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition {
                    token: fact_token, item, intent,
                } if *fact_token == token && *item == operations::model::ItemId(0) && intent == failed_intent
            )), *failed_receipt,
                "joined executor disposition fact matches whether the refused write was a receipt");
        }
        assert!(visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.worker_claimed_for_test()),
            "worker lane remains claimed while its joined return future is explicitly held");
        if let Some((_, _, copy_output, _, _, _, _)) = queued_copy.as_ref() {
            assert!(!copy_output.exists(), "queued Copy remains filesystem-inert after E7 native join while its return is held");
        }
        if terminal_scenario == E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused {
            use operations::journal::JournalDirectoryMoveReplaceRenameChildIntent as CleanupIntent;

            let selected = selected_cleanup.lock().unwrap().clone().expect("selected exact pending cleanup intent");
            let exact_fact = observed_by_worker.lock().unwrap().iter().find_map(|fact| match fact {
                executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, item, intent }
                    if *fact_token == token && item.0 == 0 && intent == &selected => Some(fact.clone()),
                _ => None,
            }).expect("capture the actual cleanup intent submitted by the E7 executor");
            let mut changed = selected.clone();
            changed.content_fact.push_str("-changed");
            let changed_intent = CleanupIntent { content_fact: changed.content_fact, ..selected.clone() };
            let changed_fact = executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent {
                token,
                item: operations::model::ItemId(0),
                intent: changed_intent.clone(),
            };
            let attempt_before = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).expect("accepted in-memory Partial terminal remains available"));
            assert_eq!(attempt_before.state, operations::journal::JournalState::Terminal);
            assert_eq!(attempt_before.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Partial));
            assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.pending_directory_move_replace_rename_cleanup_transition(token, &selected, false)));
            assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.pending_directory_move_replace_rename_cleanup_transition(token, &selected, true)));
            assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.pending_directory_move_replace_rename_cleanup_transition(token, &changed_intent, false)));
            assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.directory_move_replace_rename_backup_complete_pending(token)));
            let queued_token = queued_copy.as_ref().expect("queued successor remains behind E7").0;
            let queued_before = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(queued_token).expect("queued successor snapshot"));
            let predecessor_bytes = std::fs::read(&journal_path).unwrap();
            assert_eq!(predecessor_bytes, terminal_predecessor.as_ref().unwrap().1);

            // Swap in an observing writer only while the two stale facts are
            // pumped. Any attempted JournalWriter submission is visible here.
            let (observing_writer, driver) = operations::journal::JournalWriter::test_driver();
            visual.update(|_, cx| cx.update_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.journal = Some(observing_writer)));
            let sender = stale_fact_sender.lock().unwrap().take().expect("retain the original worker fact route");
            while cancel_forwarded_rx.try_recv().is_ok() {}
            sender.publish(exact_fact);
            sender.publish(changed_fact);
            visual.run_until_parked();
            assert!(driver.try_command().is_none(), "terminal cleanup replays submit no journal writes");
            visual.update(|_, cx| cx.update_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.journal = Some(real_writer.clone())));
            assert_eq!(std::fs::read(&journal_path).unwrap(), predecessor_bytes,
                "stale exact and discriminator-mismatched cleanup facts preserve predecessor bytes");
            assert_eq!(real_writer.read_attempt(attempt_before.key.clone()).recv_blocking().unwrap().unwrap().unwrap(),
                terminal_predecessor.as_ref().unwrap().0,
                "durable A remains the exact Running/BackupCleanup predecessor");
            assert_eq!(visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(token).unwrap()), attempt_before,
                "stale cleanup facts do not mutate A's terminal Runtime snapshot");
            assert_eq!(visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.journal_attempt(queued_token).unwrap()), queued_before,
                "stale cleanup facts do not change queued B");
            assert!(!queued_copy.as_ref().unwrap().2.exists());
            assert_eq!(queued_copy_worker_state.load(std::sync::atomic::Ordering::Acquire), 0,
                "stale cleanup facts do not start queued B early");
            assert!(cancel_forwarded_rx.try_recv().is_err(), "stale cleanup facts send no worker cancellation");
        }
        let readback = real_writer.read_attempt(terminal_attempt.key.clone()).recv_blocking().unwrap().unwrap().unwrap();
        if let Some(cancel_phase) = cancellation_phase {
            let expected_outcome = if cancel_phase == E7Phase::DisplaceIntent {
                operations::journal::JournalTerminalOutcome::Cancelled
            } else {
                operations::journal::JournalTerminalOutcome::Partial
            };
            if terminal_refused {
                let predecessor = &terminal_predecessor.as_ref().unwrap().0;
                assert_eq!(readback, *predecessor, "refused Partial terminal leaves exact Running/BackupCleanup predecessor durable");
                assert_eq!(std::fs::read(&journal_path).unwrap(), terminal_predecessor.as_ref().unwrap().1);
            } else {
                assert_eq!(readback, terminal_attempt, "real JournalWriter readback is the exact E7 cancellation terminal");
                assert_eq!(readback.state, operations::journal::JournalState::Terminal);
                assert_eq!(readback.terminal_outcome, Some(expected_outcome));
            }
            let e7 = if terminal_refused {
                terminal_attempt.directory_move_replace_rename.as_ref().expect("Runtime terminal retains typed E7 cleanup ledger")
            } else {
                readback.directory_move_replace_rename.as_ref().expect("terminal retains exact E7 ledger")
            };
            let expected_phase = match cancel_phase {
                E7Phase::DisplaceIntent => E7Phase::NoEffect,
                E7Phase::TargetDisplaced => E7Phase::TargetDisplaced,
                E7Phase::DestinationPublished if cleanup_cancel => E7Phase::BackupCleanup,
                E7Phase::DestinationPublished => E7Phase::DestinationPublished,
                _ => unreachable!(),
            };
            assert_eq!(e7.phase, expected_phase);
            if cancel_phase == E7Phase::DestinationPublished {
                assert_eq!(e7.source_location, operations::journal::DirectoryMoveReplaceSourceLocation::Published);
                assert_eq!(e7.target_location, if root_cleanup_cancel && cleanup_receipt_cancel {
                    operations::journal::DirectoryMoveReplaceTargetLocation::Disposed
                } else {
                    operations::journal::DirectoryMoveReplaceTargetLocation::Backup
                });
                assert_eq!(e7.backup_root_disposed, root_cleanup_cancel && cleanup_receipt_cancel);
            }
            assert!(readback.directory_moves.is_empty());
            assert!(readback.cross_volume_move_replace.is_none());
            let facts = observed_by_worker.lock().unwrap();
            assert!(!facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent {
                    token: fact_token, ledger, ..
                } if *fact_token == token && matches!(ledger.phase,
                    E7Phase::BackupComplete | E7Phase::Complete)
            )), "cancellation emits no backup completion phase");
            if !cleanup_cancel {
                assert!(!facts.iter().any(|fact| matches!(fact,
                    executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { token: fact_token, ledger, .. }
                        if *fact_token == token && ledger.phase == E7Phase::BackupCleanup)),
                    "pre-cleanup cancellation emits no BackupCleanup phase");
            }
            let publication_phases = facts.iter().filter_map(|fact| match fact {
                executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { token: fact_token, ledger, .. }
                    if *fact_token == token && matches!(ledger.phase, E7Phase::PublishIntent | E7Phase::DestinationPublished) => Some(ledger.phase),
                _ => None,
            }).collect::<Vec<_>>();
            if cancel_phase == E7Phase::DestinationPublished {
                assert_eq!(publication_phases, [E7Phase::PublishIntent, E7Phase::DestinationPublished]);
            } else {
                assert!(publication_phases.is_empty(), "pre-publication cancellation emits no publication phase");
            }
            if cleanup_cancel {
                let selected = selected_cleanup.lock().unwrap().clone().unwrap();
                assert!(facts.iter().any(|fact| matches!(fact,
                    executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { token: fact_token, ledger, .. }
                        if *fact_token == token && ledger.phase == E7Phase::BackupCleanup)),
                    "the cleanup phase is emitted before the selected child intent/receipt");
                if !root_cleanup_cancel {
                    assert!(!facts.iter().any(|fact| matches!(fact,
                        executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, intent, .. }
                        | executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, intent, .. }
                            if *fact_token == token && intent.relative_components.is_empty())),
                        "backup root cleanup is not emitted before child cleanup finishes");
                }
                let intents = facts.iter().filter_map(|fact| match fact {
                    executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, item, intent }
                        if *fact_token == token && *item == operations::model::ItemId(0) => Some(intent.clone()),
                    _ => None,
                }).collect::<Vec<_>>();
                let dispositions = facts.iter().filter_map(|fact| match fact {
                    executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, item, intent }
                        if *fact_token == token && *item == operations::model::ItemId(0) => Some(intent.clone()),
                    _ => None,
                }).collect::<Vec<_>>();
                assert!(intents.contains(&selected), "selected cleanup intent was emitted");
                if cleanup_intent_cancel {
                    assert!(!dispositions.contains(&selected), "intent ACK cancellation precedes native disposition");
                } else {
                    assert!(dispositions.contains(&selected), "receipt ACK cancellation follows native disposition fact");
                }
                if root_cleanup_cancel {
                    assert_eq!(intents.iter().filter(|intent| *intent == &selected).count(), 1,
                        "the approved backup root receives exactly one cleanup intent");
                    assert_eq!(dispositions.iter().filter(|intent| *intent == &selected).count(),
                        usize::from(cleanup_receipt_cancel),
                        "only the root receipt selector records a root disposition");
                }
            } else {
                assert!(!facts.iter().any(|fact| matches!(fact,
                    executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, .. }
                    | executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, .. }
                        if *fact_token == token
                )), "pre-cleanup cancellation emits no backup cleanup intent or disposition");
            }
            assert!(!facts.iter().any(|fact| matches!(fact,
                executor::ExecutorFact::DirectoryMoveReplaceRenameBackupComplete { token: fact_token, .. }
                    if *fact_token == token
            )), "cancellation emits no BackupComplete fact");
            drop(facts);

            let source_snapshot = source_cancel_snapshot.as_ref().unwrap();
            let target_snapshot = target_cancel_snapshot.as_ref().unwrap();
            let backup = {
                use std::os::windows::ffi::OsStringExt;
                PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units))
            };
            if cancel_phase == E7Phase::DisplaceIntent {
                assert_eq!(snapshot_e7_tree(&destination), *target_snapshot);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                assert!(!backup.exists());
            } else if cancel_phase == E7Phase::TargetDisplaced {
                assert_eq!(snapshot_e7_tree(&source), *source_snapshot);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                assert!(!destination.exists());
                assert_eq!(snapshot_e7_tree(&backup), *target_snapshot);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
            } else if cleanup_cancel {
                assert!(!source.exists());
                assert_eq!(snapshot_e7_tree(&destination), *source_snapshot);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                if !root_cleanup_cancel || cleanup_intent_cancel {
                    assert!(backup.is_dir());
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                }
                let selected = selected_cleanup.lock().unwrap().clone().unwrap();
                if root_cleanup_cancel {
                    assert_eq!(e7.pending_cleanup.as_ref(), cleanup_intent_cancel.then_some(&selected));
                    assert_eq!(e7.backup_root_disposed, cleanup_receipt_cancel);
                    assert_eq!(e7.approved_target_children.iter().filter(|child| child.disposition_recorded).count(),
                        e7.approved_target_children.len());
                    if !cleanup_receipt_cancel {
                        assert_eq!(snapshot_e7_tree(&backup),
                            expected_e7_backup_after_receipts(target_snapshot, &e7.approved_target_children),
                            "root intent preserves the empty, approved backup directory");
                        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                            &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    }
                } else {
                let b_index = e7.approved_target_children.iter()
                    .position(|child| child.ordinal == selected.ordinal).unwrap();
                let a = e7.approved_target_children[..b_index].iter().rev()
                    .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                    .expect("A precedes B in the approved manifest");
                let c = e7.approved_target_children[b_index + 1..].iter()
                    .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                    .expect("C follows B in the approved manifest");
                assert!(a.disposition_recorded, "A has a durable cleanup receipt before B");
                assert_eq!(e7.approved_target_children[b_index].disposition_recorded,
                    terminal_scenario == E7TerminalScenario::CancelAtBackupCleanupReceipt);
                assert!(!c.disposition_recorded, "later C remains untouched");
                assert_eq!(e7.pending_cleanup.as_ref(),
                    matches!(terminal_scenario,
                        E7TerminalScenario::CancelAtBackupCleanupIntent
                        | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused).then_some(&selected));
                assert!(!e7.backup_root_disposed);
                let expected_backup = expected_e7_backup_after_receipts(target_snapshot, &e7.approved_target_children);
                assert_eq!(snapshot_e7_tree(&backup), expected_backup,
                    "backup tree equals manifest with only receipted entries removed");
                assert!(e7_child_path(&backup, &c.relative_components).is_file(),
                    "later C remains present in the retained backup");
                if terminal_scenario == E7TerminalScenario::CancelAtBackupCleanupReceipt {
                    assert!(!e7_child_path(&backup, &selected.relative_components).exists(),
                        "B absence is checked only after native return");
                }
                }
            } else {
                assert!(!source.exists());
                assert_eq!(snapshot_e7_tree(&destination), *source_snapshot);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                assert_eq!(snapshot_e7_tree(&backup), *target_snapshot);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
            }
            let terminal_bytes = std::fs::read(&journal_path).unwrap();
            for _ in 0..2 {
                let fresh = operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap());
                assert!(fresh.runtime.jobs().is_empty(), "fresh owner does not replay the E7 cancellation");
                let (reserved, undo) = fresh.runtime.undo_snapshot_for_test();
                assert!(!reserved && undo.is_empty(), "fresh owner creates no Undo authority");
                if cancel_phase != E7Phase::DisplaceIntent {
                    assert_eq!(fresh.recovery_records.len(), 1);
                    assert_eq!(fresh.recovery_records[0].state, operations::journal::JournalState::RecoveryRequired);
                    assert_eq!(fresh.recovery_records[0].directory_move_replace_rename.as_ref(), Some(e7));
                } else {
                    assert!(fresh.recovery_records.is_empty(), "durable NoEffect cancellation requires no reinspection");
                }
                assert_eq!(std::fs::read(&journal_path).unwrap(), terminal_bytes,
                    "fresh owner leaves the exact durable E7 journal bytes unchanged");
                assert_eq!(real_writer.read_attempt(terminal_attempt.key.clone()).recv_blocking().unwrap().unwrap().unwrap(), readback,
                    "each fresh owner retains the exact terminal JournalWriter ledger");
                if cleanup_cancel {
                    assert_eq!(snapshot_e7_tree(&destination), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    let selected = selected_cleanup.lock().unwrap().clone().unwrap();
                    if root_cleanup_cancel {
                        assert_eq!(e7.backup_root_disposed, cleanup_receipt_cancel);
                        assert_eq!(e7.pending_cleanup.as_ref(), cleanup_intent_cancel.then_some(&selected));
                        assert!(e7.approved_target_children.iter().all(|child| child.disposition_recorded));
                        if cleanup_intent_cancel {
                            assert_eq!(snapshot_e7_tree(&backup),
                                expected_e7_backup_after_receipts(target_snapshot, &e7.approved_target_children));
                            assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                                &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                        }
                    } else {
                    assert_eq!(snapshot_e7_tree(&backup),
                        expected_e7_backup_after_receipts(target_snapshot, &e7.approved_target_children));
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    let b_index = e7.approved_target_children.iter()
                        .position(|child| child.ordinal == selected.ordinal).unwrap();
                    let c = e7.approved_target_children[b_index + 1..].iter()
                        .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                        .expect("C follows B in approved manifest");
                    let c_path = e7_child_path(&backup, &c.relative_components);
                    assert!(c_path.is_file(), "later manifest entry C remains present");
                    if terminal_scenario == E7TerminalScenario::CancelAtBackupCleanupReceipt {
                        assert!(!e7_child_path(&backup, &selected.relative_components).exists(),
                            "B is absent after native return and remains absent on reopen");
                    }
                    }
                }
            }

            let job_terminal = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.runtime.job(token).unwrap().attempts.iter()
                    .find(|attempt| attempt.token == token).unwrap().terminal.clone().unwrap());
            if cancel_phase == E7Phase::DisplaceIntent {
                assert_eq!(job_terminal.outcome, operations::model::TerminalOutcome::Cancelled);
            } else {
                assert_eq!(job_terminal.outcome, operations::model::TerminalOutcome::Partial);
                assert_eq!(job_terminal.retry, operations::model::RetryPlan::RequiresReinspection);
            }
            assert!(!queued_copy.as_ref().unwrap().2.exists(),
                "queued Copy remains inert through durable terminal readback and native join");

            test_release_return_tx.send_blocking(()).expect("release native return after exact terminal and fresh-owner assertions");
            let release_deadline = Instant::now() + Duration::from_secs(30);
            while visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.worker_claimed_for_test())
                && queued_copy_worker_state.load(std::sync::atomic::Ordering::Acquire) == 0
            {
                visual.run_until_parked();
                if Instant::now() >= release_deadline {
                    let queued_token = queued_copy.as_ref().unwrap().0;
                    let diagnostic = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                        let running = owner.runtime.active_job().and_then(|job| job.attempts.last().map(|attempt| attempt.token));
                        let published_inspection = owner.runtime.latest_published_move_inspection(token)
                            .map(|(ticket, result)| (ticket, result.is_some()));
                        let queued_state = owner.runtime.job(queued_token)
                            .and_then(|job| job.attempts.last().map(|attempt| attempt.state));
                        (owner.worker_claimed_for_test(), running, published_inspection, queued_state)
                    });
                    panic!(
                        "E7 cancellation lane did not release after native join (native_joined={native_joined}, return_released=true, owner/Runtime/B={diagnostic:?}, queued_worker_state={})",
                        queued_copy_worker_state.load(std::sync::atomic::Ordering::Acquire),
                    );
                }
                std::thread::sleep(Duration::from_millis(1));
            }
            assert!(
                !visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.worker_claimed_for_test())
                    || queued_copy_worker_state.load(std::sync::atomic::Ordering::Acquire) > 0,
                "the lane must be idle or already running queued B after A's native return",
            );
            if root_cleanup_cancel {
                assert!(!source.exists());
                assert_eq!(snapshot_e7_tree(&destination), *source_snapshot);
                assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                let backup = {
                    use std::os::windows::ffi::OsStringExt;
                    PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units))
                };
                if cleanup_intent_cancel {
                    assert_eq!(snapshot_e7_tree(&backup),
                        expected_e7_backup_after_receipts(target_snapshot, &e7.approved_target_children));
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    assert!(backup.is_dir(), "root intent cancellation retains the approved empty backup root");
                } else {
                    assert!(!backup.exists(), "native worker return closes the held root handle and removes the backup root");
                }
            }
            let (queued_token, source_copy, copy_output, _, _, _, _) = queued_copy.take().unwrap();
            let copy_deadline = Instant::now() + Duration::from_secs(45);
            loop {
                visual.run_until_parked();
                if let Some(attempt) = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.journal_attempt(queued_token).filter(|attempt|
                        attempt.state == operations::journal::JournalState::Terminal)) {
                    assert_eq!(attempt.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
                    assert_eq!(real_writer.read_attempt(attempt.key.clone()).recv_blocking().unwrap().unwrap().unwrap(), attempt);
                    break;
                }
                assert!(Instant::now() < copy_deadline, "queued Copy did not complete after E7 terminal and native join");
                std::thread::sleep(Duration::from_millis(1));
            }
            assert_eq!(std::fs::read(&copy_output).unwrap(), b"queued copy remains behind the E7 lane");
            assert_eq!(std::fs::read(source_copy).unwrap(), b"queued copy remains behind the E7 lane");
            let post_queue_journal_bytes = std::fs::read(&journal_path).unwrap();
            for _ in 0..2 {
                let fresh = operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap());
                assert!(fresh.runtime.jobs().is_empty(), "post-queue fresh owner does not replay E7");
                let (reserved, undo) = fresh.runtime.undo_snapshot_for_test();
                assert!(!reserved && undo.is_empty(), "post-queue fresh owner has no Undo authority");
                if cancel_phase != E7Phase::DisplaceIntent {
                    assert_eq!(fresh.recovery_records.len(), 1);
                    assert_eq!(fresh.recovery_records[0].state, operations::journal::JournalState::RecoveryRequired);
                    assert_eq!(fresh.recovery_records[0].directory_move_replace_rename.as_ref(), Some(e7));
                } else {
                    assert!(fresh.recovery_records.is_empty());
                }
                assert_eq!(real_writer.read_attempt(terminal_attempt.key.clone()).recv_blocking().unwrap().unwrap().unwrap(), readback,
                    "post-queue reopen retains the exact terminal record");
                assert_eq!(std::fs::read(&journal_path).unwrap(), post_queue_journal_bytes,
                    "post-queue owner construction does not rewrite exact journal bytes");
                if cancel_phase == E7Phase::DisplaceIntent {
                    assert_eq!(snapshot_e7_tree(&source), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    assert_eq!(snapshot_e7_tree(&destination), *target_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    assert!(!backup.exists());
                } else if cancel_phase == E7Phase::TargetDisplaced {
                    assert_eq!(snapshot_e7_tree(&source), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    assert!(!destination.exists());
                    assert_eq!(snapshot_e7_tree(&backup), *target_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                } else if cleanup_cancel {
                    assert!(!source.exists());
                    assert_eq!(snapshot_e7_tree(&destination), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    let selected = selected_cleanup.lock().unwrap().clone().unwrap();
                    if root_cleanup_cancel {
                        assert_eq!(e7.backup_root_disposed, cleanup_receipt_cancel);
                        assert_eq!(e7.pending_cleanup.as_ref(), cleanup_intent_cancel.then_some(&selected));
                        assert!(e7.approved_target_children.iter().all(|child| child.disposition_recorded));
                        if cleanup_receipt_cancel {
                            assert!(!backup.exists(), "fresh RecoveryRequired owner observes the disposed approved root");
                        } else {
                            assert_eq!(snapshot_e7_tree(&backup),
                                expected_e7_backup_after_receipts(target_snapshot, &e7.approved_target_children));
                            assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                                &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                        }
                    } else {
                    assert_eq!(snapshot_e7_tree(&backup),
                        expected_e7_backup_after_receipts(target_snapshot, &e7.approved_target_children));
                    assert!(backup.is_dir());
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                    let b_index = e7.approved_target_children.iter()
                        .position(|child| child.ordinal == selected.ordinal).unwrap();
                    let c = e7.approved_target_children[b_index + 1..].iter()
                        .find(|child| child.node_kind == operations::journal::JournalDirectoryNodeKind::File)
                        .expect("C follows B in approved manifest");
                    assert!(e7_child_path(&backup, &c.relative_components).is_file());
                    if terminal_scenario == E7TerminalScenario::CancelAtBackupCleanupReceipt {
                        assert!(!e7_child_path(&backup, &selected.relative_components).exists());
                    }
                    }
                } else {
                    assert!(!source.exists());
                    assert_eq!(snapshot_e7_tree(&destination), *source_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
                    assert_eq!(snapshot_e7_tree(&backup), *target_snapshot);
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                }
                assert_eq!(std::fs::read(&copy_output).unwrap(), b"queued copy remains behind the E7 lane",
                    "queued Copy remains the only expected independent filesystem effect");
                drop(fresh);
            }
            fixture_reaper.complete();
            return;
        }
        if terminal_scenario != E7TerminalScenario::Normal {
            let (predecessor, predecessor_bytes) = terminal_predecessor.take().unwrap();
            let e7 = predecessor.directory_move_replace_rename.as_ref().expect("durable E7 Complete predecessor");
            assert_eq!(e7.phase, E7Phase::Complete);
            assert!(!source.exists());
            assert!(!destination.join("nested/displaced.bin").exists());
            assert!(!destination.join("root.txt").exists());
            assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
            assert_eq!(std::fs::read(destination.join("nested/source.bin")).unwrap(), b"incoming source payload");
            assert!(destination.join("empty").is_dir());
            assert_eq!(std::fs::read(&sentinel).unwrap(), b"unrelated sentinel");
            assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                &sentinel, crate::directory::EntryKind::File).unwrap().filesystem_identity(), sentinel_identity);
            let backup = {
                use std::os::windows::ffi::OsStringExt;
                PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units))
            };
            assert!(!backup.exists(), "Complete E7 has already removed the displaced backup");

            match terminal_scenario {
                E7TerminalScenario::Refused => {
                    assert_eq!(readback, predecessor, "refused terminal leaves exact Running+Complete predecessor durable");
                    assert_eq!(std::fs::read(&journal_path).unwrap(), predecessor_bytes);
                    for _ in 0..2 {
                        let fresh = operations::application::OperationApplicationOwner::for_test_with_journal_store(
                            operations::journal::JournalStore::open(journal_path.clone()).unwrap());
                        assert_eq!(fresh.recovery_records.len(), 1);
                        assert_eq!(fresh.recovery_records[0].state, operations::journal::JournalState::RecoveryRequired);
                        assert_eq!(fresh.recovery_records[0].directory_move_replace_rename.as_ref(), Some(e7));
                        assert!(fresh.runtime.jobs().is_empty(), "RecoveryRequired is inspection-only");
                        let (reserved, undo) = fresh.runtime.undo_snapshot_for_test();
                        assert!(!reserved && undo.is_empty(), "durable Running predecessor creates no restart Undo");
                        assert_eq!(std::fs::read(&journal_path).unwrap(), predecessor_bytes);
                    }
                }
                E7TerminalScenario::LostReply => {
                    assert_eq!(readback, terminal_attempt, "lost Shell reply leaves exact durable Terminal/Succeeded");
                    assert_eq!(readback.state, operations::journal::JournalState::Terminal);
                    assert_eq!(readback.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
                    for _ in 0..2 {
                        let fresh = operations::application::OperationApplicationOwner::for_test_with_journal_store(
                            operations::journal::JournalStore::open(journal_path.clone()).unwrap());
                        assert!(fresh.recovery_records.is_empty());
                        assert!(fresh.runtime.jobs().is_empty(), "durable terminal does not replay the E7 Move");
                        let (reserved, undo) = fresh.runtime.undo_snapshot_for_test();
                        assert!(!reserved && undo.is_empty(), "durable terminal creates no restart Undo");
                    }
                }
                E7TerminalScenario::Normal
                | E7TerminalScenario::CancelAtDisplaceIntent
                | E7TerminalScenario::CancelAtTargetDisplaced
                | E7TerminalScenario::CancelAtDestinationPublished
                | E7TerminalScenario::CancelAtBackupCleanupIntent
                | E7TerminalScenario::CancelAtBackupCleanupIntentTerminalRefused
                | E7TerminalScenario::CancelAtBackupCleanupReceipt
                | E7TerminalScenario::CancelAtBackupRootCleanupIntent
                | E7TerminalScenario::CancelAtBackupRootCleanupReceipt => unreachable!(),
            }

            test_release_return_tx.send_blocking(()).expect("release E7 worker return after durable projection assertions");
            let release_deadline = Instant::now() + Duration::from_secs(30);
            while visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.worker_claimed_for_test()) {
                visual.run_until_parked();
                assert!(Instant::now() < release_deadline, "E7 lane did not release after native return");
                std::thread::sleep(Duration::from_millis(1));
            }
            let (queued_token, source_copy, copy_output, _, _, _, _) = queued_copy.take().unwrap();
            let copy_deadline = Instant::now() + Duration::from_secs(45);
            loop {
                visual.run_until_parked();
                if let Some(attempt) = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.journal_attempt(queued_token).filter(|attempt| attempt.state == operations::journal::JournalState::Terminal)) {
                    assert_eq!(attempt.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
                    assert_eq!(real_writer.read_attempt(attempt.key.clone()).recv_blocking().unwrap().unwrap().unwrap(), attempt);
                    break;
                }
                assert!(Instant::now() < copy_deadline, "queued Copy did not complete after terminal resolution and native return");
                std::thread::sleep(Duration::from_millis(1));
            }
            assert_eq!(std::fs::read(copy_output).unwrap(), b"queued copy remains behind the E7 lane");
            assert_eq!(std::fs::read(source_copy).unwrap(), b"queued copy remains behind the E7 lane");
            fixture_reaper.complete();
            return;
        }
        assert_eq!(readback, terminal_attempt, "real JournalWriter retains exact terminal E7 ledger");
        let e7 = readback.directory_move_replace_rename.as_ref().expect("E7 ledger is durable");
        if let Some((failed_intent, failed_receipt, predecessor)) = failed_cleanup_checkpoint.as_ref() {
            assert_eq!(readback.state, operations::journal::JournalState::Terminal);
            assert_eq!(readback.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Partial));
            assert!(readback.receipts_recorded);
            assert_eq!(e7.phase, E7Phase::BackupCleanup);
            assert_eq!(e7.source_location, operations::journal::DirectoryMoveReplaceSourceLocation::Published);
            assert_eq!(e7.target_location, operations::journal::DirectoryMoveReplaceTargetLocation::Backup);
            assert!(!e7.backup_root_disposed);
            assert_eq!(e7.pending_cleanup.as_ref(), (*failed_receipt).then_some(failed_intent),
                "receipt refusal retains its exact pending intent; intent refusal does not invent one");
            if !root_cleanup_selected {
                let first_child = e7.approved_target_children.first().expect("approved backup manifest has a child");
                assert_eq!(failed_intent.ordinal, first_child.ordinal);
                assert_eq!(failed_intent.node_kind, first_child.node_kind);
                assert_eq!(failed_intent.relative_components, first_child.relative_components);
                assert_eq!(failed_intent.identity, first_child.identity);
                assert_eq!(failed_intent.content_fact, first_child.content_fact);
                assert!(!first_child.disposition_recorded,
                    "the refused receipt is absent from durable child disposition evidence");
            } else {
                assert!(e7.approved_target_children.iter().all(|child| child.disposition_recorded),
                    "root cleanup is attempted only after all child receipts");
            }
            assert!(readback.cross_volume_move_replace.is_none());
            assert!(readback.directory_moves.is_empty());
            assert!(readback.copy_replace_cleanups.is_empty());
            assert!(readback.copy_directory_stage.is_none());

            use std::os::windows::ffi::OsStringExt;
            let backup = PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units));
            match cleanup_write_refusal {
                E7CleanupWriteRefusal::FirstChildIntent | E7CleanupWriteRefusal::FirstChildReceipt => {
                    let mut expected = expected_e7_backup_after_receipts(
                        target_cancel_snapshot.as_ref().unwrap(), &e7.approved_target_children);
                    if *failed_receipt {
                        expected.retain(|(relative, _, _, _)| relative != &e7_child_path(Path::new(""), &failed_intent.relative_components));
                    }
                    assert_eq!(snapshot_e7_tree(&backup), expected,
                        "child refusal leaves only nodes actually disposed before the refused write");
                    assert!(backup.is_dir());
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                }
                E7CleanupWriteRefusal::BackupRootIntent => {
                    assert_eq!(snapshot_e7_tree(&backup), Vec::new(), "root intent refusal leaves the emptied root in place");
                    assert!(backup.is_dir());
                    assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
                        &backup, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), target_identity);
                }
                E7CleanupWriteRefusal::BackupRootReceipt => assert!(!backup.exists(), "root receipt refusal follows native root disposition"),
                E7CleanupWriteRefusal::None => unreachable!(),
            }
            assert!(!source.exists());
            assert_eq!(
                crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination,
                    crate::directory::EntryKind::Folder,
                ).unwrap().filesystem_identity(),
                source_identity,
                "the published incoming source remains at its destination",
            );
            assert_eq!(std::fs::read(destination.join("nested/source.bin")).unwrap(), b"incoming source payload");
            assert!(destination.join("empty").is_dir());
            assert_eq!(std::fs::read(&sentinel).unwrap(), b"unrelated sentinel");

            let (terminal_report, undo) = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                let attempt = owner.runtime.job(token).unwrap().attempts.into_iter()
                    .find(|attempt| attempt.token == token).expect("Shell retains the exact terminal attempt");
                (attempt.terminal.expect("Partial report is retained"), owner.runtime.undo_snapshot_for_test())
            });
            assert_eq!(terminal_report.outcome, operations::model::TerminalOutcome::Partial);
            assert_eq!(terminal_report.retry, operations::model::RetryPlan::RequiresReinspection);
            assert!(terminal_report.receipts.iter().all(|receipt| receipt.move_receipt.is_none()));
            assert!(!undo.0 && undo.1.is_empty(), "the partial Move creates no Undo authority");
            let terminal_bytes = std::fs::read(&journal_path).unwrap();
            assert_ne!(terminal_bytes, *predecessor, "the released writer persists the exact Partial terminal after refusal");

            let terminal_store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
            let recoveries = terminal_store.recoveries();
            let [operations::journal::RecoveryItem::RecoveryRequired(recovery)] = recoveries.as_slice() else {
                panic!("durable cleanup refusal reopens as one RecoveryRequired record");
            };
            let recovery = recovery.clone();
            assert_eq!(recovery.state, operations::journal::JournalState::RecoveryRequired);
            assert_eq!(recovery.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Partial));
            assert_eq!(recovery.directory_move_replace_rename.as_ref(), Some(e7));
            drop(terminal_store);
            let backup_snapshot = backup.exists().then(|| snapshot_e7_tree(&backup));
            let destination_snapshot = snapshot_e7_tree(&destination);
            let sentinel_bytes = std::fs::read(&sentinel).unwrap();
            for _ in 0..2 {
                let fresh = operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap(),
                );
                assert_eq!(fresh.recovery_records, [recovery.clone()]);
                assert!(fresh.runtime.jobs().is_empty(), "RecoveryRequired does not replay the Move or cleanup");
                let (reserved, undo) = fresh.runtime.undo_snapshot_for_test();
                assert!(!reserved && undo.is_empty(), "fresh owners receive no restart Undo authority");
                assert_eq!(std::fs::read(&journal_path).unwrap(), terminal_bytes,
                    "inspection-only reopen leaves the durable terminal bytes unchanged");
                assert_eq!(backup.exists(), backup_snapshot.is_some());
                if let Some(expected) = backup_snapshot.as_ref() {
                    assert_eq!(snapshot_e7_tree(&backup), *expected,
                        "inspection-only reopen leaves backup identities and content unchanged");
                }
                assert_eq!(snapshot_e7_tree(&destination), destination_snapshot,
                    "inspection-only reopen leaves the published destination unchanged");
                assert_eq!(std::fs::read(&sentinel).unwrap(), sentinel_bytes,
                    "inspection-only reopen leaves unrelated sentinel bytes unchanged");
                drop(fresh);
            }
            test_release_return_tx.send_blocking(()).expect("release joined worker return after durable failure assertions");
            let (queued_token, source_copy, copy_output, _, _, _, _) = queued_copy.take().unwrap();
            let copy_deadline = Instant::now() + Duration::from_secs(45);
            loop {
                visual.run_until_parked();
                if let Some(attempt) = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.journal_attempt(queued_token).filter(|attempt| attempt.state == operations::journal::JournalState::Terminal)) {
                    assert_eq!(attempt.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
                    assert_eq!(real_writer.read_attempt(attempt.key.clone()).recv_blocking().unwrap().unwrap().unwrap(), attempt);
                    break;
                }
                assert!(Instant::now() < copy_deadline, "queued Copy did not complete after the E7 worker returned");
                std::thread::sleep(Duration::from_millis(1));
            }
            assert_eq!(std::fs::read(copy_output).unwrap(), b"queued copy remains behind the E7 lane");
            assert_eq!(std::fs::read(source_copy).unwrap(), b"queued copy remains behind the E7 lane");
            fixture_reaper.complete();
            return;
        }
        assert_eq!(e7.phase, E7Phase::Complete);
        assert_eq!(e7.approved_target_identity, {
            let (volume, index) = target_identity.windows_parts().unwrap();
            format!("{volume}:{index:016x}")
        });
        assert!(readback.cross_volume_move_replace.is_none());
        assert!(readback.directory_moves.is_empty());
        assert!(readback.copy_replace_cleanups.is_empty());
        assert!(readback.copy_directory_stage.is_none());
        let facts = observed.lock().unwrap();
        let phases = facts.iter().filter_map(|fact| match fact {
            executor::ExecutorFact::DirectoryMoveReplaceRenamePhaseIntent { token: fact_token, ledger, .. }
                if *fact_token == token && ledger.phase != E7Phase::Prepared => Some(ledger.phase),
            executor::ExecutorFact::DirectoryMoveReplaceRenameBackupComplete { token: fact_token, .. }
                if *fact_token == token => Some(E7Phase::BackupComplete),
            _ => None,
        }).collect::<Vec<_>>();
        assert_eq!(phases, [E7Phase::DisplaceIntent, E7Phase::TargetDisplaced, E7Phase::PublishIntent,
            E7Phase::DestinationPublished, E7Phase::BackupCleanup, E7Phase::BackupComplete, E7Phase::Complete]);
        let cleanup = facts.iter().filter_map(|fact| match fact {
            executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupIntent { token: fact_token, intent, .. } if *fact_token == token => Some((false, intent.clone())),
            executor::ExecutorFact::DirectoryMoveReplaceRenameCleanupDisposition { token: fact_token, intent, .. } if *fact_token == token => Some((true, intent.clone())),
            _ => None,
        }).collect::<Vec<_>>();
        let expected_cleanup = e7.approved_target_children.iter().map(|child| {
            operations::journal::JournalDirectoryMoveReplaceRenameChildIntent {
                ordinal: child.ordinal,
                node_kind: child.node_kind,
                relative_components: child.relative_components.clone(),
                identity: child.identity.clone(),
                content_fact: child.content_fact.clone(),
            }
        }).collect::<Vec<_>>();
        assert!(expected_cleanup.windows(2).all(|pair|
            pair[0].relative_components.len() >= pair[1].relative_components.len()),
            "approved backup cleanup manifest is deepest-first");
        assert_eq!(cleanup.len(), expected_cleanup.len() * 2 + 2);
        for (pair, expected) in cleanup.chunks_exact(2).zip(expected_cleanup.iter()) {
            assert!(!pair[0].0 && pair[1].0, "cleanup receipt follows exact intent");
            assert_eq!(&pair[0].1, expected);
            assert_eq!(&pair[1].1, expected);
        }
        for pair in cleanup.chunks_exact(2).take(expected_cleanup.len()) {
            assert!(!pair[0].1.relative_components.is_empty(), "manifest child cleanup is below the backup root");
        }
        let root_cleanup = &cleanup[expected_cleanup.len() * 2..];
        assert!(!root_cleanup[0].0 && root_cleanup[1].0);
        assert_eq!(root_cleanup[0].1, root_cleanup[1].1);
        assert!(root_cleanup[0].1.relative_components.is_empty(), "final cleanup pair disposes the approved backup root");
        assert_eq!(root_cleanup[0].1.node_kind, operations::journal::JournalDirectoryNodeKind::Directory);
        assert_eq!(root_cleanup[0].1.identity, e7.approved_target_identity);
        assert!(e7.backup_root_disposed, "backup root cleanup is durably complete");
        let backup = {
            use std::os::windows::ffi::OsStringExt;
            PathBuf::from(std::ffi::OsString::from_wide(&e7.backup.units))
        };
        drop(facts);

        assert!(!source.exists());
        assert!(!backup.exists());
        assert!(destination.is_dir());
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(&destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_identity);
        let destination_inventory = {
            fn visit(root: &std::path::Path, path: &std::path::Path, out: &mut Vec<(PathBuf, Vec<u8>)>) {
                for entry in std::fs::read_dir(path).unwrap() {
                    let entry = entry.unwrap();
                    let child = entry.path();
                    let relative = child.strip_prefix(root).unwrap().to_path_buf();
                    if entry.file_type().unwrap().is_dir() {
                        out.push((relative.clone(), Vec::new()));
                        visit(root, &child, out);
                    } else {
                        out.push((relative, std::fs::read(child).unwrap()));
                    }
                }
            }
            let mut entries = Vec::new();
            visit(&destination, &destination, &mut entries);
            entries.sort_by(|a, b| a.0.cmp(&b.0));
            entries
        };
        assert_eq!(destination_inventory, source_inventory);
        assert_eq!(std::fs::read(&sentinel).unwrap(), b"unrelated sentinel");
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(&sentinel, crate::directory::EntryKind::File).unwrap().filesystem_identity(), sentinel_identity);
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(&source_parent, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), source_parent_identity);
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(&destination_parent, crate::directory::EntryKind::Folder).unwrap().filesystem_identity(), destination_parent_identity);

        if shell_lifecycle == E7ShellLifecycle::KeepOrigin {
            let listing_deadline = Instant::now() + Duration::from_secs(20);
            loop {
                visual.run_until_parked();
                let source_reconciled = visual.read_entity(&source_view, |view, _| {
                    view.location().as_ref().and_then(Location::path) == Some(source_parent.as_path())
                        && view.session.accepted_scan_ticket().is_some_and(|ticket| {
                            ticket.scan_id > source_scan && ticket.path == source_parent
                        })
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && !view.entries.iter().any(|entry| entry.path.as_deref() == Some(source.as_path()))
                });
                let destination_reconciled = visual.read_entity(&destination_view, |view, _| {
                    view.location().as_ref().and_then(Location::path) == Some(destination_parent.as_path())
                        && view.session.accepted_scan_ticket().is_some_and(|ticket| {
                            ticket.scan_id > destination_scan && ticket.path == destination_parent
                        })
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && view.entries.iter().any(|entry| {
                            entry.path.as_deref() == Some(destination.as_path())
                                && entry.source_identity.as_ref().is_some_and(|identity| {
                                    identity.filesystem_identity() == source_identity
                                })
                        })
                });
                if source_reconciled && destination_reconciled {
                    break;
                }
                assert!(Instant::now() < listing_deadline,
                    "successful E7 terminal did not reconcile both parent listings with the moved root identity");
                std::thread::sleep(Duration::from_millis(2));
            }
        }

        if let Some((_, _, _, survivor_source_view, survivor_destination_view, source_scan, destination_scan)) = queued_copy.as_ref() {
            let survivor_reconcile_deadline = Instant::now() + Duration::from_secs(20);
            loop {
                visual.run_until_parked();
                let source_reconciled = visual.read_entity(survivor_source_view, |view, _|
                    view.session.accepted_scan_ticket().is_some_and(|ticket|
                        ticket.scan_id > *source_scan && ticket.path == source_parent)
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && !view.entries.iter().any(|entry| entry.path.as_deref() == Some(source.as_path())));
                let destination_reconciled = visual.read_entity(survivor_destination_view, |view, _|
                    view.session.accepted_scan_ticket().is_some_and(|ticket|
                        ticket.scan_id > *destination_scan && ticket.path == destination_parent)
                        && view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && view.entries.iter().any(|entry| entry.path.as_deref() == Some(destination.as_path())
                            && entry.source_identity.as_ref().is_some_and(|identity|
                                identity.filesystem_identity() == source_identity)));
                if source_reconciled && destination_reconciled { break; }
                assert!(Instant::now() < survivor_reconcile_deadline,
                    "survivor parent views did not reconcile the completed E7 after origin Shell destruction");
                std::thread::sleep(Duration::from_millis(1));
            }
        }

        if shell_lifecycle == E7ShellLifecycle::DropFinalShell {
            assert!(visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.worker_claimed_for_test()),
                "the owner keeps the E7 lane claimed until native return even with no Shell entity");
        }
        test_release_return_tx.send_blocking(()).expect("release joined worker return after durable and filesystem assertions");
        let released = {
            let until = Instant::now() + Duration::from_secs(20);
            loop {
                visual.run_until_parked();
                let claimed = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.worker_claimed_for_test());
                if !claimed { break true; }
                assert!(Instant::now() < until, "E7 lane did not release after native worker join");
                std::thread::sleep(Duration::from_millis(1));
            }
        };
        assert!(released);
        if let Some((queued_token, source_copy, copy_output, _, _, _, _)) = queued_copy {
            let copy_deadline = Instant::now() + Duration::from_secs(30);
            let mut last_durable = None;
            loop {
                visual.run_until_parked();
                let settled = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.journal_attempt(queued_token).filter(|attempt|
                        attempt.state == operations::journal::JournalState::Terminal));
                if let Some(attempt) = settled {
                    assert_eq!(attempt.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
                    let durable = real_writer.read_attempt(attempt.key.clone()).recv_blocking().unwrap().unwrap().unwrap();
                    if durable == attempt {
                        break;
                    }
                    last_durable = Some((durable.state, durable.terminal_outcome));
                }
                assert!(Instant::now() < copy_deadline,
                    "survivor's queued Copy terminal did not become durable after E7 worker return: last_durable={last_durable:?}");
                std::thread::sleep(Duration::from_millis(1));
            }
            assert_eq!(std::fs::read(copy_output).unwrap(), b"queued copy remains behind the E7 lane");
            assert_eq!(std::fs::read(source_copy).unwrap(), b"queued copy remains behind the E7 lane");
        }
        for _ in 0..2 {
            let fresh = operations::application::OperationApplicationOwner::for_test_with_journal_store(
                operations::journal::JournalStore::open(journal_path.clone()).unwrap(),
            );
            assert!(fresh.recovery_records.is_empty());
            assert!(fresh.runtime.jobs().is_empty());
            let (reserved, undo) = fresh.runtime.undo_snapshot_for_test();
            assert!(!reserved);
            assert!(undo.is_empty(), "fresh owner exposes no restart Undo authority");
        }
        fixture_reaper.complete();
    }

