            let volume = temp_root.join("gpui-filer-test-fixtures");
            std::fs::create_dir_all(&volume).expect("create dedicated persistent test-fixture base");
            let metadata = std::fs::symlink_metadata(&volume).expect("inspect dedicated fixture base");
            assert!(metadata.is_dir() && !metadata.file_type().is_symlink(), "fixture base is an ordinary directory");
            let volume = volume.canonicalize().expect("resolve dedicated fixture base");
            assert!(volume.starts_with(&temp_root));
            let cwd = std::env::current_dir().unwrap().canonicalize().unwrap();
            let profile = std::path::PathBuf::from(std::env::var_os("USERPROFILE").expect("Windows Shell has USERPROFILE"))
                .canonicalize().expect("resolve Shell profile route");
            assert!(!volume.starts_with(&cwd) && !cwd.starts_with(&volume), "fixture is disjoint from cwd ancestry");
            assert!(!volume.starts_with(&profile) && !profile.starts_with(&volume), "fixture is disjoint from Shell profile ancestry");
            use std::path::{Component, Prefix};
