        let destination_parent_identity = format!("{:?}", identity(&destination, crate::directory::EntryKind::Folder));
        let fixture_root = source.parent().unwrap().parent().unwrap();
        let event_suffix = journal.parent().unwrap().file_name().unwrap().to_string_lossy();
        let checkpoint_event_name = format!("Local\\GPUI_FILER_COPY_PARTIAL_{event_suffix}_CHECKPOINT");
        let finished_event_name = format!("Local\\GPUI_FILER_COPY_PARTIAL_{event_suffix}_FINISHED");
        let checkpoint_event = ReadyEvent::create(&checkpoint_event_name);
