        wait_for_ready(&checkpoint_event, &child_stderr, &mut child.0, Duration::from_secs(60), "crash child missed exact first-child gate");
        assert!(child.0.try_wait().unwrap().is_none(), "child is live at the held worker callback");
        let cp: serde_json::Value = serde_json::from_slice(&read_ready(&checkpoint)).unwrap();
