        assert_eq!(cp["phase"], "shell-copy-first-file-progress-held-before-next-child-and-publication");
        assert_eq!(cp["source_tree"], serde_json::to_value(&source_before).unwrap());
        assert_eq!(cp["sentinel_tree"], serde_json::to_value(&destination_before).unwrap());
        assert_eq!(cp["source_parent_identity"], source_parent_identity);
        assert_eq!(cp["destination_parent_identity"], destination_parent_identity);
        let running: operations::journal::JournalAttempt = serde_json::from_value(cp["running"].clone()).unwrap();
        assert_eq!(running.state, operations::journal::JournalState::Running);
        let stage = std::path::PathBuf::from(cp["stage"].as_str().unwrap());
