            assert_eq!(gate["phase"], "terminal-command-accepted-before-store-upsert");
            let terminal: operations::journal::JournalAttempt = serde_json::from_value(gate["attempt"].clone()).unwrap();
            assert_eq!(terminal.key, predecessor.key);
            assert_eq!(terminal.state, operations::journal::JournalState::Terminal);
            assert_eq!(terminal.kind, operations::journal::JournalKind::Copy);
            assert_eq!(terminal.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
