    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires a local fixed NTFS test volume"]
    fn ordinary_directory_copy_replace_root_receipt_crash_and_release(cx: &mut gpui::TestAppContext) {
        use std::{process::{Child, Command, Stdio}, thread, time::{Duration, Instant}};
        const MODE: &str = "GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_CHILD_MODE";
        const REACHED: &str = "GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_REACHED";
        const RELEASE: &str = "GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_RELEASE";
        fn journal_path(path: &operations::journal::JournalPath) -> std::path::PathBuf {
            use std::os::windows::ffi::OsStringExt;
            std::path::PathBuf::from(std::ffi::OsString::from_wide(&path.units))
        }
        fn folder_identity(path: &std::path::Path) -> String {
            format!("{:?}", crate::directory::EntrySourceIdentity::from_path_no_follow(
                path, crate::directory::EntryKind::Folder).expect("fixture folder identity").filesystem_identity())
        }
        fn file_evidence(path: &std::path::Path) -> (String, Vec<u8>) {
            let identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
                path, crate::directory::EntryKind::File).expect("fixture file identity").filesystem_identity();
            (format!("{identity:?}"), std::fs::read(path).expect("fixture file bytes"))
        }
        fn fixture_evidence(source: &std::path::Path, destination: &std::path::Path)
            -> (String, String, (String, Vec<u8>), (String, Vec<u8>), (String, Vec<u8>), (String, Vec<u8>))
        {
            let source_parent_sentinel = source.parent().unwrap().join("source-parent-sentinel");
            let destination_parent_sentinel = destination.parent().unwrap().join("destination-parent-sentinel");
            (folder_identity(source), folder_identity(destination),
                file_evidence(&source.join("new.bin")), file_evidence(&destination.join("new.bin")),
                file_evidence(&source_parent_sentinel), file_evidence(&destination_parent_sentinel))
        }
        fn completion_fixture_evidence(source: &std::path::Path, destination: &std::path::Path)
            -> (String, String, (String, Vec<u8>), Vec<u8>, (String, Vec<u8>), (String, Vec<u8>))
        {
            let source_parent_sentinel = source.parent().unwrap().join("source-parent-sentinel");
            let destination_parent_sentinel = destination.parent().unwrap().join("destination-parent-sentinel");
            (folder_identity(source), folder_identity(destination), file_evidence(&source.join("new.bin")),
                std::fs::read(&destination.join("new.bin")).expect("read published output bytes while its identity handle is retained"),
                file_evidence(&source_parent_sentinel), file_evidence(&destination_parent_sentinel))
        }
        fn assert_completion_fixture_evidence(
            after: &(String, String, (String, Vec<u8>), (String, Vec<u8>), (String, Vec<u8>), (String, Vec<u8>)),
            at_gate: &(String, String, (String, Vec<u8>), Vec<u8>, (String, Vec<u8>), (String, Vec<u8>)),
        ) {
            assert_eq!(after.0, at_gate.0, "source root identity remains unchanged");
            assert_eq!(after.1, at_gate.1, "published output root identity remains unchanged");
            assert_eq!(after.2, at_gate.2, "source file identity and bytes remain unchanged");
            assert_eq!(after.3.1, at_gate.3, "published output bytes remain unchanged");
            assert_ne!(after.3.0, at_gate.2.0, "published output file is a distinct copy of the source file");
            assert_eq!(after.4, at_gate.4, "source-parent sentinel identity and bytes remain unchanged");
            assert_eq!(after.5, at_gate.5, "destination-parent sentinel identity and bytes remain unchanged");
        }
        if let Some(mode) = std::env::var_os(MODE) {
            let mode = mode.to_string_lossy();
            run_ordinary_directory_copy_replace_cleanup_failure(cx,
                match mode.as_ref() {
                    "before-store-crash" => CopyReplaceCleanupFailureMode::RootReceiptBeforeStoreCrash,
                    "before-store-release" => CopyReplaceCleanupFailureMode::RootReceiptBeforeStoreRelease,
                    "after-store-crash" => CopyReplaceCleanupFailureMode::RootReceiptAfterStoreCrash,
                    "after-store-release" => CopyReplaceCleanupFailureMode::RootReceiptAfterStoreRelease,
                    "completion-before-store-crash" => CopyReplaceCleanupFailureMode::CleanupCompleteBeforeStoreCrash,
                    "completion-before-store-release" => CopyReplaceCleanupFailureMode::CleanupCompleteBeforeStoreRelease,
                    "completion-after-store-crash" => CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreCrash,
                    "completion-after-store-release" => CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreRelease,
                    other => panic!("unknown Copy Replace receipt child mode: {other}"),
                });
            return;
        }
        fn wait_for(path: &std::path::Path, child: &mut Child) {
            let deadline = Instant::now() + Duration::from_secs(120);
            loop {
                if path.exists() { return; }
                assert!(child.try_wait().unwrap().is_none(), "Copy Replace child exited before receipt checkpoint");
                assert!(Instant::now() < deadline, "Copy Replace child missed root-receipt checkpoint");
                thread::sleep(Duration::from_millis(10));
            }
        }
        struct ChildGuard(Child);
        impl std::ops::Deref for ChildGuard {
            type Target = Child;
            fn deref(&self) -> &Self::Target { &self.0 }
        }
        impl std::ops::DerefMut for ChildGuard {
            fn deref_mut(&mut self) -> &mut Self::Target { &mut self.0 }
        }
        impl Drop for ChildGuard {
            fn drop(&mut self) {
                if self.0.try_wait().ok().flatten().is_none() {
                    let _ = self.0.kill();
                    let _ = self.0.wait();
                }
            }
        }
        for mode in ["before-store-crash", "before-store-release", "after-store-crash", "after-store-release", "completion-before-store-crash", "completion-before-store-release", "completion-after-store-crash", "completion-after-store-release"] {
            let reached = tempfile::Builder::new().prefix("gpui-filer-copy-replace-root-receipt-reached-")
                .tempdir().unwrap().keep().join("reached");
            let release = reached.with_extension("release");
            let mut child = ChildGuard(Command::new(std::env::current_exe().unwrap())
                .arg("--ignored").arg("--exact")
                .arg("shell::tests::ordinary_directory_copy_replace_root_receipt_crash_and_release")
                .arg("--nocapture").arg("--test-threads=1")
                .env(MODE, mode).env(REACHED, &reached).env(RELEASE, &release)
                .stdout(Stdio::inherit()).stderr(Stdio::inherit()).spawn().unwrap());
            wait_for(&reached, &mut child);
            let checkpoint_path = reached.with_extension("checkpoint.json");
            let checkpoint: serde_json::Value = serde_json::from_slice(&std::fs::read(&checkpoint_path).unwrap()).unwrap();
            let after_store = mode.starts_with("after-store");
            let completion_boundary = mode.starts_with("completion-");
            let completion_after_store = mode.starts_with("completion-after-store-");
            assert_eq!(checkpoint["phase"], if completion_boundary {
                if completion_after_store {
                    "copy-replace-cleanup-complete-after-store-before-ack"
                } else {
                    "copy-replace-cleanup-complete-before-store"
                }
            } else if after_store {
                "copy-replace-root-receipt-after-store-before-ack"
            } else {
                "copy-replace-root-disposition-before-receipt-store"
            });
            assert_eq!(checkpoint["attempt"]["state"], "running");
            assert_eq!(checkpoint["attempt"]["terminal_outcome"], serde_json::Value::Null);
            let ledger = &checkpoint["attempt"]["copy_replace_cleanups"][0];
            assert_eq!(ledger["root_disposition_recorded"], after_store || completion_boundary);
            assert_eq!(ledger["cleanup_complete"], completion_after_store);
            assert_eq!(checkpoint["attempt"]["terminal_outcome"], serde_json::Value::Null);
            assert_eq!(checkpoint["item"], 0);
            assert_eq!(checkpoint["key"], checkpoint["attempt"]["key"]);
            assert!(ledger["children"].as_array().unwrap().iter().all(|child| child["disposition_recorded"] == true));
            assert_eq!(ledger["pending"], if after_store || completion_boundary { serde_json::Value::Null } else { checkpoint["intent"].clone() });
            if !completion_boundary {
                assert_eq!(checkpoint["intent"]["node_kind"], "directory");
                assert_eq!(checkpoint["intent"]["relative_components"], serde_json::json!([]));
                assert_eq!(checkpoint["intent"]["content_fact"], "root");
            } else {
                assert!(checkpoint["runtime_token"].as_str().is_some_and(|token| !token.is_empty()));
                assert_eq!(checkpoint["runtime_complete_pending"], true);
                assert_eq!(checkpoint["runtime_no_terminal"], true);
                assert_eq!(checkpoint["runtime_no_undo"], true);
                assert_eq!(checkpoint["worker_lane_claimed"], true);
            }
            if completion_after_store {
                assert_eq!(checkpoint["phase"], "copy-replace-cleanup-complete-after-store-before-ack");
                assert_eq!(checkpoint["ledger"], ledger.clone(),
                    "after-store checkpoint ledger matches the exact persisted attempt ledger");
                let runtime_verified = reached.with_extension("runtime-verified.json");
                wait_for(&runtime_verified, &mut child);
                assert!(child.try_wait().unwrap().is_none(),
                    "child remains alive after its exact Runtime checkpoint verification");
                let verification: serde_json::Value = serde_json::from_slice(
                    &std::fs::read(runtime_verified.with_extension("payload.json")).unwrap(),
                ).unwrap();
                assert_eq!(verification["attempt_token"], checkpoint["runtime_token"]);
                assert_eq!(verification["key"], checkpoint["key"]);
                assert_eq!(verification["item"], 0);
                assert_eq!(verification["complete_pending"], true);
                assert_eq!(verification["ledger_cleanup_complete"], false);
                assert_eq!(verification["terminal_absent"], true);
                assert_eq!(verification["undo_absent"], true);
                assert_eq!(verification["worker_lane_claimed"], true);
            }
            assert_eq!(std::fs::read(std::path::PathBuf::from(checkpoint["journal_path"].as_str().unwrap())).unwrap(),
                checkpoint["primary_bytes"].as_array().unwrap().iter().map(|byte| byte.as_u64().unwrap() as u8).collect::<Vec<_>>(),
                "the checkpoint stores the exact durable Running journal bytes for its receipt boundary");
            let backup = journal_path(&serde_json::from_value(ledger["backup"].clone()).unwrap());
            assert!(child.try_wait().unwrap().is_none(), "child is alive at the exact writer gate");
            let source = std::path::PathBuf::from(checkpoint["source_path"].as_str().unwrap());
            let destination = std::path::PathBuf::from(checkpoint["destination_path"].as_str().unwrap());
            let destination_child = destination.join(source.file_name().expect("directory Copy source root has a leaf name"));
            let destination = if destination.join("new.bin").is_file() { destination } else { destination_child };
            assert!(destination.join("new.bin").is_file(), "published Copy tree contains its expected output leaf");
            let completion_at_gate = if completion_boundary {
                Some(completion_fixture_evidence(&source, &destination))
            } else { None };
            let fixture_before = if completion_boundary {
                None
            } else {
                let source_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &source, crate::directory::EntryKind::Folder).unwrap().filesystem_identity();
                let destination_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
                    &destination, crate::directory::EntryKind::Folder).unwrap().filesystem_identity();
                let evidence = fixture_evidence(&source, &destination);
                assert_ne!(source_identity, destination_identity, "published Copy output has a distinct root identity");
                Some(evidence)
            };
            if mode.ends_with("crash") {
                child.kill().unwrap();
                child.wait().unwrap();
                assert!(!backup.exists(), "successful root disposition remains absent after child reap");
                let fixture_after = fixture_evidence(&source, &destination);
                if completion_boundary {
                    assert_completion_fixture_evidence(&fixture_after, completion_at_gate.as_ref().unwrap());
                } else {
                    assert_eq!(fixture_after, fixture_before.unwrap(),
                        "source/output trees and parent sentinels preserve identities and bytes after child reap");
                }
                let journal = std::path::PathBuf::from(checkpoint["journal_path"].as_str().unwrap());
                let bytes = std::fs::read(&journal).unwrap();
                let predecessor = checkpoint["primary_bytes"].as_array().unwrap().iter().map(|byte| byte.as_u64().unwrap() as u8).collect::<Vec<_>>();
                assert_eq!(bytes, predecessor, "killed writer leaves exact Running bytes unchanged");
                for _ in 0..2 {
                    let store = operations::journal::JournalStore::open(journal.clone()).unwrap();
                    let attempt = store.attempt(checkpoint["key"].as_str().unwrap()).unwrap();
                    assert_eq!(attempt.state, operations::journal::JournalState::Running,
                        "opening preserves exact predecessor bytes while exposing a recovery projection");
                    let recovered = &attempt.copy_replace_cleanups[0];
                    assert_eq!(recovered.pending, if after_store || completion_boundary { None } else {
                        serde_json::from_value(checkpoint["intent"].clone()).ok()
                    });
                    assert_eq!(recovered.root_disposition_recorded, after_store || completion_boundary);
                    assert_eq!(recovered.cleanup_complete, completion_after_store);
                    assert_eq!(store.recoveries().len(), 1);
                    assert!(matches!(store.recoveries()[0], operations::journal::RecoveryItem::RecoveryRequired(_)));
                    let mut owner = operations::application::OperationApplicationOwner::for_test_with_journal_store(store);
                    assert_eq!(owner.recovery_records.len(), 1);
                    assert_eq!(owner.recovery_records[0].state, operations::journal::JournalState::RecoveryRequired);
                    assert!(owner.runtime.jobs().is_empty());
                    assert!(owner.runtime.start_next().is_none());
                    assert!(owner.runtime.undo_snapshot_for_test().1.is_empty());
                    assert_eq!(std::fs::read(&journal).unwrap(), predecessor);
                    assert_eq!(fixture_evidence(&source, &destination), fixture_after,
                        "fresh-owner recovery inspection preserves all fixture identities and bytes");
                }
            } else {
                std::fs::OpenOptions::new().write(true).create_new(true).open(&release).unwrap();
                let status = child.wait().unwrap();
                assert!(status.success(), "released Copy Replace child settles Succeeded");
                assert!(!backup.exists(), "released cleanup leaves displaced backup root absent");
                let fixture_after = fixture_evidence(&source, &destination);
                if completion_boundary {
                    assert_completion_fixture_evidence(&fixture_after, completion_at_gate.as_ref().unwrap());
                } else {
                    assert_eq!(fixture_after, fixture_before.unwrap(),
                        "successful receipt persistence preserves source/output and parent sentinels");
                }
                let journal = std::path::PathBuf::from(checkpoint["journal_path"].as_str().unwrap());
                let store = operations::journal::JournalStore::open(journal).unwrap();
                assert!(store.recoveries().is_empty(), "completed cleanup does not reopen for recovery");
                let attempt = store.attempt(checkpoint["key"].as_str().unwrap()).unwrap();
                assert_eq!(attempt.state, operations::journal::JournalState::Terminal);
                assert_eq!(attempt.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
                let ledger = &attempt.copy_replace_cleanups[0];
                assert!(ledger.root_disposition_recorded && ledger.cleanup_complete && ledger.pending.is_none());
            }
        }
    }

    #[cfg(windows)]
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum CopyReplaceCleanupFailureMode {
        Child,
        RootSentinel,
        RootReceiptBeforeStoreCrash,
        RootReceiptBeforeStoreRelease,
        RootReceiptAfterStoreCrash,
        RootReceiptAfterStoreRelease,
        CleanupCompleteBeforeStoreCrash,
        CleanupCompleteBeforeStoreRelease,
        CleanupCompleteAfterStoreCrash,
        CleanupCompleteAfterStoreRelease,
    }

    #[cfg(windows)]
    fn run_ordinary_directory_copy_replace_cleanup_failure(
        cx: &mut gpui::TestAppContext,
        mode: CopyReplaceCleanupFailureMode,
    ) {
        use std::{
            path::{Path, PathBuf},
            sync::mpsc,
            thread,
            time::{Duration, Instant},
        };

        initialize_directory_binding_test_globals(cx);
        let fixture_volume = PathBuf::from(r"C:\Temp");
        assert!(fixture_volume.is_dir(), "fixed NTFS fixture volume root C:\\Temp must exist");
        let drive = "C:\\".encode_utf16().chain([0]).collect::<Vec<_>>();
        let mut filesystem_name = [0u16; 32];
        assert!(
            unsafe {
                windows::Win32::Storage::FileSystem::GetDriveTypeW(windows::core::PCWSTR(drive.as_ptr())) == 3
                    && windows::Win32::Storage::FileSystem::GetVolumeInformationW(
                        windows::core::PCWSTR(drive.as_ptr()), None, None, None, None,
                        Some(&mut filesystem_name),
                    ).is_ok()
            }
                && String::from_utf16_lossy(&filesystem_name).trim_end_matches('\0').eq_ignore_ascii_case("NTFS"),
            "Copy Replace refusal fixture must use local fixed NTFS",
        );
        let fixture_root = tempfile::Builder::new()
            .prefix(match mode {
                CopyReplaceCleanupFailureMode::Child => "gpui-filer-dir-copy-replace-child-failure-",
                CopyReplaceCleanupFailureMode::RootSentinel => "gpui-filer-dir-copy-replace-root-failure-",
                CopyReplaceCleanupFailureMode::RootReceiptBeforeStoreCrash => "gpui-filer-dir-copy-replace-root-receipt-before-store-crash-",
                CopyReplaceCleanupFailureMode::RootReceiptBeforeStoreRelease => "gpui-filer-dir-copy-replace-root-receipt-before-store-release-",
                CopyReplaceCleanupFailureMode::RootReceiptAfterStoreCrash => "gpui-filer-dir-copy-replace-root-receipt-after-store-crash-",
                CopyReplaceCleanupFailureMode::RootReceiptAfterStoreRelease => "gpui-filer-dir-copy-replace-root-receipt-after-store-release-",
                CopyReplaceCleanupFailureMode::CleanupCompleteBeforeStoreCrash => "gpui-filer-dir-copy-replace-cleanup-complete-before-store-crash-",
                CopyReplaceCleanupFailureMode::CleanupCompleteBeforeStoreRelease => "gpui-filer-dir-copy-replace-cleanup-complete-before-store-release-",
                CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreCrash => "gpui-filer-dir-copy-replace-cleanup-complete-after-store-crash-",
                CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreRelease => "gpui-filer-dir-copy-replace-cleanup-complete-after-store-release-",
            })
            .tempdir_in(&fixture_volume)
            .unwrap()
            .keep();
        let source_parent = fixture_root.join("source");
        let destination_parent = fixture_root.join("destination");
        let source = source_parent.join("tree");
        let destination = destination_parent.join("tree");
        let journal_root = tempfile::Builder::new()
            .prefix("gpui-filer-dir-copy-replace-child-journal-")
            .tempdir_in(&fixture_volume)
            .unwrap()
            .keep();
        let journal_path = journal_root.join("operations.json");
        let receipt_process_mode = matches!(mode,
            CopyReplaceCleanupFailureMode::RootReceiptBeforeStoreCrash
                | CopyReplaceCleanupFailureMode::RootReceiptBeforeStoreRelease
                | CopyReplaceCleanupFailureMode::RootReceiptAfterStoreCrash
                | CopyReplaceCleanupFailureMode::RootReceiptAfterStoreRelease);
        let completion_process_mode = matches!(mode,
            CopyReplaceCleanupFailureMode::CleanupCompleteBeforeStoreCrash
                | CopyReplaceCleanupFailureMode::CleanupCompleteBeforeStoreRelease
                | CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreCrash
                | CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreRelease);
        let crash_boundary_process_mode = receipt_process_mode || completion_process_mode;
        std::fs::create_dir(&source_parent).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        std::fs::create_dir(&source).unwrap();
        std::fs::create_dir(&destination).unwrap();
        if crash_boundary_process_mode {
            std::fs::write(source_parent.join("source-parent-sentinel"), b"source parent sentinel").unwrap();
            std::fs::write(destination_parent.join("destination-parent-sentinel"), b"destination parent sentinel").unwrap();
        }
        std::fs::write(source.join("new.bin"), b"replacement-tree-bytes").unwrap();
        std::fs::write(destination.join("old.bin"), b"original-backup-bytes").unwrap();

        fn identity(path: &Path) -> crate::filesystem_identity::FilesystemIdentity {
            let kind = if path.is_dir() {
                crate::directory::EntryKind::Folder
            } else {
                crate::directory::EntryKind::File
            };
            let captured = crate::directory::EntrySourceIdentity::from_path_no_follow(path, kind);
            assert!(captured.is_some(), "could not capture filesystem identity for {path:?}");
            captured.unwrap().filesystem_identity()
        }
        fn tree(path: &Path) -> Vec<(String, crate::filesystem_identity::FilesystemIdentity, Option<Vec<u8>>)> {
            fn visit(
                root: &Path,
                path: &Path,
                entries: &mut Vec<(String, crate::filesystem_identity::FilesystemIdentity, Option<Vec<u8>>)>,
            ) {
                let relative = path.strip_prefix(root).unwrap().to_string_lossy().replace('\\', "/");
                let is_dir = path.is_dir();
                let kind = if is_dir {
                    crate::directory::EntryKind::Folder
                } else {
                    crate::directory::EntryKind::File
                };
                let id = crate::directory::EntrySourceIdentity::from_path_no_follow(path, kind)
                    .unwrap()
                    .filesystem_identity();
                entries.push((relative, id, (!is_dir).then(|| std::fs::read(path).unwrap())));
                if is_dir {
                    let mut children = std::fs::read_dir(path).unwrap()
                        .map(|entry| entry.unwrap().path()).collect::<Vec<_>>();
                    children.sort();
                    for child in children { visit(root, &child, entries); }
                }
            }
            let mut entries = Vec::new();
            visit(path, path, &mut entries);
            entries
        }
        fn path_from_journal(path: &operations::journal::JournalPath) -> PathBuf {
            use std::os::windows::ffi::OsStringExt;
            PathBuf::from(std::ffi::OsString::from_wide(&path.units))
        }

        let source_tree_before = tree(&source);
        let displaced_before = tree(&destination);
        let source_identity = identity(&source);
        let destination_parent_identity = identity(&destination_parent);
        let store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        let owner = operations::application::OperationApplicationOwner::for_test_with_journal_store_and_workers(store);
        cx.update(|cx| cx.set_global(owner));
        let real_writer = cx.update(|cx| {
            cx.global::<operations::application::OperationApplicationOwner>()
                .journal.clone().expect("owner-created serial JournalWriter")
        });
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| FilerShell::new(
                persistence::Startup::disabled(),
                Arc::new(input::KeymapRuntime::new()),
                Vec::new(),
                cx,
            ));
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let destination_view = visual.read_entity(&shell, |shell, _| shell.active_view().unwrap());
        visual.update(|_, cx| destination_view.update(cx, |view, cx| {
            view.navigate_location(crate::location::Location::Path(destination_parent.clone()), cx);
        }));
        let ready_deadline = Instant::now() + Duration::from_secs(30);
        let (view_id, view_entity, location_epoch, presentation_revision) = loop {
            visual.run_until_parked();
            if let Some(values) = visual.read_entity(&shell, |shell, cx| {
                let id = shell.active_tab_id_for_test();
                let tab = shell.workspace.active().focused_pane().tabs.iter().find(|tab| tab.id == id).unwrap();
                let view = tab.view.read(cx);
                (view.session.status() == &crate::directory_session::ListingStatus::Ready)
                    .then_some((id, tab.view.entity_id(), view.current_location_generation(), view.current_presentation_revision_for_test()))
            }) { break values; }
            assert!(Instant::now() < ready_deadline, "destination listing did not reach Ready");
            thread::sleep(Duration::from_millis(2));
        };
        let destination_guard = identity(&destination_parent);
        assert_eq!(destination_guard, destination_parent_identity);
        let (files, replace_evidence, move_evidence) = FilerShell::prepare_clipboard_file_request(
            file_clipboard::ClipboardFiles { paths: vec![source.clone()], effect: ClipboardEffect::Copy },
            &destination_guard,
        ).expect("Shell captures the clipboard request before admission");
        assert_eq!(files.paths, [source.clone()]);

        struct WorkerReleaseGuard(Option<mpsc::SyncSender<()>>);
        impl WorkerReleaseGuard {
            fn release(&mut self) {
                if let Some(sender) = self.0.take() { let _ = sender.send(()); }
            }
        }
        impl Drop for WorkerReleaseGuard {
            fn drop(&mut self) {
                if let Some(sender) = self.0.take() { let _ = sender.try_send(()); }
            }
        }
        let (ack_gate_tx, ack_gate_rx) = mpsc::sync_channel::<()>(1);
        let mut worker_release = WorkerReleaseGuard(Some(ack_gate_tx));
        let (worker_started_tx, worker_started_rx) = mpsc::sync_channel::<()>(1);
        let (worker_return_tx, worker_return_rx) = async_channel::bounded::<()>(1);
        let worker_cancellation = std::sync::Arc::new(std::sync::Mutex::new(None::<std::sync::Arc<std::sync::atomic::AtomicBool>>));
        let worker_cancellation_for_pump = worker_cancellation.clone();
        let exact_token = std::sync::Arc::new(std::sync::Mutex::new(None::<operations::model::AttemptToken>));
        let exact_token_for_worker = exact_token.clone();
        let exact_key = std::sync::Arc::new(std::sync::Mutex::new(None::<String>));
        let exact_key_for_worker = exact_key.clone();
        let receipt_journal_path = journal_path.clone();
        let receipt_source_path = source.clone();
        let receipt_destination_path = destination.clone();
        let observed_facts = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let observed_facts_for_worker = observed_facts.clone();
        visual.update_entity(&shell, |shell, cx| {
            cx.background_executor().allow_parking();
            cx.global_mut::<operations::application::OperationApplicationOwner>()
                .configure_worker_pump_test(move |worker, fact_sender| {
                    let (command, cancellation, controls, lease) = (
                        worker.command, worker.cancellation, worker.controls, worker.source_cleanup_lease,
                    );
                    *worker_cancellation_for_pump.lock().unwrap() = Some(cancellation.clone());
                    let token = exact_token_for_worker.lock().unwrap().expect("Shell admits before worker dispatch");
                    let mode = mode;
                    let observed_facts = observed_facts_for_worker.clone();
                    let (done_tx, done_rx) = async_channel::bounded::<()>(1);
                    let thread = thread::spawn(move || {
                        let mut gate = Some(ack_gate_rx);
                        executor::execute_prepare_with_source_cleanup_lease(
                            command, cancellation.as_ref(), &controls, lease,
                            |fact| {
                                observed_facts.lock().unwrap().push(format!("{fact:?}"));
                                if let executor::ExecutorFact::CopyReplaceCleanupChildIntent { token: actual, item, intent } = &fact {
                                    let is_child = intent.ordinal == 0
                                        && intent.node_kind == operations::journal::JournalDirectoryNodeKind::File
                                        && !intent.relative_components.is_empty();
                                    let is_root = intent.node_kind == operations::journal::JournalDirectoryNodeKind::Directory
                                        && intent.relative_components.is_empty()
                                        && intent.content_fact == "root";
                                    if *actual == token && *item == operations::model::ItemId(0)
                                        && mode == CopyReplaceCleanupFailureMode::Child && is_child
                                    {
                                        executor::arm_copy_replace_backup_child_cleanup_failure_for_shell_test(
                                            *actual, *item, intent.clone(),
                                            gate.take().expect("first approved child arms the one-shot failure"),
                                        );
                                        worker_started_tx.send(()).expect("test observes child cleanup intent");
                                    } else if *actual == token && *item == operations::model::ItemId(0)
                                        && mode == CopyReplaceCleanupFailureMode::RootSentinel && is_root
                                    {
                                        assert!(!cancellation.load(std::sync::atomic::Ordering::Acquire), "root intent is held without cancellation");
                                        fact_sender.publish(fact);
                                        worker_started_tx.send(()).expect("test observes acknowledged backup-root intent");
                                        gate.take().expect("root intent has one bounded release gate")
                                            .recv_timeout(Duration::from_secs(30))
                                            .expect("parent releases native worker after durable root-intent ACK");
                                        return;
                                    } else if *actual == token && *item == operations::model::ItemId(0)
                                        && crash_boundary_process_mode && is_root
                                    {
                                        if receipt_process_mode {
                                            let reached = std::env::var_os("GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_REACHED")
                                                .expect("child receives root-receipt reached path");
                                            let release = std::env::var_os("GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_RELEASE")
                                                .expect("child receives root-receipt release path");
                                            let exact_key = exact_key_for_worker.lock().unwrap().clone().expect("exact admitted attempt key");
                                            let gate_args = (exact_key, item.0, intent.clone(), reached.into(), release.into(),
                                                receipt_journal_path.clone(), receipt_source_path.clone(), receipt_destination_path.clone());
                                            let writer_mode = std::env::var("GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_CHILD_MODE")
                                                .expect("test child has an exact root-receipt boundary mode");
                                            if writer_mode.starts_with("before-store") {
                                                operations::journal::JournalWriter::gate_copy_replace_root_receipt_before_store_for_test(
                                                    gate_args.0, gate_args.1, gate_args.2, gate_args.3, gate_args.4,
                                                    gate_args.5, gate_args.6, gate_args.7,
                                                );
                                            } else {
                                                operations::journal::JournalWriter::gate_copy_replace_root_receipt_after_store_for_test(
                                                    gate_args.0, gate_args.1, gate_args.2, gate_args.3, gate_args.4,
                                                    gate_args.5, gate_args.6, gate_args.7,
                                                );
                                            }
                                        }
                                        fact_sender.publish(fact);
                                        worker_started_tx.send(()).expect("test observes published root intent");
                                        gate.take().expect("root receipt child holds native disposition until exact intent readback")
                                            .recv_timeout(Duration::from_secs(30))
                                            .expect("test releases native disposition only after exact root intent readback");
                                        return;
                                    }
                                }
                                fact_sender.publish(fact);
                            },
                        );
                        done_tx.send_blocking(()).unwrap();
                    });
                    Box::pin(async move {
                        done_rx.recv().await.expect("native worker returns");
                        thread.join().expect("native worker does not panic");
                        worker_return_tx.send(()).await.expect("worker return observed");
                    })
                });
            shell.continue_clipboard_paste(
                OperationKind::Copy, files.paths, None, replace_evidence, move_evidence,
                destination_parent.clone(), destination_parent_identity.clone(),
                view_id, view_entity, location_epoch, presentation_revision, None, cx,
            );
            let token = cx.global::<operations::application::OperationApplicationOwner>()
                .runtime.jobs().last().and_then(|job| job.attempts.last().map(|attempt| attempt.token))
                .expect("production Shell clipboard continuation admits Copy");
            *exact_token.lock().unwrap() = Some(token);
            *exact_key.lock().unwrap() = Some(cx.global::<operations::application::OperationApplicationOwner>()
                .runtime.journal_attempt(token).expect("admitted attempt has journal identity").key);
        });
        let token = exact_token.lock().unwrap().unwrap();
        let conflict_deadline = Instant::now() + Duration::from_secs(30);
        let conflict = loop {
            visual.run_until_parked();
            if let Some(conflict) = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner.runtime.job(token).and_then(|job| job.attempts.into_iter().find(|attempt| attempt.token == token))
                    .and_then(|attempt| attempt.pending_conflict.map(|conflict| conflict.token))
            }) { break conflict; }
            if Instant::now() >= conflict_deadline {
                let state = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| format!("{:?}", owner.runtime.job(token)));
                panic!("directory Copy did not reach Replace conflict; owner job={state}");
            }
            thread::sleep(Duration::from_millis(2));
        };
        visual.update(|_, cx| shell.update(cx, |shell, cx| {
            shell.resolve_operation_conflict(conflict, operations::model::ConflictDecision::Replace, false, cx);
        }));
        let worker_started_deadline = Instant::now() + Duration::from_secs(30);
        loop {
            visual.run_until_parked();
            if worker_started_rx.try_recv().is_ok() { break; }
            if Instant::now() >= worker_started_deadline {
                let state = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| format!("{:?}", owner.runtime.job(token)));
                panic!("first backup child cleanup intent was not selected; owner job={state}; executor facts={:?}", *observed_facts.lock().unwrap());
            }
            thread::sleep(Duration::from_millis(2));
        }
        let key = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.journal_attempt(token).unwrap().key);
        let writer = real_writer.clone();
        let (readback_tx, readback_rx) = mpsc::sync_channel(1);
        let key_for_reader = key.clone();
        let root_mode = mode == CopyReplaceCleanupFailureMode::RootSentinel;
        let root_intent_mode = root_mode || crash_boundary_process_mode;
        thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(30);
            loop {
                let attempt = writer.read_attempt(key_for_reader.clone()).recv_blocking().unwrap().unwrap().unwrap();
                if attempt.copy_replace_cleanups.iter().any(|ledger| ledger.item == 0
                    && ledger.pending.as_ref().is_some_and(|intent| if root_intent_mode {
                        intent.ordinal as usize == ledger.children.len()
                            && intent.node_kind == operations::journal::JournalDirectoryNodeKind::Directory
                            && intent.relative_components.is_empty() && intent.content_fact == "root"
                    } else {
                        intent.ordinal == 0
                            && intent.node_kind == operations::journal::JournalDirectoryNodeKind::File
                    }))
                {
                    readback_tx.send(attempt).unwrap();
                    break;
                }
                assert!(Instant::now() < deadline, "same-writer cleanup intent readback timed out");
                thread::sleep(Duration::from_millis(2));
            }
        });
        let ack_deadline = Instant::now() + Duration::from_secs(30);
        let acknowledged = loop {
            visual.run_until_parked();
            if let Ok(attempt) = readback_rx.try_recv() { break attempt; }
            assert!(Instant::now() < ack_deadline, "owner writer did not ACK/read back child cleanup intent");
            thread::sleep(Duration::from_millis(2));
        };
        let cleanup = acknowledged.copy_replace_cleanups.iter().find(|ledger| ledger.item == 0).unwrap();
        let intent = cleanup.pending.clone().expect("pending exact cleanup intent");
        if root_intent_mode {
            assert_eq!(intent.ordinal as usize, cleanup.children.len());
            assert_eq!(intent.node_kind, operations::journal::JournalDirectoryNodeKind::Directory);
            assert!(intent.relative_components.is_empty());
            assert_eq!(intent.content_fact, "root");
            assert_eq!(intent.identity, {
                let original_root_identity = &displaced_before.iter()
                    .find(|(relative, _, _)| relative.is_empty())
                    .expect("captured original backup root evidence").1;
                let (volume, index) = original_root_identity.windows_parts().unwrap();
                format!("{volume}:{index:016x}")
            });
            assert!(cleanup.children.iter().all(|child| child.disposition_recorded), "every approved backup child disposition is durable before root intent");
        } else {
            assert_eq!(intent.ordinal, 0);
            assert_eq!(intent.node_kind, operations::journal::JournalDirectoryNodeKind::File);
            assert_eq!(intent.relative_components, ["old.bin".encode_utf16().collect::<Vec<_>>()]);
            assert_eq!(intent.identity, {
                let original_child_identity = &displaced_before.iter()
                    .find(|(relative, _, _)| relative == "old.bin")
                    .expect("captured original backup child evidence").1;
                let (volume, index) = original_child_identity.windows_parts().unwrap();
                format!("{volume}:{index:016x}")
            });
            assert!(!cleanup.children[0].disposition_recorded);
        }
        assert!(cleanup.pending.is_some() && !cleanup.root_disposition_recorded && !cleanup.cleanup_complete);
        assert_eq!(acknowledged.key, key, "same owner writer read back the exact attempt");
        assert_eq!(acknowledged.copy_replace_cleanups.iter().find(|ledger| ledger.item == 0)
            .and_then(|ledger| ledger.pending.as_ref()), Some(&intent),
            "same owner writer read back the exact pending cleanup intent");
        let mut sentinel = None;
        let mut sentinel_identity = None;
        if root_mode {
            let backup = path_from_journal(&cleanup.backup);
            assert_eq!({
                let (volume, index) = identity(&backup).windows_parts().unwrap();
                format!("{volume}:{index:016x}")
            }, intent.identity);
            assert_eq!(std::fs::read_dir(&backup).unwrap().count(), 0, "all approved backup children are gone before root disposition");
            let path = backup.join("foreign-root-child.txt");
            use std::io::Write;
            let mut file = std::fs::OpenOptions::new().write(true).create_new(true).open(&path).unwrap();
            file.write_all(b"foreign root child").unwrap();
            drop(file);
            sentinel_identity = Some(identity(&path));
            sentinel = Some(path);
        }
        let destination_scan_before_release = visual.read_entity(&destination_view, |view, _| {
            let ticket = view.session.accepted_scan_ticket().expect("destination has a Ready scan before cleanup refusal");
            assert_eq!(view.session.status(), &crate::directory_session::ListingStatus::Ready);
            ticket.scan_id
        });
        worker_release.release();

        if crash_boundary_process_mode {
            let reached = std::path::PathBuf::from(std::env::var_os("GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_REACHED").unwrap());
            let deadline = Instant::now() + Duration::from_secs(120);
            while !reached.exists() {
                visual.run_until_parked();
                assert!(Instant::now() < deadline, "selected Copy Replace cleanup writer gate was not reached after native deletion");
                thread::sleep(Duration::from_millis(2));
            }
            if matches!(mode, CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreCrash
                | CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreRelease) {
                let runtime_key = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                    let item = operations::model::ItemId(0);
                    assert!(owner.runtime.copy_replace_cleanup_complete_pending(token, item),
                        "Runtime remains at CompletePending after durable cleanup-complete store and before ACK");
                    let attempt = owner.runtime.job(token).and_then(|job|
                        job.attempts.into_iter().find(|attempt| attempt.token == token))
                        .expect("exact Runtime attempt remains present at after-store checkpoint");
                    assert!(attempt.terminal.is_none(), "after-store checkpoint has no Runtime Terminal");
                    assert_eq!(attempt.token, token, "Runtime checkpoint retains the exact AttemptToken");
                    let record = owner.runtime.journal_attempt(token)
                        .expect("Runtime retains the exact cleanup-complete journal attempt");
                    assert_eq!(record.key, key, "Runtime cleanup ledger belongs to the exact attempt key");
                    let ledger = record.copy_replace_cleanups.iter().find(|ledger| ledger.item == item.0)
                        .expect("Runtime retains the exact Copy Replace cleanup ledger");
                    assert!(ledger.root_disposition_recorded && ledger.pending.is_none());
                    assert!(!ledger.cleanup_complete, "Runtime cleanup ledger stays incomplete until exact ACK");
                    let (reserved, entries) = owner.runtime.undo_snapshot_for_test();
                    assert!(!reserved && entries.is_empty(), "durable cleanup completion does not grant Undo");
                    assert!(owner.worker_claimed_for_test(), "Shell worker lane remains claimed before ACK");
                    record.key.clone()
                });
                let verified_path = std::path::PathBuf::from(
                    std::env::var_os("GPUI_FILER_COPY_REPLACE_ROOT_RECEIPT_REACHED").unwrap(),
                ).with_extension("runtime-verified.json");
                let verification = serde_json::json!({
                    "attempt_token": format!("{token:?}"),
                    "key": runtime_key,
                    "item": 0,
                    "complete_pending": true,
                    "ledger_cleanup_complete": false,
                    "terminal_absent": true,
                    "undo_absent": true,
                    "worker_lane_claimed": true,
                });
                use std::io::Write;
                let payload_path = verified_path.with_extension("payload.json");
                let mut payload = std::fs::OpenOptions::new().write(true).create_new(true)
                    .open(&payload_path).expect("create child Runtime verification payload after assertions");
                payload.write_all(&serde_json::to_vec(&verification).unwrap())
                    .expect("write child Runtime verification payload");
                payload.sync_all().expect("flush child Runtime verification payload");
                drop(payload);
                let marker = std::fs::OpenOptions::new().write(true).create_new(true)
                    .open(&verified_path).expect("publish child Runtime verification marker");
                marker.sync_all().expect("flush child Runtime verification marker");
            }
            if matches!(mode, CopyReplaceCleanupFailureMode::RootReceiptBeforeStoreCrash
                | CopyReplaceCleanupFailureMode::RootReceiptAfterStoreCrash
                | CopyReplaceCleanupFailureMode::CleanupCompleteBeforeStoreCrash
                | CopyReplaceCleanupFailureMode::CleanupCompleteAfterStoreCrash) {
                loop { visual.run_until_parked(); thread::sleep(Duration::from_millis(20)); }
            }
            let deadline = Instant::now() + Duration::from_secs(60);
            loop {
                visual.run_until_parked();
                let succeeded = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                    owner.runtime.job(token).and_then(|job| job.attempts.into_iter().find(|attempt| attempt.token == token))
                        .and_then(|attempt| attempt.terminal).is_some_and(|terminal| terminal.outcome == operations::model::TerminalOutcome::Succeeded));
                if succeeded { break; }
                assert!(Instant::now() < deadline, "released Copy Replace receipt did not settle Succeeded");
                thread::sleep(Duration::from_millis(2));
            }
            let writer = real_writer.clone();
            let key = key.clone();
            let durable_deadline = Instant::now() + Duration::from_secs(60);
            loop {
                let attempt = writer.read_attempt(key.clone()).recv_blocking().unwrap().unwrap().unwrap();
                if attempt.state == operations::journal::JournalState::Terminal {
                    let ledger = attempt.copy_replace_cleanups.iter().find(|ledger| ledger.item == 0).unwrap();
                    assert!(ledger.root_disposition_recorded && ledger.cleanup_complete && ledger.pending.is_none());
                    assert_eq!(attempt.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Succeeded));
                    break;
                }
                assert!(Instant::now() < durable_deadline, "Terminal/cleanup-complete journal readback timed out");
                visual.run_until_parked();
            }
            let settled_deadline = Instant::now() + Duration::from_secs(30);
            let mut worker_returned = false;
            loop {
                visual.run_until_parked();
                worker_returned |= worker_return_rx.try_recv().is_ok();
                let lane_released = visual.read_entity(&shell, |shell, cx| !shell.operation_worker_claimed_for_test(cx));
                if worker_returned && lane_released { break; }
                assert!(Instant::now() < settled_deadline, "released worker or Shell lane did not settle");
                thread::sleep(Duration::from_millis(2));
            }
            return;
        }

        let terminal_deadline = Instant::now() + Duration::from_secs(30);
        let runtime_terminal = loop {
            visual.run_until_parked();
            let terminal = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner.runtime.job(token).and_then(|job| job.attempts.into_iter().find(|attempt| attempt.token == token))
                    .and_then(|attempt| attempt.terminal)
            });
            if let Some(terminal) = terminal { break terminal; }
            assert!(Instant::now() < terminal_deadline, "Runtime did not accept cleanup Partial");
            thread::sleep(Duration::from_millis(2));
        };
        assert_eq!(runtime_terminal.outcome, operations::model::TerminalOutcome::Partial);
        assert_eq!(runtime_terminal.receipts.len(), 1);
        assert_eq!(runtime_terminal.receipts[0].outcome, operations::model::ItemOutcome::Partial);
        let receipt = runtime_terminal.receipts[0].replace_receipt.as_ref().expect("published Copy Replace receipt");
        assert!(receipt.destination_published);
        assert!(!receipt.displaced_backup_removed);
        assert_eq!(runtime_terminal.retry, operations::model::RetryPlan::RequiresReinspection);
        if root_mode {
            let expected_detail = format!(
                "backup root native delete disposition failed: Io({:?}); backup retained",
                windows::core::Error::from_hresult(windows::core::HRESULT(0x8007_0091u32 as i32)).to_string(),
            );
            assert_eq!(runtime_terminal.receipts[0].detail.as_deref(), Some(expected_detail.as_str()),
                "terminal receipt preserves the real nonempty-directory native disposition error");
            let cancellation = worker_cancellation.lock().unwrap().clone().expect("native cancellation state retained for terminal assertion");
            assert!(!cancellation.load(std::sync::atomic::Ordering::Acquire), "native root disposition refusal is not cancellation");
        }
        let runtime_attempt = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.journal_attempt(token).unwrap());
        assert_eq!(runtime_attempt.copy_replace_cleanups, acknowledged.copy_replace_cleanups);
        let (terminal_read_tx, terminal_read_rx) = mpsc::sync_channel(1);
        let terminal_writer = real_writer.clone();
        let terminal_key = key.clone();
        thread::spawn(move || {
            terminal_read_tx.send(terminal_writer.read_attempt(terminal_key).recv_blocking().unwrap().unwrap().unwrap()).unwrap();
        });
        let terminal_read_deadline = Instant::now() + Duration::from_secs(30);
        let durable = loop {
            visual.run_until_parked();
            if let Ok(attempt) = terminal_read_rx.try_recv() { break attempt; }
            assert!(Instant::now() < terminal_read_deadline, "Terminal writer readback timed out");
            thread::sleep(Duration::from_millis(2));
        };
        assert_eq!(durable.state, operations::journal::JournalState::RecoveryRequired);
        assert_eq!(durable.terminal_outcome, Some(operations::journal::JournalTerminalOutcome::Partial));
        assert!(durable.receipts_recorded);
        assert_eq!(durable.copy_replace_cleanups, runtime_attempt.copy_replace_cleanups);
        let durable_ledger = durable.copy_replace_cleanups.iter().find(|ledger| ledger.item == 0).unwrap();
        assert_eq!(durable_ledger, cleanup);
        assert_eq!(durable_ledger.pending, Some(intent));
        if root_mode {
            assert!(durable_ledger.children.iter().all(|child| child.disposition_recorded));
            assert_eq!(durable_ledger.pending.as_ref().unwrap().ordinal as usize, durable_ledger.children.len());
            assert_eq!(durable_ledger.pending.as_ref().unwrap().node_kind, operations::journal::JournalDirectoryNodeKind::Directory);
            assert!(durable_ledger.pending.as_ref().unwrap().relative_components.is_empty());
            assert_eq!(durable_ledger.pending.as_ref().unwrap().content_fact, "root");
        } else {
            assert!(!durable_ledger.children[0].disposition_recorded);
        }
        assert!(!durable_ledger.root_disposition_recorded);
        assert!(!durable_ledger.cleanup_complete);
        let backup = path_from_journal(&durable_ledger.backup);
        assert!(backup.exists());
        assert_eq!(std::fs::read(destination.join("new.bin")).unwrap(), b"replacement-tree-bytes");
        assert_eq!(source_identity, identity(&source));
        assert_eq!(tree(&source), source_tree_before);
        let published_identity = identity(&destination);
        assert_ne!(published_identity, source_identity, "published copy has a distinct root identity");
        if root_mode {
            let sentinel_path = sentinel.as_ref().expect("root refusal sentinel path");
            let expected_sentinel_identity = sentinel_identity.expect("root refusal sentinel identity");
            assert_eq!(identity(&backup), displaced_before.iter()
                .find(|(relative, _, _)| relative.is_empty()).unwrap().1,
                "displaced backup root retains its original identity");
            assert_eq!(std::fs::read(sentinel_path).unwrap(), b"foreign root child");
            assert_eq!(identity(sentinel_path), expected_sentinel_identity);
            assert_eq!(std::fs::read_dir(&backup).unwrap().count(), 1);
        } else {
            assert_eq!(tree(&backup), displaced_before, "first child failure retains original backup tree intact");
        }
        assert!(visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| owner.runtime.undo_snapshot_for_test().1.is_empty()), "Partial Copy Replace creates no Copy Undo");
        let settled_deadline = Instant::now() + Duration::from_secs(30);
        let mut worker_returned = false;
        loop {
            visual.run_until_parked();
            worker_returned |= worker_return_rx.try_recv().is_ok();
            let released = visual.read_entity(&shell, |shell, cx| !shell.operation_worker_claimed_for_test(cx));
            if worker_returned && released { break; }
            assert!(Instant::now() < settled_deadline, "Terminal ACK, native worker return, and Shell lane release must settle");
            thread::sleep(Duration::from_millis(2));
        }
        if root_mode {
            let reconcile_deadline = Instant::now() + Duration::from_secs(30);
            loop {
                visual.run_until_parked();
                let reconciled = visual.read_entity(&destination_view, |view, _| {
                    view.session.status() == &crate::directory_session::ListingStatus::Ready
                        && view.session.accepted_scan_ticket().is_some_and(|ticket| ticket.path == destination_parent
                            && ticket.scan_id > destination_scan_before_release)
                        && view.entries.iter().any(|entry| entry.path.as_deref() == Some(destination.as_path())
                            && entry.source_identity.as_ref().is_some_and(|identity| identity.filesystem_identity() == published_identity))
                });
                if reconciled { break; }
                assert!(Instant::now() < reconcile_deadline, "destination did not accept a newer matching Ready scan with the exact Copy Replace publication identity");
                thread::sleep(Duration::from_millis(2));
            }
        }
        let durable_bytes = std::fs::read(&journal_path).unwrap();
        let filesystem_snapshot = (tree(&source), tree(&destination), tree(&backup));
        drop(real_writer);
        for _ in 0..2 {
            assert_eq!(std::fs::read(&journal_path).unwrap(), durable_bytes);
            let store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
            assert_eq!(store.recoveries(), [operations::journal::RecoveryItem::RecoveryRequired(durable.clone())]);
            let mut owner = operations::application::OperationApplicationOwner::for_test_with_journal_store(store);
            assert_eq!(owner.recovery_records, [durable.clone()]);
            assert!(owner.runtime.jobs().is_empty());
            assert!(owner.runtime.start_next().is_none());
            assert!(owner.runtime.undo_snapshot_for_test().1.is_empty());
            assert_eq!((tree(&source), tree(&destination), tree(&backup)), filesystem_snapshot);
            assert_eq!(std::fs::read(&journal_path).unwrap(), durable_bytes);
        }
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires a local fixed NTFS test volume"]
    fn ordinary_same_volume_directory_copy_shell_pump_terminal_journal_failure_recovers_running_predecessor(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::path::{Component, Prefix};

        initialize_directory_binding_test_globals(cx);
        // The host may redirect TEMP to a non-NTFS scratch volume, so keep this
        // fixture beside the test binary on Cargo's local build volume.
        let volume = std::env::current_exe()
            .unwrap()
            .parent()
            .expect("test executable has a parent directory")
            .to_path_buf();
        let Some(Component::Prefix(prefix)) = volume.components().next() else {
            panic!("temporary fixture path must have a drive prefix");
        };
        let (Prefix::Disk(letter) | Prefix::VerbatimDisk(letter)) = prefix.kind() else {
            panic!("temporary fixture path must be on a local disk");
        };
        let drive = format!("{}:\\", letter as char);
        let drive_wide = drive
            .encode_utf16()
            .chain(std::iter::once(0))
            .collect::<Vec<_>>();
        let mut filesystem = [0u16; 32];
        assert!(
            unsafe {
                windows::Win32::Storage::FileSystem::GetDriveTypeW(windows::core::PCWSTR(
                    drive_wide.as_ptr(),
                )) == 3
                    && windows::Win32::Storage::FileSystem::GetVolumeInformationW(
                        windows::core::PCWSTR(drive_wide.as_ptr()),
                        None,
                        None,
                        None,
                        None,
                        Some(&mut filesystem),
                    )
                    .is_ok()
                    && String::from_utf16_lossy(&filesystem)
                        .trim_end_matches('\0')
                        .eq_ignore_ascii_case("NTFS")
            },
            "the journal sharing-violation fixture requires fixed NTFS"
        );

        let temp = tempfile::Builder::new()
            .prefix("gpui-filer-shell-directory-copy-journal-failure-")
            .tempdir_in(&volume)
            .unwrap();
        let source_root = temp.path().join("source-parent");
        let source = source_root.join("tree");
        let destination = temp.path().join("destination-parent");
        let published = destination.join("tree");
        std::fs::create_dir_all(source.join("nested/deeper")).unwrap();
        std::fs::create_dir(&destination).unwrap();
        let first = b"nested copy payload";
        let second = b"deeper copy payload";
        std::fs::write(source.join("nested/data.bin"), first).unwrap();
        std::fs::write(source.join("nested/deeper/other.bin"), second).unwrap();
        let expected_bytes = (first.len() + second.len()) as u64;

        let journal_dir = temp.path().join("journal");
        std::fs::create_dir(&journal_dir).unwrap();
        let journal_path = journal_dir.join("journal-v1.json");
        let store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        cx.update(|cx| {
            cx.set_global(
                operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    store,
                ),
            );
        });
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());

        let mut token = None;
        let mut predecessor = None;
        let mut predecessor_bytes = None;
        let mut real_writer = None;
        let mut journal_driver = None;
        let late_sender = Arc::new(std::sync::Mutex::new(
            None::<operations::transport::WorkerFactSender>,
        ));
        let late_sender_capture = late_sender.clone();
        let latest_progress = Arc::new(std::sync::Mutex::new(
            None::<operations::model::ProgressUpdate>,
        ));
        let latest_progress_capture = latest_progress.clone();

        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
                let admitted = owner
                    .runtime
                    .submit(copy_request(
                        source.to_string_lossy().as_ref(),
                        destination.to_string_lossy().as_ref(),
                    ))
                    .unwrap();
                let mut running = owner.runtime.journal_attempt(admitted).unwrap();
                running.state = operations::journal::JournalState::Running;
                let mut durable =
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap();
                durable.upsert(running.clone()).unwrap();
                drop(durable);
                predecessor_bytes = Some(std::fs::read(&journal_path).unwrap());
                predecessor = Some(running);
                token = Some(admitted);
                real_writer = Some(operations::journal::JournalWriter::start(
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap(),
                ));
                let (writer, driver) = operations::journal::JournalWriter::test_driver();
                owner.journal = Some(writer);
                journal_driver = Some(driver);
                owner.configure_worker_pump_test(move |worker, fact_sender| {
                    *late_sender_capture.lock().unwrap() = Some(fact_sender.clone());
                    let (command, cancellation, controls, lease) = (
                        worker.command,
                        worker.cancellation,
                        worker.controls,
                        worker.source_cleanup_lease,
                    );
                    let (finished_tx, finished_rx) = async_channel::bounded(1);
                    let thread = std::thread::spawn(move || {
                        executor::execute_prepare_with_source_cleanup_lease(
                            command,
                            cancellation.as_ref(),
                            &controls,
                            lease,
                            |fact| {
                                if let executor::ExecutorFact::Progress { update, .. } = &fact {
                                    *latest_progress_capture.lock().unwrap() = Some(update.clone());
                                }
                                fact_sender.publish(fact);
                            },
                        );
                        let _ = finished_tx.send_blocking(());
                    });
                    Box::pin(async move {
                        finished_rx.recv().await.expect("Copy executor completion");
                        thread.join().expect("Copy executor thread panicked");
                    })
                });
                cx.background_executor().allow_parking();
                shell.start_next_operation(cx);
            });
        });

        let token = token.expect("directory Copy was admitted");
        let predecessor = predecessor.expect("durable Running predecessor was captured");
        let predecessor_bytes = predecessor_bytes.expect("Running primary bytes were captured");
        let real_writer = real_writer.expect("real JournalWriter was started");
        let driver = journal_driver.expect("Shell journal test driver was installed");

        struct JournalPrimaryLock(windows::Win32::Foundation::HANDLE);
        impl JournalPrimaryLock {
            fn hold(path: &std::path::Path) -> Self {
                use std::os::windows::ffi::OsStrExt;
                use windows::Win32::Storage::FileSystem::{
                    CreateFileW, FILE_ATTRIBUTE_NORMAL, FILE_SHARE_MODE, OPEN_EXISTING,
                };
                let wide = path
                    .as_os_str()
                    .encode_wide()
                    .chain(std::iter::once(0))
                    .collect::<Vec<_>>();
                const GENERIC_READ: u32 = 0x8000_0000;
                let handle = unsafe {
                    CreateFileW(
                        windows::core::PCWSTR(wide.as_ptr()),
                        GENERIC_READ,
                        FILE_SHARE_MODE(0),
                        None,
                        OPEN_EXISTING,
                        FILE_ATTRIBUTE_NORMAL,
                        None,
                    )
                }
                .expect("hold the durable Running journal primary without sharing");
                Self(handle)
            }
        }
        impl Drop for JournalPrimaryLock {
            fn drop(&mut self) {
                let _ = unsafe { windows::Win32::Foundation::CloseHandle(self.0) };
            }
        }
        let primary_lock = JournalPrimaryLock::hold(&journal_path);

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        let terminal = 'found: loop {
            visual.run_until_parked();
            while let Some(command) = driver.try_command() {
                match command {
                    operations::journal::JournalWriterCommandForTest::Upsert(upsert)
                        if upsert.attempt.state
                            == operations::journal::JournalState::Terminal =>
                    {
                        break 'found upsert;
                    }
                    operations::journal::JournalWriterCommandForTest::Upsert(upsert) => {
                        upsert.reply(Ok(()));
                    }
                    operations::journal::JournalWriterCommandForTest::UnacknowledgedUpsert(
                        _,
                    ) => {}
                    _ => panic!("unexpected journal command during ordinary Copy"),
                }
            }
            assert!(
                std::time::Instant::now() < deadline,
                "Copy terminal journal request timed out"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        let terminal_record = terminal.attempt.clone();
        assert_eq!(terminal_record.kind, operations::journal::JournalKind::Copy);
        assert_eq!(
            terminal_record.state,
            operations::journal::JournalState::Terminal
        );
        assert_eq!(
            terminal_record.terminal_outcome,
            Some(operations::journal::JournalTerminalOutcome::Succeeded)
        );
        let writer_receipt = real_writer.upsert_with_reply(terminal_record.clone());
        let writer_error = {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
            loop {
                match writer_receipt.try_recv() {
                    Ok(result) => break result.expect_err("sharing-locked ReplaceFileW must fail"),
                    Err(async_channel::TryRecvError::Closed) => {
                        panic!("JournalWriter dropped its receipt")
                    }
                    Err(async_channel::TryRecvError::Empty) => {}
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "JournalWriter terminal reply timed out"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        };
        const SHARING_VIOLATION_HRESULT: u32 = 0x8007_0020;
        assert!(
            writer_error.contains(&format!("replace failed ({SHARING_VIOLATION_HRESULT})")),
            "expected ReplaceFileW sharing violation, got {writer_error}"
        );
        terminal.reply(Err(writer_error));
        drop(primary_lock);

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let terminal_snapshot = loop {
            visual.run_until_parked();
            let snapshot = visual.read_entity(&shell, |_, cx| {
                cx.read_global::<operations::application::OperationApplicationOwner, _>(
                    |owner, _| {
                        owner
                            .runtime
                            .job(token)
                            .expect("Copy job remains in Runtime")
                    },
                )
            });
            let attempt = snapshot
                .attempts
                .iter()
                .find(|attempt| attempt.token == token)
                .unwrap();
            if attempt.terminal.is_some() {
                assert_eq!(attempt.state, operations::model::AttemptState::Terminal);
                let report = attempt.terminal.as_ref().unwrap();
                assert_eq!(
                    report.outcome,
                    operations::model::TerminalOutcome::Succeeded
                );
                assert_eq!(
                    report.receipts,
                    vec![operations::model::ItemReceipt {
                        item: operations::model::ItemId(0),
                        outcome: operations::model::ItemOutcome::Completed,
                        detail: None,
                        created_folder_path: None,
                        created_archive_path: None,
                        move_receipt: None,
                        replace_receipt: None,
                        copy_undo: None,
                    }]
                );
                assert_eq!(report.final_counters.processed_bytes, expected_bytes);
                break snapshot;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "Copy terminal journal ACK timed out"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        };

        assert_eq!(
            std::fs::read(published.join("nested/data.bin")).unwrap(),
            first
        );
        assert_eq!(
            std::fs::read(published.join("nested/deeper/other.bin")).unwrap(),
            second
        );
        assert_eq!(
            std::fs::read(source.join("nested/data.bin")).unwrap(),
            first
        );
        assert_eq!(
            std::fs::read(source.join("nested/deeper/other.bin")).unwrap(),
            second
        );
        assert_eq!(std::fs::read(&journal_path).unwrap(), predecessor_bytes);
        assert!(std::fs::read_dir(&journal_dir).unwrap().all(|entry| {
            entry
                .unwrap()
                .path()
                .extension()
                .is_none_or(|extension| extension != "tmp")
        }));
        assert!(!journal_path.with_file_name("journal-v1.json.bak").exists());

        let mut late = latest_progress
            .lock()
            .unwrap()
            .clone()
            .expect("executor published progress");
        late.sequence = late.sequence.checked_add(1).unwrap();
        late.counters.processed_bytes = late.counters.processed_bytes.checked_add(1).unwrap();
        late_sender
            .lock()
            .unwrap()
            .take()
            .expect("retained Shell WorkerFactSender")
            .publish(executor::ExecutorFact::Progress {
                token,
                update: late,
            });
        drop(late_sender);
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(6);
        loop {
            visual.run_until_parked();
            let lane_claimed = visual.read_entity(&shell, |shell, cx| {
                shell.operation_worker_claimed_for_test(cx)
            });
            if !lane_claimed {
                let current = visual.read_entity(&shell, |_, cx| {
                    cx.read_global::<operations::application::OperationApplicationOwner, _>(
                        |owner, _| owner.runtime.job(token).unwrap(),
                    )
                });
                assert_eq!(
                    current, terminal_snapshot,
                    "late progress cannot mutate terminal Runtime state"
                );
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "Shell worker lane did not drain after terminal"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        drop(real_writer);
        let reopened = operations::journal::JournalStore::open(journal_path).unwrap();
        assert_eq!(reopened.attempt_keys(), [predecessor.key.clone()]);
        assert_eq!(
            reopened.recoveries(),
            vec![operations::journal::RecoveryItem::RecoveryRequired({
                let mut expected = predecessor;
                expected.state = operations::journal::JournalState::RecoveryRequired;
                expected
            })]
        );
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires a local fixed NTFS test volume"]
    fn directory_copy_staging_and_terminal_journal_failures_reopen_running_without_replay(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::os::windows::fs::OpenOptionsExt;
        use std::path::{Component, Prefix};

        initialize_directory_binding_test_globals(cx);
        let volume = std::env::current_exe()
            .unwrap()
            .parent()
            .unwrap()
            .to_path_buf();
        let Some(Component::Prefix(prefix)) = volume.components().next() else {
            panic!("temporary fixture path must have a drive prefix");
        };
        let (Prefix::Disk(letter) | Prefix::VerbatimDisk(letter)) = prefix.kind() else {
            panic!("temporary fixture path must be on a local disk");
        };
        let drive = format!("{}:\\", letter as char);
        let drive_wide = drive.encode_utf16().chain([0]).collect::<Vec<_>>();
        let mut filesystem = [0u16; 32];
        assert!(
            unsafe {
                windows::Win32::Storage::FileSystem::GetDriveTypeW(windows::core::PCWSTR(
                    drive_wide.as_ptr(),
                )) == 3
                    && windows::Win32::Storage::FileSystem::GetVolumeInformationW(
                        windows::core::PCWSTR(drive_wide.as_ptr()),
                        None,
                        None,
                        None,
                        None,
                        Some(&mut filesystem),
                    )
                    .is_ok()
                    && String::from_utf16_lossy(&filesystem)
                        .trim_end_matches('\0')
                        .eq_ignore_ascii_case("NTFS")
            },
            "the journal sharing-violation fixture requires fixed NTFS"
        );

        let temp = tempfile::Builder::new()
            .prefix("gpui-filer-shell-directory-copy-staging-journal-failure-")
            .tempdir_in(&volume)
            .unwrap();
        let source = temp.path().join("source-parent").join("tree");
        let destination = temp.path().join("destination-parent");
        let published = destination.join("tree");
        std::fs::create_dir_all(&source).unwrap();
        std::fs::create_dir(&destination).unwrap();
        let first_source = source.join("first.txt");
        let second_source = source.join("second.txt");
        let first_bytes = b"first staged sibling payload";
        let second_bytes = b"source denied after sibling staging";
        std::fs::write(&first_source, first_bytes).unwrap();
        std::fs::write(&second_source, second_bytes).unwrap();
        let first_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &first_source,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity();
        let second_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &second_source,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity();

        let journal_dir = temp.path().join("journal");
        std::fs::create_dir(&journal_dir).unwrap();
        let journal_path = journal_dir.join("journal-v1.json");
        let store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        cx.update(|cx| {
            cx.set_global(
                operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    store,
                ),
            )
        });
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let mut token = None;
        let mut predecessor = None;
        let mut predecessor_bytes = None;
        let mut predecessor_artifacts = None;
        let mut real_writer = None;
        let mut journal_driver = None;
        let stage_observed = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let stage_observed_capture = stage_observed.clone();
        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
                let admitted = owner
                    .runtime
                    .submit(copy_request(
                        source.to_string_lossy().as_ref(),
                        destination.to_string_lossy().as_ref(),
                    ))
                    .unwrap();
                let mut running = owner.runtime.journal_attempt(admitted).unwrap();
                running.state = operations::journal::JournalState::Running;
                let mut durable =
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap();
                durable.upsert(running.clone()).unwrap();
                drop(durable);
                predecessor_bytes = Some(std::fs::read(&journal_path).unwrap());
                predecessor_artifacts = Some({
                    let mut artifacts = std::fs::read_dir(&journal_dir)
                        .unwrap()
                        .map(|entry| {
                            let path = entry.unwrap().path();
                            (
                                path.file_name().unwrap().to_os_string(),
                                std::fs::read(path).unwrap(),
                            )
                        })
                        .collect::<Vec<_>>();
                    artifacts.sort_by(|left, right| left.0.cmp(&right.0));
                    artifacts
                });
                predecessor = Some(running);
                token = Some(admitted);
                real_writer = Some(operations::journal::JournalWriter::start(
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap(),
                ));
                let (writer, driver) = operations::journal::JournalWriter::test_driver();
                owner.journal = Some(writer);
                journal_driver = Some(driver);
                let stage_parent = destination.clone();
                let first = first_source.clone();
                let second = second_source.clone();
                owner.configure_worker_pump_test(move |worker, fact_sender| {
                    let (command, cancellation, controls, lease) = (
                        worker.command,
                        worker.cancellation,
                        worker.controls,
                        worker.source_cleanup_lease,
                    );
                    let (finished_tx, finished_rx) = async_channel::bounded(1);
                    let thread = std::thread::spawn(move || {
                        let mut blocker = None;
                        executor::execute_prepare_with_source_cleanup_lease(
                            command,
                            cancellation.as_ref(),
                            &controls,
                            lease,
                            |fact| {
                                if matches!(
                                    &fact,
                                    executor::ExecutorFact::Progress { update, .. }
                                        if update.counters.processed_items > 0
                                ) && !stage_observed_capture
                                    .swap(true, std::sync::atomic::Ordering::AcqRel)
                                {
                                    let stages = std::fs::read_dir(&stage_parent)
                                        .unwrap()
                                        .map(|entry| entry.unwrap().path())
                                        .filter(|path| {
                                            path.file_name().is_some_and(|name| {
                                                name.to_string_lossy()
                                                    .starts_with(".gpui-filer-copy-")
                                            })
                                        })
                                        .collect::<Vec<_>>();
                                    assert_eq!(stages.len(), 1);
                                    let children = std::fs::read_dir(&stages[0])
                                        .unwrap()
                                        .map(|entry| entry.unwrap().path())
                                        .collect::<Vec<_>>();
                                    assert_eq!(children.len(), 1, "one sibling has staged");
                                    let staged = children[0].file_name().unwrap();
                                    let blocked = if staged == first.file_name().unwrap() {
                                        &second
                                    } else {
                                        assert_eq!(staged, second.file_name().unwrap());
                                        &first
                                    };
                                    blocker = Some(
                                        std::fs::OpenOptions::new()
                                            .read(true)
                                            .share_mode(0)
                                            .open(blocked)
                                            .expect("deny source sharing after staging a sibling"),
                                    );
                                }
                                fact_sender.publish(fact);
                            },
                        );
                        drop(blocker);
                        let _ = finished_tx.send_blocking(());
                    });
                    Box::pin(async move {
                        finished_rx.recv().await.expect("Copy executor completion");
                        thread.join().expect("Copy executor thread panicked");
                    })
                });
                cx.background_executor().allow_parking();
                shell.start_next_operation(cx);
            })
        });

        let token = token.expect("directory Copy was admitted");
        let predecessor = predecessor.expect("durable Running predecessor captured");
        let predecessor_bytes = predecessor_bytes.expect("Running bytes captured");
        let predecessor_artifacts =
            predecessor_artifacts.expect("Running artifact snapshot captured");
        let real_writer = real_writer.expect("real JournalWriter started");
        let driver = journal_driver.expect("Shell journal test driver installed");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        let terminal = 'found: loop {
            visual.run_until_parked();
            while let Some(command) = driver.try_command() {
                match command {
                    operations::journal::JournalWriterCommandForTest::Upsert(upsert)
                        if upsert.attempt.state == operations::journal::JournalState::Terminal =>
                    {
                        break 'found upsert;
                    }
                    operations::journal::JournalWriterCommandForTest::Upsert(upsert) => {
                        upsert.reply(Ok(()))
                    }
                    operations::journal::JournalWriterCommandForTest::UnacknowledgedUpsert(_) => {}
                    _ => panic!("unexpected journal command during folder Copy"),
                }
            }
            assert!(
                std::time::Instant::now() < deadline,
                "Copy terminal timed out"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        assert!(stage_observed.load(std::sync::atomic::Ordering::Acquire));
        let terminal_record = terminal.attempt.clone();
        assert_eq!(terminal_record.key, predecessor.key);
        assert_eq!(terminal_record.kind, operations::journal::JournalKind::Copy);
        assert_eq!(
            terminal_record.terminal_outcome,
            Some(operations::journal::JournalTerminalOutcome::Failed)
        );

        struct JournalPrimaryLock(windows::Win32::Foundation::HANDLE);
        impl JournalPrimaryLock {
            fn hold(path: &std::path::Path) -> Self {
                use std::os::windows::ffi::OsStrExt;
                use windows::Win32::Storage::FileSystem::{
                    CreateFileW, FILE_ATTRIBUTE_NORMAL, FILE_SHARE_MODE, OPEN_EXISTING,
                };
                let wide = path
                    .as_os_str()
                    .encode_wide()
                    .chain([0])
                    .collect::<Vec<_>>();
                let handle = unsafe {
                    CreateFileW(
                        windows::core::PCWSTR(wide.as_ptr()),
                        0x8000_0000u32,
                        FILE_SHARE_MODE(0),
                        None,
                        OPEN_EXISTING,
                        FILE_ATTRIBUTE_NORMAL,
                        None,
                    )
                }
                .expect("hold durable Running primary without sharing");
                Self(handle)
            }
        }
        impl Drop for JournalPrimaryLock {
            fn drop(&mut self) {
                let _ = unsafe { windows::Win32::Foundation::CloseHandle(self.0) };
            }
        }
        let lock = JournalPrimaryLock::hold(&journal_path);
        let receipt = real_writer.upsert_with_reply(terminal_record);
        let writer_deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
        let writer_error = loop {
            match receipt.try_recv() {
                Ok(result) => break result.expect_err("sharing-locked terminal write must fail"),
                Err(async_channel::TryRecvError::Closed) => panic!("JournalWriter dropped receipt"),
                Err(async_channel::TryRecvError::Empty) => {}
            }
            assert!(
                std::time::Instant::now() < writer_deadline,
                "terminal write timed out"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        assert!(
            writer_error.contains("replace failed (2147942432)"),
            "{writer_error}"
        );
        drop(lock);
        assert_eq!(std::fs::read(&journal_path).unwrap(), predecessor_bytes);
        let after_failure_artifacts = {
            let mut artifacts = std::fs::read_dir(&journal_dir)
                .unwrap()
                .map(|entry| {
                    let path = entry.unwrap().path();
                    (
                        path.file_name().unwrap().to_os_string(),
                        std::fs::read(path).unwrap(),
                    )
                })
                .collect::<Vec<_>>();
            artifacts.sort_by(|left, right| left.0.cmp(&right.0));
            artifacts
        };
        assert_eq!(after_failure_artifacts, predecessor_artifacts);
        terminal.reply(Err(writer_error));
        visual.run_until_parked();

        let lane_deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
        while visual.read_entity(&shell, |shell, cx| {
            shell.operation_worker_claimed_for_test(cx)
        }) {
            visual.run_until_parked();
            assert!(
                std::time::Instant::now() < lane_deadline,
                "Shell worker lane did not drain"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        let runtime = visual.read_entity(&shell, |_, cx| {
            cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner.runtime.job(token).unwrap()
            })
        });
        let attempt = runtime
            .attempts
            .iter()
            .find(|attempt| attempt.token == token)
            .unwrap();
        assert_eq!(attempt.state, operations::model::AttemptState::Terminal);
        let report = attempt.terminal.as_ref().unwrap();
        assert_eq!(report.outcome, operations::model::TerminalOutcome::Failed);
        assert_eq!(
            report.retry,
            operations::model::RetryPlan::RequiresReinspection
        );
        assert_eq!(report.final_counters.processed_items, 1);
        assert_eq!(report.receipts.len(), 1);
        assert_eq!(report.receipts[0].item, operations::model::ItemId(0));
        assert_eq!(
            report.receipts[0].outcome,
            operations::model::ItemOutcome::Failed
        );
        let detail = report.receipts[0].detail.as_deref().unwrap();
        assert!(
            detail.contains("Io(") && detail.contains("(os error 32)"),
            "{detail}"
        );
        assert!(
            !published.exists(),
            "failed folder copy must not publish destination"
        );
        let stages = std::fs::read_dir(&destination)
            .unwrap()
            .map(|entry| entry.unwrap().path())
            .filter(|path| {
                path.file_name()
                    .is_some_and(|name| name.to_string_lossy().starts_with(".gpui-filer-copy-"))
            })
            .collect::<Vec<_>>();
        assert_eq!(
            stages.len(),
            1,
            "failed folder Copy retains its private stage"
        );
        let staged_children = std::fs::read_dir(&stages[0])
            .unwrap()
            .map(|entry| entry.unwrap().path())
            .collect::<Vec<_>>();
        assert_eq!(
            staged_children.len(),
            1,
            "only the completed sibling remains staged"
        );
        let staged_name = staged_children[0].file_name().unwrap();
        let staged_bytes = std::fs::read(&staged_children[0]).unwrap();
        assert!(
            (staged_name == first_source.file_name().unwrap() && staged_bytes == first_bytes)
                || (staged_name == second_source.file_name().unwrap()
                    && staged_bytes == second_bytes),
            "the retained stage contains exactly the completed source sibling"
        );
        assert_eq!(
            report.final_counters.processed_bytes,
            staged_bytes.len() as u64
        );
        assert_eq!(std::fs::read(&first_source).unwrap(), first_bytes);
        assert_eq!(std::fs::read(&second_source).unwrap(), second_bytes);
        assert_eq!(
            crate::directory::EntrySourceIdentity::from_path_no_follow(
                &first_source,
                crate::directory::EntryKind::File
            )
            .unwrap()
            .filesystem_identity(),
            first_identity
        );
        assert_eq!(
            crate::directory::EntrySourceIdentity::from_path_no_follow(
                &second_source,
                crate::directory::EntryKind::File
            )
            .unwrap()
            .filesystem_identity(),
            second_identity
        );
        assert_eq!(std::fs::read(&journal_path).unwrap(), predecessor_bytes);
        drop(real_writer);
        let reopened = operations::journal::JournalStore::open(journal_path).unwrap();
        assert_eq!(reopened.attempt_keys(), [predecessor.key.clone()]);
        assert_eq!(
            reopened.recoveries(),
            vec![operations::journal::RecoveryItem::RecoveryRequired({
                let mut expected = predecessor;
                expected.state = operations::journal::JournalState::RecoveryRequired;
                expected
            })]
        );
        assert!(
            !published.exists(),
            "reopen must not replay the failed Copy"
        );
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires distinct local fixed NTFS C: and E: fixtures"]
    fn ordinary_cross_volume_file_move_terminal_journal_io_failure_keeps_runtime_success_and_recovers_running_predecessor(
        cx: &mut gpui::TestAppContext,
    ) {
        run_ordinary_file_move_terminal_journal_io_failure(cx, true);
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires a local fixed NTFS fixture volume"]
    fn ordinary_same_volume_file_move_terminal_journal_io_failure_keeps_runtime_success_and_recovers_running_predecessor(
        cx: &mut gpui::TestAppContext,
    ) {
        run_ordinary_file_move_terminal_journal_io_failure(cx, false);
    }

    #[cfg(windows)]
    fn run_ordinary_file_move_terminal_journal_io_failure(
        cx: &mut gpui::TestAppContext,
        cross_volume: bool,
    ) {
        use std::path::{Component, Prefix};

        initialize_directory_binding_test_globals(cx);
        fn fixed_drive(path: &std::path::Path) -> Option<u8> {
            use windows::{Win32::Storage::FileSystem::GetDriveTypeW, core::PCWSTR};
            let Some(Component::Prefix(prefix)) = path.components().next() else {
                return None;
            };
            let (Prefix::Disk(letter) | Prefix::VerbatimDisk(letter)) = prefix.kind() else {
                return None;
            };
            let root = format!("{}:\\", letter as char);
            let wide = root
                .encode_utf16()
                .chain(std::iter::once(0))
                .collect::<Vec<_>>();
            (unsafe { GetDriveTypeW(PCWSTR(wide.as_ptr())) } == 3)
                .then_some(letter.to_ascii_uppercase())
        }
        fn fixed_ntfs(path: &std::path::Path) -> bool {
            use windows::{
                Win32::Storage::FileSystem::{GetDriveTypeW, GetVolumeInformationW},
                core::PCWSTR,
            };
            let Some(Component::Prefix(prefix)) = path.components().next() else {
                return false;
            };
            let (Prefix::Disk(letter) | Prefix::VerbatimDisk(letter)) = prefix.kind() else {
                return false;
            };
            let root = format!("{}:\\", letter as char);
            let wide = root
                .encode_utf16()
                .chain(std::iter::once(0))
                .collect::<Vec<_>>();
            let mut filesystem = [0u16; 32];
            unsafe {
                GetDriveTypeW(PCWSTR(wide.as_ptr())) == 3
                    && GetVolumeInformationW(
                        PCWSTR(wide.as_ptr()),
                        None,
                        None,
                        None,
                        None,
                        Some(&mut filesystem),
                    )
                    .is_ok()
                    && String::from_utf16_lossy(&filesystem)
                        .trim_end_matches('\0')
                        .eq_ignore_ascii_case("NTFS")
            }
        }

        let source_volume = std::env::temp_dir();
        let destination_volume = if cross_volume {
            let Some(destination_volume) = std::env::var_os("GPUI_FILER_CROSS_VOLUME_TEST_ROOT")
                .map(PathBuf::from)
                .filter(|path| path.is_absolute() && fixed_drive(path).is_some())
            else {
                eprintln!(
                    "skipping cross-volume file Move test: configured destination root is unavailable"
                );
                return;
            };
            destination_volume
        } else {
            source_volume.clone()
        };
        let (Some(source_drive), Some(destination_drive)) = (
            fixed_drive(&source_volume),
            fixed_drive(&destination_volume),
        ) else {
            eprintln!(
                "skipping ordinary file Move journal failure test: source or destination is not a fixed local volume"
            );
            return;
        };
        if cross_volume && source_drive == destination_drive {
            eprintln!(
                "skipping cross-volume file Move test: source and destination volumes are not distinct"
            );
            return;
        }
        if !cross_volume {
            assert_eq!(
                source_drive, destination_drive,
                "same-volume fixture roots share one drive"
            );
        }
        assert!(
            fixed_ntfs(&source_volume),
            "source fixture must be on fixed NTFS"
        );
        assert!(
            fixed_ntfs(&destination_volume),
            "destination fixture must be on fixed NTFS"
        );

        let (source_parent, destination_parent, fixture_roots) = if cross_volume {
            let source_root = tempfile::Builder::new()
                .prefix("gpui-filer-shell-file-move-source-")
                .tempdir_in(&source_volume)
                .unwrap();
            let destination_root = tempfile::Builder::new()
                .prefix("gpui-filer-shell-file-move-destination-")
                .tempdir_in(&destination_volume)
                .unwrap();
            let source_parent = source_root.path().to_path_buf();
            let destination_parent = destination_root.path().to_path_buf();
            (
                source_parent,
                destination_parent,
                vec![source_root, destination_root],
            )
        } else {
            let root = tempfile::Builder::new()
                .prefix("gpui-filer-shell-file-move-same-volume-")
                .tempdir_in(&source_volume)
                .unwrap();
            let source_parent = root.path().join("source");
            let destination_parent = root.path().join("destination");
            std::fs::create_dir(&source_parent).unwrap();
            std::fs::create_dir(&destination_parent).unwrap();
            (source_parent, destination_parent, vec![root])
        };
        let source = source_parent.join("payload.bin");
        let expected = if cross_volume {
            b"ordinary cross-volume file Move terminal journal failure".as_slice()
        } else {
            b"ordinary same-volume file Move terminal journal failure".as_slice()
        };
        std::fs::write(&source, expected).unwrap();
        let source_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &source,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity();
        let destination = destination_parent.join("payload.bin");
        assert!(
            !destination.exists(),
            "ordinary Move fixture has no collision"
        );

        // Keep every volume fixture alive until the real executor thread has been joined.
        let fixture_owners = Arc::new(std::sync::Mutex::new(Some(fixture_roots)));
        let worker_handle = Arc::new(std::sync::Mutex::new(None::<std::thread::JoinHandle<()>>));
        let worker_finished = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let (worker_finished_tx, worker_finished_rx) = async_channel::bounded::<()>(1);
        let late_progress_sender = Arc::new(std::sync::Mutex::new(
            None::<operations::transport::WorkerFactSender>,
        ));
        struct WorkerFinishSignal(Arc<std::sync::atomic::AtomicBool>);
        impl Drop for WorkerFinishSignal {
            fn drop(&mut self) {
                self.0.store(true, std::sync::atomic::Ordering::Release);
            }
        }
        struct WorkerCleanupGuard<'a> {
            worker: Arc<std::sync::Mutex<Option<std::thread::JoinHandle<()>>>>,
            worker_finished: Arc<std::sync::atomic::AtomicBool>,
            fixture_owners: Arc<std::sync::Mutex<Option<Vec<tempfile::TempDir>>>>,
            cleanup: Option<Box<dyn FnMut() + 'a>>,
        }
        impl Drop for WorkerCleanupGuard<'_> {
            fn drop(&mut self) {
                if let Some(mut cleanup) = self.cleanup.take() {
                    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| cleanup()));
                }
                let worker = self.worker.lock().unwrap_or_else(|p| p.into_inner()).take();
                if let Some(worker) = worker {
                    if self
                        .worker_finished
                        .load(std::sync::atomic::Ordering::Acquire)
                    {
                        let _ = worker.join();
                        drop(
                            self.fixture_owners
                                .lock()
                                .unwrap_or_else(|p| p.into_inner())
                                .take(),
                        );
                    } else {
                        let owners = self.fixture_owners.clone();
                        if std::thread::Builder::new()
                            .name("gpui-filer-file-move-test-reaper".into())
                            .spawn(move || {
                                let _ = worker.join();
                                drop(owners.lock().unwrap_or_else(|p| p.into_inner()).take());
                            })
                            .is_err()
                        {
                            if let Some(owners) = self
                                .fixture_owners
                                .lock()
                                .unwrap_or_else(|p| p.into_inner())
                                .take()
                            {
                                std::mem::forget(owners);
                            }
                        }
                    }
                }
            }
        }
        let mut worker_guard = WorkerCleanupGuard {
            worker: worker_handle.clone(),
            worker_finished: worker_finished.clone(),
            fixture_owners,
            cleanup: None,
        };

        let journal_root = if cross_volume {
            source_parent.clone()
        } else {
            source_parent.parent().unwrap().to_path_buf()
        };
        let journal_dir = journal_root.join("journal");
        std::fs::create_dir(&journal_dir).unwrap();
        let journal_path = journal_dir.join("journal-v1.json");
        let empty_store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        cx.update(|cx| {
            cx.set_global(
                operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    empty_store,
                ),
            );
        });

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let mut predecessor = None;
        let mut predecessor_bytes = None;
        let mut journal_driver = None;
        let mut real_writer = None;
        let mut token = None;
        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
                let mut request = copy_request(
                    source.to_string_lossy().as_ref(),
                    destination_parent.to_string_lossy().as_ref(),
                );
                request.kind = OperationKind::Move;
                let admitted = owner.runtime.submit(request).unwrap();
                let mut running = owner.runtime.journal_attempt(admitted).unwrap();
                running.state = operations::journal::JournalState::Running;
                let mut store =
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap();
                store.upsert(running.clone()).unwrap();
                drop(store);
                predecessor_bytes = Some(std::fs::read(&journal_path).unwrap());
                predecessor = Some(running);
                token = Some(admitted);
                real_writer = Some(operations::journal::JournalWriter::start(
                    operations::journal::JournalStore::open(journal_path.clone()).unwrap(),
                ));
                let (writer, driver) = operations::journal::JournalWriter::test_driver();
                owner.journal = Some(writer);
                journal_driver = Some(driver);
                let sender_capture = late_progress_sender.clone();
                let handle_capture = worker_handle.clone();
                let finished_flag = worker_finished.clone();
                owner.configure_worker_pump_test(move |worker, fact_sender| {
                    *sender_capture.lock().unwrap() = Some(fact_sender.clone());
                    let (command, cancellation, controls, lease) = (
                        worker.command,
                        worker.cancellation,
                        worker.controls,
                        worker.source_cleanup_lease,
                    );
                    let finished_flag = finished_flag.clone();
                    let worker_thread = std::thread::spawn(move || {
                        let _finish_signal = WorkerFinishSignal(finished_flag);
                        executor::execute_prepare_with_source_cleanup_lease(
                            command,
                            cancellation.as_ref(),
                            &controls,
                            lease,
                            |fact| fact_sender.publish(fact),
                        );
                        let _ = worker_finished_tx.try_send(());
                    });
                    *handle_capture.lock().unwrap() = Some(worker_thread);
                    Box::pin(async move {
                        let _ = worker_finished_rx.recv().await;
                    })
                });
                cx.background_executor().allow_parking();
                shell.start_next_operation(cx);
            });
        });

        let token = token.expect("ordinary Move was admitted");
        let predecessor = predecessor.expect("exact Running predecessor was persisted");
        let predecessor_bytes = predecessor_bytes.expect("Running bytes were captured");
        let driver = journal_driver.expect("Shell test writer was installed");
        let real_writer = real_writer.expect("real JournalWriter was started");

        let mut cleanup_visual = (*visual).clone();
        let cleanup_shell = shell.clone();
        let cleanup_worker_finished = worker_finished.clone();
        worker_guard.cleanup = Some(Box::new(move || {
            cleanup_visual.update(|_, cx| {
                cleanup_shell.update(cx, |_, cx| {
                    cx.update_global::<operations::application::OperationApplicationOwner, _>(
                        |owner, _| {
                            let _ = owner.runtime.cancel(token);
                        },
                    );
                });
            });
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
            while std::time::Instant::now() < deadline {
                cleanup_visual.run_until_parked();
                let lane_claimed = cleanup_visual.read_entity(&cleanup_shell, |shell, cx| {
                    shell.operation_worker_claimed_for_test(cx)
                });
                if cleanup_worker_finished.load(std::sync::atomic::Ordering::Acquire)
                    && !lane_claimed
                {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        }));

        struct PrimaryLock(windows::Win32::Foundation::HANDLE);
        impl PrimaryLock {
            fn hold(path: &std::path::Path) -> Self {
                use std::os::windows::ffi::OsStrExt;
                use windows::Win32::Storage::FileSystem::{
                    CreateFileW, FILE_ATTRIBUTE_NORMAL, FILE_SHARE_MODE, OPEN_EXISTING,
                };
                let wide = path
                    .as_os_str()
                    .encode_wide()
                    .chain(std::iter::once(0))
                    .collect::<Vec<_>>();
                let handle = unsafe {
                    CreateFileW(
                        windows::core::PCWSTR(wide.as_ptr()),
                        0x8000_0000,
                        FILE_SHARE_MODE(0),
                        None,
                        OPEN_EXISTING,
                        FILE_ATTRIBUTE_NORMAL,
                        None,
                    )
                }
                .expect("block delete-sharing on the existing journal primary");
                Self(handle)
            }
            fn read_all(&self, limit: usize) -> Vec<u8> {
                use windows::Win32::Storage::FileSystem::{FILE_BEGIN, ReadFile, SetFilePointerEx};
                let mut bytes = vec![0; limit];
                let mut read = 0;
                unsafe {
                    SetFilePointerEx(self.0, 0, None, FILE_BEGIN).unwrap();
                    ReadFile(self.0, Some(&mut bytes), Some(&mut read), None).unwrap();
                }
                bytes.truncate(read as usize);
                bytes
            }
        }
        impl Drop for PrimaryLock {
            fn drop(&mut self) {
                let _ = unsafe { windows::Win32::Foundation::CloseHandle(self.0) };
            }
        }
        fn artifact_snapshot(
            directory: &std::path::Path,
        ) -> Vec<(std::ffi::OsString, u64, Option<Vec<u8>>)> {
            let mut entries = std::fs::read_dir(directory)
                .unwrap()
                .map(|entry| {
                    let entry = entry.unwrap();
                    let path = entry.path();
                    let name = entry.file_name();
                    let len = entry.metadata().unwrap().len();
                    let artifact = path.extension().is_some_and(|ext| ext == "tmp")
                        || name == "journal-v1.json.bak";
                    (name, len, artifact.then(|| std::fs::read(path).unwrap()))
                })
                .collect::<Vec<_>>();
            entries.sort_by(|left, right| left.0.cmp(&right.0));
            entries
        }

        let lock = PrimaryLock::hold(&journal_path);
        let before_artifacts = artifact_snapshot(&journal_dir);
        let terminal = {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
            loop {
                visual.run_until_parked();
                match driver.try_command() {
                    Some(
                        operations::journal::JournalWriterCommandForTest::UnacknowledgedUpsert(_),
                    ) => {}
                    Some(operations::journal::JournalWriterCommandForTest::Upsert(upsert))
                        if upsert.attempt.state == operations::journal::JournalState::Terminal =>
                    {
                        break upsert;
                    }
                    Some(_) => panic!("unexpected journal command for ordinary file Move"),
                    None => {}
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "ordinary Move terminal did not reach Shell's journal pump"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        };
        assert_eq!(terminal.attempt.key, predecessor.key);
        assert_eq!(
            terminal.attempt.kind,
            operations::journal::JournalKind::Move
        );
        assert_eq!(
            terminal.attempt.state,
            operations::journal::JournalState::Terminal
        );
        assert_eq!(
            terminal.attempt.terminal_outcome,
            Some(operations::journal::JournalTerminalOutcome::Succeeded)
        );
        assert_eq!(std::fs::read(&destination).unwrap(), expected);
        assert!(
            !source.exists(),
            "cross-volume Move removed its source before terminal persistence"
        );
        let destination_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &destination,
            crate::directory::EntryKind::File,
        )
        .unwrap()
        .filesystem_identity();
        if cross_volume {
            assert_ne!(source_drive, destination_drive);
            assert_ne!(destination_identity, source_identity);
        } else {
            assert_eq!(source_drive, destination_drive);
            assert_eq!(
                destination_identity, source_identity,
                "same-volume Move uses handle rename and preserves file identity"
            );
        }
        let destination_entries = std::fs::read_dir(&destination_parent)
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect::<Vec<_>>();
        assert_eq!(
            destination_entries,
            [std::ffi::OsString::from("payload.bin")],
            "Move leaves no stage or backup artifacts"
        );
        for parent in [&source_parent, &destination_parent] {
            let unexpected_artifacts = std::fs::read_dir(parent)
                .unwrap()
                .map(|entry| entry.unwrap().file_name())
                .filter(|name| name.to_string_lossy().starts_with(".gpui-filer"))
                .collect::<Vec<_>>();
            assert!(
                unexpected_artifacts.is_empty(),
                "ordinary Move left stage or backup artifacts: {unexpected_artifacts:?}"
            );
        }

        let terminal_record = terminal.attempt.clone();
        let receipt = real_writer.upsert_with_reply(terminal_record.clone());
        let writer_error = {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
            loop {
                match receipt.try_recv() {
                    Ok(result) => break result.expect_err("blocked ReplaceFileW must fail"),
                    Err(async_channel::TryRecvError::Closed) => {
                        panic!("real writer dropped terminal receipt")
                    }
                    Err(async_channel::TryRecvError::Empty) => {}
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "real JournalWriter did not finish the blocked replacement"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        };
        assert!(
            writer_error.contains("replace failed (2147942432)"),
            "expected ReplaceFileW HRESULT 0x80070020, got {writer_error}"
        );
        assert_eq!(
            lock.read_all(predecessor_bytes.len() + 1),
            predecessor_bytes
        );
        assert_eq!(
            artifact_snapshot(&journal_dir),
            before_artifacts,
            "failed replacement leaves journal artifacts unchanged"
        );
        terminal.reply(Err(writer_error));
        visual.run_until_parked();
        drop(lock);

        let runtime_snapshot = visual.read_entity(&shell, |_, cx| {
            cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                owner.runtime.job(token).unwrap()
            })
        });
        let attempt = runtime_snapshot.attempts.last().unwrap();
        assert_eq!(attempt.state, operations::model::AttemptState::Terminal);
        let successful_terminal = attempt
            .terminal
            .clone()
            .expect("Runtime retained terminal success");
        assert_eq!(
            successful_terminal.outcome,
            operations::model::TerminalOutcome::Succeeded
        );
        assert_eq!(successful_terminal.final_counters.processed_items, 1);
        assert_eq!(successful_terminal.receipts.len(), 1);
        assert_eq!(
            successful_terminal.receipts[0].outcome,
            operations::model::ItemOutcome::Completed
        );
        let move_receipt = successful_terminal.receipts[0]
            .move_receipt
            .as_ref()
            .expect("ordinary Move terminal retains its exact filesystem receipt");
        assert_eq!(move_receipt.source, source);
        assert_eq!(move_receipt.destination, destination);
        assert!(move_receipt.destination_published && move_receipt.source_removed);
        let mut late = attempt
            .progress
            .clone()
            .unwrap_or(operations::model::ProgressUpdate {
                sequence: 0,
                counters: operations::model::ProgressCounters::default(),
                current_item: None,
            });
        late.sequence = late.sequence.saturating_add(1);
        late.counters.processed_bytes = late.counters.processed_bytes.saturating_add(1);
        let sender = late_progress_sender
            .lock()
            .unwrap()
            .take()
            .expect("Shell test seam retained the actual worker fact sender");
        sender.publish(executor::ExecutorFact::Progress {
            token,
            update: late,
        });
        drop(sender);
        let late_deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let after_late = loop {
            visual.run_until_parked();
            let snapshot = visual.read_entity(&shell, |_, cx| {
                cx.read_global::<operations::application::OperationApplicationOwner, _>(
                    |owner, _| owner.runtime.job(token).unwrap(),
                )
            });
            let lane_claimed = visual.read_entity(&shell, |shell, cx| {
                shell.operation_worker_claimed_for_test(cx)
            });
            if !lane_claimed {
                assert_eq!(
                    snapshot, runtime_snapshot,
                    "higher-sequence late transport progress cannot alter terminal state"
                );
                break snapshot;
            }
            assert!(
                std::time::Instant::now() < late_deadline,
                "Shell pump did not drain the late worker fact"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        assert!(
            !visual.read_entity(&shell, |shell, cx| shell
                .operation_worker_claimed_for_test(cx)),
            "dropping the retained sender drained terminal facts and released the Shell worker lane"
        );
        visual.update(|_, cx| {
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            assert!(
                owner
                    .runtime
                    .commit_fact(executor::ExecutorFact::Terminal {
                        token,
                        report: successful_terminal.clone()
                    })
                    .is_none(),
                "terminal rejects duplicate terminal facts"
            );
        });
        assert_eq!(after_late, runtime_snapshot);
        assert_eq!(
            std::fs::read(&destination).unwrap(),
            expected,
            "recovery projection does not replay the Move"
        );
        assert!(!source.exists());
        assert_eq!(
            crate::directory::EntrySourceIdentity::from_path_no_follow(
                &destination,
                crate::directory::EntryKind::File
            )
            .unwrap()
            .filesystem_identity(),
            destination_identity,
        );
        if cross_volume {
            assert_ne!(
                destination_identity, source_identity,
                "cross-volume copy-and-remove publishes a new file identity"
            );
        } else {
            assert_eq!(destination_identity, source_identity);
        }
        assert_eq!(std::fs::read(&journal_path).unwrap(), predecessor_bytes);
        let reopened = operations::journal::JournalStore::open(journal_path).unwrap();
        assert_eq!(reopened.attempt_keys(), [predecessor.key.clone()]);
        assert_eq!(
            reopened.recoveries(),
            vec![operations::journal::RecoveryItem::RecoveryRequired({
                let mut expected = predecessor;
                expected.state = operations::journal::JournalState::RecoveryRequired;
                expected
            })]
        );
        assert!(
            !source.exists(),
            "opening RecoveryRequired does not replay the Move"
        );
        assert_eq!(std::fs::read(&destination).unwrap(), expected);
        assert_eq!(
            crate::directory::EntrySourceIdentity::from_path_no_follow(
                &destination,
                crate::directory::EntryKind::File
            )
            .unwrap()
            .filesystem_identity(),
            destination_identity,
        );
    }

    #[gpui::test]
    fn published_zip_ack_cancel_flows_through_shell_journal_pump(cx: &mut gpui::TestAppContext) {
        initialize_directory_binding_test_globals(cx);
        let (harness, mut visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let root = tempfile::tempdir().unwrap();
        let source = root.path().join("source.txt");
        let output = root.path().join("source.zip");
        std::fs::write(&source, b"source").unwrap();
        let request = operations::model::OperationRequest::create_zip(
            source.clone(),
            output.clone(),
            operations::model::test_zip_create_guard(&source, &output),
        )
        .unwrap();
        let (controls_tx, controls_rx) = async_channel::bounded(1);
        let (release_tx, release_rx) = async_channel::bounded(4);
        let mut journal_driver = None;
        let mut token = None;
        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
                let (writer, driver) = operations::journal::JournalWriter::test_driver();
                owner.journal = Some(writer);
                journal_driver = Some(driver);
                let worker_source = source.clone();
                let worker_output = output.clone();
                owner.configure_worker_pump_test(move |worker, fact_sender| {
                    let token = match worker.command {
                        operations::model::ExecutorCommand::Prepare { token, .. } => token,
                        command => panic!("unexpected test worker command: {command:?}"),
                    };
                    let controls = worker.controls;
                    controls_tx.try_send(controls).unwrap();
                    Box::pin(async move {
                        let source_identity =
                            crate::directory::EntrySourceIdentity::from_path_no_follow(
                                &worker_source,
                                crate::directory::EntryKind::File,
                            )
                            .unwrap()
                            .filesystem_identity();
                        let parent_identity =
                            crate::directory::EntrySourceIdentity::from_path_no_follow(
                                worker_output.parent().unwrap(),
                                crate::directory::EntryKind::Folder,
                            )
                            .unwrap()
                            .filesystem_identity();
                        let mut ledger = operations::journal::JournalZipCreate {
                            sources: vec![operations::journal::JournalZipCreateSource {
                                source: operations::journal::JournalPath::from_path(&worker_source),
                                source_identity: format!("{source_identity:?}"),
                            }],
                            output: operations::journal::JournalPath::from_path(&worker_output),
                            stage: operations::journal::JournalPath::from_path(
                                &worker_output.with_extension("stage"),
                            ),
                            parent_identity: format!("{parent_identity:?}"),
                            stage_identity: None,
                            output_identity: None,
                            phase: operations::journal::JournalZipCreatePhase::StagePlanned,
                        };
                        for phase in [
                            operations::journal::JournalZipCreatePhase::StagePlanned,
                            operations::journal::JournalZipCreatePhase::StageOwned,
                            operations::journal::JournalZipCreatePhase::PublishIntent,
                        ] {
                            ledger.phase = phase;
                            if phase == operations::journal::JournalZipCreatePhase::StageOwned {
                                ledger.stage_identity = Some("test-stage-identity".to_owned());
                            }
                            fact_sender
                                .send(executor::ExecutorFact::ZipCreateLedgerIntent {
                                    token,
                                    ledger: ledger.clone(),
                                })
                                .await
                                .unwrap();
                            release_rx.recv().await.unwrap();
                        }

                        std::fs::write(&worker_output, b"published test archive").unwrap();
                        let output_identity =
                            crate::directory::EntrySourceIdentity::from_path_no_follow(
                                &worker_output,
                                crate::directory::EntryKind::File,
                            )
                            .expect("published test archive has a file identity")
                            .filesystem_identity();
                        #[cfg(windows)]
                        {
                            let (volume, index) = output_identity
                                .windows_parts()
                                .expect("published test archive has a Windows file identity");
                            ledger.output_identity = Some(format!(
                                "{volume:08x}:{:08x}{:08x}",
                                (index >> 32) as u32,
                                index as u32
                            ));
                        }
                        #[cfg(not(windows))]
                        {
                            ledger.output_identity = Some(format!("{output_identity:?}"));
                        }
                        ledger.phase = operations::journal::JournalZipCreatePhase::Published;
                        fact_sender
                            .send(executor::ExecutorFact::ZipCreateLedgerIntent { token, ledger })
                            .await
                            .unwrap();
                        release_rx.recv().await.unwrap();
                        fact_sender
                            .send(executor::ExecutorFact::Terminal {
                                token,
                                report: operations::model::TerminalReport {
                                    outcome: operations::model::TerminalOutcome::Unknown,
                                    final_counters: operations::model::ProgressCounters::default(),
                                    receipts: vec![operations::model::ItemReceipt {
                                        item: operations::model::ItemId(0),
                                        outcome: operations::model::ItemOutcome::Unknown,
                                        detail: Some("published but unjournaled".into()),
                                        created_folder_path: None,
                                        created_archive_path: Some(worker_output.clone()),
                                        move_receipt: None,
                                        replace_receipt: None,
                                        copy_undo: None,
                                    }],
                                    retry: operations::model::RetryPlan::RequiresReinspection,
                                    change_hints: vec![operations::model::FsChangeHint {
                                        directory: worker_output.parent().unwrap().to_path_buf(),
                                    }],
                                },
                            })
                            .await
                            .unwrap();
                    })
                });
                token = Some(owner.runtime.submit(request).unwrap());
                shell.start_next_operation(cx);
            });
        });
        let token = token.unwrap();
        let controls_receiver = run_until_worker_control_receiver(&mut visual, &controls_rx);
        let journal_driver = journal_driver.expect("test journal writer is configured");

        for expected_phase in [
            operations::journal::JournalZipCreatePhase::StagePlanned,
            operations::journal::JournalZipCreatePhase::StageOwned,
            operations::journal::JournalZipCreatePhase::PublishIntent,
        ] {
            let upsert = wait_for_journal_upsert(&mut visual, &journal_driver, "ZIP ledger phase");
            assert_eq!(
                upsert.attempt.zip_create.as_ref().unwrap().phase,
                expected_phase
            );
            upsert.reply(Ok(()));
            assert!(matches!(
                run_until_pumped_worker_control(&mut visual, &controls_receiver),
                executor::WorkerControl::ZipCreateLedgerJournaledExact { token: ack_token, .. }
                    if ack_token == token
            ));
            release_tx.try_send(()).unwrap();
        }

        let published_upsert =
            wait_for_journal_upsert(&mut visual, &journal_driver, "Published ZIP receipt");
        assert!(
            output.exists(),
            "filesystem publication precedes its receipt ACK"
        );
        assert_eq!(
            published_upsert.attempt.zip_create.as_ref().unwrap().phase,
            operations::journal::JournalZipCreatePhase::Published
        );
        visual.update(|_, cx| {
            shell.update(cx, |_, cx| {
                let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
                assert!(owner.runtime.cancel(token).is_none());
            });
        });
        published_upsert.reply(Ok(()));
        assert_eq!(
            run_until_pumped_worker_control(&mut visual, &controls_receiver),
            executor::WorkerControl::Cancel
        );
        release_tx.try_send(()).unwrap();

        let terminal_upsert =
            wait_for_journal_upsert(&mut visual, &journal_driver, "Unknown ZIP terminal");
        assert_eq!(
            terminal_upsert.attempt.terminal_outcome,
            Some(operations::journal::JournalTerminalOutcome::Unknown)
        );
        terminal_upsert.reply(Ok(()));
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(6);
        loop {
            visual.run_until_parked();
            let terminal = visual
                .read_global::<operations::application::OperationApplicationOwner, _>(
                    |owner, _| {
                        owner
                            .runtime
                            .job(token)
                            .and_then(|job| {
                                job.attempts
                                    .into_iter()
                                    .find(|attempt| attempt.token == token)
                            })
                            .is_some_and(|attempt| {
                                attempt.terminal.is_some_and(|report| {
                                    report.outcome == operations::model::TerminalOutcome::Unknown
                                        && report.receipts.iter().any(|receipt| {
                                            receipt.created_archive_path.as_deref()
                                                == Some(output.as_path())
                                        })
                                })
                            })
                    },
                );
            if terminal {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "ZIP terminal receipt did not commit"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
    }

    #[gpui::test]
    fn replace_backup_late_success_after_cancel_is_ignored_by_shell_worker_pump(
        cx: &mut gpui::TestAppContext,
    ) {
        initialize_directory_binding_test_globals(cx);
        let (harness, mut visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let (control_receivers, finish_worker, token, source, destination, backup, journal_driver) =
            replace_intent_pump_harness(shell.clone(), &mut visual, true, true);
        let controls = run_until_worker_control_receiver(&mut visual, &control_receivers);
        let journal_driver = journal_driver.expect("test writer is configured");
        let upsert = {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(6);
            loop {
                visual.run_until_parked();
                if let Some(upsert) = journal_driver.try_upsert() {
                    break upsert;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "Shell pump did not submit the Replace backup intent"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        };
        assert_eq!(
            upsert.attempt.replace_backup,
            Some(operations::journal::JournalReplaceBackup {
                source: operations::journal::JournalPath::from_path(&source),
                destination: operations::journal::JournalPath::from_path(&destination),
                backup: operations::journal::JournalPath::from_path(&backup),
            }),
        );
        assert!(matches!(
            controls.try_recv(),
            Err(std::sync::mpsc::TryRecvError::Empty)
        ));

        assert!(visual.update(|_, cx| {
            cx.global_mut::<operations::application::OperationApplicationOwner>()
                .runtime
                .cancel(token)
                .is_none()
        }));
        assert_eq!(
            run_until_pumped_worker_control(&mut visual, &controls),
            executor::WorkerControl::Cancel,
            "Runtime cancellation must reach the worker while Shell awaits the journal receipt"
        );

        upsert.reply(Ok(()));
        visual.run_until_parked();
        assert!(
            matches!(
                controls.try_recv(),
                Err(std::sync::mpsc::TryRecvError::Empty)
            ),
            "a late successful receipt must not authorize displacement"
        );
        assert_ne!(
            visual.read_entity(&shell, |shell, _| shell.session_notice.clone()),
            Some(SessionNotice::Message(
                Message::ReplaceRecoveryIntentNotSaved
            )),
            "late success must not create a recovery-intent failure notice"
        );

        finish_worker.try_send(()).unwrap();
        let terminal = {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(6);
            loop {
                visual.run_until_parked();
                if let Some(upsert) = journal_driver.try_upsert() {
                    break upsert;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "Shell pump did not submit the cancelled terminal journal update"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        };
        assert_eq!(
            terminal.attempt.state,
            operations::journal::JournalState::Terminal
        );
        assert_eq!(
            terminal.attempt.terminal_outcome,
            Some(operations::journal::JournalTerminalOutcome::Cancelled)
        );
        assert_eq!(
            terminal.attempt.replace_backup, None,
            "known cancellation clears an intent-only backup marker to avoid a false recovery row"
        );
        assert!(
            visual.read_entity(&shell, |shell, cx| {
                shell.operation_worker_claimed_for_test(cx)
            }),
            "worker lane remains claimed while terminal persistence is pending"
        );
        terminal.reply(Ok(()));
        visual.run_until_parked();
        assert!(
            !visual.read_entity(&shell, |shell, cx| {
                shell.operation_worker_claimed_for_test(cx)
            }),
            "worker lane is released after terminal persistence and worker return"
        );
    }

