    #[gpui::test]
    fn replace_backup_journal_failure_notifies_shell_and_releases_worker_lane(
        cx: &mut gpui::TestAppContext,
    ) {
        initialize_directory_binding_test_globals(cx);
        let (harness, mut visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let (control_receivers, finish_worker, _token, _source, _destination, _backup, driver) =
            replace_intent_pump_harness(shell.clone(), &mut visual, true, true);
        let controls = run_until_worker_control_receiver(&mut visual, &control_receivers);
        let driver = driver.expect("test writer is configured");
        let initial_intent = {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(6);
            loop {
                visual.run_until_parked();
                if let Some(upsert) = driver.try_upsert() {
                    break upsert;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "Shell pump did not submit the Replace backup intent"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        };
        initial_intent.reply(Err("journal write failed".into()));

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(6);
        loop {
            visual.run_until_parked();
            let notice = visual.read_entity(&shell, |shell, _| shell.session_notice.clone());
            if notice
                == Some(SessionNotice::Message(
                    Message::ReplaceRecoveryIntentNotSaved,
                ))
            {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "Shell pump did not publish the Replace recovery notice"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert_eq!(
            controls.try_recv().unwrap(),
            executor::WorkerControl::Cancel
        );

        finish_worker.try_send(()).unwrap();
        let terminal = {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(6);
            loop {
                visual.run_until_parked();
                if let Some(upsert) = driver.try_upsert() {
                    break upsert;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "Shell pump did not submit the cancelled terminal update"
                );
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        };
        assert_eq!(
            terminal.attempt.state,
            operations::journal::JournalState::Terminal
        );
        terminal.reply(Ok(()));
        visual.run_until_parked();
        assert!(!visual.read_entity(&shell, |shell, cx| {
            shell.operation_worker_claimed_for_test(cx)
        }));
    }

    #[cfg(target_os = "windows")]
    #[gpui::test]
    fn quick_preview_real_png_uses_production_background_decode(cx: &mut gpui::TestAppContext) {
        initialize_directory_binding_test_globals(cx);
        let fixture_dir = tempfile::tempdir().unwrap();
        let path = fixture_dir.path().join("generated-preview.png");
        let fixture = image::RgbaImage::from_fn(4, 3, |x, y| {
            image::Rgba([(x * 61) as u8, (y * 83) as u8, ((x + y) * 37) as u8, 255])
        });
        fixture.save(&path).unwrap();
        let identity = directory::EntrySourceIdentity::from_path(&path, EntryKind::File)
            .expect("generated regular PNG has a source identity");
        let (completion_sender, completions) = async_channel::unbounded();

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                // Decoder injection intentionally remains unset; only observe the production commit.
                shell.quick_preview_test_completions = Some(completion_sender);
                let replacement = cx.new(|cx| {
                    DirectoryListDemo::new_at(Arc::new(input::KeymapRuntime::new()), None, cx)
                });
                shell.replace_active_view_with_binding_for_test(replacement, cx);
            });
        });
        let view = visual.read_entity(&shell, |shell, _| {
            shell.workspace.active().focused_pane().tabs[0].view.clone()
        });
        visual.update(|_, cx| {
            view.update(cx, |view, _| {
                view.entries = vec![quick_preview_entry_with_identity(&path, identity)];
                view.selection.apply(
                    SelectionIntent::Pick {
                        index: 0,
                        toggle: false,
                        range: false,
                    },
                    1,
                );
            });
        });

        let expected_path = path.clone();
        visual.update(|_, cx| {
            view.update(cx, |view, cx| {
                cx.emit(DirectoryEvent::QuickPreview {
                    target: view.quick_preview_target(0),
                    open: true,
                });
            });
        });
        visual.run_until_parked();

        let (completed_target, accepted) = completions
            .try_recv()
            .expect("production decoder completion should reach Shell");
        assert_eq!(completed_target.path, expected_path);
        assert!(accepted, "real generated PNG should be accepted");
        visual.read_entity(&shell, |shell, _| match shell.quick_preview.content() {
            Some(quick_preview::Content::Image(_)) => {}
            Some(quick_preview::Content::Failed) => {
                panic!("generated regular PNG should decode successfully")
            }
            Some(quick_preview::Content::Loading) | None => {
                panic!("production decode should complete before the test parks")
            }
            _ => panic!("PNG preview should publish image content"),
        });

        let generic_path = fixture_dir.path().join("unsupported.gpui-filer-test");
        visual.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.entries = vec![quick_preview_entry_with_identity(
                    &generic_path,
                    directory::EntrySourceIdentity::test(
                        EntryKind::File,
                        generic_path.to_string_lossy().into_owned(),
                    ),
                )];
                let target = view.quick_preview_target(0);
                assert!(target.is_some(), "ordinary unsupported row stays eligible");
                assert_eq!(
                    target.as_ref().and_then(|target| target.fallback_icon),
                    Some(gpui_filer_resources::IconId::File)
                );
                cx.emit(DirectoryEvent::QuickPreview { target, open: true });
            });
        });
        visual.run_until_parked();
        let (completed_target, accepted) = completions
            .try_recv()
            .expect("generic production decode completion should reach Shell");
        assert_eq!(completed_target.path, generic_path);
        assert!(
            accepted,
            "generic fallback should pass the normal owner gate"
        );
        visual.read_entity(&shell, |shell, _| {
            assert!(matches!(
                shell.quick_preview.content(),
                Some(quick_preview::Content::Generic(
                    gpui_filer_resources::IconId::File
                ))
            ));
        });
    }

    #[gpui::test]
    fn focus_retarget_rejects_late_quick_preview_decode(cx: &mut gpui::TestAppContext) {
        initialize_directory_binding_test_globals(cx);
        let (decode_sender, decode_requests) = async_channel::unbounded();
        let (completion_sender, completions) = async_channel::unbounded();
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());

        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                shell.quick_preview_decode_test_requests = Some(decode_sender);
                shell.quick_preview_test_completions = Some(completion_sender);
                let replacement = cx.new(|cx| {
                    DirectoryListDemo::new_at(Arc::new(input::KeymapRuntime::new()), None, cx)
                });
                shell.replace_active_view_with_binding_for_test(replacement, cx);
            });
        });
        let view = visual.read_entity(&shell, |shell, _| {
            shell.workspace.active().focused_pane().tabs[0].view.clone()
        });
        visual.update(|_, cx| {
            view.update(cx, |view, _| {
                let mut supported_without_identity =
                    quick_preview_test_entry("C:/quick-preview/identity-less.txt");
                supported_without_identity.source_identity = None;
                let mut unsupported_without_identity =
                    quick_preview_test_entry("C:/quick-preview/identity-less.unknown");
                unsupported_without_identity.source_identity = None;
                let mut reparse_file = quick_preview_test_entry("C:/quick-preview/link.txt");
                reparse_file.link = Some(directory::LinkKind::LinkOrJunction);
                view.entries = vec![
                    supported_without_identity,
                    unsupported_without_identity,
                    reparse_file,
                ];
                assert!(view.quick_preview_target(0).is_some());
                assert!(view.quick_preview_target(1).is_none());
                assert!(view.quick_preview_target(2).is_none());

                view.entries = vec![
                    quick_preview_test_entry("C:/quick-preview/a.txt"),
                    quick_preview_test_entry("C:/quick-preview/b.gpui-filer-test"),
                ];
                view.selection.apply(
                    SelectionIntent::Pick {
                        index: 0,
                        toggle: false,
                        range: false,
                    },
                    2,
                );
            });
        });

        // A のdecode requestを保持し、実際のfocus移動eventでBへretargetしてから順にcommitする。
        visual.update(|_, cx| {
            view.update(cx, |view, cx| {
                cx.emit(DirectoryEvent::QuickPreview {
                    target: view.quick_preview_target(0),
                    open: true,
                });
            });
        });
        visual.run_until_parked();
        let request_a = decode_requests.try_recv().unwrap();
        let completion_a = request_a.completion.clone();
        assert!(completion_a.target.path.ends_with("a.txt"));
        assert!(completions.try_recv().is_err());

        visual.update(|_, cx| {
            view.update(cx, |view, cx| {
                assert!(view.move_focus(FocusDelta::Right, false, cx));
            });
        });
        visual.run_until_parked();
        let request_b = decode_requests.try_recv().unwrap();
        let completion_b = request_b.completion.clone();
        assert!(completion_b.target.path.ends_with("b.gpui-filer-test"));
        assert_eq!(
            completion_b.target.fallback_icon,
            Some(gpui_filer_resources::IconId::File)
        );
        assert_ne!(completion_a.target, completion_b.target);
        assert!(completions.try_recv().is_err());

        request_a
            .result_sender
            .try_send(quick_preview::Decoded::test_envelope(
                quick_preview::Content::Text(quick_preview::TextPreview {
                    text: "A result".into(),
                    encoding: "UTF-8",
                    lossy: false,
                    truncated: false,
                }),
            ))
            .unwrap();
        visual.run_until_parked();
        let (completed_a, accepted_a) = completions.try_recv().unwrap();
        assert_eq!(completed_a, completion_a.target);
        assert!(!accepted_a);
        visual.read_entity(&shell, |shell, _| {
            assert!(matches!(
                shell.quick_preview.content(),
                Some(quick_preview::Content::Loading)
            ));
        });

        request_b
            .result_sender
            .try_send(quick_preview::Decoded::test_envelope(
                quick_preview::Content::Generic(gpui_filer_resources::IconId::File),
            ))
            .unwrap();
        visual.run_until_parked();
        let (completed_b, accepted_b) = completions.try_recv().unwrap();
        assert_eq!(completed_b, completion_b.target);
        assert!(accepted_b);
        visual.read_entity(&shell, |shell, _| match shell.quick_preview.content() {
            Some(quick_preview::Content::Generic(gpui_filer_resources::IconId::File)) => {}
            _ => panic!("B quick preview should be committed"),
        });
    }

    #[gpui::test]
    fn transferred_directory_event_subscription_replaces_source_binding(
        cx: &mut gpui::TestAppContext,
    ) {
        initialize_directory_binding_test_globals(cx);
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let keymap_runtime = Arc::new(input::KeymapRuntime::new());
            let source = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    keymap_runtime.clone(),
                    Vec::new(),
                    cx,
                )
            });
            let destination = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    keymap_runtime,
                    Vec::new(),
                    cx,
                )
            });
            DirectoryBindingHarness {
                source,
                destination,
            }
        });
        let (source, destination) = visual.read_entity(&harness, |harness, _| {
            (harness.source.clone(), harness.destination.clone())
        });
        let view = visual.read_entity(&source, |source, _| {
            let tab = source.workspace.active().tabs().next().unwrap();
            tab.view.clone()
        });
        visual.update(|_, cx| {
            source.update(cx, |source, _| source.save_requested = false);
            destination.update(cx, |destination, _| destination.save_requested = false);
        });

        // 未採用の間は元のsubscriptionだけがイベントを受け取る。
        visual.update(|_, cx| {
            view.update(cx, |_, cx| cx.emit(DirectoryEvent::StateChanged));
        });
        visual.read_entity(&source, |source, _| assert!(source.save_requested));
        visual.read_entity(&destination, |destination, _| {
            assert!(!destination.save_requested)
        });

        // Transfer commitと同じ順序でWorkspaceを移し、保持したTabのsubscriptionを置換する。
        visual.update(|_, cx| {
            source.update(cx, |source, _| source.save_requested = false);
            destination.update(cx, |destination, _| destination.save_requested = false);
            let (workspace_id, workspace) =
                source.update(cx, |source, _| source.workspace.ordered.remove(0));
            destination.update(cx, |destination, cx| {
                destination.workspace.ordered.clear();
                destination
                    .workspace
                    .ordered
                    .push((workspace_id, workspace));
                destination.workspace.active = workspace_id;
                destination.bind_workspace_tabs(workspace_id, cx);
            });
            view.update(cx, |_, cx| cx.emit(DirectoryEvent::StateChanged));
        });

        visual.read_entity(&source, |source, _| assert!(!source.save_requested));
        visual.read_entity(&destination, |destination, _| {
            assert!(destination.save_requested)
        });
    }

    #[gpui::test]
    fn create_folder_admission_rejects_stale_tab_view_and_location(cx: &mut gpui::TestAppContext) {
        initialize_directory_binding_test_globals(cx);
        let original = tempfile::tempdir().unwrap();
        let destination = tempfile::tempdir().unwrap();
        let original_path = original.path().to_path_buf();
        let destination_path = destination.path().to_path_buf();
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let keymap_runtime = Arc::new(input::KeymapRuntime::new());
            let source = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    keymap_runtime.clone(),
                    Vec::new(),
                    cx,
                )
            });
            let destination = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    keymap_runtime,
                    Vec::new(),
                    cx,
                )
            });
            DirectoryBindingHarness {
                source,
                destination,
            }
        });
        let (source, other_shell) = visual.read_entity(&harness, |harness, _| {
            (harness.source.clone(), harness.destination.clone())
        });
        visual.update(|_, app| {
            source.update(app, |shell, cx| {
                let pane = shell.workspace.active().focused_pane();
                let tab = pane
                    .tabs
                    .iter()
                    .find(|tab| tab.id == pane.active_tab_id)
                    .expect("active directory tab");
                tab.view
                    .update(cx, |view, cx| view.navigate(original_path.clone(), cx));
            });
        });
        visual.run_until_parked();

        let (view_id, view_entity, identity, epoch, revision) =
            visual.read_entity(&source, |shell, cx| {
                let pane = shell.workspace.active().focused_pane();
                let tab = pane
                    .tabs
                    .iter()
                    .find(|tab| tab.id == pane.active_tab_id)
                    .expect("active directory tab");
                let view = tab.view.read(cx);
                (
                    tab.id,
                    tab.view.entity_id(),
                    view.session.directory_identity().cloned().unwrap(),
                    view.location_generation,
                    view.presentation_revision,
                )
            });
        macro_rules! check_target {
            ($target_view_id:expr, $target_view_entity:expr) => {{
                let accepted = std::rc::Rc::new(std::cell::Cell::new(false));
                let accepted_copy = accepted.clone();
                let target_view_id = $target_view_id;
                let target_view_entity = $target_view_entity;
                visual.update(|_, app| {
                    source.update(app, |shell, cx| {
                        accepted_copy.set(shell.clipboard_paste_target_is_current(
                            &original_path,
                            &identity,
                            target_view_id,
                            target_view_entity,
                            epoch,
                            revision,
                            None,
                            cx,
                        ));
                    });
                });
                accepted.get()
            }};
        }
        assert!(check_target!(view_id, view_entity));

        let other_view_entity = visual.read_entity(&other_shell, |shell, _| {
            let pane = shell.workspace.active().focused_pane();
            pane.tabs
                .iter()
                .find(|tab| tab.id == pane.active_tab_id)
                .expect("other active directory tab")
                .view
                .entity_id()
        });
        assert!(!check_target!(view_id, other_view_entity));
        assert!(!check_target!(view_id.wrapping_add(1), view_entity));

        visual.update(|_, app| {
            source.update(app, |shell, cx| {
                let pane = shell.workspace.active().focused_pane();
                let tab = pane
                    .tabs
                    .iter()
                    .find(|tab| tab.id == pane.active_tab_id)
                    .expect("active directory tab");
                tab.view
                    .update(cx, |view, cx| view.navigate(destination_path.clone(), cx));
            });
        });
        visual.run_until_parked();
        assert!(!check_target!(view_id, view_entity));
    }

