    #[gpui::test]
    fn recovery_copy_real_journal_primary_lock_rejects_admission_without_starting_worker(
        cx: &mut gpui::TestAppContext,
    ) {
        use operations::journal::{JournalPath, JournalStore};
        use std::os::windows::ffi::OsStrExt;
        use windows::Win32::Storage::FileSystem::{
            CreateFileW, FILE_ATTRIBUTE_NORMAL, FILE_SHARE_MODE, OPEN_EXISTING,
        };

        struct JournalPrimaryLock(windows::Win32::Foundation::HANDLE);
        impl JournalPrimaryLock {
            fn hold(path: &std::path::Path) -> Self {
                let wide = path
                    .as_os_str()
                    .encode_wide()
                    .chain([0])
                    .collect::<Vec<_>>();
                let handle = unsafe {
                    CreateFileW(
                        windows::core::PCWSTR(wide.as_ptr()),
                        0x8000_0000u32,
                        FILE_SHARE_MODE(0),
                        None,
                        OPEN_EXISTING,
                        FILE_ATTRIBUTE_NORMAL,
                        None,
                    )
                }
                .expect("hold the existing journal primary without sharing");
                Self(handle)
            }
        }
        impl Drop for JournalPrimaryLock {
            fn drop(&mut self) {
                let _ = unsafe { windows::Win32::Foundation::CloseHandle(self.0) };
            }
        }

        initialize_directory_binding_test_globals(cx);
        let temp = tempfile::tempdir().unwrap();
        let journal_path = temp.path().join("operations.json");
        let backup_path = temp.path().join("operations.json.bak");
        let source = temp.path().join("recovery-current.txt");
        let destination = temp.path().join("destination");
        let source_bytes = b"current source bytes";
        std::fs::write(&source, source_bytes).unwrap();
        std::fs::create_dir(&destination).unwrap();
        let source_identity = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &source,
            crate::directory::EntryKind::File,
        )
        .unwrap();

        let mut historical = test_recovery_attempt("recovery-copy-journal-lock");
        historical.sources = vec![JournalPath::from_path(&source)];
        historical.destination = Some(JournalPath::from_path(&destination));
        let historical_json = serde_json::to_vec(&historical).unwrap();
        let mut store = JournalStore::open(journal_path.clone()).unwrap();
        store.upsert(historical.clone()).unwrap();
        drop(store);
        let historical_primary = std::fs::read(&journal_path).unwrap();
        let historical_backup = std::fs::read(&backup_path).ok();
        cx.update(|cx| {
            *cx.global_mut::<operations::application::OperationApplicationOwner>() =
                operations::application::OperationApplicationOwner::for_test_with_journal_store(
                    JournalStore::open(journal_path.clone()).unwrap(),
                );
        });
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            SearchShellRoot { shell }
        });
        let shell = visual.read_entity(&harness, |root, _| root.shell.clone());
        let writer = visual.read_global::<
            operations::application::OperationApplicationOwner,
            _,
        >(|owner, _| owner.journal.clone().expect("production JournalWriter is installed"));
        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                shell.operation_progress_open = true;
                cx.notify();
            });
        });
        visual.run_until_parked();
        assert!(visual.debug_bounds("operation-recovery-summary").is_some());

        // H と Shell route が用意できてから primary を開き、retry の間も保持する。
        let primary_lock = JournalPrimaryLock::hold(&journal_path);
        visual.update(|_, cx| cx.background_executor().allow_parking());
        let action_id = "operation-recovery-new-copy-recovery-copy-journal-lock";
        let action = visual.debug_bounds(action_id).expect("rendered Recovery Copy action");
        let point = gpui::point(
            action.origin.x + action.size.width / 2.0,
            action.origin.y + action.size.height / 2.0,
        );
        visual.simulate_mouse_down(point, gpui::MouseButton::Left, gpui::Modifiers::default());
        visual.simulate_mouse_up(point, gpui::MouseButton::Left, gpui::Modifiers::default());

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
        let (token, queued_record) = loop {
            visual.run_until_parked();
            let queued = visual.read_global::<
                operations::application::OperationApplicationOwner,
                _,
            >(|owner, _| {
                owner.runtime.jobs().iter().find_map(|job| {
                    job.request.sources.iter().any(|path| path == &source)
                        .then(|| job.attempts.last().map(|attempt| (attempt.token, job)))
                        .flatten()
                        .and_then(|(token, _)| owner.runtime.journal_attempt(token).map(|record| (token, record)))
                })
            });
            if let Some((token, record)) = queued {
                if record.state == operations::journal::JournalState::Queued {
                    break (token, record);
                }
            }
            assert!(std::time::Instant::now() < deadline, "Recovery Copy did not create a queued attempt");
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        assert_ne!(queued_record.key, historical.key);
        assert!(visual.debug_bounds(action_id).is_none(), "the reserved action stays unavailable until the writer receipt");

        // This second real writer receipt exposes the OS code while the Shell's own
        // queued upsert is ahead of it and fails under the same held primary lock.
        let probe_receipt = writer.upsert_with_reply(queued_record.clone());
        let writer_error = loop {
            visual.run_until_parked();
            match probe_receipt.try_recv() {
                Ok(Err(error)) => break error,
                Ok(Ok(())) => panic!("locked journal replacement unexpectedly succeeded"),
                Err(async_channel::TryRecvError::Closed) => panic!("JournalWriter dropped its failure receipt"),
                Err(async_channel::TryRecvError::Empty) => {}
            }
            assert!(std::time::Instant::now() < deadline, "locked JournalWriter replacement did not fail");
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        let sharing_hresult = 0x8007_0020u32;
        assert!(writer_error.contains(&sharing_hresult.to_string()), "expected HRESULT 0x80070020, got: {writer_error}");

        loop {
            visual.run_until_parked();
            let settled = visual.read_global::<
                operations::application::OperationApplicationOwner,
                _,
            >(|owner, _| {
                owner.runtime.jobs().is_empty()
                    && !owner.recovery_copy_admission_pending(&historical.key)
                    && owner.recovery_copy_action_available(&owner.recovery_records[0])
                    && owner.recovery_records[0] == historical
                    && serde_json::to_vec(&owner.recovery_records[0]).ok().as_deref()
                        == Some(historical_json.as_slice())
            });
            if settled && visual.debug_bounds(action_id).is_some() {
                break;
            }
            assert!(std::time::Instant::now() < deadline, "Shell did not reject the failed durable admission");
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert!(!visual.read_global::<operations::application::OperationApplicationOwner, _>(
            |owner, _| owner.worker_claimed_for_test()
        ));
        drop(primary_lock);
        assert_eq!(std::fs::read(&journal_path).unwrap(), historical_primary);
        assert_eq!(std::fs::read(&backup_path).ok(), historical_backup);
        assert_eq!(std::fs::read(&source).unwrap(), source_bytes);
        assert_eq!(
            crate::directory::EntrySourceIdentity::from_path_no_follow(
                &source,
                crate::directory::EntryKind::File,
            )
            .unwrap(),
            source_identity,
        );
        assert!(std::fs::read_dir(&destination).unwrap().next().is_none());
        let journal_files = std::fs::read_dir(temp.path())
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .collect::<Vec<_>>();
        assert!(!journal_files.iter().any(|name| name.ends_with(".tmp")));
        let persisted: serde_json::Value = serde_json::from_slice(&historical_primary).unwrap();
        let persisted_attempts = persisted["attempts"].as_array().unwrap();
        assert_eq!(persisted_attempts.len(), 1);
        assert_eq!(
            serde_json::from_value::<operations::journal::JournalAttempt>(persisted_attempts[0].clone()).unwrap(),
            historical,
        );
        assert_eq!(historical_json, serde_json::to_vec(&historical).unwrap());

        let reopened = JournalStore::open(journal_path).unwrap();
        assert_eq!(reopened.recoveries(), [operations::journal::RecoveryItem::RecoveryRequired(historical.clone())]);
        let fresh = operations::application::OperationApplicationOwner::for_test_with_journal_store(reopened);
        assert!(fresh.runtime.jobs().is_empty());
        assert_eq!(fresh.recovery_records, [historical]);
        assert_eq!(fresh.runtime.job(token), None);
    }

    fn run_recovery_copy_shell_admission(
        cx: &mut gpui::TestAppContext,
        admission_result: Result<(), String>,
    ) {
        use operations::journal::{JournalPath, JournalWriterCommandForTest};

        initialize_directory_binding_test_globals(cx);
        let temp = tempfile::tempdir().unwrap();
        let source = temp.path().join("recovery-current.txt");
        let destination = temp.path().join("destination");
        std::fs::write(&source, b"current source bytes").unwrap();
        std::fs::create_dir(&destination).unwrap();
        let mut attempt = test_recovery_attempt("recovery-copy-shell-route");
        attempt.sources = vec![JournalPath::from_path(&source)];
        attempt.destination = Some(JournalPath::from_path(&destination));
        let historical_bytes = serde_json::to_vec(&attempt).unwrap();
        let (journal_writer, journal_driver) = operations::journal::JournalWriter::test_driver();
        cx.update(|cx| {
            *cx.global_mut::<operations::application::OperationApplicationOwner>() =
                operations::application::OperationApplicationOwner::for_test();
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            owner.recovery_records = vec![attempt];
            owner.journal = Some(journal_writer);
        });
        cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
            assert_eq!(owner.recovery_records.len(), 1);
            assert!(owner.recovery_copy_action_available(&owner.recovery_records[0]));
        });

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            SearchShellRoot { shell }
        });
        let shell = visual.read_entity(&harness, |root, _| root.shell.clone());
        visual.update(|_, cx| shell.update(cx, |shell, cx| {
            shell.operation_progress_open = true;
            cx.notify();
        }));
        visual.run_until_parked();
        assert!(visual.debug_bounds("operation-recovery-summary").is_some(), "history pane is rendered");

        let action_id = "operation-recovery-new-copy-recovery-copy-shell-route";
        let action = visual.debug_bounds(action_id).expect("recovery Copy action is rendered");
        let point = gpui::point(
            action.origin.x + action.size.width / 2.0,
            action.origin.y + action.size.height / 2.0,
        );
        visual.simulate_mouse_down(point, gpui::MouseButton::Left, gpui::Modifiers::default());
        visual.simulate_mouse_up(point, gpui::MouseButton::Left, gpui::Modifiers::default());

        let admission_succeeds = admission_result.is_ok();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let mut durable_admission_reply_received = false;
        loop {
            visual.run_until_parked();
            if !durable_admission_reply_received {
                if let Some(command) = journal_driver.try_command() {
                    match command {
                        JournalWriterCommandForTest::Upsert(upsert) => {
                            assert_eq!(upsert.attempt.kind, operations::journal::JournalKind::Copy);
                            assert_eq!(upsert.attempt.state, operations::journal::JournalState::Queued);
                            assert_ne!(upsert.attempt.key, "recovery-copy-shell-route");
                            upsert.reply(admission_result.clone());
                            durable_admission_reply_received = true;
                        }
                        other => panic!("unexpected Recovery Copy admission command: {}", other.name()),
                    }
                }
            }
            let settled = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                let admitted = owner.runtime.jobs().iter().any(|job| job.request.sources == vec![source.clone()]
                    && job.request.destination.as_deref() == Some(destination.as_path()));
                if admission_succeeds {
                    admitted && !owner.recovery_copy_action_available(&owner.recovery_records[0])
                } else {
                    !admitted && owner.runtime.jobs().is_empty()
                        && owner.recovery_copy_action_available(&owner.recovery_records[0])
                }
            });
            let action_is_projected = visual.debug_bounds(action_id).is_some() == !admission_succeeds;
            if settled && action_is_projected && durable_admission_reply_received {
                break;
            }
            assert!(std::time::Instant::now() < deadline, "rendered Recovery Copy admission did not settle");
            std::thread::sleep(std::time::Duration::from_millis(1));
        }

        visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
            assert_eq!(owner.recovery_records.len(), 1, "admission result preserves the historical record");
            assert_eq!(serde_json::to_vec(&owner.recovery_records[0]).unwrap(), historical_bytes);
            if admission_succeeds {
                assert_eq!(owner.runtime.jobs().len(), 1, "one click admits exactly one new job");
                let job = &owner.runtime.jobs()[0];
                assert_eq!(job.attempts.last().unwrap().state, operations::model::AttemptState::Queued);
            } else {
                assert!(owner.runtime.jobs().is_empty(), "failed durable admission leaves no Runtime job");
            }
        });
        assert!(!destination.join("recovery-current.txt").exists());
        assert_eq!(std::fs::read(source).unwrap(), b"current source bytes");
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires a disposable local NTFS fixture"]
    fn directory_copy_created_stage_identity_failure_reopens_as_indeterminate_review(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::path::{Component, Prefix};
        use std::os::windows::ffi::OsStringExt;

        initialize_directory_binding_test_globals(cx);
        let volume = std::env::current_exe().unwrap().parent().unwrap().to_path_buf();
        let Some(Component::Prefix(prefix)) = volume.components().next() else {
            panic!("test binary must be on a drive volume");
        };
        let (Prefix::Disk(letter) | Prefix::VerbatimDisk(letter)) = prefix.kind() else {
            panic!("test binary must be on a local drive");
        };
        let drive = format!("{}:\\", letter as char);
        let drive_wide = drive.encode_utf16().chain([0]).collect::<Vec<_>>();
        let mut filesystem = [0u16; 32];
        assert!(unsafe {
            windows::Win32::Storage::FileSystem::GetDriveTypeW(windows::core::PCWSTR(drive_wide.as_ptr())) == 3
                && windows::Win32::Storage::FileSystem::GetVolumeInformationW(
                    windows::core::PCWSTR(drive_wide.as_ptr()), None, None, None, None, Some(&mut filesystem),
                ).is_ok()
                && String::from_utf16_lossy(&filesystem).trim_end_matches(char::from(0)).eq_ignore_ascii_case("NTFS")
        }, "fixture requires a local NTFS volume");

        let fixture = tempfile::Builder::new().prefix("gpui-filer-copy-stage-id-review-")
            .tempdir_in(&volume).unwrap();
        let source = fixture.path().join("source-parent").join("tree");
        let destination_parent = fixture.path().join("destination-parent");
        let destination = destination_parent.join("tree");
        std::fs::create_dir_all(&source).unwrap();
        std::fs::create_dir(&destination_parent).unwrap();
        std::fs::write(source.join("payload.bin"), b"identity query fault payload").unwrap();
        let journal_path = fixture.path().join("operations.json");
        let store = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        cx.update(|cx| cx.set_global(
            operations::application::OperationApplicationOwner::for_test_with_journal_store(store)));
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| FilerShell::new(
                persistence::Startup::disabled(), Arc::new(input::KeymapRuntime::new()), Vec::new(), cx));
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let mut token = None;
        let mut driver = None;
        let mut real_writer = None;
        visual.update(|_, cx| shell.update(cx, |shell, cx| {
            let owner = cx.global_mut::<operations::application::OperationApplicationOwner>();
            let admitted = owner.runtime.submit(copy_request(
                source.to_string_lossy().as_ref(), destination_parent.to_string_lossy().as_ref(),
            )).unwrap();
            token = Some(admitted);
            let mut running = owner.runtime.journal_attempt(admitted).unwrap();
            running.state = operations::journal::JournalState::Running;
            operations::journal::JournalStore::open(journal_path.clone()).unwrap()
                .upsert(running).unwrap();
            real_writer = Some(operations::journal::JournalWriter::start(
                operations::journal::JournalStore::open(journal_path.clone()).unwrap()));
            let (writer, test_driver) = operations::journal::JournalWriter::test_driver();
            owner.journal = Some(writer);
            driver = Some(test_driver);
            owner.configure_worker_pump_test(move |worker, fact_sender| {
                let (command, cancellation, controls, lease) = (
                    worker.command, worker.cancellation, worker.controls, worker.source_cleanup_lease,
                );
                let (finished_tx, finished_rx) = async_channel::bounded::<()>(1);
                let (joined_tx, joined_rx) = async_channel::bounded::<()>(1);
                let thread = std::thread::spawn(move || {
                    executor::fail_next_copy_directory_stage_root_identity_for_test();
                    executor::execute_prepare_with_source_cleanup_lease(
                        command, cancellation.as_ref(), &controls, lease,
                        |fact| fact_sender.publish(fact),
                    );
                    finished_tx.send_blocking(()).unwrap();
                });
                std::thread::spawn(move || {
                    thread.join().unwrap();
                    joined_tx.send_blocking(()).unwrap();
                });
                Box::pin(async move {
                    finished_rx.recv().await.unwrap();
                    joined_rx.recv().await.unwrap();
                })
            });
            cx.background_executor().allow_parking();
            shell.start_next_operation(cx);
        }));
        let token = token.unwrap();
        let driver = driver.unwrap();
        let real_writer = real_writer.unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        let terminal = loop {
            visual.run_until_parked();
            if let Some(operations::journal::JournalWriterCommandForTest::Upsert(upsert)) = driver.try_command() {
                if upsert.attempt.state == operations::journal::JournalState::Terminal {
                    break upsert;
                }
                upsert.reply(Ok(()));
            }
            assert!(std::time::Instant::now() < deadline, "Copy terminal journal command timed out");
            std::thread::sleep(std::time::Duration::from_millis(1));
        };
        assert_eq!(terminal.attempt.terminal_outcome,
            Some(operations::journal::JournalTerminalOutcome::Unknown));
        let stage_record = terminal.attempt.copy_directory_stage.as_ref().expect("worker emits stage evidence");
        assert_eq!(stage_record.item, 0);
        assert_eq!(stage_record.source, operations::journal::JournalPath::from_path(&source));
        assert_eq!(stage_record.destination, operations::journal::JournalPath::from_path(&destination));
        assert_eq!(stage_record.evidence.phase,
            operations::model::CopyDirectoryStagePhase::CreatedRootIdentityUnverified);
        assert!(stage_record.evidence.expected_root_identity.is_empty());
        let stage_evidence = stage_record.evidence.clone();
        let stage = std::path::PathBuf::from(std::ffi::OsString::from_wide(
            &stage_evidence.stage_path_units));
        assert!(stage.is_dir());
        let stage_identity_before_review = crate::directory::EntrySourceIdentity::from_path_no_follow(
            &stage, crate::directory::EntryKind::Folder,
        ).unwrap().filesystem_identity();
        let stage_children_before_review = std::fs::read_dir(&stage).unwrap()
            .map(|entry| entry.unwrap().file_name()).collect::<Vec<_>>();
        assert!(stage_children_before_review.is_empty());
        assert!(!destination.exists());
        let exact_record = terminal.attempt.clone();
        let durable = real_writer.upsert_with_reply(exact_record.clone());
        while durable.is_empty() {
            assert!(std::time::Instant::now() < deadline, "real JournalWriter terminal ACK timed out");
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert!(durable.recv_blocking().unwrap().is_ok());
        terminal.reply(Ok(()));
        while visual.update(|_, cx| cx.global::<operations::application::OperationApplicationOwner>()
            .worker_claimed_for_test()) {
            visual.run_until_parked();
            assert!(std::time::Instant::now() < deadline, "Copy worker lane did not release");
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        let (live_ticket, live_review, live_terminal) = visual.read_entity(&shell, |_, cx| {
            cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
                let (ticket, review) = owner.runtime.latest_copy_failure_inspection(token)
                    .expect("returned live Copy inspection has an exact ticket");
                (ticket, review.cloned(), owner.runtime.job(token).unwrap().attempts[0].terminal.clone().unwrap())
            })
        });
        let live_review = live_review.expect("live Copy Review completed before owner replacement");
        assert_eq!(live_review.attempt, token);
        assert_eq!(live_review.directory_candidates.len(), 1);
        assert_eq!(live_review.directory_candidates[0].evidence,
            operations::model::CopyDirectoryInspectionEvidence::RetainedStage(stage_evidence.clone()));
        assert_eq!(live_review.directory_candidates[0].stage_root, operations::model::CopyInspectionState::Indeterminate);
        assert!(visual.read_entity(&shell, |_, cx| cx.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
            owner.runtime.verified_copy_retry_guards(token, live_ticket).unwrap_or_default().is_empty()
                && owner.runtime.verified_copy_stage_cleanup_items(token, live_ticket).unwrap_or_default().is_empty()
                && owner.runtime.undo_snapshot_for_test().1.is_empty()
        })), "live directory Review grants no retry, cleanup, or Undo authority");
        assert_eq!(visual.read_entity(&shell, |_, cx| cx.global::<operations::application::OperationApplicationOwner>()
            .runtime.job(token).unwrap().attempts[0].terminal.clone().unwrap()), live_terminal);
        visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
            let snapshot = owner.runtime.job(token).unwrap();
            let report = snapshot.attempts.iter().find(|attempt| attempt.token == token)
                .and_then(|attempt| attempt.terminal.as_ref()).expect("Unknown terminal reached Runtime");
            assert_eq!(report.outcome, operations::model::TerminalOutcome::Unknown);
            assert!(matches!(report.receipts.as_slice(), [receipt]
                if receipt.item == operations::model::ItemId(0)
                    && receipt.outcome == operations::model::ItemOutcome::Unknown));
        });
        drop(real_writer);
        let bytes_before_review = std::fs::read(&journal_path).unwrap();
        let reopened = operations::journal::JournalStore::open(journal_path.clone()).unwrap();
        assert!(matches!(reopened.recoveries().as_slice(), [operations::journal::RecoveryItem::RecoveryRequired(attempt)]
            if attempt.key == exact_record.key && attempt.copy_directory_stage == exact_record.copy_directory_stage));
        let owner = operations::application::OperationApplicationOwner::for_test_with_journal_store(reopened);
        assert!(owner.runtime.jobs().is_empty());
        cx.update(|cx| cx.set_global(owner));
        let (fresh_shell, fresh_visual) = cx.add_window_view(|_, cx| FilerShell::new(
            persistence::Startup::disabled(), Arc::new(input::KeymapRuntime::new()), Vec::new(), cx));
        let recovery_key = exact_record.key.clone();
        fresh_visual.update(|_, cx| fresh_shell.update(cx, |shell, cx| {
            shell.toggle_recovery_details(recovery_key.clone(), cx);
        }));
        loop {
            fresh_visual.run_until_parked();
            let reviewed = fresh_visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.reopened_copy_stage_review(&recovery_key).is_some_and(|(_, state)|
                    matches!(state, operations::model::ReopenedCopyStageReviewState::Available(review)
                        if review.historical.evidence.phase == operations::model::CopyDirectoryStagePhase::CreatedRootIdentityUnverified
                            && review.historical.evidence.expected_root_identity.is_empty()
                            && review.historical.evidence.stage_path_units == stage_evidence.stage_path_units
                            && review.stage_root_observation == operations::model::CopyInspectionState::Indeterminate
                            && review.destination_root_observation == operations::model::CopyInspectionState::Indeterminate)));
            if reviewed { break; }
            assert!(std::time::Instant::now() < deadline, "fresh-owner stage review timed out");
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert!(fresh_visual.debug_bounds("operation-recovery-summary").is_some());
        assert!(fresh_visual.debug_bounds("operation-recovery-detail-text").is_some());
        fresh_visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
            assert!(owner.runtime.jobs().is_empty(), "reopened Review starts no Runtime job"));
        assert_eq!(std::fs::read(&journal_path).unwrap(), bytes_before_review,
            "fresh-owner Review does not mutate durable journal bytes");
        assert_eq!(std::fs::read(source.join("payload.bin")).unwrap(), b"identity query fault payload");
        assert!(stage.is_dir());
        assert_eq!(crate::directory::EntrySourceIdentity::from_path_no_follow(
            &stage, crate::directory::EntryKind::Folder,
        ).unwrap().filesystem_identity(), stage_identity_before_review);
        assert_eq!(std::fs::read_dir(&stage).unwrap().map(|entry| entry.unwrap().file_name())
            .collect::<Vec<_>>(), stage_children_before_review);
        assert!(!destination.exists());
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore = "requires a disposable local NTFS fixture"]
    fn reopened_copy_stage_review_renders_persisted_evidence_without_mutation_authority(
        cx: &mut gpui::TestAppContext,
    ) {
        use operations::journal::{
            JournalCopyDirectoryStageEvidence, JournalPath, JournalState, JournalStore,
            JournalTerminalOutcome, RecoveryItem,
        };
        use operations::model::{CopyDirectoryStageEvidence, CopyDirectoryStagePhase};

        initialize_directory_binding_test_globals(cx);
        let fixture = tempfile::tempdir().unwrap();
        let source = fixture.path().join("source-folder");
        let target_parent = fixture.path().join("target");
        let destination = target_parent.join("source-folder");
        let stage = target_parent.join(".gpui-filer-copy-stage");
        std::fs::create_dir(&source).unwrap();
        std::fs::create_dir(&target_parent).unwrap();
        std::fs::create_dir(&stage).unwrap();
        std::fs::write(stage.join("partial.txt"), b"partial payload").unwrap();

        let mut record = test_recovery_attempt("retained-copy-stage");
        record.kind = operations::journal::JournalKind::Copy;
        record.state = JournalState::Terminal;
        record.sources = vec![JournalPath::from_path(&source)];
        record.destination = Some(JournalPath::from_path(&target_parent));
        record.receipts_recorded = true;
        record.terminal_outcome = Some(JournalTerminalOutcome::Unknown);
        record.copy_directory_stage = Some(JournalCopyDirectoryStageEvidence {
            item: 0,
            source: JournalPath::from_path(&source),
            destination: JournalPath::from_path(&destination),
            evidence: CopyDirectoryStageEvidence {
                stage_path_units: JournalPath::from_path(&stage).units,
                destination_path_units: JournalPath::from_path(&destination).units,
                expected_root_identity: "historical-stage-root-identity".into(),
                phase: CopyDirectoryStagePhase::StagingCancelled,
                detail: "copy stopped after staging partial.txt".into(),
            },
        });
        let journal_path = fixture.path().join("operations.json");
        let mut store = JournalStore::open(journal_path.clone()).unwrap();
        store.upsert(record).unwrap();
        drop(store);
        let before = std::fs::read(&journal_path).unwrap();
        let reopened = JournalStore::open(journal_path.clone()).unwrap();
        assert!(matches!(reopened.recoveries().as_slice(), [RecoveryItem::RecoveryRequired(attempt)]
            if attempt.key == "retained-copy-stage"
                && attempt.state == JournalState::RecoveryRequired
                && attempt.copy_directory_stage.is_some()));
        let owner = operations::application::OperationApplicationOwner::for_test_with_journal_store(reopened);
        assert!(owner.runtime.jobs().is_empty(), "reopened Review creates no runnable job");
        cx.update(|cx| cx.set_global(owner));

        let (shell, visual) = cx.add_window_view(|_, cx| {
            FilerShell::new(
                persistence::Startup::disabled(),
                Arc::new(input::KeymapRuntime::new()),
                Vec::new(),
                cx,
            )
        });
        assert_eq!(visual.read_entity(&shell, |shell, _| shell.recovery_records.len()), 1);
        visual.update(|_, cx| shell.update(cx, |shell, cx| {
            shell.toggle_recovery_details("retained-copy-stage".into(), cx);
            assert_eq!(shell.recovery_expanded.as_deref(), Some("retained-copy-stage"));
        }));
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            visual.run_until_parked();
            let available = visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _|
                owner.reopened_copy_stage_review("retained-copy-stage").is_some_and(|(_, state)|
                    matches!(state, operations::model::ReopenedCopyStageReviewState::Available(review)
                    if review.historical.evidence.detail == "copy stopped after staging partial.txt"
                            && review.historical.evidence.expected_root_identity == "historical-stage-root-identity"
                            && review.historical.evidence.phase == CopyDirectoryStagePhase::StagingCancelled
                            && review.stage_root_observation == operations::model::CopyInspectionState::Changed
                            && review.destination_root_observation == operations::model::CopyInspectionState::Indeterminate)));
            if available { break; }
            assert!(std::time::Instant::now() < deadline, "reopened Copy Review probe timed out");
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert!(visual.debug_bounds("operation-recovery-summary").is_some());
        assert!(visual.debug_bounds("operation-recovery-detail-text").is_some(), "expanded recovery evidence is rendered");
        visual.read_global::<operations::application::OperationApplicationOwner, _>(|owner, _| {
            assert!(owner.runtime.jobs().is_empty());
            assert_eq!(owner.recovery_records[0].copy_directory_stage.as_ref().unwrap().evidence.detail,
                "copy stopped after staging partial.txt");
        });
        assert_eq!(std::fs::read(&journal_path).unwrap(), before, "Review leaves journal bytes unchanged");
        assert!(!destination.exists(), "Review does not publish the requested destination");
        assert_eq!(std::fs::read(stage.join("partial.txt")).unwrap(), b"partial payload");
    }

    #[test]
    fn workspace_tab_drop_hit_uses_current_strip_visibility() {
        let hit_point = point(px(20.0), px(15.0));
        let bounds = gpui::Bounds {
            origin: point(px(10.0), px(10.0)),
            size: size(px(40.0), px(20.0)),
        };

        assert_eq!(
            workspace_tab_bounds_hit(false, Some(bounds), hit_point),
            Some(bounds)
        );
        assert_eq!(
            workspace_tab_bounds_hit(true, Some(bounds), hit_point),
            None
        );
        assert_eq!(workspace_tab_bounds_hit(false, None, hit_point), None);
    }

    #[test]
    fn cancelled_touch_drag_cleans_only_the_matching_native_lifecycle() {
        use gpui::{MouseInputSource, TouchPhase};
        let start = point(px(10.0), px(20.0));
        let stale_start = point(px(11.0), px(20.0));

        assert_eq!(
            touch_drag_cancellation_action(
                MouseInputSource::Touch,
                TouchPhase::Cancelled,
                false,
                Some(start),
                start,
            ),
            TouchDragCancellationAction::CancelCandidate
        );
        assert_eq!(
            touch_drag_cancellation_action(
                MouseInputSource::Touch,
                TouchPhase::Cancelled,
                true,
                Some(start),
                start,
            ),
            TouchDragCancellationAction::SignalNativeDrag
        );
        assert_eq!(
            touch_drag_cancellation_action(
                MouseInputSource::Touch,
                TouchPhase::Cancelled,
                false,
                Some(start),
                stale_start,
            ),
            TouchDragCancellationAction::Ignore
        );
        assert_eq!(
            touch_drag_cancellation_action(
                MouseInputSource::Touch,
                TouchPhase::Ended,
                false,
                Some(start),
                start,
            ),
            TouchDragCancellationAction::Ignore
        );
        assert_eq!(
            touch_drag_cancellation_action(
                MouseInputSource::Mouse,
                TouchPhase::Cancelled,
                false,
                Some(start),
                start,
            ),
            TouchDragCancellationAction::Ignore
        );
    }

    #[test]
    fn local_ole_terminal_requires_drop_and_policy_exact_effect() {
        let dropped = |effect| win_shell_dnd::DragExecution {
            result: win_shell_dnd::DragResult::Dropped,
            performed_effect: effect,
            shell_performed_effect: None,
            visual_warning: None,
        };
        let move_policy = win_shell_dnd::FileDragPinPolicy::MoveCapable;
        let copy_policy = win_shell_dnd::FileDragPinPolicy::CopyOnly;

        assert!(local_move_terminal_authorized(
            move_policy,
            Some(&dropped(Some(2)))
        ));
        assert!(local_move_terminal_authorized(
            copy_policy,
            Some(&dropped(Some(1)))
        ));
        assert!(!local_move_terminal_authorized(
            move_policy,
            Some(&dropped(Some(1)))
        ));
        assert!(!local_move_terminal_authorized(
            copy_policy,
            Some(&dropped(Some(2)))
        ));
        assert!(!local_move_terminal_authorized(
            copy_policy,
            Some(&dropped(None))
        ));
        let cancelled = win_shell_dnd::DragExecution {
            result: win_shell_dnd::DragResult::Cancelled,
            ..dropped(Some(1))
        };
        assert!(!local_move_terminal_authorized(
            copy_policy,
            Some(&cancelled)
        ));
    }

    #[cfg(windows)]
    #[gpui::test]
    fn native_ole_navigation_move_terminal_is_single_admission_and_single_drain(
        cx: &mut gpui::TestAppContext,
    ) {
        use crate::location::Location;

        initialize_directory_binding_test_globals(cx);
        let fixture = tempfile::tempdir().unwrap();
        let source_dir = fixture.path().join("source");
        std::fs::create_dir(&source_dir).unwrap();
        let source_path = source_dir.join("source.txt");
        std::fs::write(&source_path, b"native OLE timeline").unwrap();
        let source_identity =
            directory::EntrySourceIdentity::from_path(&source_path, EntryKind::File)
                .expect("real source file has a filesystem identity");

        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let source_view = visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                let source_view = cx.new(|cx| {
                    DirectoryListDemo::new_at(
                        Arc::new(input::KeymapRuntime::new()),
                        Some(Location::from(source_dir.clone())),
                        cx,
                    )
                });
                source_view.update(cx, |view, _| {
                    let entries = vec![quick_preview_entry_with_identity(
                        &source_path,
                        source_identity.clone(),
                    )];
                    view.session
                        .navigate(Location::from(source_dir.clone()), None);
                    view.entries = entries.clone();
                    view.rebuild_row_details();
                    view.session.adopt_demo(Arc::new(entries));
                    view.location_generation = 7;
                    view.presentation_revision = 11;
                    view.reset_projected_rows();
                    view.next_internal_drag_session_id = 3;
                    let mut snapshot = view
                        .internal_drag_snapshot(0)
                        .expect("real source row produces a native drag snapshot");
                    snapshot.session_id = 3;
                    *view.internal_drag_snapshot.borrow_mut() = Some(snapshot);
                });
                shell.replace_active_view_with_binding_for_test(source_view.clone(), cx);
                source_view
            })
        });
        let (snapshot, source_paths, view_id) = visual.read_entity(&source_view, |view, _| {
            let snapshot = view
                .internal_drag_snapshot(0)
                .expect("source row remains eligible");
            let snapshot = InternalDragSnapshot {
                session_id: 3,
                ..snapshot
            };
            let paths: Vec<PathBuf> = snapshot
                .sources
                .iter()
                .map(|source| source.path.clone())
                .collect();
            (snapshot, paths, source_view.entity_id())
        });
        let initial_target_snapshot = visual.read_entity(&source_view, |view, _| {
            view.capture_navigation_target_snapshot(view_id, fixture.path(), false)
        });
        visual.update_entity(&source_view, |view, cx| {
            view.prepare_navigation_target(&initial_target_snapshot, cx);
        });
        visual.run_until_parked();
        let target = visual
            .read_entity(&source_view, |view, _| {
                let snapshot =
                    view.capture_navigation_target_snapshot(view_id, fixture.path(), false);
                view.navigation_drop_target(&snapshot)
            })
            .expect("real parent directory identity resolves as a breadcrumb target");
        let tab_id = visual.read_entity(&shell, |shell, _| shell.active_tab_id_for_test());
        visual.update_entity(&shell, |shell, _| {
            shell.prepare_native_drag_for_test(
                view_id,
                0x1234,
                source_paths.clone(),
                snapshot.clone(),
                7,
                11,
                win_shell_dnd::FileDragPinPolicy::MoveCapable,
                gpui::MouseInputSource::Mouse,
            );
        });

        assert!(
            visual.read_entity(&source_view, |view, _| {
                internal_drag_snapshot_is_current(
                    &snapshot,
                    &view.entries,
                    view.location_generation,
                    view.presentation_revision,
                )
            }),
            "the test pointer-down snapshot must still match the live row"
        );
        assert!(visual.read_entity(&source_view, |view, _| {
            internal_drag_session_id_is_current(
                view.next_internal_drag_session_id,
                snapshot.session_id,
            )
        }));
        assert!(
            visual.read_entity(&source_view, |view, _| {
                view.accepts_navigation_drop_target(&target)
            }),
            "the breadcrumb identity projection must still be current"
        );
        assert!(navigation_move_request(&snapshot.sources, &target, tab_id).is_some());
        assert_eq!(
            visual.read_entity(&shell, |shell, cx| {
                shell.local_ole_navigation_move_candidate_effect(
                    0x1234,
                    tab_id,
                    view_id,
                    &target,
                    Some(&source_paths),
                    cx,
                )
            }),
            Some(LocalOleDropEffect::Move),
            "a valid captured source and current breadcrumb must be eligible"
        );

        let admitted_effect = visual.update_entity(&shell, |shell, cx| {
            shell.admit_local_ole_navigation_move(
                0x1234,
                tab_id,
                view_id,
                target.clone(),
                source_paths.clone(),
                cx,
            )
        });
        assert_eq!(admitted_effect, Some(LocalOleDropEffect::Move));
        let attempt = visual.read_entity(&shell, |shell, _| {
            shell
                .pending_native_drag
                .as_ref()
                .and_then(|pending| pending.admitted_local_move)
                .expect("production admission stores the exact held attempt")
        });
        assert_eq!(
            visual.read_entity(&shell, |shell, cx| {
                shell.operation_requests_for_test(cx).len()
            }),
            1
        );
        assert_eq!(
            visual.update_entity(&shell, |shell, cx| {
                shell.admit_local_ole_navigation_move(
                    0x1234,
                    tab_id,
                    view_id,
                    target.clone(),
                    source_paths,
                    cx,
                )
            }),
            None,
            "duplicate Submit after local admission must be rejected"
        );

        let dropped_move = win_shell_dnd::DragExecution {
            result: win_shell_dnd::DragResult::Dropped,
            performed_effect: Some(2),
            shell_performed_effect: None,
            visual_warning: None,
        };
        let route = visual.update_entity(&shell, |shell, cx| {
            shell.route_local_ole_terminal(0x1234, Some(&dropped_move), cx)
        });
        assert_eq!(
            route,
            LocalOleTerminalRoute {
                admitted: true,
                authorized: true
            }
        );
        assert!(
            route.admitted,
            "local admission suppresses external-Move cleanup"
        );
        let mut cleanup_submissions = 0;
        dispatch_external_move_cleanup(route, Some(()), |_| cleanup_submissions += 1);
        assert_eq!(cleanup_submissions, 0);
        let no_local_attempt = visual.update_entity(&shell, |shell, cx| {
            shell.route_local_ole_terminal(0xffff, None, cx)
        });
        dispatch_external_move_cleanup(no_local_attempt, Some(()), |_| cleanup_submissions += 1);
        assert_eq!(cleanup_submissions, 1);

        let actions = visual.update_entity(&shell, |shell, _| {
            finish_pin_drain(None::<()>, &mut shell.native_drag_pin_drains, 0x1234)
        });
        assert_eq!(actions.len(), 1);
        let duplicate_actions = visual.update_entity(&shell, |shell, _| {
            finish_pin_drain(None::<()>, &mut shell.native_drag_pin_drains, 0x1234)
        });
        assert!(duplicate_actions.is_empty());
        visual.update_entity(&shell, |shell, cx| {
            for action in actions {
                shell.process_deferred_native_action(action, cx);
            }
        });
        assert_eq!(
            visual.read_entity(&shell, |shell, cx| {
                shell.operation_requests_for_test(cx).len()
            }),
            1,
            "the local Move is the only operation submitted for this token"
        );
        assert_eq!(
            visual.update_entity(&shell, |_shell, cx| {
                let worker = cx
                    .global_mut::<operations::application::OperationApplicationOwner>()
                    .runtime
                    .start_next()
                    .expect("pin drain releases the exact previously held attempt");
                match worker.command {
                    operations::model::ExecutorCommand::Prepare { token, .. } => token,
                    operations::model::ExecutorCommand::Cancel { .. } => {
                        panic!("released held attempt must be runnable")
                    }
                    operations::model::ExecutorCommand::ResolveConflict { .. } => {
                        panic!("released held attempt must prepare, not resolve a conflict")
                    }
                }
            }),
            attempt,
            "the exact admitted attempt becomes runnable once after drain"
        );

        // 次のtokenではOLE cancelを二度観測しても、同じattemptを再解放せずcleanupも送らない。
        let second_snapshot = visual.update_entity(&source_view, |view, _| {
            view.next_internal_drag_session_id = 4;
            let mut snapshot = view
                .internal_drag_snapshot(0)
                .expect("the source row can begin a new drag session");
            snapshot.session_id = 4;
            *view.internal_drag_snapshot.borrow_mut() = Some(snapshot.clone());
            snapshot
        });
        visual.update_entity(&shell, |shell, _| {
            shell.prepare_native_drag_for_test(
                view_id,
                0x1235,
                second_snapshot
                    .sources
                    .iter()
                    .map(|source| source.path.clone())
                    .collect(),
                second_snapshot,
                7,
                11,
                win_shell_dnd::FileDragPinPolicy::MoveCapable,
                gpui::MouseInputSource::Mouse,
            );
        });
        let second_attempt_effect = visual.update_entity(&shell, |shell, cx| {
            shell.admit_local_ole_navigation_move(
                0x1235,
                tab_id,
                view_id,
                target.clone(),
                vec![source_path.clone()],
                cx,
            )
        });
        assert_eq!(second_attempt_effect, Some(LocalOleDropEffect::Move));
        let cancelled_attempt = visual.read_entity(&shell, |shell, _| {
            shell
                .pending_native_drag
                .as_ref()
                .and_then(|pending| pending.admitted_local_move)
                .expect("second production admission stores its exact attempt")
        });
        let cancelled = win_shell_dnd::DragExecution {
            result: win_shell_dnd::DragResult::Cancelled,
            performed_effect: Some(2),
            shell_performed_effect: None,
            visual_warning: None,
        };
        let cancelled_route = visual.update_entity(&shell, |shell, cx| {
            shell.route_local_ole_terminal(0x1235, Some(&cancelled), cx)
        });
        assert_eq!(
            cancelled_route,
            LocalOleTerminalRoute {
                admitted: true,
                authorized: false
            }
        );
        dispatch_external_move_cleanup(cancelled_route, Some(()), |_| cleanup_submissions += 1);
        assert_eq!(cleanup_submissions, 1);
        assert_eq!(
            visual.update_entity(&shell, |shell, cx| {
                shell.route_local_ole_terminal(0x1235, Some(&cancelled), cx)
            }),
            cancelled_route,
            "repeated terminal observation is idempotent"
        );
        let cancelled_actions = visual.update_entity(&shell, |shell, _| {
            finish_pin_drain(None::<()>, &mut shell.native_drag_pin_drains, 0x1235)
        });
        assert_eq!(cancelled_actions.len(), 1);
        assert!(
            visual
                .update_entity(&shell, |shell, _| {
                    finish_pin_drain(None::<()>, &mut shell.native_drag_pin_drains, 0x1235)
                })
                .is_empty()
        );
        visual.update_entity(&shell, |shell, cx| {
            for action in cancelled_actions {
                shell.process_deferred_native_action(action, cx);
            }
        });
        assert_eq!(
            visual.read_entity(&shell, |shell, cx| {
                shell.operation_requests_for_test(cx).len()
            }),
            2,
            "neither terminal path submits external source cleanup"
        );
        assert_eq!(
            visual.read_entity(&shell, |_shell, cx| {
                cx.read_global::<operations::application::OperationApplicationOwner, _>(
                    |owner, _| {
                        owner
                            .runtime
                            .job(cancelled_attempt)
                            .and_then(|job| {
                                job.attempts
                                    .into_iter()
                                    .find(|attempt| attempt.token == cancelled_attempt)
                            })
                            .and_then(|attempt| attempt.terminal.map(|terminal| terminal.outcome))
                    },
                )
            }),
            Some(operations::model::TerminalOutcome::Cancelled)
        );
    }

    #[test]
    fn local_ole_forced_token_must_be_active_and_older_overlapping_move_fails_closed() {
        let pinned_source = PathBuf::from(r"C:\items\pinned-source.txt");
        let drop_source = PathBuf::from(r"C:\items\drop-source.txt");
        let mut drains = NativeDragPinDrains::default();
        drains.begin(4, vec![pinned_source.clone()]);
        drains.begin(8, vec![drop_source.clone()]);
        assert!(drains.defer(10, vec![drop_source.clone()]).is_ok());
        assert!(drains.has_conflicting_deferred_move(std::slice::from_ref(&drop_source)));
        assert!(
            drains
                .defer_waiting_for(11, vec![drop_source.clone()], HashSet::from([99]))
                .is_err()
        );
        // The source of the current pin is unrelated to the Drop-time path, so the local
        // reservation must use the latter to order subsequent moves correctly.
        let mut ordered = NativeDragPinDrains::default();
        ordered.begin(4, vec![pinned_source]);
        assert!(
            ordered
                .defer_waiting_for(12, vec![drop_source.clone()], HashSet::from([4]),)
                .is_ok()
        );
        assert!(ordered.defer(13, vec![drop_source]).is_ok());
        let ready = ordered.complete(4);
        assert_eq!(ready, vec![12, 13]);
    }

