    #[test]
    fn cancelled_or_replaced_everything_request_cannot_commit() {
        let first = SearchRequest {
            id: 1,
            query: "first".into(),
            cancellation: Arc::new(AtomicBool::new(false)),
            provider_revision: everything::ProviderRevision::current(),
            test_command: None,
            test_outcome: None,
        };
        let replacement = SearchRequest {
            id: 2,
            query: "second".into(),
            cancellation: Arc::new(AtomicBool::new(false)),
            provider_revision: everything::ProviderRevision::current(),
            test_command: None,
            test_outcome: None,
        };
        first.cancellation.store(true, Ordering::Release);

        assert!(!search_request_is_current(Some(&replacement), &first));
        assert!(same_search_request(Some(&first), &first));
        assert!(search_request_is_current(Some(&replacement), &replacement));

        replacement.cancellation.store(true, Ordering::Release);
        assert!(!search_request_is_current(Some(&replacement), &replacement));
    }

    #[cfg(windows)]
    fn isolated_everything_test_helper_executable() -> std::path::PathBuf {
        use sha2::{Digest, Sha256};
        use std::{fs, process::Command};

        // Cargo can leave artifacts for multiple dependency fingerprints in `deps`.
        // The helper's embedded source hash distinguishes those from older helper code.
        let expected_fingerprint = format!(
            "{:x}",
            Sha256::digest(include_str!("../tests/everything_search_helper.rs").as_bytes())
        );
        let deps = std::env::current_exe()
            .unwrap()
            .parent()
            .expect("test executable has a deps directory")
            .to_path_buf();
        let mut matches = fs::read_dir(&deps)
            .expect("read test executable directory")
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .filter(|path| {
                path.file_stem()
                    .and_then(|stem| stem.to_str())
                    .is_some_and(|stem| stem.starts_with("everything_search_helper-"))
                    && path.extension().is_some_and(|extension| extension == "exe")
            })
            .filter(|path| {
                Command::new(path)
                    .arg("--source-fingerprint")
                    .output()
                    .is_ok_and(|output| {
                        output.status.success()
                            && String::from_utf8_lossy(&output.stdout).trim()
                                == expected_fingerprint
                    })
            })
            .collect::<Vec<_>>();
        matches.sort();
        matches.pop().unwrap_or_else(|| {
            panic!(
                "expected a helper artifact built from the current test source in {}",
                deps.display()
            )
        })
    }

    #[cfg(windows)]
    #[test]
    fn everything_shell_replacement_cancellation_isolated_gpui_regression() {
        use std::{
            io::Read,
            process::{Command, Stdio},
            thread,
            time::{Duration, Instant},
        };

        let temp = tempfile::tempdir().unwrap();
        let stdout_path = temp.path().join("inner.stdout.log");
        let stderr_path = temp.path().join("inner.stderr.log");
        let stdout = std::fs::File::create(&stdout_path).unwrap();
        let stderr = std::fs::File::create(&stderr_path).unwrap();
        let helper_executable = isolated_everything_test_helper_executable();
        let mut child = Command::new(std::env::current_exe().unwrap())
            .arg("--ignored")
            .arg("--exact")
            .arg("shell::tests::everything_shell_replacement_waits_for_cancelled_helper_reap_and_commits_latest")
            .env("GPUI_FILER_TEST_HELPER_EXECUTABLE", helper_executable)
            .stdin(Stdio::null())
            .stdout(stdout)
            .stderr(stderr)
            .spawn()
            .expect("start isolated GPUI cancellation regression");
        let deadline = Instant::now() + Duration::from_secs(60);
        let status = loop {
            if let Some(status) = child.try_wait().unwrap() {
                break status;
            }
            if Instant::now() >= deadline {
                let _ = child.kill();
                let _ = child.wait();
                panic!("isolated GPUI cancellation regression timed out");
            }
            thread::sleep(Duration::from_millis(10));
        };
        if !status.success() {
            let mut stdout = String::new();
            let mut stderr = String::new();
            std::fs::File::open(stdout_path)
                .unwrap()
                .read_to_string(&mut stdout)
                .unwrap();
            std::fs::File::open(stderr_path)
                .unwrap()
                .read_to_string(&mut stderr)
                .unwrap();
            panic!("isolated regression failed ({status})\nstdout:\n{stdout}\nstderr:\n{stderr}");
        }
    }

    #[cfg(windows)]
    #[test]
    fn everything_shell_escape_cancellation_isolated_gpui_regression() {
        use std::os::windows::io::AsRawHandle;
        use std::{
            io::Read,
            process::{Command, Stdio},
            thread,
            time::{Duration, Instant},
        };
        use windows::Win32::{
            Foundation::{CloseHandle, HANDLE},
            System::JobObjects::{
                AssignProcessToJobObject, CreateJobObjectW, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
                JOBOBJECT_EXTENDED_LIMIT_INFORMATION, JobObjectExtendedLimitInformation,
                SetInformationJobObject,
            },
            System::Threading::{CreateEventW, SetEvent},
        };
        use windows::core::PCWSTR;

        const START_GATE_ENV: &str = "GPUI_FILER_TEST_EVERYTHING_SHELL_ESCAPE_START_GATE";

        struct WrapperJob(HANDLE);
        impl Drop for WrapperJob {
            fn drop(&mut self) {
                unsafe {
                    let _ = windows::Win32::Foundation::CloseHandle(self.0);
                }
            }
        }
        struct WrapperGate(HANDLE);
        impl Drop for WrapperGate {
            fn drop(&mut self) {
                unsafe {
                    let _ = CloseHandle(self.0);
                }
            }
        }

        let job = WrapperJob(unsafe { CreateJobObjectW(None, None) }.expect("create fixture job"));
        let gate_name = format!(
            "Local\\gpui-filer-shell-escape-gate-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        );
        let gate_wide = gate_name.encode_utf16().chain([0]).collect::<Vec<_>>();
        let gate = WrapperGate(
            unsafe { CreateEventW(None, true, false, PCWSTR(gate_wide.as_ptr())) }
                .expect("create parent-controlled fixture startup gate"),
        );
        let mut limits = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        unsafe {
            SetInformationJobObject(
                job.0,
                JobObjectExtendedLimitInformation,
                (&limits as *const JOBOBJECT_EXTENDED_LIMIT_INFORMATION).cast(),
                std::mem::size_of_val(&limits) as u32,
            )
            .expect("configure fixture kill-on-close job");
        }

        let temp = tempfile::tempdir().unwrap();
        let stdout_path = temp.path().join("inner.stdout.log");
        let stderr_path = temp.path().join("inner.stderr.log");
        let mut child = Command::new(std::env::current_exe().unwrap())
            .arg("--ignored")
            .arg("--exact")
            .arg("shell::tests::everything_shell_escape_cancellation_routes_through_search_input")
            .env(START_GATE_ENV, &gate_name)
            .stdout(std::fs::File::create(&stdout_path).unwrap())
            .stderr(std::fs::File::create(&stderr_path).unwrap())
            .stdin(Stdio::null())
            .spawn()
            .expect("start isolated routed Search Escape regression");
        if let Err(error) =
            unsafe { AssignProcessToJobObject(job.0, HANDLE(child.as_raw_handle() as _)) }
        {
            let _ = child.kill();
            let _ = child.wait();
            panic!("contain isolated regression and descendants: {error}");
        }
        unsafe { SetEvent(gate.0).expect("release inner fixture after job assignment") };
        let deadline = Instant::now() + Duration::from_secs(60);
        let status = loop {
            if let Some(status) = child.try_wait().unwrap() {
                break status;
            }
            if Instant::now() >= deadline {
                let _ = child.kill();
                let _ = child.wait();
                let stdout = std::fs::read_to_string(&stdout_path).unwrap_or_default();
                let stderr = std::fs::read_to_string(&stderr_path).unwrap_or_default();
                panic!(
                    "isolated routed Search Escape regression timed out\nstdout:\n{stdout}\nstderr:\n{stderr}"
                );
            }
            thread::sleep(Duration::from_millis(10));
        };
        if !status.success() {
            let mut stdout = String::new();
            let mut stderr = String::new();
            std::fs::File::open(stdout_path)
                .unwrap()
                .read_to_string(&mut stdout)
                .unwrap();
            std::fs::File::open(stderr_path)
                .unwrap()
                .read_to_string(&mut stderr)
                .unwrap();
            panic!("isolated regression failed ({status})\nstdout:\n{stdout}\nstderr:\n{stderr}");
        }
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore]
    fn everything_shell_escape_cancellation_routes_through_search_input(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::{
            os::windows::io::AsRawHandle,
            process::Command,
            sync::atomic::Ordering,
            thread,
            time::{Duration, Instant},
        };
        use windows::Win32::{
            Foundation::{CloseHandle, HANDLE, WAIT_OBJECT_0, WAIT_TIMEOUT},
            System::Threading::{
                CreateEventW, OpenEventW, OpenProcess, PROCESS_QUERY_LIMITED_INFORMATION,
                PROCESS_SYNCHRONIZE, PROCESS_TERMINATE, SYNCHRONIZATION_ACCESS_RIGHTS, SetEvent,
                TerminateProcess, WaitForSingleObject,
            },
        };
        use windows::core::PCWSTR;

        const START_GATE_ENV: &str = "GPUI_FILER_TEST_EVERYTHING_SHELL_ESCAPE_START_GATE";
        const BLOCKED_IPC_INSTANCE_ENV: &str = "GPUI_FILER_EVERYTHING_BLOCKED_IPC_INSTANCE";
        const BLOCKED_IPC_ENTERED_ENV: &str = "GPUI_FILER_EVERYTHING_BLOCKED_IPC_ENTERED";
        const BLOCKED_IPC_RELEASE_ENV: &str = "GPUI_FILER_EVERYTHING_BLOCKED_IPC_RELEASE";
        const BLOCKED_IPC_SERVER_READY_ENV: &str = "GPUI_FILER_EVERYTHING_BLOCKED_IPC_SERVER_READY";
        const BLOCKED_IPC_HELPER_READY_ENV: &str = "GPUI_FILER_EVERYTHING_BLOCKED_IPC_HELPER_READY";
        const BLOCKED_IPC_HELPER_GATE_ENV: &str = "GPUI_FILER_EVERYTHING_BLOCKED_IPC_HELPER_GATE";
        const BLOCKED_IPC_SERVER_DIAGNOSTIC_ENV: &str =
            "GPUI_FILER_EVERYTHING_BLOCKED_IPC_SERVER_DIAGNOSTIC";
        const BLOCKED_IPC_QUERY_ENV: &str = "GPUI_FILER_EVERYTHING_BLOCKED_IPC_QUERY";

        struct PrivateServer {
            child: std::process::Child,
            entered: HANDLE,
            release: HANDLE,
            ready: std::path::PathBuf,
        }
        struct EventHandle(HANDLE);
        impl Drop for EventHandle {
            fn drop(&mut self) {
                unsafe {
                    let _ = CloseHandle(self.0);
                }
            }
        }
        impl Drop for PrivateServer {
            fn drop(&mut self) {
                unsafe {
                    let _ = SetEvent(self.release);
                    let process = HANDLE(self.child.as_raw_handle() as _);
                    if WaitForSingleObject(process, 4_000) == WAIT_TIMEOUT {
                        let _ = self.child.kill();
                        let _ = WaitForSingleObject(process, 4_000);
                    }
                    let _ = self.child.try_wait();
                    let _ = CloseHandle(self.entered);
                    let _ = CloseHandle(self.release);
                }
                let _ = std::fs::remove_file(&self.ready);
            }
        }
        let startup_gate_name =
            std::env::var(START_GATE_ENV).expect("wrapper provides startup gate");
        let startup_gate_wide = startup_gate_name
            .encode_utf16()
            .chain([0])
            .collect::<Vec<_>>();
        let startup_gate = EventHandle(
            unsafe {
                OpenEventW(
                    SYNCHRONIZATION_ACCESS_RIGHTS(0x0010_0000),
                    false,
                    PCWSTR(startup_gate_wide.as_ptr()),
                )
            }
            .expect("open parent-controlled fixture startup gate"),
        );
        assert_eq!(
            unsafe { WaitForSingleObject(startup_gate.0, 15_000) },
            WAIT_OBJECT_0,
            "fixture startup gate was not released after Job Object assignment"
        );

        struct ChildCleanup {
            process: Option<HANDLE>,
            cancellation: Option<Arc<std::sync::atomic::AtomicBool>>,
        }
        impl Drop for ChildCleanup {
            fn drop(&mut self) {
                if let Some(cancellation) = &self.cancellation {
                    cancellation.store(true, Ordering::Release);
                }
                let Some(process) = self.process.take() else {
                    return;
                };
                unsafe {
                    if WaitForSingleObject(process, 5_000) == WAIT_TIMEOUT {
                        let _ = TerminateProcess(process, 1);
                        let _ = WaitForSingleObject(process, 5_000);
                    }
                    let _ = CloseHandle(process);
                }
            }
        }

        initialize_directory_binding_test_globals(cx);
        let temp = tempfile::tempdir().unwrap();
        let ready = temp.path().join("helper.ready");
        let server_ready = temp.path().join("server.ready");
        let server_diagnostic = temp.path().join("server.diagnostic");
        let unique_id = format!(
            "{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        );
        let instance = format!("gpui-filer-{unique_id}");
        let query = format!("blocked-send-{unique_id}");
        let entered_name = format!("Local\\gpui-filer-entered-{unique_id}");
        let release_name = format!("Local\\gpui-filer-release-{unique_id}");
        let gate_name = format!("Local\\gpui-filer-helper-gate-{unique_id}");
        let entered_wide = entered_name.encode_utf16().chain([0]).collect::<Vec<_>>();
        let release_wide = release_name.encode_utf16().chain([0]).collect::<Vec<_>>();
        let gate_wide = gate_name.encode_utf16().chain([0]).collect::<Vec<_>>();
        let entered = unsafe { CreateEventW(None, true, false, PCWSTR(entered_wide.as_ptr())) }
            .expect("create private IPC entered event");
        let release = unsafe { CreateEventW(None, true, false, PCWSTR(release_wide.as_ptr())) }
            .expect("create private IPC release event");
        let helper_gate = EventHandle(
            unsafe { CreateEventW(None, true, false, PCWSTR(gate_wide.as_ptr())) }
                .expect("create private helper gate"),
        );
        let executable = std::env::current_exe().expect("test executable");
        let mut server_command = Command::new(&executable);
        server_command
            .arg("--ignored")
            .arg("--exact")
            .arg("everything::tests::everything_ipc_private_blocked_server_fixture")
            .env(BLOCKED_IPC_INSTANCE_ENV, &instance)
            .env(BLOCKED_IPC_ENTERED_ENV, &entered_name)
            .env(BLOCKED_IPC_RELEASE_ENV, &release_name)
            .env(BLOCKED_IPC_QUERY_ENV, &query)
            .env(BLOCKED_IPC_SERVER_READY_ENV, &server_ready)
            .env(BLOCKED_IPC_SERVER_DIAGNOSTIC_ENV, &server_diagnostic)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        let server_child = server_command
            .spawn()
            .expect("start private Everything fixture");
        let mut server = PrivateServer {
            child: server_child,
            entered,
            release,
            ready: server_ready.clone(),
        };
        let server_deadline = Instant::now() + Duration::from_secs(10);
        loop {
            if let Ok(class_name) = std::fs::read_to_string(&server_ready) {
                assert_eq!(
                    class_name,
                    format!("EVERYTHING_TASKBAR_NOTIFICATION({instance})")
                );
                assert_ne!(class_name, "EVERYTHING_TASKBAR_NOTIFICATION");
                assert_ne!(class_name, "EVERYTHING_TASKBAR_NOTIFICATION(1.5a)");
                break;
            }
            assert!(
                Instant::now() < server_deadline,
                "private Everything fixture did not start"
            );
            thread::sleep(Duration::from_millis(5));
        }
        let (root, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            SearchShellRoot { shell }
        });
        let shell = visual.read_entity(&root, |root, _| root.shell.clone());
        visual.update(|_, cx| shell.update(cx, |shell, cx| shell.open_search(cx)));
        visual.executor().advance_clock(Duration::from_millis(10));
        thread::sleep(Duration::from_millis(1));

        let terminal_events = Arc::new(std::sync::Mutex::new(Vec::new()));
        let observed = terminal_events.clone();
        let (completion_ack_tx, completion_ack_rx) = async_channel::bounded(1);
        let ready_for_command = ready.clone();
        let instance_for_command = instance.clone();
        let query_for_command = query.clone();
        let gate_for_command = gate_name.clone();
        let executable_for_command = executable.clone();
        let spare_slot = everything::occupy_provider_slot_for_test();
        let factory = Arc::new(move || {
            let mut command = Command::new(&executable_for_command);
            command
                .arg("--ignored")
                .arg("--exact")
                .arg("everything::tests::everything_ipc_private_blocked_search_helper_fixture")
                .env(BLOCKED_IPC_INSTANCE_ENV, &instance_for_command)
                .env(BLOCKED_IPC_QUERY_ENV, &query_for_command)
                .env(BLOCKED_IPC_HELPER_READY_ENV, &ready_for_command)
                .env(BLOCKED_IPC_HELPER_GATE_ENV, &gate_for_command)
                .stdin(std::process::Stdio::piped());
            command
        });
        let revision = everything::ProviderRevision::current();
        visual.update(|_, cx| {
            shell.update(cx, |shell, _| {
                shell.set_next_search_command_for_test(everything::TestSearchCommand {
                    factory,
                    expect_response: false,
                    captured_reply: Arc::new(std::sync::Mutex::new(None)),
                    terminal_observer: Some(Arc::new(move |terminal, rev| {
                        observed.lock().unwrap().push((terminal, rev));
                    })),
                });
                shell.set_search_completion_ack_for_test(completion_ack_tx);
            });
        });
        // KeyDown is consumed by the Shell modal before GPUI dispatches its simulated
        // character input. Exercise the real focused editor boundary, which emits the
        // production TextChanged event consumed by SearchUi's subscription.
        let input = visual
            .read_entity(&shell, |shell, _| shell.search_input_for_test())
            .expect("Search editor");
        visual.update(|window, cx| {
            assert!(
                input.read(cx).is_focused(window),
                "Search editor should own focus"
            );
            input.update(cx, |input, cx| {
                gpui::EntityInputHandler::replace_text_in_range(input, None, &query, window, cx);
            });
        });
        let cancellation = visual.read_entity(&shell, |shell, cx| {
            assert_eq!(
                shell.search_input_state_for_test(cx),
                Some((query.clone(), "loading"))
            );
            shell.search_cancellation_for_test().expect("request token")
        });
        let mut cleanup = ChildCleanup {
            process: None,
            cancellation: Some(cancellation.clone()),
        };
        visual.read_entity(&shell, |shell, _| {
            assert!(
                !shell.has_pending_test_search_command(),
                "typed query must consume the command seam"
            );
        });

        let process = {
            let deadline = Instant::now() + Duration::from_secs(10);
            let mut last_marker: String;
            loop {
                match std::fs::read_to_string(&ready) {
                    Ok(contents) => {
                        let marker = contents.trim();
                        match marker.parse::<u32>() {
                            Ok(pid) if pid > 0 => match unsafe {
                                OpenProcess(
                                    PROCESS_SYNCHRONIZE
                                        | PROCESS_QUERY_LIMITED_INFORMATION
                                        | PROCESS_TERMINATE,
                                    false,
                                    pid,
                                )
                            } {
                                Ok(process) => {
                                    cleanup.process = Some(process);
                                    unsafe {
                                        SetEvent(helper_gate.0).expect("release exact helper gate")
                                    };
                                    assert_eq!(
                                        unsafe { WaitForSingleObject(process, 0) },
                                        WAIT_TIMEOUT,
                                        "helper must still be alive before Escape"
                                    );
                                    break process;
                                }
                                Err(error) => last_marker = format!("PID {pid}: {error}"),
                            },
                            Ok(_) => last_marker = format!("zero PID marker {marker:?}"),
                            Err(_) => {
                                last_marker = format!("incomplete or malformed marker {marker:?}")
                            }
                        }
                    }
                    Err(error) => last_marker = error.to_string(),
                }
                assert!(
                    Instant::now() < deadline,
                    "helper readiness timed out; last marker: {last_marker}"
                );
                visual.executor().advance_clock(Duration::from_millis(10));
                thread::sleep(Duration::from_millis(1));
            }
        };

        let entered_deadline = Instant::now() + Duration::from_secs(10);
        loop {
            if unsafe { WaitForSingleObject(server.entered, 0) } == WAIT_OBJECT_0 {
                break;
            }
            assert_eq!(
                unsafe { WaitForSingleObject(process, 0) },
                WAIT_TIMEOUT,
                "exact helper exited before validated private WndProc entry; diagnostic={}",
                std::fs::read_to_string(&server_diagnostic).unwrap_or_default()
            );
            assert!(
                Instant::now() < entered_deadline,
                "validated private WndProc entry timed out"
            );
            visual.executor().advance_clock(Duration::from_millis(5));
            thread::sleep(Duration::from_millis(1));
        }
        assert!(
            everything::provider_has_no_free_slot_for_test(),
            "provider capacity must remain held while helper is blocked in WM_COPYDATA"
        );
        assert_eq!(
            unsafe { WaitForSingleObject(process, 0) },
            WAIT_TIMEOUT,
            "exact helper must remain alive in the blocked WndProc before Escape"
        );

        visual.simulate_keystrokes("escape");
        let close_deadline = Instant::now() + Duration::from_secs(2);
        loop {
            if visual.read_entity(&shell, |shell, _| shell.search_request_state_for_test().0)
                == false
            {
                break;
            }
            assert!(
                Instant::now() < close_deadline,
                "Escape did not close Search promptly"
            );
            visual.executor().advance_clock(Duration::from_millis(10));
            thread::sleep(Duration::from_millis(1));
        }
        assert!(
            cancellation.load(Ordering::Acquire),
            "real request token was not cancelled"
        );
        let terminal_deadline = Instant::now() + Duration::from_secs(10);
        loop {
            let events = terminal_events.lock().unwrap();
            if !events.is_empty() {
                assert_eq!(
                    *events,
                    vec![(everything::ProviderTerminal::Cancelled, revision)]
                );
                break;
            }
            drop(events);
            assert!(
                Instant::now() < terminal_deadline,
                "provider terminal timed out"
            );
            visual.executor().advance_clock(Duration::from_millis(10));
            thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            unsafe { WaitForSingleObject(process, 5_000) },
            WAIT_OBJECT_0,
            "exact helper did not exit after cancellation"
        );
        cleanup.process = None;
        unsafe { CloseHandle(process).expect("close exact helper handle") };
        cleanup.cancellation = None;
        assert!(
            unsafe { WaitForSingleObject(server.entered, 0) } == WAIT_OBJECT_0,
            "validated WndProc entry should remain observable until explicitly released"
        );
        // The test seam acknowledges only after Shell's detached callback returns.
        let completion_deadline = Instant::now() + Duration::from_secs(5);
        loop {
            if completion_ack_rx.try_recv().is_ok() {
                break;
            }
            assert!(
                Instant::now() < completion_deadline,
                "Shell completion callback acknowledgement timed out"
            );
            visual.executor().advance_clock(Duration::from_millis(10));
            thread::sleep(Duration::from_millis(1));
        }
        let capacity_deadline = Instant::now() + Duration::from_secs(5);
        loop {
            if !everything::provider_has_no_free_slot_for_test() {
                break;
            }
            assert!(
                Instant::now() < capacity_deadline,
                "provider capacity did not recover after exact helper exit/reap"
            );
            visual.executor().advance_clock(Duration::from_millis(5));
            thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            *terminal_events.lock().unwrap(),
            vec![(everything::ProviderTerminal::Cancelled, revision)],
            "provider must report exactly one current-revision terminal"
        );
        assert!(
            !visual.read_entity(&shell, |shell, _| shell.search_request_state_for_test().0),
            "provider completion must not reopen Search"
        );
        visual.update(|_, cx| shell.update(cx, |shell, cx| shell.open_search(cx)));
        visual.run_until_parked();
        visual.read_entity(&shell, |shell, cx| {
            assert_eq!(
                shell.search_input_state_for_test(cx),
                Some((String::new(), "idle"))
            );
            assert!(shell.search_cancellation_for_test().is_none());
            assert!(!shell.has_pending_test_search_command());
        });
        unsafe { SetEvent(server.release).expect("release blocked fake Everything WndProc") };
        assert_eq!(
            unsafe { WaitForSingleObject(HANDLE(server.child.as_raw_handle() as _), 5_000) },
            WAIT_OBJECT_0,
            "private fake server should exit after release"
        );
        let _ = server.child.try_wait();
        drop(spare_slot);
    }

    #[cfg(windows)]
    #[gpui::test]
    #[ignore]
    fn everything_shell_replacement_waits_for_cancelled_helper_reap_and_commits_latest(
        cx: &mut gpui::TestAppContext,
    ) {
        use std::process::Command;
        use std::time::{Duration, Instant};

        initialize_directory_binding_test_globals(cx);
        let temp = tempfile::tempdir().unwrap();
        let a_ready = temp.path().join("a.ready");
        let b_ready = temp.path().join("b.ready");
        let b_release = temp.path().join("b.release");
        let b_result = temp.path().join("echo-result.txt");
        let helper_executable = std::env::var_os("GPUI_FILER_TEST_HELPER_EXECUTABLE")
            .map(std::path::PathBuf::from)
            .expect("wrapper provides the source-verified isolated helper executable");
        let reserved_slot = everything::occupy_provider_slot_for_test();
        let (harness, visual) = cx.add_window_view(|_, cx| {
            let shell = cx.new(|cx| {
                FilerShell::new(
                    persistence::Startup::disabled(),
                    Arc::new(input::KeymapRuntime::new()),
                    Vec::new(),
                    cx,
                )
            });
            QuickPreviewHarness { shell }
        });
        let shell = visual.read_entity(&harness, |harness, _| harness.shell.clone());
        let a_ready_for_command = a_ready.clone();
        let helper_for_a = helper_executable.clone();
        let a_factory = Arc::new(move || {
            let mut command = Command::new(&helper_for_a);
            command
                .arg("hold")
                .env("GPUI_FILER_HELPER_READY", &a_ready_for_command);
            command
        });
        let b_ready_for_command = b_ready.clone();
        let b_release_for_command = b_release.clone();
        let b_result_for_command = b_result.clone();
        let helper_for_b = helper_executable.clone();
        let b_factory = Arc::new(move || {
            let mut command = Command::new(&helper_for_b);
            command
                .arg("echo")
                .env("GPUI_FILER_HELPER_READY", &b_ready_for_command)
                .env("GPUI_FILER_HELPER_RESULT_PATH", &b_result_for_command)
                .env("GPUI_FILER_ECHO_RELEASE", &b_release_for_command);
            command
        });

        let revision = everything::ProviderRevision::current();
        let a_terminal = Arc::new(std::sync::Mutex::new(None));
        let a_terminal_observer = a_terminal.clone();
        let a = SearchRequest {
            id: 1,
            query: "held-query".into(),
            cancellation: Arc::new(AtomicBool::new(false)),
            provider_revision: revision,
            test_command: Some(everything::TestSearchCommand {
                factory: a_factory,
                expect_response: false,
                captured_reply: Arc::new(std::sync::Mutex::new(None)),
                terminal_observer: Some(Arc::new(move |terminal, outcome_revision| {
                    *a_terminal_observer.lock().unwrap() = Some((terminal, outcome_revision));
                })),
            }),
            test_outcome: None,
        };
        visual.update(|_, cx| {
            shell.update(cx, |shell, cx| {
                shell.start_search_request_for_test(a.clone(), cx)
            });
        });
        use windows::Win32::{
            Foundation::{CloseHandle, WAIT_OBJECT_0},
            System::Threading::{
                OpenProcess, PROCESS_QUERY_LIMITED_INFORMATION, PROCESS_SYNCHRONIZE,
                WaitForSingleObject,
            },
        };
        let helper_process = {
            let deadline = Instant::now() + Duration::from_secs(10);
            loop {
                visual.run_until_parked();
                if let Ok(contents) = std::fs::read_to_string(&a_ready) {
                    let pid = contents.parse::<u32>().expect("held helper wrote its pid");
                    break unsafe {
                        OpenProcess(
                            PROCESS_SYNCHRONIZE | PROCESS_QUERY_LIMITED_INFORMATION,
                            false,
                            pid,
                        )
                    }
                    .expect("open exact held helper before cancellation");
                }
                assert!(
                    Instant::now() < deadline,
                    "query A did not reach its held helper"
                );
                std::thread::sleep(Duration::from_millis(2));
            }
        };
        assert!(everything::provider_has_no_free_slot_for_test());

        let b_reply_capture = Arc::new(std::sync::Mutex::new(None));
        let b = SearchRequest {
            id: 2,
            query: "latest-query".into(),
            cancellation: Arc::new(AtomicBool::new(false)),
            provider_revision: revision,
            test_command: Some(everything::TestSearchCommand {
                factory: b_factory,
                expect_response: true,
                captured_reply: b_reply_capture.clone(),
                terminal_observer: None,
            }),
            test_outcome: None,
        };
        visual.update(|_, cx| {
            shell.update(cx, |shell, _cx| {
                shell.replace_search_request_for_test(b.clone())
            });
        });
        assert!(a.cancellation.load(Ordering::Acquire));
        assert_eq!(
            visual.read_entity(&shell, |shell, _| shell.search_request_state_for_test()),
            (true, Some(1), Some(2), Some(2), "loading", None, 0),
            "replacing A must retain B while A owns the running lane"
        );

        // A has no cooperative release path: cancellation must terminate and reap this exact child.
        let b_identity = {
            let deadline = Instant::now() + Duration::from_secs(15);
            loop {
                visual.run_until_parked();
                visual.executor().advance_clock(Duration::from_millis(10));
                if let Ok(contents) = std::fs::read_to_string(&b_ready) {
                    break contents;
                }
                assert!(
                    Instant::now() < deadline,
                    "pending query B did not reach provider helper; shell state: {:?}",
                    visual.read_entity(&shell, |shell, _| shell.search_request_state_for_test())
                );
                std::thread::sleep(Duration::from_millis(2));
            }
        };
        let (request_id, echoed_revision) = b_identity
            .split_once(':')
            .expect("helper reported echoed request identity");
        assert_eq!(request_id.parse::<u64>().unwrap(), b.id);
        assert_eq!(
            format!("ProviderRevision({echoed_revision})"),
            format!("{revision:?}"),
            "helper must echo the current provider revision"
        );
        assert_eq!(
            *a_terminal.lock().unwrap(),
            Some((everything::ProviderTerminal::Cancelled, revision)),
            "A must finish as Cancelled, not Timeout or another terminal outcome, before B launches"
        );
        assert_eq!(everything::ProviderRevision::current(), revision);
        assert!(
            visual.read_entity(&shell, |shell, _| shell.search_request_state_for_test())
                == (true, Some(2), Some(2), None, "loading", None, 0),
            "the stale A completion must advance the lane without clearing B"
        );
        assert!(everything::provider_has_no_free_slot_for_test());

        assert_eq!(
            unsafe { WaitForSingleObject(helper_process, 0) },
            WAIT_OBJECT_0,
            "B can start only after the exact cancelled A helper signals exit"
        );
        unsafe {
            let _ = CloseHandle(helper_process);
        }

        std::fs::write(&b_release, b"release").unwrap();
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            visual.run_until_parked();
            visual.executor().advance_clock(Duration::from_millis(10));
            let state =
                visual.read_entity(&shell, |shell, _| shell.search_request_state_for_test());
            if state.4 == "ready" {
                assert_eq!(state, (true, None, None, None, "ready", None, 1));
                assert_eq!(everything::ProviderRevision::current(), revision);
                let results =
                    visual.read_entity(&shell, |shell, _| shell.search_results_for_test());
                assert_eq!(
                    results,
                    vec![everything::SearchResult {
                        path: b_result.clone(),
                        name: "echo-result.txt".into(),
                        is_folder: false,
                        size: Some(42),
                        revision,
                    }],
                    "Shell must store the exact result decoded from query B's provider reply"
                );
                break;
            }
            assert!(
                Instant::now() < deadline,
                "query B helper did not commit Ready; shell state: {:?}; captured reply: {:?}",
                state,
                b_reply_capture
                    .lock()
                    .ok()
                    .and_then(|frame| frame.clone())
                    .map(|frame| frame
                        .iter()
                        .take(64)
                        .map(|byte| format!("{byte:02x}"))
                        .collect::<Vec<_>>())
            );
            std::thread::sleep(Duration::from_millis(2));
        }
        drop(reserved_slot);
    }

