    #[test]
    fn external_move_policy_and_request_follow_the_captured_source_order() {
        let snapshot = InternalDragSnapshot {
            sources: ["first.txt", "second.txt"]
                .into_iter()
                .map(|name| InternalDragSource {
                    key: entry_identity::EntryKey::path(
                        format!("C:/items/{name}").into(),
                        EntryKind::File,
                    ),
                    path: format!("C:/items/{name}").into(),
                    identity: filesystem_identity::FilesystemIdentity::from_fallback_token(
                        name.into(),
                    ),
                    is_directory: false,
                    size: Some(1),
                    modified: None,
                })
                .collect(),
            touch_start_position: None,
            location_generation: 17,
            presentation_revision: 23,
            session_id: 9,
        };
        assert_eq!(
            native_drag_pin_policy(&snapshot),
            win_shell_dnd::FileDragPinPolicy::MoveCapable
        );
        let paths = snapshot
            .sources
            .iter()
            .map(|source| source.path.clone())
            .collect::<Vec<_>>();
        let routes = snapshot
            .sources
            .iter()
            .map(|source| {
                let mut route = source
                    .path
                    .parent()
                    .unwrap()
                    .ancestors()
                    .map(std::path::Path::to_path_buf)
                    .collect::<Vec<_>>();
                route.reverse();
                route
                    .into_iter()
                    .map(|path| operations::model::SourceCleanupParentIdentity {
                        path,
                        identity: filesystem_identity::FilesystemIdentity::from_fallback_token(
                            "parent".into(),
                        ),
                    })
                    .collect()
            })
            .collect();
        let signatures = vec![
            operations::model::SourceCleanupLeafSignature {
                number_of_links: 1,
                change_time: 7,
            },
            operations::model::SourceCleanupLeafSignature {
                number_of_links: 1,
                change_time: 9,
            },
        ];
        let request =
            external_move_cleanup_request(&snapshot, 41, paths.clone(), routes, signatures)
                .unwrap();
        assert_eq!(request.kind, OperationKind::ExternalMoveCleanup);
        assert_eq!(request.sources, paths);
        assert_eq!(request.destination, None);
        assert_eq!(request.move_identity_guard, None);
        assert_eq!(
            request
                .source_cleanup_identity_guard
                .unwrap()
                .source_identities,
            snapshot
                .sources
                .iter()
                .map(|source| source.identity.clone())
                .collect::<Vec<_>>()
        );
        assert_eq!(
            request.origin,
            Some(OperationOrigin {
                view_id: 41,
                location_epoch: 17,
                presentation_revision: 23,
            })
        );

        let mut folder_snapshot = snapshot.clone();
        folder_snapshot.sources[1].is_directory = true;
        assert_eq!(
            native_drag_pin_policy(&folder_snapshot),
            win_shell_dnd::FileDragPinPolicy::CopyOnly
        );
        assert!(
            external_move_cleanup_request(
                &folder_snapshot,
                41,
                paths.clone(),
                Vec::new(),
                Vec::new()
            )
            .is_none()
        );
        assert!(
            external_move_cleanup_request(
                &snapshot,
                41,
                paths.into_iter().rev().collect(),
                Vec::new(),
                Vec::new()
            )
            .is_none()
        );
    }

